def _session_key_cad(contrato_id: int, usuario_id: int):
    return (int(contrato_id), int(usuario_id) if usuario_id is not None else 0)


def _dwg_activo(contrato_id: int, usuario_id: int = None) -> bool:
    """
    True si *algún* usuario tiene heartbeat CAD reciente para el contrato (p. ej. cola a AutoCAD).
    No confundir con /cad-queue/.../estado, que es solo el usuario de la petición.
    """
    t = time.time()
    ctx = int(contrato_id)
    for (cid, _uid), last in _dwg_sessions.items():
        if int(cid) == ctx and (t - float(last)) < 10:
            return True
    return False


def _layer_prefijo_del(nombre: str) -> str:
    """Prefijo del_ sin duplicar si la capa ya lo tiene."""
    if not nombre:
        return nombre
    s = str(nombre).strip()
    return s if s.startswith("del_") else f"del_{s}"


def _encolar_layoff_presupuesto_item(item_id: int, r: dict) -> None:
    """
    Encola cambiar_layer (layoff) y actualiza layer_ent/layer_txt en presupuesto.
    Igual que edición de capítulo/ítem: la operación queda en cad_queue aunque AutoCAD
    no esté enlazado en este worker; el Agent la procesa al hacer poll.
    """
    old_lent = (r.get("layer_ent") or "").strip()
    old_ltxt = (r.get("layer_txt") or "").strip()
    ent_handle = (r.get("ent_handle") or "").strip()

    if not old_lent or old_lent.startswith("del_"):
        return
    if not ent_handle:
        return

    new_lent = _layer_prefijo_del(old_lent)
    new_ltxt = _layer_prefijo_del(old_ltxt) if old_ltxt else f"del_{old_ltxt}"

    try:
        supabase.table("cad_queue").insert({
            "contrato_id": r["contrato_id"],
            "tipo": "cambiar_layer",
            "estado": "pendiente",
            "payload": {
                "ent_handle": ent_handle,
                "txt_handle": (r.get("txt_handle") or "").strip(),
                "layer_ent": new_lent,
                "layer_txt": new_ltxt,
                "color_hex": "",
                "rev_block_handle": r.get("rev_block_handle") or "",
                "layoff": True,
            },
        }).execute()
    except Exception:
        try:
            _log_api.warning("dar_baja: falló insert cad_queue item_id=%s", item_id, exc_info=True)
        except Exception:
            pass

    try:
        supabase.table("presupuesto").update({
            "layer_ent": new_lent,
            "layer_txt": new_ltxt,
        }).eq("id", item_id).execute()
    except Exception:
        try:
            _log_api.warning("dar_baja: falló update layers item_id=%s", item_id, exc_info=True)
        except Exception:
            pass


def _encolar_restaurar_presupuesto_item(item_id: int, r: dict) -> None:
    """
    Quita prefijo del_ de layers y encola reactivación en CAD.
    Simétrico a `_encolar_layoff_presupuesto_item`: no depende de heartbeat DWG.
    """
    old_lent = (r.get("layer_ent") or "").strip()
    old_ltxt = (r.get("layer_txt") or "").strip()
    ent_handle = (r.get("ent_handle") or "").strip()

    if not old_lent:
        return

    new_lent = old_lent[4:] if old_lent.startswith("del_") else old_lent
    new_ltxt = old_ltxt[4:] if old_ltxt.startswith("del_") else old_ltxt

    # Si no había prefijo del_, no hay nada que restaurar en capas.
    if new_lent == old_lent and new_ltxt == old_ltxt:
        return

    if ent_handle:
        try:
            supabase.table("cad_queue").insert({
                "contrato_id": r["contrato_id"],
                "tipo": "cambiar_layer",
                "estado": "pendiente",
                "payload": {
                    "ent_handle": ent_handle,
                    "txt_handle": (r.get("txt_handle") or "").strip(),
                    "layer_ent": new_lent,
                    "layer_txt": new_ltxt,
                    "color_hex": r.get("color_hex") or "",
                    "rev_block_handle": r.get("rev_block_handle") or "",
                    "layoff": False,
                },
            }).execute()
        except Exception:
            try:
                _log_api.warning("restaurar: falló insert cad_queue item_id=%s", item_id, exc_info=True)
            except Exception:
                pass

    try:
        supabase.table("presupuesto").update({
            "layer_ent": new_lent,
            "layer_txt": new_ltxt,
        }).eq("id", item_id).execute()
    except Exception:
        try:
            _log_api.warning("restaurar: falló update layers item_id=%s", item_id, exc_info=True)
        except Exception:
            pass

