def _so_registro_fetch_validacion_audit(contrato_id: int, registro_id: int) -> Optional[dict]:
    def _q():
        return supabase.table("so_registros").select(
            "nivel1_estado, nivel1_usuario_id, nivel1_fecha,"
            "nivel2_estado, nivel2_usuario_id, nivel2_fecha, nivel2_objeto_pago_sub,"
            "nivel3_estado, nivel3_usuario_id, nivel3_fecha,"
            "nivel4_estado, nivel4_usuario_id, nivel4_fecha,"
            "nivel5_estado, nivel5_usuario_id, nivel5_fecha,"
            "nivel6_estado, nivel6_usuario_id, nivel6_fecha,"
            "sub_estado, sub_usuario_id, sub_fecha, bloqueado, solicitud_reversion,"
            "reversion_arm_n2_usuario_id, reversion_arm_n3_usuario_id"
        ).eq("id", registro_id).eq("contrato_id", contrato_id).limit(1).execute().data
    r = supabase_execute(_q)
    return r[0] if r else None


def _enriquecer_registros_labels_reversion_doble_llave(registros: Optional[list]) -> None:
    """Expone nombre legible para quien disparó cada llave (UI doble autorización reversión N3)."""
    if not registros:
        return
    ids: List[int] = []
    for reg in registros:
        if not isinstance(reg, dict):
            continue
        for key in ("reversion_arm_n2_usuario_id", "reversion_arm_n3_usuario_id"):
            v = reg.get(key)
            if v is None:
                continue
            try:
                ids.append(int(v))
            except (TypeError, ValueError):
                pass
    uniq = list({i for i in ids})
    if not uniq:
        for reg in registros:
            if isinstance(reg, dict):
                reg["reversion_arm_n2_nombre"] = None
                reg["reversion_arm_n3_nombre"] = None
        return
    nombres_por_id: Dict[int, str] = {}
    try:
        step = 200
        for i in range(0, len(uniq), step):
            batch = uniq[i : i + step]

            def _lookup(b=batch):
                return (
                    supabase.table("usuarios")
                    .select("id, nombre, apellidos")
                    .in_("id", b)
                    .execute()
                    .data
                )

            rows = supabase_execute(_lookup) or []
            for ur in rows:
                uid = ur.get("id")
                if uid is None:
                    continue
                lbl = f"{ur.get('nombre') or ''} {ur.get('apellidos') or ''}".strip()
                if not lbl:
                    lbl = f"Usuario #{uid}"
                nombres_por_id[int(uid)] = lbl
    except Exception:
        pass
    for reg in registros:
        if not isinstance(reg, dict):
            continue
        for key_uid, key_nom in (
            ("reversion_arm_n2_usuario_id", "reversion_arm_n2_nombre"),
            ("reversion_arm_n3_usuario_id", "reversion_arm_n3_nombre"),
        ):
            v = reg.get(key_uid)
            if v is None:
                reg[key_nom] = None
                continue
            try:
                reg[key_nom] = nombres_por_id.get(int(v))
            except (TypeError, ValueError):
                reg[key_nom] = None


def _so_reporte_audit_snapshot(row: Optional[dict]) -> Optional[dict]:
    if not row:
        return None
    keys = (
        "id", "numero_reporte", "estado", "capitulo", "semana_id", "acta_rpo_id", "corte_id",
        "pk_id_id", "civ", "tramo", "infraestructura", "calzada", "ubicacion",
        "coord_lat", "coord_lng", "abs_inicio", "abs_final", "nodo_ini", "nodo_fin", "margen",
        "subcontratista_id", "inspector_id",
    )
    return _json_for_log({k: row.get(k) for k in keys})


def _default_severidad(accion: str, modulo: str, resultado: str) -> str:
    if resultado and str(resultado).lower() not in ("ok", "success", "éxito"):
        return "ERROR" if "denegado" not in str(resultado).lower() else "WARNING"
    if modulo == "PERMISOS" or accion in (
        "ELIMINAR", "VALIDAR", "APROBAR", "RECHAZAR", "IMPORTAR_MASIVO",
        "ASIGNAR_ITEM", "MOVER", "COMENTAR",
    ):
        return "AUDIT"
    if accion in ("LOGIN_FAIL", "ACCESO_DENEGADO"):
        return "WARNING"
    return "INFO"


_CORS_ORIGIN_REGEX_HANDLER = re.compile(
    r"^https://([a-z0-9-]+\.)*claracore\.co$|^https?://(localhost|127\.0\.0\.1)(:\d+)?$"
)


def _cors_headers_para_error(request: Request) -> dict:
    """Cabeceras CORS para respuestas de error.

    CRÍTICO: el handler de Exception lo invoca ServerErrorMiddleware, que está POR FUERA
    del CORSMiddleware; por eso un 500 salía SIN 'Access-Control-Allow-Origin' y el
    navegador lo reportaba como error de CORS (enmascarando el 500 real). Añadimos las
    cabeceras a mano, reflejando el Origin si está permitido (mismo criterio que el CORS).
    """
    origin = request.headers.get("origin")
    if not origin:
        return {}
    permitido = origin in _cors_origins or bool(_CORS_ORIGIN_REGEX_HANDLER.match(origin))
    if not permitido:
        return {}
    return {
        "Access-Control-Allow-Origin": origin,
        "Access-Control-Allow-Credentials": "true",
        "Vary": "Origin",
    }


@app.exception_handler(Exception)
async def unhandled_exception_to_json(request: Request, exc: Exception):
    """Evita HTML genérico 'Internal Server Error'; el front puede mostrar `detail` en JSON.

    Incluye cabeceras CORS para que el 500 sea legible por el navegador (no enmascarado).
    """
    cors = _cors_headers_para_error(request)
    if isinstance(exc, HTTPException):
        return JSONResponse(status_code=exc.status_code, content={"detail": exc.detail}, headers=cors)
    if isinstance(exc, RequestValidationError):
        return JSONResponse(status_code=422, content={"detail": exc.errors()}, headers=cors)
    # PostgREST 401 por cliente httpx corrupto / KEY inválida → 503 recuperable (no 500 opaco).
    try:
        if _is_supabase_auth_error(exc):
            try:
                reset_supabase_client()
            except Exception:
                pass
            return JSONResponse(
                status_code=503,
                content={
                    "detail": (
                        "El servicio de datos rechazó la autenticación (PostgREST 401). "
                        "Reintenta; si persiste, revise SUPABASE_KEY en Azure App Service."
                    )
                },
                headers=cors,
            )
        if _is_supabase_transport_error(exc):
            try:
                reset_supabase_client()
            except Exception:
                pass
            return JSONResponse(
                status_code=503,
                content={"detail": "El servicio de datos no respondió a tiempo. Intente de nuevo en unos segundos."},
                headers=cors,
            )
    except Exception:
        pass
    _log_api.exception("Error no manejado: %s %s", request.method, request.url.path)
    try:
        registrar_log_sistema(
            "ERROR",
            request.url.path,
            request.method,
            {"error": type(exc).__name__, "msg": str(exc)[:2000]},
            traceback.format_exc()[:12000],
            resultado="error",
            alerta_generada=False,
        )
        _track_500_endpoint_alert(request.url.path)
    except Exception:
        pass
    debug = os.getenv("CLARACORE_DEBUG", "").lower() in ("1", "true", "yes")
    detail = traceback.format_exc() if debug else f"{type(exc).__name__}: {exc}"
    return JSONResponse(status_code=500, content={"detail": detail}, headers=cors)


_SUPABASE_URL = os.getenv("SUPABASE_URL")
_SUPABASE_KEY = os.getenv("SUPABASE_KEY")
# PostgREST puede tardar bajo carga; el default de httpx (~5s) provoca ReadTimeout en /auth/refresh y otras rutas.
# Updates con `plano_geojson` muy grande (decenas de MB) necesitan write/read largos hacia PostgREST.
_SUPABASE_HTTP_TIMEOUT = httpx.Timeout(
    connect=float(os.getenv("SUPABASE_HTTP_CONNECT_TIMEOUT", "20")),
    read=float(os.getenv("SUPABASE_HTTP_READ_TIMEOUT", "180")),
    write=float(os.getenv("SUPABASE_HTTP_WRITE_TIMEOUT", "600")),
    pool=float(os.getenv("SUPABASE_HTTP_POOL_TIMEOUT", "30")),
)

# httpx.Client NO es thread-safe. Un único cliente global compartido entre el worker
# principal y ThreadPoolExecutor corrompe Authorization → PostgREST responde 401
# y el backend empieza a devolver 500/503 en casi todos los endpoints hasta reiniciar.
_supabase_tls = threading.local()


def _supabase_credentials():
    """Lee URL/KEY en cada creación (permite rotar App Settings sin redeploy de código)."""
    url = (os.getenv("SUPABASE_URL") or _SUPABASE_URL or "").strip()
    key = (os.getenv("SUPABASE_KEY") or _SUPABASE_KEY or "").strip()
    return url, key


def _close_supabase_httpx(client) -> None:
    if client is None:
        return
    session = None
    try:
        session = getattr(getattr(client, "postgrest", None), "session", None)
    except Exception:
        session = None
    if session is not None:
        try:
            session.close()
        except Exception:
            pass


def _make_supabase_client():
    url, key = _supabase_credentials()
    return create_client(
        url,
        key,
        options=ClientOptions(
            httpx_client=httpx.Client(http2=False, timeout=_SUPABASE_HTTP_TIMEOUT)
        ),
    )


def get_supabase():
    """Cliente Supabase del hilo actual (un httpx.Client por hilo)."""
    client = getattr(_supabase_tls, "client", None)
    if client is None:
        client = _make_supabase_client()
        _supabase_tls.client = client
    return client


def reset_supabase_client():
    """Descarta el cliente del hilo (p. ej. tras 401/timeout) y crea uno nuevo."""
    old = getattr(_supabase_tls, "client", None)
    _supabase_tls.client = None
    _close_supabase_httpx(old)
    return get_supabase()


class _SupabaseThreadLocalProxy:
    """Proxy para que `supabase.table(...)` use siempre el cliente del hilo actual."""

    def __getattr__(self, name):
        return getattr(get_supabase(), name)


supabase = _SupabaseThreadLocalProxy()
security = HTTPBearer(auto_error=False)

SECRET_KEY = os.getenv("SECRET_KEY")
ALGORITHM = os.getenv("ALGORITHM")
EXPIRE_MINUTES = int(os.getenv("ACCESS_TOKEN_EXPIRE_MINUTES") or "10080")


@app.middleware("http")
async def exigir_politicas_confidencialidad(request: Request, call_next):
    """Bloquea el uso de la API con token si el usuario no ha aceptado las políticas (salvo rutas mínimas)."""
    if request.method == "OPTIONS":
        return await call_next(request)
    path = request.url.path
    auth = request.headers.get("authorization") or ""
    if not auth.startswith("Bearer "):
        return await call_next(request)
    if (
        (request.method == "POST" and path == "/auth/refresh")
        or (request.method == "GET" and path == "/usuarios/me")
        or (request.method == "POST" and path == "/usuarios/me/politicas-aceptar")
    ):
        return await call_next(request)
    try:
        payload = jwt.decode(auth[7:], SECRET_KEY, algorithms=[ALGORITHM])
        sub = payload.get("sub")
        if not sub:
            return await call_next(request)
        uid = int(sub)
    except (JWTError, ValueError, TypeError):
        return await call_next(request)
    cached = _politicas_cache_get(uid)
    if cached == "ok":
        return await call_next(request)
    if cached == "pend":
        return JSONResponse(status_code=403, content={"detail": "politicas_pendientes"})
    if cached == "none":
        return JSONResponse(status_code=403, content={"detail": "politicas_pendientes"})
    try:
        r = supabase.table("usuarios").select("politicas_aceptadas").eq("id", uid).limit(1).execute()
        row = r.data[0] if r.data else None
        if row is None:
            _politicas_cache_set(uid, "none")
            return JSONResponse(status_code=403, content={"detail": "politicas_pendientes"})
        if row.get("politicas_aceptadas") is True:
            _politicas_cache_set(uid, "ok")
            return await call_next(request)
        _politicas_cache_set(uid, "pend")
        return JSONResponse(status_code=403, content={"detail": "politicas_pendientes"})
    except Exception as e:
        # Columna aún no migrada u cliente Supabase corrupto: no bloquear; reset si es 401.
        try:
            if _is_supabase_auth_error(e) or _is_supabase_transport_error(e):
                reset_supabase_client()
        except Exception:
            pass
        return await call_next(request)


