def _estado_mantenimiento():
    now = time.time()
    if _maintenance_state["activo"] and _maintenance_state["expires_at"] is not None and now >= _maintenance_state["expires_at"]:
        _maintenance_state["activo"] = False
        _maintenance_state["expires_at"] = None

    restantes = None
    if _maintenance_state["activo"] and _maintenance_state["expires_at"] is not None:
        restantes = max(0, int(_maintenance_state["expires_at"] - now))

    return {
        "activo": _maintenance_state["activo"],
        "mensaje": _maintenance_state["mensaje"],
        "segundos_restantes": restantes,
    }

# ─────────────────────────────────────────────
# HELPER SUPABASE CON REINTENTOS
# ─────────────────────────────────────────────
def _is_supabase_statement_timeout(err: Exception) -> bool:
    """Postgres 57014 — evita 500 genérico y alinea con saturación de la BD."""
    s = str(err).lower()
    if "57014" in s or "statement timeout" in s or "canceling statement" in s:
        return True
    code = getattr(err, "code", None)
    if code == "57014":
        return True
    d = getattr(err, "dict", None)
    if callable(d):
        try:
            di = d()
            if isinstance(di, dict) and str(di.get("code") or "") == "57014":
                return True
        except Exception:
            pass
    return False


def _is_supabase_auth_error(err: Exception) -> bool:
    """PostgREST 401 / JWT inválido (cliente httpx corrupto o SUPABASE_KEY inválida)."""
    if err is None:
        return False
    code = str(getattr(err, "code", "") or "")
    if code in ("401", "PGRST301", "PGRST302"):
        return True
    status = getattr(err, "status_code", None) or getattr(err, "status", None)
    if status == 401:
        return True
    s = str(err).lower()
    if "invalid jwt" in s or "jwt expired" in s or "invalid api key" in s:
        return True
    if "401" in s and ("unauthorized" in s or "jwt" in s or "api key" in s):
        return True
    d = getattr(err, "dict", None)
    if callable(d):
        try:
            di = d()
            if isinstance(di, dict):
                if str(di.get("code") or "") in ("401", "PGRST301", "PGRST302"):
                    return True
                msg = str(di.get("message") or "").lower()
                if "invalid jwt" in msg or "invalid api key" in msg:
                    return True
        except Exception:
            pass
    return False


def _is_supabase_transport_error(err: Exception) -> bool:
    return isinstance(
        err,
        (
            httpx.ReadTimeout,
            httpx.ConnectTimeout,
            httpx.ConnectError,
            httpx.RemoteProtocolError,
            httpx.WriteTimeout,
            httpx.PoolTimeout,
        ),
    )


def supabase_execute(fn, retries=3, delay=0.5):
    import time
    last_err = None
    for i in range(retries):
        try:
            return fn()
        except Exception as e:
            last_err = e
            # Recrear cliente del hilo: recupera Authorization tras corrupción / timeout.
            if _is_supabase_auth_error(e) or _is_supabase_transport_error(e) or i == 0:
                try:
                    reset_supabase_client()
                except Exception:
                    pass
            if i < retries - 1:
                time.sleep(delay)
    try:
        registrar_log_sistema(
            "ERROR",
            "supabase_execute",
            "RPC",
            {"error": type(last_err).__name__, "msg": str(last_err)[:2000], "reintentos": retries},
            traceback.format_exc()[:8000],
            resultado="error",
            alerta_generada=False,
        )
    except Exception:
        pass
    if _is_supabase_statement_timeout(last_err):
        raise HTTPException(
            status_code=503,
            detail="La base de datos está ocupada o la consulta tardó demasiado. Reintenta en unos segundos o acota el filtro.",
        )
    if _is_supabase_auth_error(last_err):
        raise HTTPException(
            status_code=503,
            detail="El servicio de datos rechazó la autenticación (PostgREST 401). Reintenta; si persiste, revise SUPABASE_KEY en Azure App Service.",
        )
    if _is_supabase_transport_error(last_err):
        raise HTTPException(
            status_code=503,
            detail="El servicio de datos no respondió a tiempo. Intente de nuevo en unos segundos.",
        )
    raise last_err

# ─────────────────────────────────────────────
# SISTEMA DE LOGS
# ─────────────────────────────────────────────
_LOGS_INSERT_MAX_STRIPS = 32


def _logs_pgrst_unknown_column(err: Exception) -> Optional[str]:
    """PGRST204: columna ausente en la caché de esquema de PostgREST (tabla logs sin ALTER)."""
    text = str(err)
    if "PGRST204" not in text and "schema cache" not in text.lower():
        return None
    m = re.search(r"find the '([^']+)' column", text, re.I)
    if m:
        return m.group(1)
    m = re.search(r'find the "([^"]+)" column', text, re.I)
    return m.group(1) if m else None


def _error_es_columna_reversion_arm(ex: Exception) -> bool:
    """Columnas reversion_arm_* ausentes o caché PostgREST sin recargar tras migración."""
    text = str(ex)
    low = text.lower()
    if "reversion_arm" in low:
        return True
    col = _logs_pgrst_unknown_column(ex)
    return bool(col and "reversion_arm" in col)


def _http_reversion_doble_llave_db_error(ex: Exception) -> HTTPException:
    """Mensaje accionable: migración SQL y/o recargar esquema API en Supabase."""
    if _error_es_columna_reversion_arm(ex):
        return HTTPException(
            status_code=503,
            detail=(
                "Base de datos: ejecute en Supabase (SQL Editor), en este orden: "
                "1) reversion_n3_doble_llave_so_registros.sql "
                "2) alter_so_registro_comentarios_tipo_reversion_doble_llave.sql. "
                "Si ya las ejecutó, vaya a Configuración del proyecto → API → «Reload schema» "
                "(o ejecute NOTIFY pgrst, 'reload schema';) y reintente."
            ),
        )
    low = str(ex).lower()
    if "so_registro_comentarios_tipo_check" in low or (
        "23514" in low and "tipo" in low and "comentario" in low
    ):
        return HTTPException(
            status_code=503,
            detail=(
                "Falta ejecutar alter_so_registro_comentarios_tipo_reversion_doble_llave.sql "
                "en Supabase (tipos de comentario de reversión)."
            ),
        )
    return HTTPException(
        status_code=500,
        detail=f"No se pudo guardar la reversión: {str(ex)[:500]}",
    )


def _logs_insert_row(row: Dict[str, Any]) -> bool:
    """Inserta en logs; omite columnas desconocidas y las guarda en caché para no penalizar cada request."""
    payload = dict(row)
    with _logs_omit_lock:
        frozen_omit = frozenset(_logs_omit_columns)
    for c in frozen_omit:
        payload.pop(c, None)
    strips = 0
    while strips <= _LOGS_INSERT_MAX_STRIPS:
        try:
            supabase.table("logs").insert(payload).execute()
            return True
        except Exception as e:
            col = _logs_pgrst_unknown_column(e)
            if col and col in payload:
                with _logs_omit_lock:
                    _logs_omit_columns.add(col)
                payload.pop(col, None)
                strips += 1
                continue
            try:
                _log_api.warning(
                    "registrar_log: insert falló (%s) (strips=%s)",
                    e,
                    strips,
                )
            except Exception:
                pass
            return False
    try:
        _log_api.warning("registrar_log: se alcanzó el máximo de columnas omitidas; revise esquema de logs")
    except Exception:
        pass
    return False


def registrar_log_sistema(
    severidad: str,
    endpoint: str,
    metodo_http: str,
    detalle: dict,
    stack_trace: Optional[str] = None,
    resultado: str = "error",
    alerta_generada: bool = False,
    duracion_ms: Optional[int] = None,
):
    """Errores y eventos técnicos (categoría sistema). No requiene usuario."""
    try:
        row = {
            "usuario_id":       None,
            "usuario_nombre":   "SISTEMA",
            "cargo_nombre":     "",
            "rol_nombre":       None,
            "contrato_id":      None,
            "contrato_numero":  None,
            "accion":           "ERROR_SISTEMA" if severidad == "ERROR" else "EVENTO_SISTEMA",
            "modulo":           "SISTEMA",
            "entidad_tipo":     "endpoint",
            "entidad_id":       None,
            "detalle":          _json_for_log(detalle) if detalle is not None else {},
            "resultado":        resultado,
            "categoria":        "sistema",
            "severidad":        severidad,
            "endpoint":         (endpoint or "")[:1024],
            "metodo_http":      (metodo_http or "")[:32],
            "stack_trace":      (stack_trace or "")[:12000] if stack_trace else None,
            "duracion_ms":      duracion_ms,
            "alerta_generada":  alerta_generada,
        }
        _logs_insert_row(row)
    except Exception:
        pass


def registrar_log(
    usuario,
    accion,
    modulo,
    entidad_tipo=None,
    entidad_id=None,
    detalle=None,
    resultado="ok",
    *,
    valor_anterior=None,
    valor_nuevo=None,
    ip=None,
    severidad=None,
    categoria="auditoria",
    rol_nombre=None,
    endpoint=None,
    metodo_http=None,
    stack_trace=None,
    duracion_ms=None,
    alerta_generada=None,
):
    try:
        uid = usuario.get("sub") or usuario.get("id")
        uid_int = None
        if uid is not None and str(uid).strip() != "":
            try:
                uid_int = int(str(uid).strip())
            except (ValueError, TypeError):
                uid_int = None
        if severidad is None:
            severidad = _default_severidad(accion, modulo, resultado)
        row = {
            "usuario_id":       uid_int,
            "usuario_nombre":   usuario.get("nombre") or usuario.get("email", ""),
            "cargo_nombre":     usuario.get("cargo_nombre") or "",
            "rol_nombre":       rol_nombre if rol_nombre is not None else usuario.get("rol_nombre"),
            "contrato_id":      usuario.get("contrato_id"),
            "contrato_numero":  usuario.get("contrato_numero"),
            "accion":           accion,
            "modulo":           modulo,
            "entidad_tipo":     entidad_tipo,
            "entidad_id":       str(entidad_id) if entidad_id is not None else None,
            "detalle":          _json_for_log(detalle) if detalle is not None else {},
            "resultado":        resultado,
            "valor_anterior":   _json_for_log(valor_anterior),
            "valor_nuevo":      _json_for_log(valor_nuevo),
            "ip":               ip,
            "categoria":        categoria,
            "severidad":        severidad,
            "endpoint":         (endpoint or "")[:1024] if endpoint else None,
            "metodo_http":      (metodo_http or "")[:32] if metodo_http else None,
            "stack_trace":      (stack_trace or "")[:12000] if stack_trace else None,
            "duracion_ms":      duracion_ms,
            "alerta_generada":  alerta_generada if alerta_generada is not None else False,
        }
        if not _logs_insert_row(row):
            pass
    except Exception:
        pass


def _registrar_logs_presupuesto_por_fila(
    usuario,
    accion: str,
    filas: List[Tuple[dict, dict]],
    detalle_extra: Optional[dict] = None,
):
    """Auditoría por registro (entidad presupuesto/{id}) para trazabilidad en la grilla."""
    base = dict(detalle_extra or {})
    base.setdefault("edicion_masiva", True)
    for prev, nuevo in filas:
        rid = prev.get("id") or nuevo.get("id")
        if rid is None:
            continue
        det = {**base, "id_pol": nuevo.get("id_pol") or prev.get("id_pol")}
        try:
            registrar_log(
                usuario,
                accion,
                "PRESUPUESTO",
                "presupuesto",
                str(rid),
                det,
                valor_anterior=_json_for_log(prev),
                valor_nuevo=_json_for_log(nuevo),
            )
        except Exception:
            pass


def _track_login_failure_alert(email: str, ip: str):
    import time
    now = time.time()
    key = (email.strip().lower(), ip or "")
    q = _login_fail_tracker.setdefault(key, [])
    q.append(now)
    cutoff = now - 900
    while q and q[0] < cutoff:
        q.pop(0)
    if len(q) >= 5:
        try:
            registrar_log_sistema(
                "WARNING",
                "/auth/login",
                "POST",
                {"email": email, "ip": ip, "ventana_seg": 900, "intentos": len(q)},
                None,
                resultado="alerta",
                alerta_generada=True,
            )
        except Exception:
            pass
        q.clear()


def _track_500_endpoint_alert(path: str):
    import time
    now = time.time()
    q = _endpoint_500_tracker.setdefault(path, [])
    q.append(now)
    cutoff = now - 300
    while q and q[0] < cutoff:
        q.pop(0)
    if len(q) >= 3:
        try:
            registrar_log_sistema(
                "ERROR",
                path,
                "—",
                {"tipo": "error_500_repetido", "ventana_seg": 300, "conteo": len(q)},
                None,
                resultado="alerta",
                alerta_generada=True,
            )
        except Exception:
            pass
        q.clear()


def _cargo_puede_auditar_logs(current_user) -> bool:
    try:
        uid = int(current_user.get("sub"))
    except (TypeError, ValueError):
        return False
    try:
        u = supabase.table("usuarios").select("cargo_id").eq("id", uid).limit(1).execute().data
        u = u[0] if u else None
        if not u or not u.get("cargo_id"):
            return False
        c = supabase.table("cargos").select("nombre").eq("id", u["cargo_id"]).limit(1).execute().data
        c = c[0] if c else None
        n = ((c or {}).get("nombre") or "").strip().lower()
        return n in ("desarrollador", "administrador")
    except Exception:
        return False


def _es_desarrollador(current_user) -> bool:
    """Cargo Desarrollador (o rol Desarrollador en JWT): acceso total sin matriz."""
    rol_jwt = (current_user.get("rol_nombre") or "").strip().lower()
    if rol_jwt == "desarrollador":
        return True
    cargo_jwt = (current_user.get("cargo_nombre") or "").strip().lower()
    if cargo_jwt == "desarrollador":
        return True
    try:
        uid = int(current_user.get("sub"))
    except (TypeError, ValueError):
        return False
    try:
        u = supabase.table("usuarios").select("cargo_id").eq("id", uid).limit(1).execute().data
        u = u[0] if u else None
        if not u or not u.get("cargo_id"):
            return False
        c = supabase.table("cargos").select("nombre").eq("id", u["cargo_id"]).limit(1).execute().data
        c = c[0] if c else None
        n = ((c or {}).get("nombre") or "").strip().lower()
        return n == "desarrollador"
    except Exception:
        return False


def _permisos_desarrollador_acceso_total(permisos: list, funciones_rows: list, cargo_id) -> list:
    """Desarrollador: todas las acciones en funciones existentes + filas sintéticas faltantes."""
    full = {
        "ver": True,
        "crear": True,
        "editar": True,
        "eliminar": True,
        "validar": True,
        "exportar": True,
    }
    out = [{**p, **full} for p in (permisos or [])]
    nombres = {(p.get("funcion_nombre") or "").strip().lower() for p in out}
    for func in funciones_rows or []:
        fn = (func.get("nombre") or "").strip()
        key = fn.lower()
        if key and key not in nombres:
            out.append({
                "id": None,
                "cargo_id": cargo_id,
                "funcion_id": func.get("id"),
                "funcion_nombre": fn,
                **full,
            })
            nombres.add(key)
    return out


def _es_cargo_administrador_sicoe(current_user) -> bool:
    """Cargo Administrador (sin ser Desarrollador): validación SICOE N1–N3 solo en su contrato."""
    try:
        uid = int(current_user.get("sub"))
    except (TypeError, ValueError):
        return False
    try:
        u = supabase.table("usuarios").select("cargo_id").eq("id", uid).limit(1).execute().data
        u = u[0] if u else None
        if not u or not u.get("cargo_id"):
            return False
        c = supabase.table("cargos").select("nombre").eq("id", u["cargo_id"]).limit(1).execute().data
        c = c[0] if c else None
        n = ((c or {}).get("nombre") or "").strip().lower()
        return n == "administrador"
    except Exception:
        return False


def _es_admin_o_desarrollador(current_user) -> bool:
    """True si el usuario tiene cargo Administrador (Desarrollador se cubre aparte en callers que lo combinan con OR)."""
    return _es_cargo_administrador_sicoe(current_user)


def _usuario_contrato_id_por_user_id(user_id: int) -> Optional[int]:
    try:
        uid = int(user_id)
    except (TypeError, ValueError):
        return None
    try:
        urows = supabase.table("usuarios").select("contrato_id").eq("id", uid).limit(1).execute().data
        u = urows[0] if urows else None
        if not u or u.get("contrato_id") is None:
            return None
        return int(u["contrato_id"])
    except Exception:
        return None


def _caller_cargo_id(current_user) -> Optional[int]:
    """cargo_id del usuario autenticado (tabla usuarios)."""
    try:
        uid = int(current_user.get("sub"))
    except (TypeError, ValueError):
        return None
    try:
        u = supabase.table("usuarios").select("cargo_id").eq("id", uid).limit(1).execute().data
        u = u[0] if u else None
        if not u:
            return None
        cid = u.get("cargo_id")
        return int(cid) if cid is not None else None
    except Exception:
        return None


def _cargo_tiene_permiso_funcion(
    current_user,
    funcion_nombre: str,
    flag: str,
    contrato_id: Optional[int] = None,
) -> bool:
    """Matriz por cargo; si contrato_id, filas de ese contrato (misma lógica que login y /usuarios/me)."""
    if _es_desarrollador(current_user):
        return True
    cid = _caller_cargo_id(current_user)
    if cid is None:
        return False
    want = (funcion_nombre or "").strip().lower()
    try:
        perms = _permisos_rows_para_cargo(
            int(cid),
            int(contrato_id) if contrato_id is not None else None,
        )
        fids = [p["funcion_id"] for p in perms if p.get(flag)]
        if not fids:
            return False
        funcs = supabase_execute(
            lambda: supabase.table("funciones")
            .select("id, nombre")
            .in_("id", fids)
            .execute()
            .data
        ) or []
        return any((f.get("nombre") or "").strip().lower() == want for f in funcs)
    except Exception:
        return False


