def _sicoe_vm_grilla_paginar(
    contrato_id: int,
    offset: int,
    limit: int,
    *,
    numero_reporte: Optional[int] = None,
    semana_id: Optional[int] = None,
    acta_id: Optional[int] = None,
    estado: Optional[str] = None,
    excluir_estados_avanzados: bool = False,
    reporte_ids: Optional[List[int]] = None,
) -> Tuple[List[int], bool]:
    """IDs de reporte ordenados por numero_reporte desc desde vm_sicoe_grilla."""
    page_lim = max(1, min(int(limit or 50), 100))
    off = max(0, int(offset or 0))

    def _q():
        q = supabase.table("vm_sicoe_grilla").select("id, numero_reporte").eq("contrato_id", contrato_id)
        if numero_reporte is not None:
            q = q.eq("numero_reporte", numero_reporte)
        if semana_id is not None:
            q = q.eq("semana_id", semana_id)
        if acta_id is not None:
            q = q.eq("acta_rpo_id", acta_id)
        if estado:
            q = _so_reportes_q_por_estado(q, estado)
        elif excluir_estados_avanzados:
            q = q.not_.in_("estado", list(ESTADOS_REPORTE_EXCL_VALIDACION_AVANZADA))
        if reporte_ids is not None:
            if not reporte_ids:
                return type("R", (), {"data": []})()
            q = q.in_("id", reporte_ids)
        return q.order("numero_reporte", desc=True).range(off, off + page_lim).execute()

    data = supabase_execute(_q).data or []
    ids = [int(r["id"]) for r in data if r.get("id") is not None]
    hay_mas = len(ids) > page_lim
    return ids[:page_lim], hay_mas


def _sicoe_vm_grilla_agregados(reporte_ids: List[int]) -> Dict[int, Dict[str, Any]]:
    if not reporte_ids:
        return {}
    out: Dict[int, Dict[str, Any]] = {}
    chunk = 200
    for i in range(0, len(reporte_ids), chunk):
        part = reporte_ids[i : i + chunk]

        def _q(p=part):
            return (
                supabase.table("vm_sicoe_grilla")
                .select("id, total_registros, costo_directo_total")
                .in_("id", p)
                .execute()
                .data
            )

        for row in supabase_execute(_q) or []:
            rid = row.get("id")
            if rid is not None:
                out[int(rid)] = row
    return out


def _fetch_dashboard_resumen_from_vm(contrato_id: int, campo_max: str, niveles_activos: List[int]):
    """Construye payload tipo dashboard_resumen_sicoe_agg desde vistas materializadas."""
    try:

        def _caps():
            return (
                supabase.table("vm_dashboard_resumen")
                .select("*")
                .eq("contrato_id", contrato_id)
                .execute()
                .data
            )

        cap_rows = supabase_execute(_caps) or []
        if not cap_rows:
            return None

        cob_col = _vm_cobrado_col(campo_max)
        nr_col = _vm_nr_col(campo_max)
        obra_caps = {}
        total_cobrado = 0.0
        total_nr = 0.0
        comparativo_sicoe = []
        for r in cap_rows:
            cap = r.get("capitulo") or "Sin capítulo"
            cob = float(r.get(cob_col) or 0)
            nr = float(r.get(nr_col) or 0)
            obra_caps[cap] = cob
            total_cobrado += cob
            total_nr += nr
            comparativo_sicoe.append(
                {
                    "capitulo": cap,
                    "cobrado": round(cob, 2),
                    "sicoe_aprobado": round(cob, 2),
                    "sicoe_no_revisado": round(nr, 2),
                }
            )

        def _actas_vm():
            return (
                supabase.table("vm_dashboard_por_acta")
                .select("acta_rpo_id, " + cob_col)
                .eq("contrato_id", contrato_id)
                .execute()
                .data
            )

        acta_vm = supabase_execute(_actas_vm) or []
        acta_id_to_nr = {}
        if acta_vm:
            aids = list({a["acta_rpo_id"] for a in acta_vm if a.get("acta_rpo_id") is not None})

            def _actas_nr():
                return (
                    supabase.table("actas")
                    .select("id, numero_rpo")
                    .eq("contrato_id", contrato_id)
                    .in_("id", aids)
                    .execute()
                    .data
                )

            for a in supabase_execute(_actas_nr) or []:
                if a.get("id") is not None:
                    acta_id_to_nr[int(a["id"])] = a.get("numero_rpo")

        por_acta = []
        actas_keys = []
        for row in acta_vm:
            aid = row.get("acta_rpo_id")
            nr = acta_id_to_nr.get(int(aid)) if aid is not None else None
            if nr is None:
                continue
            v = round(float(row.get(cob_col) or 0), 2)
            por_acta.append({"acta": nr, "cobrado": v})
            actas_keys.append(nr)

        def _sort_acta_key(x):
            try:
                return float(x)
            except (TypeError, ValueError):
                return 0.0

        por_acta.sort(key=lambda x: _sort_acta_key(x.get("acta")), reverse=True)
        actas_keys = sorted(set(actas_keys), key=_sort_acta_key, reverse=True)

        return {
            "total_cobrado": round(total_cobrado, 2),
            "total_sicoe_n3_no_revisado": round(total_nr, 2),
            "comparativo_capitulos": comparativo_sicoe,
            "por_acta": por_acta,
            "actas": actas_keys,
            "obra_por_capitulo": obra_caps,
            "_fuente": "vm_dashboard_resumen",
        }
    except Exception:
        return None


# Caché de config de niveles por contrato: es config de admin que cambia muy rara vez,
# pero se consulta decenas de veces por request (por capa, por armado de query, por KPI).
# Sin caché, cada llamada es un round-trip a Supabase (remoto) y multiplica la latencia.
# cid → (monotonic_ts, niveles_activos, roles_por_nivel_raw)
_NIVELES_ACTIVOS_CACHE: Dict[int, Tuple[float, List[int], Dict[int, int]]] = {}
_NIVELES_ACTIVOS_TTL_S = 60.0


def _invalidar_cache_niveles_contrato(contrato_id: Optional[int] = None) -> None:
    """Limpia la caché de niveles activos (al cambiar config de validación del contrato)."""
    try:
        if contrato_id is None:
            _NIVELES_ACTIVOS_CACHE.clear()
        else:
            _NIVELES_ACTIVOS_CACHE.pop(int(contrato_id), None)
    except (TypeError, ValueError):
        _NIVELES_ACTIVOS_CACHE.clear()


def _parse_roles_por_nivel_raw(raw: Any) -> Dict[int, int]:
    """Normaliza JSON/dict de roles_por_nivel → {nivel: rol_id} (solo 1–6)."""
    if isinstance(raw, str) and raw.strip():
        try:
            raw = json.loads(raw)
        except (json.JSONDecodeError, TypeError):
            return {}
    if not isinstance(raw, dict):
        return {}
    out: Dict[int, int] = {}
    for k, v in raw.items():
        try:
            nivel = int(k)
            rid = int(v)
        except (TypeError, ValueError):
            continue
        if 1 <= nivel <= 6 and rid > 0:
            out[nivel] = rid
    return out


def _roles_por_nivel_efectivo(raw: Optional[Dict[int, int]] = None) -> Dict[int, int]:
    """Defaults de plataforma + overrides del contrato (raw puede ser vacío)."""
    out = dict(DEFAULT_ROLES_POR_NIVEL)
    if raw:
        out.update(raw)
    return out


def _get_contrato_niveles_cfg(contrato_id: int) -> Tuple[List[int], Dict[int, int]]:
    """Lee niveles_activos y roles_por_nivel crudos; sin fila → ([1,2,3], {})."""
    try:
        cid = int(contrato_id)
    except (TypeError, ValueError):
        return [1, 2, 3], {}
    _now = time.monotonic()
    _hit = _NIVELES_ACTIVOS_CACHE.get(cid)
    if _hit is not None and (_now - _hit[0]) < _NIVELES_ACTIVOS_TTL_S:
        return list(_hit[1]), dict(_hit[2])
    na_default = [1, 2, 3]
    roles_raw: Dict[int, int] = {}
    try:
        res = (
            supabase.table("contrato_niveles_validacion")
            .select("niveles_activos, roles_por_nivel")
            .eq("contrato_id", cid)
            .limit(1)
            .execute()
            .data
        )
        if res and res[0] is not None:
            row = res[0]
            raw = row.get("niveles_activos")
            if isinstance(raw, str) and raw.strip():
                try:
                    raw = json.loads(raw)
                except (json.JSONDecodeError, TypeError):
                    raw = None
            if isinstance(raw, list) and raw:
                out: List[int] = []
                for x in raw:
                    try:
                        n = int(x)
                        if 1 <= n <= 6:
                            out.append(n)
                    except (TypeError, ValueError):
                        continue
                out = sorted(set(out))
                if out:
                    na_default = out
            try:
                roles_raw = _parse_roles_por_nivel_raw(row.get("roles_por_nivel"))
            except Exception:
                roles_raw = {}
    except Exception:
        # Columna roles_por_nivel aún no migrada u otro error: intentar solo niveles_activos.
        try:
            res2 = (
                supabase.table("contrato_niveles_validacion")
                .select("niveles_activos")
                .eq("contrato_id", cid)
                .limit(1)
                .execute()
                .data
            )
            if res2 and res2[0] is not None:
                raw = res2[0].get("niveles_activos")
                if isinstance(raw, str) and raw.strip():
                    try:
                        raw = json.loads(raw)
                    except (json.JSONDecodeError, TypeError):
                        raw = None
                if isinstance(raw, list) and raw:
                    out2: List[int] = []
                    for x in raw:
                        try:
                            n = int(x)
                            if 1 <= n <= 6:
                                out2.append(n)
                        except (TypeError, ValueError):
                            continue
                    out2 = sorted(set(out2))
                    if out2:
                        na_default = out2
        except Exception:
            pass
    _NIVELES_ACTIVOS_CACHE[cid] = (_now, list(na_default), dict(roles_raw))
    return list(na_default), dict(roles_raw)


def _get_niveles_activos_contrato(contrato_id: int) -> List[int]:
    """Lee `contrato_niveles_validacion.niveles_activos`; sin fila o error → [1, 2, 3].

    Cachea por contrato con TTL corto: evita repetir el round-trip a Supabase en la
    misma búsqueda (se invoca muchas veces). Usar _invalidar_cache_niveles_contrato
    cuando se modifique la config de validación del contrato.
    """
    na, _ = _get_contrato_niveles_cfg(contrato_id)
    return na


def _get_roles_por_nivel_contrato(contrato_id: int) -> Dict[int, int]:
    """Mapa efectivo nivel → rol_id (defaults + overrides del contrato)."""
    _, raw = _get_contrato_niveles_cfg(contrato_id)
    return _roles_por_nivel_efectivo(raw)


def _rol_id_para_nivel_contrato(contrato_id: int, nivel: int) -> Optional[int]:
    try:
        n = int(nivel)
    except (TypeError, ValueError):
        return None
    if n < 1 or n > 6:
        return None
    return _get_roles_por_nivel_contrato(contrato_id).get(n)


def _nivel_para_rol_id_en_contrato(contrato_id: int, rol_id: int) -> Optional[int]:
    """Nivel 1–6 asignado a este rol_id en el contrato (mapa efectivo). None si no figura."""
    try:
        rid = int(rol_id)
    except (TypeError, ValueError):
        return None
    rpm = _get_roles_por_nivel_contrato(contrato_id)
    for nivel in sorted(rpm.keys()):
        if rpm[nivel] == rid:
            return nivel
    return None


def _get_nivel_numero_maximo_contrato(contrato_id: int) -> int:
    ns = _get_niveles_activos_contrato(contrato_id)
    return max(ns) if ns else 3


def _get_nivel_maximo_contrato(contrato_id: int) -> str:
    """Campo `nivelN_estado` del nivel más alto activo (p. ej. [1,2,4] → nivel4_estado)."""
    mx = _get_nivel_numero_maximo_contrato(contrato_id)
    mx = min(6, max(1, mx))
    return f"nivel{mx}_estado"


def _sicoe_capa_alinea_dashboard_kpi(capa: dict, contrato_id: Optional[int]) -> bool:
    """
    Una capa «Aprobado» en el nivel máximo del contrato usa la misma regla que
    dashboard_resumen_sicoe_agg (solo nmax = Aprobado, sin prerrequisitos ni exigir ítem).
    """
    if contrato_id is None or not isinstance(capa, dict):
        return False
    ev = (capa.get("estado") or "").strip()
    if ev != "Aprobado":
        return False
    fld = capa.get("campo") or _capa_campo_validacion(capa)
    if not fld:
        return False
    try:
        return fld == _get_nivel_maximo_contrato(int(contrato_id))
    except (TypeError, ValueError):
        return False


def _sicoe_campo_usuario_fecha_desde_estado(campo_estado: str) -> tuple:
    base = (campo_estado or "").replace("_estado", "")
    return f"{base}_usuario_id", f"{base}_fecha"


def _matriz_estado_nivel_final_row(row: Optional[dict], contrato_id: int):
    if not row:
        return None
    fld = _get_nivel_maximo_contrato(contrato_id)
    return row.get(fld)


def _matriz_validacion_norm_estado_nivel_final(row: Optional[dict], contrato_id: int) -> str:
    return _matriz_validacion_norm_estado(_matriz_estado_nivel_final_row(row, contrato_id))


def _registro_nivel_max_aprobado(row: Optional[Dict[str, Any]], contrato_id: int) -> bool:
    if not row:
        return False
    try:
        cid = int(contrato_id)
    except (TypeError, ValueError):
        cid = 0
    campo = _get_nivel_maximo_contrato(cid) if cid else "nivel3_estado"
    return (row.get(campo) or "").strip() == "Aprobado"


def _registro_reversion_bloqueada_por_aprobacion_nivel6(
    row: Optional[Dict[str, Any]], contrato_id: int
) -> bool:
    """
    Nivel 6 = aprobación del funcionario para pago directo: con N6 activo en el contrato,
    un registro con nivel6_estado Aprobado no admite reversión (masiva ni individual).
    """
    if not row:
        return False
    try:
        cid = int(contrato_id)
    except (TypeError, ValueError):
        return False
    if 6 not in _get_niveles_activos_contrato(cid):
        return False
    return (row.get("nivel6_estado") or "").strip() == "Aprobado"


def _registro_nivel3_aprobado(row: Optional[Dict[str, Any]]) -> bool:
    """Compatibilidad: delega en el nivel máximo activo del contrato cuando la fila trae `contrato_id`."""
    if not row:
        return False
    cid = row.get("contrato_id")
    if cid is not None:
        try:
            return _registro_nivel_max_aprobado(row, int(cid))
        except (TypeError, ValueError):
            pass
    return (row.get("nivel3_estado") or "").strip() == "Aprobado"


def _sicoe_aplicar_bloqueado_si_nivel_es_maximo(contrato_id: int, nivel: int, update: dict, estado: str) -> None:
    if estado == "Aprobado" and nivel == _get_nivel_numero_maximo_contrato(contrato_id):
        update["bloqueado"] = True

# Mismo catálogo que el desplegable de validación en frontend (ETIQUETAS_VALIDACION).
SICOE_ETIQUETAS_VALIDACION = (
    "01. Ensayos de Laboratorio",
    "02. Certificados de Calidad",
    "03. Información y/o Entrega Topografía",
    "04. Entrega en obra",
    "05. Informe o Concepto Especialista",
    "06. Incluida dentro del precio",
    "07. Reportado en actas anteriores",
    "08. Pendiente por aprobación de precio",
    "09. Actividad sin concluir",
    "10. Precio no corresponde con la actividad",
    "11. Actualizar información",
    "12. Reproceso",
    "13. Actividad no ejecutada",
    "14. Relacionada con Balance de Obra",
)
SICOE_ETIQUETAS_VALIDACION_SET = frozenset(SICOE_ETIQUETAS_VALIDACION)


def _sicoe_parse_etiqueta_validacion_param(raw: Optional[str]) -> Optional[str]:
    if raw is None:
        return None
    t = str(raw).strip()
    if not t:
        return None
    if t not in SICOE_ETIQUETAS_VALIDACION_SET:
        raise HTTPException(
            status_code=422,
            detail="etiqueta_validacion no está en el catálogo de etiquetas de validación.",
        )
    return t


def _sicoe_fetch_registro_ids_etiqueta_validacion(contrato_id: int, etiqueta: str) -> Set[int]:
    """registro_id con al menos un comentario tipo validación y etiqueta exacta."""
    out: Set[int] = set()
    off = 0
    page = 1000
    while True:
        def _pg(o=off):
            return (
                supabase.table("so_registro_comentarios")
                .select("registro_id")
                .eq("contrato_id", contrato_id)
                .eq("tipo", "validacion")
                .eq("etiqueta", etiqueta)
                .range(o, o + page - 1)
                .execute()
                .data
            )

        batch = supabase_execute(_pg)
        for row in batch:
            rid = row.get("registro_id")
            if rid is not None:
                try:
                    out.add(int(rid))
                except (TypeError, ValueError):
                    pass
        if len(batch) < page:
            break
        off += page
    return out


def _sicoe_chunks_int(ids: List[int], size: int):
    for i in range(0, len(ids), size):
        yield ids[i : i + size]


def _sicoe_norm_txt(s: Optional[str]) -> str:
    if s is None:
        return ""
    import unicodedata
    t = unicodedata.normalize("NFD", str(s).strip().lower())
    return "".join(c for c in t if unicodedata.category(c) != "Mn")


def _capa_campo_validacion(capa: dict) -> Optional[str]:
    if not isinstance(capa, dict):
        return None
    campo = capa.get("campo")
    if campo in (
        "nivel1_estado",
        "nivel2_estado",
        "nivel3_estado",
        "nivel4_estado",
        "nivel5_estado",
        "nivel6_estado",
    ):
        return str(campo)
    nv = capa.get("nivel")
    if nv is not None and str(nv).strip() != "":
        try:
            n = int(nv)
            return NIVEL_VALIDACION_NUM_A_CAMPO.get(n)
        except (TypeError, ValueError):
            pass
    cid = capa.get("cargo_id")
    if cid is not None and str(cid).strip() != "":
        try:
            return CARGO_ID_NIVEL_MAP.get(int(cid))
        except (TypeError, ValueError):
            pass
    return None


def _sicoe_capa_etiqueta_panel(capx: dict) -> str:
    """Etiqueta del panel dinámico por capa: nivel (rol) o nombre de cargo (legado)."""
    if not isinstance(capx, dict):
        return "Validación"
    nv = capx.get("nivel")
    if nv is not None and str(nv).strip() != "":
        try:
            ni = int(nv)
            return NIVEL_VALIDACION_ENCABEZADO.get(ni) or f"Nivel {ni}"
        except (TypeError, ValueError):
            pass
    cid = capx.get("cargo_id")
    if cid is not None and str(cid).strip() != "":
        try:
            ci = int(cid)
            lbl = f"cargo {ci}"
            try:
                crow = supabase.table("cargos").select("nombre").eq("id", ci).single().execute().data
                if crow and crow.get("nombre"):
                    lbl = crow["nombre"]
            except Exception:
                pass
            return lbl
        except (TypeError, ValueError):
            pass
    fld = capx.get("campo") or _capa_campo_validacion(capx)
    if fld == "nivel1_estado":
        return NIVEL_VALIDACION_ENCABEZADO[1]
    if fld == "nivel2_estado":
        return NIVEL_VALIDACION_ENCABEZADO[2]
    if fld == "nivel3_estado":
        return NIVEL_VALIDACION_ENCABEZADO[3]
    if fld == "nivel4_estado":
        return NIVEL_VALIDACION_ENCABEZADO[4]
    if fld == "nivel5_estado":
        return NIVEL_VALIDACION_ENCABEZADO[5]
    if fld == "nivel6_estado":
        return NIVEL_VALIDACION_ENCABEZADO[6]
    return "Validación"


def _sicoe_nivel_num_desde_campo(campo: Optional[str]) -> Optional[int]:
    if campo == "nivel1_estado":
        return 1
    if campo == "nivel2_estado":
        return 2
    if campo == "nivel3_estado":
        return 3
    if campo == "nivel4_estado":
        return 4
    if campo == "nivel5_estado":
        return 5
    if campo == "nivel6_estado":
        return 6
    return None


def _sicoe_db_nivel_validacion_usuario(
    user_id: int, contrato_id: Optional[int] = None
) -> Optional[int]:
    """
    Nivel de validación SICOE obra: 1–6, 0 = acceso total (rol Desarrollador en mapa), None = sin validar.

    Con `contrato_id`, prioriza el mapa `roles_por_nivel` del contrato (defaults + overrides),
    de modo que p. ej. Operativo Interventoría pueda ser N1 si así se configuró.
    Sin contrato: ROL_ID_NIVEL_MAP global; si no aplica, nombre de rol; último recurso cargo_id.
    """
    try:
        uid = int(user_id)
    except (TypeError, ValueError):
        return None
    try:
        urows = supabase.table("usuarios").select("rol_id, cargo_id").eq("id", uid).limit(1).execute().data
        if not urows:
            return None
        u = urows[0]
    except Exception:
        return None

    rid_int = None
    if u.get("rol_id") is not None:
        try:
            rid_int = int(u["rol_id"])
        except (TypeError, ValueError):
            rid_int = None

    # Desarrollador: acceso total siempre (independiente del contrato).
    if rid_int is not None and ROL_ID_NIVEL_MAP.get(rid_int) == 0:
        return 0

    if contrato_id is not None and rid_int is not None:
        nivel_cfg = _nivel_para_rol_id_en_contrato(contrato_id, rid_int)
        if nivel_cfg is not None:
            return nivel_cfg
        # Rol conocido en el mapa global pero no asignado a ningún nivel de este contrato
        # (p. ej. Operativo Contratista cuando N1 quedó en Interventoría) → sin nivel aquí.
        if rid_int in ROL_ID_NIVEL_MAP:
            return ROL_ID_NIVEL_MAP[rid_int] if ROL_ID_NIVEL_MAP[rid_int] is None else None

    if rid_int is not None and rid_int in ROL_ID_NIVEL_MAP:
        return ROL_ID_NIVEL_MAP[rid_int]

    rn = ""
    if u.get("rol_id"):
        try:
            rrows = supabase.table("roles").select("nombre").eq("id", u["rol_id"]).limit(1).execute().data
            if rrows:
                rn = _sicoe_norm_txt(rrows[0].get("nombre"))
        except Exception:
            pass

    try:
        cid = int(u.get("cargo_id")) if u.get("cargo_id") is not None else None
    except (TypeError, ValueError):
        cid = None

    # Fallback por nombre de rol (legado o rol_id no listado en ROL_ID_NIVEL_MAP)
    if rn == "operativo interventoria" or ("operativo" in rn and "intervent" in rn):
        # Con contrato: si el nombre corresponde a un rol configurado, ya se resolvió arriba.
        return None
    if rn == "operativo contratista" or ("operativo" in rn and "contrat" in rn and "intervent" not in rn):
        return 1
    if "gerencial" in rn and "contrat" in rn and "intervent" not in rn:
        return 3
    if "gerencial" in rn and "intervent" in rn:
        return 5
    if "supervisor" in rn and ("externo" in rn or "entidad" in rn):
        return 6
    if rn == "contratista" or (
        "contrat" in rn
        and "intervent" not in rn
        and "gerencial" not in rn
        and "operativo" not in rn
        and "supervisor" not in rn
    ):
        return 2
    if "intervent" in rn:
        if cid in (9, 58):
            return 5
        if cid == 50:
            return 4
        return 4

    if cid is not None:
        n_cargo = _sicoe_nivel_num_desde_campo(CARGO_ID_NIVEL_MAP.get(cid))
        if n_cargo is not None:
            return n_cargo

    return None


def _require_sicoe_puede_validar_nivel(
    current_user, user_id: int, nivel: int, contrato_id: Optional[int] = None
) -> None:
    """
    Desarrollador: solo niveles 1–3 (lado contratista), cualquier contrato.
    Administrador: cualquier nivel activo si tiene «validar» en «reporte de cantidades»
    y el contrato coincide con el asignado al usuario.
    """
    if _es_desarrollador(current_user):
        if nivel < 1 or nivel > 3:
            raise HTTPException(
                status_code=403,
                detail="El desarrollador solo puede validar niveles 1 a 3 (contratista). Los niveles 4 a 6 corresponden a Interventoría.",
            )
        return
    if _es_cargo_administrador_sicoe(current_user):
        if not _cargo_permiso_validar_reporte_cantidades_user_id(user_id, contrato_id):
            raise HTTPException(
                status_code=403,
                detail="No tiene permiso de validación en «Reporte de cantidades» (matriz de accesos).",
            )
        if contrato_id is None:
            raise HTTPException(
                status_code=500,
                detail="Falta contrato_id en la verificación de permisos de administrador.",
            )
        uc = _usuario_contrato_id_por_user_id(user_id)
        if uc is None or int(uc) != int(contrato_id):
            raise HTTPException(
                status_code=403,
                detail="El administrador solo puede validar SICOE obra en el contrato asignado a su usuario.",
            )
        return
    if not _cargo_permiso_validar_reporte_cantidades_user_id(user_id, contrato_id):
        raise HTTPException(
            status_code=403,
            detail="No tiene permiso de validación en «Reporte de cantidades» (matriz de accesos).",
        )
    got = _sicoe_db_nivel_validacion_usuario(user_id, contrato_id)
    if got == 0:
        return
    if got != nivel:
        raise HTTPException(
            status_code=403,
            detail="Tu rol no autoriza validar en este nivel de SICOE obra.",
        )


def _sicoe_slot_llave_reversion(nivel: Optional[int]) -> Optional[int]:
    """Mapea nivel de validación (2–6) al slot de doble llave: 2 = costos, 3 = interventoría."""
    if nivel is None:
        return None
    try:
        n = int(nivel)
    except (TypeError, ValueError):
        return None
    if n == 2:
        return 2
    if n in (3, 4, 5, 6):
        return 3
    return None


def _require_llave_reversion_sicoe_nivel(current_user, user_id: int, nivel_arm: int) -> None:
    """
    Doble llave reversión N3: debe coincidir el slot (N2 o N3) del usuario con la llave solicitada.
    Interventoría N4/N5/N6 usa el mismo slot que N3.
    """
    if _es_desarrollador(current_user):
        return
    slot = _sicoe_slot_llave_reversion(nivel_arm)
    if slot not in (2, 3):
        raise HTTPException(status_code=403, detail="Llave de reversión no reconocida.")
    got = _sicoe_db_nivel_validacion_usuario(user_id)
    if got == 0:
        return
    got_slot = _sicoe_slot_llave_reversion(got)
    if got_slot != slot:
        raise HTTPException(
            status_code=403,
            detail="Tu rol no autoriza esta llave en SICOE obra.",
        )


def _estado_registro_eq_desde_filtro_ui(evp: str) -> str:
    """Alinea plural de la UI con el valor almacenado en so_registros."""
    p = (evp or "").strip()
    m = {
        "Aprobados": "Aprobado",
        "Pendientes": "Pendiente",
        "Rechazados": "Rechazado",
    }
    return m.get(p, p)


def _parse_validacion_capas_param(
    validacion_capas: Optional[str],
    cargo_id: Optional[int],
    estado_validacion: Optional[str],
) -> List[dict]:
    out: List[dict] = []
    if validacion_capas and str(validacion_capas).strip():
        try:
            raw = json.loads(validacion_capas)
            if isinstance(raw, list):
                for c in raw:
                    if not isinstance(c, dict):
                        continue
                    est = (c.get("estado") or "").strip()
                    if not est:
                        continue
                    fld = _capa_campo_validacion(c)
                    if fld:
                        row: dict = {"estado": est, "campo": fld}
                        if c.get("nivel") is not None:
                            try:
                                row["nivel"] = int(c["nivel"])
                            except (TypeError, ValueError):
                                pass
                        if c.get("cargo_id") is not None:
                            try:
                                row["cargo_id"] = int(c["cargo_id"])
                            except (TypeError, ValueError):
                                pass
                        out.append(row)
        except (json.JSONDecodeError, TypeError, ValueError, KeyError):
            pass
    if not out and cargo_id is not None and (estado_validacion or "").strip():
        fld = CARGO_ID_NIVEL_MAP.get(int(cargo_id))
        if fld:
            out = [{
                "cargo_id": int(cargo_id),
                "estado": str(estado_validacion).strip(),
                "campo": fld,
            }]
    return out


def _get_prereq_nivel_activo(campo_nivel: str, contrato_id: int) -> Optional[tuple]:
    """
    Devuelve el prerrequisito real según niveles activos del contrato.
    Si el nivel anterior inmediato no está activo, busca el anterior activo.
    """
    niveles_activos = _get_niveles_activos_contrato(contrato_id)
    num_map = {v: k for k, v in NIVEL_VALIDACION_NUM_A_CAMPO.items()}
    nivel_num = num_map.get(campo_nivel)
    if nivel_num is None:
        return None
    anteriores = sorted([n for n in niveles_activos if n < nivel_num], reverse=True)
    if not anteriores:
        return None
    nivel_previo = anteriores[0]
    campo_previo = NIVEL_VALIDACION_NUM_A_CAMPO.get(nivel_previo)
    if not campo_previo:
        return None
    return (campo_previo, "Aprobado")


def _sicoe_matriz_prereqs_activos_para_campo(campo_nivel: str, contrato_id: int) -> List[tuple]:
    """(campo, 'Aprobado') por cada nivel activo estrictamente menor (misma regla que matriz dashboard)."""
    na = sorted(_get_niveles_activos_contrato(contrato_id))
    n = _sicoe_nivel_num_desde_campo(campo_nivel)
    if n is None:
        return []
    out: List[tuple] = []
    for prev_n in na:
        if prev_n >= n:
            break
        prev_f = NIVEL_VALIDACION_NUM_A_CAMPO.get(prev_n)
        if prev_f:
            out.append((prev_f, "Aprobado"))
    return out


def _so_registros_q_y_capas_validacion(
    q,
    capas: List[dict],
    pk_id_val,
    tramo_v,
    costado_v,
    cap_v,
    sub_v,
    item_v,
    contrato_id: Optional[int] = None,
):
    """AND en la misma fila de so_registros: todas las capas (cargo+estado) a la vez."""
    for capa in capas:
        fld = capa.get("campo") or _capa_campo_validacion(capa)
        if not fld:
            continue
        evp = (capa.get("estado") or "").strip()
        if not evp:
            continue
        alinea_dash = _sicoe_capa_alinea_dashboard_kpi(capa, contrato_id)
        if not alinea_dash:
            if contrato_id is not None:
                try:
                    for prereq in _sicoe_matriz_prereqs_activos_para_campo(fld, int(contrato_id)):
                        q = q.eq(prereq[0], prereq[1])
                except (TypeError, ValueError):
                    pass
            else:
                prereq = CARGO_NIVEL_PRERREQUISITO.get(fld)
                if prereq:
                    q = q.eq(prereq[0], prereq[1])
        if evp in ("No Revisado", "No Revisados"):
            q = _so_reg_or_pendiente_nivel(q, fld)
            # N1: misma lógica que "cola" N2/N3: sin ítem asignado no entra a revisión de inspector
            if fld == "nivel1_estado":
                q = _so_reg_item_asignado(q)
        else:
            evq = _estado_registro_eq_desde_filtro_ui(evp)
            if alinea_dash and evp == "Aprobado":
                q = q.eq(fld, "Aprobado")
            else:
                q = q.eq(fld, evq)
        if _es_validacion_avanzada(fld) and not alinea_dash:
            q = _so_reg_item_asignado(q)
    if pk_id_val is not None:
        q = q.eq("pk_id_id", pk_id_val)
    if tramo_v:
        q = q.eq("tramo", tramo_v)
    if costado_v:
        q = _so_reg_filtro_costado(q, costado_v)
    if cap_v:
        q = q.eq("capitulo", cap_v)
    if sub_v is not None:
        q = q.eq("subcontratista_id", sub_v)
    if item_v:
        q = q.ilike("item_numero", f"%{item_v}%")
    return q


def _validacion_cualquier_nivel2_o_3(capas: List[dict]) -> bool:
    for c in capas:
        fld = c.get("campo") or _capa_campo_validacion(c)
        if fld and _es_validacion_avanzada(fld):
            return True
    return False

# Nivel 2/3: no listar cantidades en reportes borrador / sin ítem asignado a nivel reporte,
# ni registros sin item_numero (cola de validación solo sobre cantidades listas).
NIVEL_FIELD_VALIDACION_AVANZADA = (
    "nivel2_estado",
    "nivel3_estado",
    "nivel4_estado",
    "nivel5_estado",
    "nivel6_estado",
)
ESTADOS_REPORTE_EXCL_VALIDACION_AVANZADA = ('Borrador', 'Sin Asignar Ítem')


def _so_reportes_estado_valores_desde_filtro_ui(estado: Optional[str]) -> Optional[List[str]]:
    """La grilla filtra con etiquetas en plural (Aprobados, …); en BD puede haber plural o singular."""
    if estado is None or not str(estado).strip():
        return None
    s = str(estado).strip()
    plur_sing = {
        "Aprobados": ("Aprobados", "Aprobado"),
        "Pendientes": ("Pendientes", "Pendiente"),
        "Rechazados": ("Rechazados", "Rechazado"),
        "No Revisados": ("No Revisados", "No Revisado"),
    }
    if s in plur_sing:
        return list(plur_sing[s])
    sl = s.lower()
    if "sin asignar" in sl and "item" in sl.replace("í", "i"):
        return list({
            "Sin Asignar Ítem", "Sin Asignar Item", "sin asignar ítem", "SIN ASIGNAR ITEM",
        })
    return [s]


def _estado_filtro_omite_validacion_por_cargo(estado: Optional[str]) -> bool:
    """Borrador / Sin asignar ítem / Reversión: cola distinta a validación N1–N3; no combinar con filtro por cargo."""
    if estado is None or not str(estado).strip():
        return False
    if _estado_filtro_es_reversion(estado):
        return True
    sl = str(estado).strip().lower()
    if sl == "borrador":
        return True
    if "sin asignar" in sl and "item" in sl.replace("í", "i"):
        return True
    return False


def _estado_filtro_es_sin_asignar_item(estado: Optional[str]) -> bool:
    """Filtro de grilla por cabecera 'Sin Asignar Ítem' (excl. Borrador)."""
    if estado is None or not str(estado).strip():
        return False
    sl = str(estado).strip().lower()
    return "sin asignar" in sl and "item" in sl.replace("í", "i")


def _estado_filtro_es_reversion(estado: Optional[str]) -> bool:
    if estado is None or not str(estado).strip():
        return False
    sl = str(estado).strip().lower().replace("ó", "o")
    return sl == "reversion"


def _usuario_filtro_reversion_solo_interventoria(current_user) -> bool:
    """Operativo / Interventoría / Interventoría Gerencial: solo opción Reversión en filtros."""
    r = (current_user.get("rol_nombre") or "").strip().lower().replace("í", "i")
    if r == "operativo interventoria":
        return True
    if r == "interventoria":
        return True
    if "gerencial" in r and "intervent" in r:
        return True
    return False


def _sicoe_reversion_modo_filtro(estado: Optional[str], current_user) -> Optional[str]:
    """
    Modo de filtro virtual «Reversión» (no es estado de so_reportes).
    interv_primera_llave: N2 ya firmó, falta llave de interventoría.
    contratista: solicitud o doble llave en curso.
    """
    if not _estado_filtro_es_reversion(estado):
        return None
    if _usuario_filtro_reversion_solo_interventoria(current_user):
        return "interv_primera_llave"
    return "contratista"


def _so_reg_q_aplicar_filtro_reversion(q, reversion_modo: Optional[str]):
    if reversion_modo == "interv_primera_llave":
        return (
            q.not_.is_("reversion_arm_n2_usuario_id", "null")
            .is_("reversion_arm_n3_usuario_id", "null")
            .eq("bloqueado", True)
        )
    if reversion_modo == "contratista":
        return q.or_(
            "solicitud_reversion.eq.true,"
            "reversion_arm_n2_usuario_id.not.is.null,"
            "reversion_arm_n3_usuario_id.not.is.null"
        )
    return q


def _sicoe_so_reportes_q_filtro_estado_ui(q, contrato_id: int, estado: Optional[str], current_user):
    """Estado de cabecera en UI o filtro virtual Reversión (por rol)."""
    rev = _sicoe_reversion_modo_filtro(estado, current_user)
    if rev:
        ids_r = list(
            _sicoe_collect_reporte_ids_misma_linea(
                int(contrato_id), reversion_modo=rev, estado=estado
            )
        )
        if not ids_r:
            return q.eq("id", -1)
        return q.in_("id", ids_r)
    if estado and str(estado).strip():
        return _so_reportes_q_por_estado(q, estado)
    return q


def _so_reportes_q_por_estado(q, estado: Optional[str]):
    """Aplica filtro por estado de cabecera (OR entre variantes plural/singular)."""
    if _estado_filtro_es_reversion(estado):
        return q
    evs = _so_reportes_estado_valores_desde_filtro_ui(estado)
    if not evs:
        return q
    if len(evs) == 1:
        return q.eq("estado", evs[0])
    return q.in_("estado", evs)


def _es_validacion_avanzada(nivel_field: Optional[str]) -> bool:
    return nivel_field in NIVEL_FIELD_VALIDACION_AVANZADA


def _so_reg_item_asignado(q):
    """Registro con ítem asignado (no null ni cadena vacía)."""
    return q.not_.is_("item_numero", "null").neq("item_numero", "")


def _so_reg_sin_item_asignado(q):
    """Registro sin ítem (cola 'Sin Asignar Ítem' a nivel línea; alineado con UI)."""
    return q.or_('item_numero.is.null,item_numero.eq.""')


def _sicoe_registro_tiene_item_asignado(row: Optional[dict]) -> bool:
    """True si la línea tiene ítem (misma regla que la UI: trim sobre item_numero)."""
    if not row:
        return False
    return bool(str(row.get("item_numero") or "").strip())


def _sicoe_reporte_ids_con_lineas_sin_item(
    contrato_id: int,
    restrict_to: Optional[Iterable[int]] = None,
) -> set:
    """IDs de reporte con al menos una línea sin ítem (post-filtro trim; no cabecera)."""
    out: set = set()
    restrict_list: Optional[List[int]] = None
    if restrict_to is not None:
        restrict_list = sorted({int(x) for x in restrict_to if x is not None})
        if not restrict_list:
            return out

    rep_chunks: List[Optional[List[int]]]
    if restrict_list is None:
        rep_chunks = [None]
    else:
        rep_chunks = [
            restrict_list[i : i + 500]
            for i in range(0, len(restrict_list), 500)
        ]

    for rep_chunk in rep_chunks:
        off = 0
        page = 2000
        while True:
            def _page(o=off, rc=rep_chunk):
                q = supabase.table("so_registros").select("reporte_id, item_numero")\
                    .eq("contrato_id", contrato_id)
                if rc is not None:
                    q = q.in_("reporte_id", rc)
                else:
                    q = _so_reg_sin_item_asignado(q)
                return q.order("id").range(o, o + page - 1).execute().data

            batch = supabase_execute(_page) or []
            for row in batch:
                if _sicoe_registro_tiene_item_asignado(row):
                    continue
                rid = row.get("reporte_id")
                if rid is not None:
                    out.add(int(rid))
            if len(batch) < page:
                break
            off += page
    return out


def _so_reg_or_pendiente_nivel(q, nivel_field: str):
    """(campo IS NULL OR campo = 'No Revisado'). PostgREST exige comillas en valores con espacio."""
    return q.or_(f'{nivel_field}.is.null,{nivel_field}.eq."No Revisado"')


def _so_reg_filtro_costado(q, valor: Optional[str]):
    """Barra 'costado': opciones vienen de cabecera (calzada). En línea el valor suele estar en
    calzada (columna Excel CALZADA); datos antiguos pueden usar margen."""
    if valor is None:
        return q
    s = str(valor).strip()
    if not s:
        return q
    esc = s.replace('"', '""')
    return q.or_(f'calzada.eq."{esc}",margen.eq."{esc}"')


def _sicoe_parse_nodo_tokens(q: Optional[str]) -> list:
    if not q or not str(q).strip():
        return []
    return [t for t in re.split(r"[\s,;/]+", str(q).strip()) if t]


def _sicoe_norm_txt(s) -> str:
    return re.sub(r"\s+", " ", str(s or "").strip().lower())


def _sicoe_row_match_nodo_tokens(tokens: list, *vals) -> bool:
    if not tokens:
        return True
    hay = " ".join(_sicoe_norm_txt(v) for v in vals)
    for tok in tokens:
        t = _sicoe_norm_txt(tok)
        if t and t not in hay:
            return False
    return True


def _sicoe_reporte_ids_coinciden_nodo(
    contrato_id: int,
    q_nodo: str,
    reporte_ids_prev: Optional[list],
) -> Optional[set]:
    """
    None = no aplicar filtro.
    set vacío = sin coincidencias.
    set no vacío = IDs de reporte que cumplen (cabecera nodo_ini/nodo_fin y/o líneas no_inicio/no_final).
    """
    if not q_nodo or not str(q_nodo).strip():
        return None
    tokens = _sicoe_parse_nodo_tokens(q_nodo)
    if not tokens:
        return None

    def _ids_para_token(tok: str) -> set:
        s_rep: set = set()
        pat = f"%{tok}%"
        if reporte_ids_prev is not None:
            if not reporte_ids_prev:
                return set()
            for i in range(0, len(reporte_ids_prev), 200):
                chunk = reporte_ids_prev[i : i + 200]

                def _qc(c=chunk):
                    try:
                        return supabase.table("so_reportes").select("id").eq("contrato_id", contrato_id).in_("id", c).or_(
                            f"nodo_ini.ilike.{pat},nodo_fin.ilike.{pat}"
                        ).limit(50000).execute().data
                    except Exception:
                        return []

                for row in supabase_execute(_qc):
                    if row.get("id"):
                        s_rep.add(row["id"])
        else:
            try:
                def _qa():
                    return supabase.table("so_reportes").select("id").eq("contrato_id", contrato_id).or_(
                        f"nodo_ini.ilike.{pat},nodo_fin.ilike.{pat}"
                    ).limit(50000).execute().data

                for row in supabase_execute(_qa):
                    if row.get("id"):
                        s_rep.add(row["id"])
            except Exception:
                pass
        s_reg: set = set()
        if reporte_ids_prev is not None:
            if not reporte_ids_prev:
                return set()
            for i in range(0, len(reporte_ids_prev), 200):
                chunk = reporte_ids_prev[i : i + 200]

                def _rc(c=chunk):
                    try:
                        return supabase.table("so_registros").select("reporte_id, no_inicio, no_final").eq("contrato_id", contrato_id).in_("reporte_id", c).execute().data
                    except Exception:
                        return []

                for row in supabase_execute(_rc):
                    if _sicoe_row_match_nodo_tokens([tok], row.get("no_inicio"), row.get("no_final")):
                        rid = row.get("reporte_id")
                        if rid:
                            s_reg.add(rid)
        else:
            off = 0
            while True:
                def _rb(o=off):
                    try:
                        return supabase.table("so_registros").select("reporte_id, no_inicio, no_final").eq("contrato_id", contrato_id).order("id").range(o, o + 999).execute().data
                    except Exception:
                        return []

                batch = supabase_execute(_rb)
                for row in batch:
                    if _sicoe_row_match_nodo_tokens([tok], row.get("no_inicio"), row.get("no_final")):
                        rid = row.get("reporte_id")
                        if rid:
                            s_reg.add(rid)
                if len(batch) < 1000:
                    break
                off += 1000
        return s_rep | s_reg

    out: Optional[set] = None
    for tok in tokens:
        s_tok = _ids_para_token(tok)
        if out is None:
            out = s_tok
        else:
            out &= s_tok
        if not out:
            return set()
    return out


def _sicoe_reporte_ids_abs_solapa_registros(
    contrato_id: int,
    q_abs0: Optional[float],
    q_abs1: Optional[float],
    reporte_ids_prev: Optional[list],
) -> Optional[set]:
    """
    Filtro tipo Excel sobre abscisas en líneas (so_registros).

    Un registro con tramo [a, b] se incluye si se solapa con el rango solicitado [q_abs0, q_abs1]:
    a <= q_abs1 y b >= q_abs0 (con ambos límites del query opcionales).

    None = no hay filtro de abscisa.
    set() = ningún reporte cumple.
    """
    if q_abs0 is None and q_abs1 is None:
        return None
    if reporte_ids_prev is not None and len(reporte_ids_prev) == 0:
        return set()

    out: set = set()
    CHUNK = 200

    def _apply_solape(q):
        q = q.not_.is_("abs_inicio", "null").not_.is_("abs_final", "null")
        if q_abs0 is not None:
            q = q.gte("abs_final", q_abs0)
        if q_abs1 is not None:
            q = q.lte("abs_inicio", q_abs1)
        return q

    if reporte_ids_prev is not None:
        for i in range(0, len(reporte_ids_prev), CHUNK):
            chunk = reporte_ids_prev[i : i + CHUNK]

            def _page(c=chunk):
                q = supabase.table("so_registros").select("reporte_id").eq("contrato_id", contrato_id).in_("reporte_id", c)
                return _apply_solape(q).limit(50000).execute().data

            for row in supabase_execute(_page):
                rid = row.get("reporte_id")
                if rid:
                    out.add(rid)
    else:
        off = 0
        while True:
            def _page(o=off):
                q = supabase.table("so_registros").select("reporte_id").eq("contrato_id", contrato_id)
                return _apply_solape(q).order("id").range(o, o + 999).execute().data

            batch = supabase_execute(_page)
            for row in batch:
                rid = row.get("reporte_id")
                if rid:
                    out.add(rid)
            if len(batch) < 1000:
                break
            off += 1000
    return out


def _sicoe_so_registros_q_aplicar_filtro_pendiente_item_matriz(q, contrato_id: Optional[int] = None, niveles_activos: Optional[List[int]] = None):
    """
    Alineado con dashboard «PENDIENTE N{n_min}»: línea con ítem asignado y
    nivel{n_min}_estado = Pendiente (n_min = mínimo nivel activo del contrato).
    """
    q = _so_reg_item_asignado(q)
    na = sorted({int(x) for x in (niveles_activos or (_get_niveles_activos_contrato(contrato_id) if contrato_id else [1, 2, 3])) if 1 <= int(x) <= 6}) or [1, 2, 3]
    n_min = na[0]
    campo = NIVEL_VALIDACION_NUM_A_CAMPO.get(n_min)
    if campo:
        q = q.in_(campo, ["Pendiente", "pendiente", "PENDIENTE"])
    return q


def _sicoe_parse_filtros_fecha_usuario(
    ambito_fecha: Optional[str] = None,
    tipo_fecha: Optional[str] = None,
    fecha_desde: Optional[str] = None,
    fecha_hasta: Optional[str] = None,
    usuario_id: Optional[int] = None,
    usuario_accion: Optional[str] = None,
):
    amb = (ambito_fecha or "reporte").strip().lower()
    if amb not in ("reporte", "registro"):
        amb = "reporte"
    tip = (tipo_fecha or "creacion").strip().lower()
    if tip not in ("creacion", "modificacion"):
        tip = "creacion"
    fd = (fecha_desde or "").strip() or None
    fh = (fecha_hasta or "").strip() or None
    uid = None
    if usuario_id is not None:
        try:
            uid = int(usuario_id)
        except (TypeError, ValueError):
            uid = None
    uacc = (usuario_accion or "creo").strip().lower()
    if uacc not in ("creo", "edito", "valido"):
        uacc = "creo"
    tiene = bool(fd or fh or uid is not None)
    return amb, tip, fd, fh, uid, uacc, tiene


def _sicoe_fecha_hasta_iso(fecha_hasta: Optional[str]) -> Optional[str]:
    if not fecha_hasta or not str(fecha_hasta).strip():
        return None
    s = str(fecha_hasta).strip()
    if "T" in s:
        return s
    return f"{s}T23:59:59"


def _sicoe_aplicar_filtro_fecha_q(q, campo: str, fecha_desde: Optional[str], fecha_hasta: Optional[str]):
    if fecha_desde and str(fecha_desde).strip():
        q = q.gte(campo, str(fecha_desde).strip())
    fh = _sicoe_fecha_hasta_iso(fecha_hasta)
    if fh:
        q = q.lte(campo, fh)
    return q


def _sicoe_aplicar_filtro_usuario_reportes_q(q, usuario_id: Optional[int], usuario_accion: Optional[str]):
    if usuario_id is None:
        return q
    acc = (usuario_accion or "creo").strip().lower()
    if acc == "edito":
        return q.eq("modificado_por", usuario_id)
    if acc == "valido":
        return q.eq("modificado_por", usuario_id)
    return q.eq("creado_por", usuario_id)


def _sicoe_aplicar_filtro_usuario_registros_q(q, usuario_id: Optional[int], usuario_accion: Optional[str]):
    if usuario_id is None:
        return q
    acc = (usuario_accion or "creo").strip().lower()
    if acc == "edito":
        return q.eq("modificado_por_reg", usuario_id)
    if acc == "valido":
        parts = [f"nivel{i}_usuario_id.eq.{usuario_id}" for i in range(1, 7)]
        return q.or_(",".join(parts))
    return q.eq("creado_por_reg", usuario_id)


def _sicoe_so_registros_q_linea_filtros_busqueda(
    q,
    *,
    numero_registro: Optional[int] = None,
    abs_inicio: Optional[float] = None,
    abs_final: Optional[float] = None,
    cantidad_desde: Optional[float] = None,
    cantidad_hasta: Optional[float] = None,
    costo_directo_desde: Optional[float] = None,
    costo_directo_hasta: Optional[float] = None,
    capitulo: Optional[str] = None,
    capitulos: Optional[List[str]] = None,
    item: Optional[str] = None,
    items: Optional[List[str]] = None,
    items_op: Optional[str] = None,
    subcontratista_id: Optional[int] = None,
    tramo: Optional[str] = None,
    costado: Optional[str] = None,
    pk_id: Optional[int] = None,
    q_observacion: Optional[str] = None,
    semana_id: Optional[int] = None,
    acta_rpo_id: Optional[int] = None,
    acta_rpo_ids: Optional[List[int]] = None,
    reporte_id_in: Optional[List[int]] = None,
    require_item: bool = False,
    capas_v: Optional[List[dict]] = None,
    estado: Optional[str] = None,
    pendiente_item: bool = False,
    registro_id_in: Optional[List[int]] = None,
    contrato_id: Optional[int] = None,
    fecha_desde: Optional[str] = None,
    fecha_hasta: Optional[str] = None,
    tipo_fecha: Optional[str] = None,
    usuario_id: Optional[int] = None,
    usuario_accion: Optional[str] = None,
    ambito_fecha_registro: bool = True,
    reversion_modo: Optional[str] = None,
):
    """AND sobre columnas de so_registros; misma semántica que /reportes/buscar y /analisis."""
    items_eff = list(items) if items else []
    if not items_eff and item is not None and str(item).strip():
        items_eff = [str(item).strip()]
    if numero_registro is not None:
        q = q.eq("numero_registro", numero_registro)
    q = _so_reg_filtro_abs_solape(q, abs_inicio, abs_final)
    # La cantidad real de la línea vive en cantidad_total (la columna `cantidad`
    # quedó casi vacía/legada); es además la que muestra el panel. Filtrar por
    # `cantidad` no devolvía nada.
    if cantidad_desde is not None:
        q = q.gte("cantidad_total", cantidad_desde)
    if cantidad_hasta is not None:
        q = q.lte("cantidad_total", cantidad_hasta)
    if costo_directo_desde is not None:
        q = q.gte("costo_directo", costo_directo_desde)
    if costo_directo_hasta is not None:
        q = q.lte("costo_directo", costo_directo_hasta)
    caps_eff = list(capitulos) if capitulos else []
    if not caps_eff and capitulo is not None and str(capitulo).strip():
        caps_eff = [str(capitulo).strip()]
    if caps_eff:
        q = _apply_capitulos_to_so_registros_q(q, caps_eff)
    q = _apply_item_patterns_to_so_registros_q(q, items_eff, items_op)
    if subcontratista_id is not None:
        q = q.eq("subcontratista_id", subcontratista_id)
    if tramo:
        q = q.eq("tramo", tramo)
    if costado:
        q = _so_reg_filtro_costado(q, costado)
    if pk_id is not None:
        q = q.eq("pk_id_id", pk_id)
    if semana_id is not None:
        q = q.eq("semana_id", semana_id)
    # reporte_id_in tiene precedencia (p. ej. chunk de IDs ya resueltos).
    # Acta del modal: misma semántica que panel /analisis → so_registros.acta_rpo_id (línea).
    # Antes se usaba cabecera so_reportes vía scope y la grilla divergía del panel.
    if reporte_id_in is not None:
        q = q.in_("reporte_id", reporte_id_in)
    else:
        aids_eff = list(acta_rpo_ids) if acta_rpo_ids else []
        if not aids_eff and acta_rpo_id is not None:
            aids_eff = [int(acta_rpo_id)]
        if aids_eff:
            q = _apply_acta_rpo_ids_to_so_registros_q(q, aids_eff)
    if q_observacion and str(q_observacion).strip():
        q = q.ilike("observacion", f"%{str(q_observacion).strip()}%")
    if capas_v:
        q = _so_registros_q_y_capas_validacion(
            q, capas_v, pk_id, tramo, costado, capitulo, subcontratista_id, None, contrato_id
        )
    # require_item: alinea con la vista del dashboard (solo registros con ítem asignado)
    # Solo se aplica si el estado no es "sin_asignar_item" (filtro inverso explícito)
    if require_item and not _estado_filtro_es_sin_asignar_item(estado):
        q = _so_reg_item_asignado(q)
    elif _estado_filtro_es_sin_asignar_item(estado):
        q = _so_reg_sin_item_asignado(q)
    if pendiente_item:
        q = _sicoe_so_registros_q_aplicar_filtro_pendiente_item_matriz(q, contrato_id=contrato_id)
    if registro_id_in is not None:
        if len(registro_id_in) == 0:
            q = q.eq("id", -1)
        else:
            q = q.in_("id", registro_id_in)
    if ambito_fecha_registro and (fecha_desde or fecha_hasta):
        col_f = "updated_at" if (tipo_fecha or "").strip().lower() == "modificacion" else "created_at"
        q = _sicoe_aplicar_filtro_fecha_q(q, col_f, fecha_desde, fecha_hasta)
    if ambito_fecha_registro and usuario_id is not None:
        q = _sicoe_aplicar_filtro_usuario_registros_q(q, usuario_id, usuario_accion)
    if reversion_modo:
        q = _so_reg_q_aplicar_filtro_reversion(q, reversion_modo)
    return q


def _sicoe_filtrar_registros_coinciden_nodo_ui(regs: list, reporte_row: dict, q_nodo: Optional[str]) -> list:
    """Cabecera del reporte y/o líneas no_inicio/no_final (coherente con la grilla)."""
    if not q_nodo or not str(q_nodo).strip():
        return regs
    tokens = _sicoe_parse_nodo_tokens(q_nodo)
    if not tokens:
        return regs
    hdr_ok = _sicoe_row_match_nodo_tokens(tokens, reporte_row.get("nodo_ini"), reporte_row.get("nodo_fin"))
    out = []
    for reg in regs:
        if hdr_ok or _sicoe_row_match_nodo_tokens(tokens, reg.get("no_inicio"), reg.get("no_final")):
            out.append(reg)
    return out


def _sicoe_collect_reporte_ids_misma_linea(
    contrato_id: int,
    *,
    numero_registro: Optional[int] = None,
    abs_inicio: Optional[float] = None,
    abs_final: Optional[float] = None,
    cantidad_desde: Optional[float] = None,
    cantidad_hasta: Optional[float] = None,
    costo_directo_desde: Optional[float] = None,
    costo_directo_hasta: Optional[float] = None,
    capitulo: Optional[str] = None,
    capitulos: Optional[List[str]] = None,
    item: Optional[str] = None,
    items: Optional[List[str]] = None,
    items_op: Optional[str] = None,
    subcontratista_id: Optional[int] = None,
    tramo: Optional[str] = None,
    costado: Optional[str] = None,
    pk_id: Optional[int] = None,
    q_observacion: Optional[str] = None,
    semana_id: Optional[int] = None,
    acta_rpo_id: Optional[int] = None,
    acta_rpo_ids: Optional[List[int]] = None,
    reporte_ids_restrict: Optional[List[int]] = None,
    capas_v: Optional[List[dict]] = None,
    estado: Optional[str] = None,
    registro_ids_etiqueta: Optional[Set[int]] = None,
    capas_v_op: Optional[str] = None,
    pendiente_item: bool = False,
    filtro_fecha_usuario_registro: bool = False,
    fecha_desde: Optional[str] = None,
    fecha_hasta: Optional[str] = None,
    tipo_fecha: Optional[str] = None,
    usuario_id: Optional[int] = None,
    usuario_accion: Optional[str] = None,
    reversion_modo: Optional[str] = None,
) -> set:
    """
    reporte_id tales que existe al menos una fila en so_registros que cumple todos
    los criterios a la vez (AND). Evita intersectar IDs por criterios distintos, que
    incluía reportes sin ninguna línea coincidente con el panel /analisis.
    Cuando reporte_ids_restrict está presente, pagina sobre esos IDs en lugar de
    usar acta_rpo_id en la columna del registro (semántica correcta: acta del reporte).
    """
    items_eff: List[str] = list(items) if items else []
    if not items_eff and item is not None and str(item).strip():
        items_eff = [str(item).strip()]
    caps_eff: List[str] = list(capitulos) if capitulos else []
    if not caps_eff and capitulo is not None and str(capitulo).strip():
        caps_eff = [str(capitulo).strip()]
    aids_eff: List[int] = list(acta_rpo_ids) if acta_rpo_ids else []
    if not aids_eff and acta_rpo_id is not None:
        aids_eff = [int(acta_rpo_id)]
    # Acta del modal = filtro en línea (so_registros.acta_rpo_id), igual que panel /analisis.
    # No reescribir a cabecera so_reportes: eso dejaba panel con filas y grilla en 0
    # cuando el acta está en la línea y no en la cabecera del reporte.
    _reg_fu: Dict[str, Any] = {}
    if filtro_fecha_usuario_registro:
        _reg_fu = {
            "fecha_desde": fecha_desde,
            "fecha_hasta": fecha_hasta,
            "tipo_fecha": tipo_fecha,
            "usuario_id": usuario_id,
            "usuario_accion": usuario_accion,
            "ambito_fecha_registro": True,
        }
    ids: set = set()
    capas_ok = bool(capas_v) and not reversion_modo
    if (
        capas_ok
        and not _estado_filtro_omite_validacion_por_cargo(estado)
        and _parse_capas_validacion_op(capas_v_op) == "or"
        and len(capas_v or []) > 1
    ):
        merged: set = set()
        for c in capas_v or []:
            if not (str(c.get("estado") or "").strip()):
                continue
            fld = c.get("campo") or _capa_campo_validacion(c)
            if not fld:
                continue
            merged |= _sicoe_collect_reporte_ids_misma_linea(
                contrato_id,
                numero_registro=numero_registro,
                abs_inicio=abs_inicio,
                abs_final=abs_final,
                cantidad_desde=cantidad_desde,
                cantidad_hasta=cantidad_hasta,
                costo_directo_desde=costo_directo_desde,
                costo_directo_hasta=costo_directo_hasta,
                capitulos=caps_eff,
                items=items_eff,
                items_op=items_op,
                subcontratista_id=subcontratista_id,
                tramo=tramo,
                costado=costado,
                pk_id=pk_id,
                q_observacion=q_observacion,
                semana_id=semana_id,
                acta_rpo_ids=aids_eff,
                reporte_ids_restrict=reporte_ids_restrict,
                capas_v=[c],
                capas_v_op="and",
                estado=estado,
                registro_ids_etiqueta=registro_ids_etiqueta,
                pendiente_item=pendiente_item,
                filtro_fecha_usuario_registro=filtro_fecha_usuario_registro,
                fecha_desde=fecha_desde,
                fecha_hasta=fecha_hasta,
                tipo_fecha=tipo_fecha,
                usuario_id=usuario_id,
                usuario_accion=usuario_accion,
                reversion_modo=reversion_modo,
            )
        return merged

    # Sincroniza la grilla con el panel /analisis: el filtro SQL de capas se complementa
    # con la MISMA normalización de estado por nivel que aplica el panel
    # (_sicoe_registros_postfiltro_capas_norm, alineada con la matriz/dashboard). Sin esto,
    # la grilla incluía reportes con líneas que el SQL aceptaba pero el panel descartaba al
    # normalizar el estado por nivel — la grilla "traía todo" y tardaba el triple.
    _postfiltrar_capas_norm = bool(
        capas_ok and capas_v and not _estado_filtro_omite_validacion_por_cargo(estado)
    )
    # El postfiltro usa _sicoe_registro_cumple_capa_matriz: necesita item_numero + todos los
    # nivelX_estado (prerrequisitos). Si solo se trae la columna de la capa filtrada, el
    # postfiltro descarta TODAS las filas → panel con datos y grilla vacía.
    _select_ids_cols = (
        f"reporte_id,item_numero,{SICOE_SELECT_NIVELES_ESTADO}"
        if _postfiltrar_capas_norm
        else "reporte_id"
    )

    def _ids_agregar_filas(filas):
        if not filas:
            return
        if _postfiltrar_capas_norm:
            filas = _sicoe_registros_postfiltro_capas_norm(filas, capas_v, contrato_id)
        for _f in filas:
            _rid = _f.get("reporte_id")
            if _rid:
                ids.add(_rid)

    if registro_ids_etiqueta is not None:
        if not registro_ids_etiqueta:
            return set()
        reg_list = sorted(registro_ids_etiqueta)
        CHUNK_R = 200
        if reporte_ids_restrict is not None:
            CHUNK_REP = 500
            for reg_chunk in _sicoe_chunks_int(reg_list, CHUNK_R):
                rc = list(reg_chunk)
                for i in range(0, len(reporte_ids_restrict), CHUNK_REP):
                    rep_chunk = reporte_ids_restrict[i : i + CHUNK_REP]
                    rp = list(rep_chunk)

                    def _chunk_page(c=rc, rp_fix=rp):
                        q = supabase.table("so_registros").select(_select_ids_cols).eq("contrato_id", contrato_id)
                        q = _sicoe_so_registros_q_linea_filtros_busqueda(
                            q,
                            numero_registro=numero_registro,
                            abs_inicio=abs_inicio,
                            abs_final=abs_final,
                            cantidad_desde=cantidad_desde,
                            cantidad_hasta=cantidad_hasta,
                            costo_directo_desde=costo_directo_desde,
                            costo_directo_hasta=costo_directo_hasta,
                            capitulos=caps_eff,
                            items=items_eff,
                            items_op=items_op,
                            subcontratista_id=subcontratista_id,
                            tramo=tramo,
                            costado=costado,
                            pk_id=pk_id,
                            q_observacion=q_observacion,
                            semana_id=semana_id,
                            acta_rpo_ids=aids_eff,
                            reporte_id_in=rp_fix,
                            require_item=True,
                            capas_v=(capas_v if capas_ok else None),
                            estado=estado,
                            pendiente_item=pendiente_item,
                            registro_id_in=c,
                            contrato_id=contrato_id,
                            reversion_modo=reversion_modo,
                            **_reg_fu,
                        )
                        return q.limit(5000).execute().data

                    _ids_agregar_filas(supabase_execute(_chunk_page))
        else:
            for reg_chunk in _sicoe_chunks_int(reg_list, CHUNK_R):
                rc = list(reg_chunk)

                def _one_page(c=rc):
                    q = supabase.table("so_registros").select(_select_ids_cols).eq("contrato_id", contrato_id)
                    q = _sicoe_so_registros_q_linea_filtros_busqueda(
                        q,
                        numero_registro=numero_registro,
                        abs_inicio=abs_inicio,
                        abs_final=abs_final,
                        cantidad_desde=cantidad_desde,
                        cantidad_hasta=cantidad_hasta,
                        costo_directo_desde=costo_directo_desde,
                        costo_directo_hasta=costo_directo_hasta,
                        capitulos=caps_eff,
                        items=items_eff,
                        items_op=items_op,
                        subcontratista_id=subcontratista_id,
                        tramo=tramo,
                        costado=costado,
                        pk_id=pk_id,
                        q_observacion=q_observacion,
                        semana_id=semana_id,
                        acta_rpo_ids=aids_eff,
                        require_item=bool(aids_eff),
                        capas_v=(capas_v if capas_ok else None),
                        estado=estado,
                        pendiente_item=pendiente_item,
                        registro_id_in=c,
                        contrato_id=contrato_id,
                        reversion_modo=reversion_modo,
                        **_reg_fu,
                    )
                    return q.limit(5000).execute().data

                _ids_agregar_filas(supabase_execute(_one_page))
        return ids

    if reporte_ids_restrict is not None:
        # Iterar en chunks sobre los report_ids del acta; no necesita paginación ilimitada
        CHUNK = 500
        for i in range(0, len(reporte_ids_restrict), CHUNK):
            chunk = reporte_ids_restrict[i:i + CHUNK]

            def _chunk_page(c=chunk):
                q = supabase.table("so_registros").select(_select_ids_cols).eq("contrato_id", contrato_id)
                q = _sicoe_so_registros_q_linea_filtros_busqueda(
                    q,
                    numero_registro=numero_registro,
                    abs_inicio=abs_inicio,
                    abs_final=abs_final,
                    cantidad_desde=cantidad_desde,
                    cantidad_hasta=cantidad_hasta,
                    costo_directo_desde=costo_directo_desde,
                    costo_directo_hasta=costo_directo_hasta,
                    capitulos=caps_eff,
                    items=items_eff,
                    items_op=items_op,
                    subcontratista_id=subcontratista_id,
                    tramo=tramo,
                    costado=costado,
                    pk_id=pk_id,
                    q_observacion=q_observacion,
                    semana_id=semana_id,
                    acta_rpo_ids=aids_eff,
                    reporte_id_in=c,
                    # Cuando filtramos por acta del reporte, alineamos con la semántica
                    # del dashboard: solo registros con ítem asignado cuentan.
                    require_item=True,
                    capas_v=(capas_v if capas_ok else None),
                    estado=estado,
                    pendiente_item=pendiente_item,
                    contrato_id=contrato_id,
                    reversion_modo=reversion_modo,
                    **_reg_fu,
                )
                return q.limit(5000).execute().data

            _ids_agregar_filas(supabase_execute(_chunk_page))
    else:
        off = 0
        page = 1000
        max_pages = int(os.getenv("SICOE_BUSCAR_VALIDACION_MAX_PAGES", "100"))
        for _pn in range(max_pages):

            def _one_page(o=off):
                q = supabase.table("so_registros").select(_select_ids_cols).eq("contrato_id", contrato_id)
                q = _sicoe_so_registros_q_linea_filtros_busqueda(
                    q,
                    numero_registro=numero_registro,
                    abs_inicio=abs_inicio,
                    abs_final=abs_final,
                    cantidad_desde=cantidad_desde,
                    cantidad_hasta=cantidad_hasta,
                    costo_directo_desde=costo_directo_desde,
                    costo_directo_hasta=costo_directo_hasta,
                    capitulos=caps_eff,
                    items=items_eff,
                    items_op=items_op,
                    subcontratista_id=subcontratista_id,
                    tramo=tramo,
                    costado=costado,
                    pk_id=pk_id,
                    q_observacion=q_observacion,
                    semana_id=semana_id,
                    acta_rpo_ids=aids_eff,
                    # Ítem: misma regla que panel /analisis (lo imponen las capas),
                    # no el solo hecho de filtrar por Acta del modal.
                    require_item=(reversion_modo == "interv_primera_llave"),
                    capas_v=(capas_v if capas_ok else None),
                    estado=estado,
                    pendiente_item=pendiente_item,
                    contrato_id=contrato_id,
                    reversion_modo=reversion_modo,
                    **_reg_fu,
                )
                return q.order("id").range(o, o + page - 1).execute().data

            batch = supabase_execute(_one_page) or []
            _ids_agregar_filas(batch)
            if len(batch) < page:
                break
            off += page
        else:
            raise HTTPException(
                status_code=503,
                detail="El filtro devuelve demasiados registros. Acote con tramo, capítulo, PK, subcontratista, ítem, semana, acta u observación.",
            )
    # No filtrar por estado de so_reportes: la matriz dashboard y consultas en BD usan solo líneas
    # (so_registros + validación); excluir Borrador/Sin Asignar Ítem en cabecera omitía millones
    # de costo aunque nivel3_estado en línea ya estuviera Aprobado.
    return ids


def _sicoe_ocultar_costo_directo_reportes(current_user) -> bool:
    """Operativo Contratista / Interventoría no reciben montos en la grilla SICOE Obra."""
    rol = (current_user.get("rol_nombre") or "").strip().lower()
    return rol in ("operativo contratista", "operativo interventoria", "operativo interventoría")


def _filtrar_registros_validacion_por_campo(
    regs: list,
    fld: str,
    estado_validacion: Optional[str],
    reporte_row: Optional[dict] = None,
    contrato_id: Optional[int] = None,
) -> list:
    """Filtra registros por campo nivelX_estado y estado UI (coherente con matriz Validación por rol)."""
    if not regs or not fld or not (estado_validacion or "").strip():
        return regs
    capa = {"campo": fld, "estado": estado_validacion.strip()}
    if contrato_id is not None:
        try:
            cid = int(contrato_id)
        except (TypeError, ValueError):
            cid = None
    else:
        cid = None
    if cid is not None:
        return [r for r in regs if _sicoe_registro_cumple_capa_matriz(r, capa, cid)]
    ev = estado_validacion.strip()
    alinea_dash = False
    prereq = None if alinea_dash else CARGO_NIVEL_PRERREQUISITO.get(fld)
    out: List[dict] = []
    for reg in regs:
        if _es_validacion_avanzada(fld) and not alinea_dash:
            if not (reg.get("item_numero") or "").strip():
                continue
        if fld == "nivel1_estado" and ev in ("No Revisado", "No Revisados"):
            if not (reg.get("item_numero") or "").strip():
                continue
        if prereq and reg.get(prereq[0]) != prereq[1]:
            continue
        cur = reg.get(fld)
        if ev in ("No Revisado", "No Revisados"):
            if _matriz_validacion_norm_estado(cur) == "No Revisado":
                out.append(reg)
        elif _matriz_validacion_norm_estado(cur) == ev or cur == ev:
            out.append(reg)
    return out


def _filtrar_registros_validacion_sicoe(
    regs: list,
    cargo_id: Optional[int],
    estado_validacion: Optional[str],
    reporte_row: Optional[dict] = None,
) -> list:
    """Misma semántica que la búsqueda por cargo: nivel 2/3 solo si cumple prerrequisito del nivel previo."""
    if not regs or cargo_id is None or not (estado_validacion or "").strip():
        return regs
    fld = CARGO_ID_NIVEL_MAP.get(int(cargo_id))
    if not fld:
        return regs
    return _filtrar_registros_validacion_por_campo(regs, fld, estado_validacion, reporte_row)


def _parse_capas_validacion_op(val: Optional[str]) -> str:
    """AND por defecto. OR acepta variantes en español / inglés."""
    s = (str(val or "").strip().lower())
    if s in ("or", "o", "||", "any", "cualquiera"):
        return "or"
    return "and"


def _normalize_actas_filtro_list(actas_filtro_json: Optional[str], acta_rpo_legacy: Optional[int]) -> List[int]:
    """Varios RPO vía JSON `actas_filtro` o un solo `acta_rpo` (query legado)."""
    out: List[int] = []
    if actas_filtro_json and str(actas_filtro_json).strip():
        try:
            j = json.loads(actas_filtro_json)
            if isinstance(j, list):
                for x in j:
                    try:
                        n = int(x)
                        if n not in out:
                            out.append(n)
                    except (TypeError, ValueError):
                        pass
        except Exception:
            pass
    if not out and acta_rpo_legacy is not None:
        try:
            out = [int(acta_rpo_legacy)]
        except (TypeError, ValueError):
            pass
    return out


def _sicoe_resolve_acta_ids_por_rpo(contrato_id: int, rpo_list: List[int]) -> List[int]:
    if not rpo_list:
        return []
    ids: List[int] = []
    seen: Set[int] = set()
    for rpo in rpo_list:
        try:
            def _one(rv=rpo):
                rows = supabase.table("actas").select("id")\
                    .eq("contrato_id", contrato_id).eq("numero_rpo", rv).execute().data
                if not rows:
                    rows = supabase.table("actas").select("id")\
                        .eq("contrato_id", contrato_id).eq("consecutivo", rv).execute().data
                return rows
            for row in supabase_execute(_one):
                aid = row.get("id")
                if aid is not None and aid not in seen:
                    seen.add(aid)
                    ids.append(int(aid))
        except Exception:
            pass
    return ids


def _apply_capitulos_to_so_registros_q(q, capitulos: List[str]):
    if not capitulos:
        return q
    if len(capitulos) == 1:
        return q.eq("capitulo", capitulos[0])
    return q.in_("capitulo", capitulos)


def _apply_acta_rpo_ids_to_so_registros_q(q, acta_rpo_ids: List[int]):
    if not acta_rpo_ids:
        return q
    if len(acta_rpo_ids) == 1:
        return q.eq("acta_rpo_id", acta_rpo_ids[0])
    return q.in_("acta_rpo_id", acta_rpo_ids)


def _sicoe_reporte_ids_por_acta_ids(contrato_id: int, acta_rpo_ids: List[int]) -> List[int]:
    """IDs de so_reportes con acta_rpo_id en el conjunto (alcance acta vía cabecera del reporte)."""
    if not acta_rpo_ids:
        return []
    try:
        cid = int(contrato_id)
    except (TypeError, ValueError):
        return []
    aids = sorted({int(x) for x in acta_rpo_ids})
    out: List[int] = []
    seen: Set[int] = set()
    for chunk in _sicoe_chunks_int(aids, 80):
        ac = list(chunk)

        def _q(c=ac):
            return (
                supabase.table("so_reportes")
                .select("id")
                .eq("contrato_id", cid)
                .in_("acta_rpo_id", c)
                .limit(50000)
                .execute()
                .data
            )

        for row in supabase_execute(_q) or []:
            rid = row.get("id")
            if rid is None:
                continue
            try:
                ri = int(rid)
            except (TypeError, ValueError):
                continue
            if ri not in seen:
                seen.add(ri)
                out.append(ri)
    return out


def _sicoe_registros_q_filtrar_actas_scope(q, contrato_id: int, acta_rpo_ids: List[int]):
    """
    Filtra líneas por acta usando cabecera del reporte (so_reportes.acta_rpo_id).
    Muchos contratos no replican acta_rpo_id en cada so_registros; filtrar solo la columna
    de línea deja la cola de validación vacía aunque haya cantidades pendientes.

    Para totales del panel /analisis usar _sicoe_registros_q_filtrar_actas_linea (acta_rpo_id
    en so_registros), alineado con validación SQL del usuario.
    """
    if not acta_rpo_ids:
        return q
    rep_ids = _sicoe_reporte_ids_por_acta_ids(contrato_id, acta_rpo_ids)
    if not rep_ids:
        return q.eq("id", -1)
    if len(rep_ids) == 1:
        return q.eq("reporte_id", rep_ids[0])
    return q.in_("reporte_id", rep_ids)


def _sicoe_registros_q_filtrar_actas_linea(q, acta_rpo_ids: List[int]):
    """Filtra por so_registros.acta_rpo_id (una fila = un registro, sin ampliar por cabecera)."""
    if not acta_rpo_ids:
        return q
    aids = sorted({int(x) for x in acta_rpo_ids})
    if len(aids) == 1:
        return q.eq("acta_rpo_id", aids[0])
    return q.in_("acta_rpo_id", aids)


def _sicoe_analisis_aplicar_filtro_actas(
    q,
    contrato_id: int,
    acta_rpo_ids: List[int],
    *,
    mapa_calor: bool,
):
    """
    Panel /analisis (KPI): filtra por acta en la *línea* (totales alineados a SQL de validación).
    Mapa de calor: filtra por acta en la *cabecera* del reporte (mismo alcance que la grilla
    y que la vista de detalle, donde las coords GPS suelen vivir en so_reportes).
    """
    if not acta_rpo_ids:
        return q
    if mapa_calor:
        return _sicoe_registros_q_filtrar_actas_scope(q, int(contrato_id), acta_rpo_ids)
    return _sicoe_registros_q_filtrar_actas_linea(q, acta_rpo_ids)


def _normalize_items_filtro_list(items_filtro_json: Optional[str], item_legacy: Optional[str]) -> List[str]:
    """Varios ítems vía JSON `items_filtro` o un solo `item` (query legado). Sin duplicados, orden estable."""
    out: List[str] = []
    if items_filtro_json and str(items_filtro_json).strip():
        try:
            j = json.loads(items_filtro_json)
            if isinstance(j, list):
                out = [str(x).strip() for x in j if x is not None and str(x).strip()]
        except Exception:
            pass
    if not out and item_legacy is not None and str(item_legacy).strip():
        out = [str(item_legacy).strip()]
    seen: Set[str] = set()
    deduped: List[str] = []
    for x in out:
        if x not in seen:
            seen.add(x)
            deduped.append(x)
    return deduped


def _item_numero_filter_variants(item: str) -> List[str]:
    """Variantes con/sin punto final (p. ej. 1.02 vs 1.02.) para igualdad exacta."""
    it = (item or "").strip()
    if not it:
        return []
    out: List[str] = [it]
    if it.endswith("."):
        bare = it.rstrip(".")
        if bare and bare not in out:
            out.append(bare)
    else:
        dotted = it + "."
        if dotted not in out:
            out.append(dotted)
    return out


def _apply_item_patterns_to_so_registros_q(q, items: List[str], items_op: Optional[str] = None):
    """
    Un ítem: igualdad exacta (variantes 1.02 / 1.02.) para no mezclar 21.02 con 1.02.
    Varios ítems: ilike %pat% por patrón; Y (todas) u O (cualquiera).
    """
    if not items:
        return q
    if len(items) == 1:
        variants = _item_numero_filter_variants(items[0])
        if not variants:
            return q
        if len(variants) == 1:
            return q.eq("item_numero", variants[0])
        return q.in_("item_numero", variants)
    op = _parse_capas_validacion_op(items_op)
    if op == "or":
        parts = [f"item_numero.ilike.%{it}%" for it in items]
        try:
            return q.or_(",".join(parts))
        except Exception:
            pass
    for it in items:
        q = q.ilike("item_numero", f"%{it}%")
    return q


def _registro_cumple_capa_validacion_sicoe(
    reg: dict,
    capa: dict,
    reporte_row: Optional[dict] = None,
    contrato_id: Optional[int] = None,
) -> bool:
    fld = capa.get("campo") or _capa_campo_validacion(capa)
    if not fld or not (str(capa.get("estado") or "").strip()):
        return False
    return bool(
        _filtrar_registros_validacion_por_campo(
            [reg], fld, capa.get("estado"), reporte_row, contrato_id
        )
    )


def _filtrar_registros_validacion_capas_sicoe(
    regs: list,
    capas: List[dict],
    reporte_row: Optional[dict] = None,
    op: str = "and",
    contrato_id: Optional[int] = None,
) -> list:
    """AND: todas las capas (legado). OR: basta que el registro cumpla una capa cualquiera."""
    if not capas:
        return regs
    o = _parse_capas_validacion_op(op)
    if o == "or" and len(capas) > 1:
        return [
            reg for reg in regs
            if any(
                _registro_cumple_capa_validacion_sicoe(reg, c, reporte_row, contrato_id)
                for c in capas
            )
        ]
    out = regs
    for c in capas:
        fld = c.get("campo") or _capa_campo_validacion(c)
        if not fld:
            continue
        out = _filtrar_registros_validacion_por_campo(
            out, fld, c.get("estado"), reporte_row, contrato_id
        )
    return out


