@app.post("/frase-del-dia")
def frase_del_dia(body: dict, current_user=Depends(get_current_user)):
    from frase_del_dia_sources import (
        TIPOS_CONTENIDO_DIA,
        _pool_local_aleatoria,
        frase_desde_anthropic,
        frase_dia_espanol,
    )

    def _fallback_min(tipo: str = "reflexion"):
        return {
            "frase": "El avance de hoy construye el resultado de mañana.",
            "autor": "Aforismo de obra",
            "tipo": tipo if tipo in TIPOS_CONTENIDO_DIA else "reflexion",
        }

    tipo_req = (body or {}).get("tipo")
    if tipo_req not in TIPOS_CONTENIDO_DIA:
        import random
        tipo_req = random.choice(list(TIPOS_CONTENIDO_DIA))

    try:
        f = frase_desde_anthropic(tipo_req)
        if f and f.get("frase"):
            return f
    except Exception as e:
        print(f"WARNING /frase-del-dia anthropic: {e}", flush=True)

    if tipo_req == "reflexion":
        try:
            f = frase_dia_espanol()
            if f and f.get("frase"):
                f["tipo"] = f.get("tipo") or "reflexion"
                if f.get("tipo") in ("motivadora", "reflexiva", "bíblica"):
                    f["tipo"] = "reflexion"
                return f
        except Exception as e:
            print(f"WARNING /frase-del-dia: {e}", flush=True)

    p = _pool_local_aleatoria()
    if p and p.get("frase"):
        p["tipo"] = tipo_req
        return p
    return _fallback_min(tipo_req)


_SLOW_REQUEST_MS = int(os.getenv("CLARACORE_SLOW_REQUEST_MS", "8000"))


@app.middleware("http")
async def registrar_respuesta_lenta(request: Request, call_next):
    import time
    t0 = time.perf_counter()
    response = await call_next(request)
    ms = int((time.perf_counter() - t0) * 1000)
    # No escribir en `logs` por /healthz lento: en incidentes eso añade carga a la misma BD.
    if ms >= _SLOW_REQUEST_MS and request.url.path != "/healthz":
        try:
            registrar_log_sistema(
                "WARNING",
                request.url.path,
                request.method,
                {"tipo": "respuesta_lenta", "duracion_ms": ms},
                None,
                resultado="ok",
                duracion_ms=ms,
            )
        except Exception:
            pass
    return response


# Debe ir después de todos los @app.middleware("http") para quedar como capa externa y que
# todas las respuestas (incl. cortocircuitos 403) lleven cabeceras CORS.
app.add_middleware(
    CORSMiddleware,
    allow_origins=_cors_origins,
    allow_origin_regex=r"^https://([a-z0-9-]+\.)*claracore\.co$|^https?://(localhost|127\.0\.0\.1)(:\d+)?$",
    allow_methods=["*"],
    allow_headers=["*"],
    allow_credentials=True,
)


@app.middleware("http")
async def cors_preflight_temprano(request: Request, call_next):
    """
    Capa más externa: responde OPTIONS preflight antes del enrutador.

    En Azure (gunicorn + muchas rutas bajo /informes) algunas peticiones OPTIONS devolvían
    500 sin cabeceras CORS; el navegador lo reporta como «blocked by CORS policy» y el
    módulo Informes no carga datos. Este atajo evita que el preflight llegue al router.
    """
    if request.method != "OPTIONS":
        return await call_next(request)
    origin = request.headers.get("origin")
    if not origin or not request.headers.get("access-control-request-method"):
        return await call_next(request)
    if origin not in _cors_origins and not _CORS_ORIGIN_REGEX_HANDLER.match(origin):
        return await call_next(request)
    req_hdrs = (request.headers.get("access-control-request-headers") or "").strip()
    allow_hdrs = req_hdrs if req_hdrs else "*"
    return Response(
        status_code=200,
        headers={
            "Access-Control-Allow-Origin": origin,
            "Access-Control-Allow-Credentials": "true",
            "Access-Control-Allow-Methods": "DELETE, GET, HEAD, OPTIONS, PATCH, POST, PUT",
            "Access-Control-Allow-Headers": allow_hdrs,
            "Access-Control-Max-Age": "600",
            "Vary": "Origin",
        },
    )


