@app.post("/admin/contratos/{contrato_id}/pk-ids/eliminar-sin-uso")
def admin_eliminar_pk_ids_sin_uso(
    contrato_id: int,
    current_user=Depends(get_current_user),
):
    """Elimina filas del maestro sin vínculos SICOE ni Presupuesto."""
    _require_admin_contratos_pk_maestro(current_user)

    def _contrato():
        return supabase.table("contratos").select("id, numero").eq("id", contrato_id).limit(1).execute().data

    crows = supabase_execute(_contrato)
    if not crows:
        raise HTTPException(status_code=404, detail="Contrato no encontrado")

    bundle = _pk_ids_panorama_bundle(contrato_id)
    eliminables = [f for f in bundle["pano"].get("filas") or [] if f.get("eliminable") and f.get("maestro_id")]
    if not eliminables:
        return {
            "ok": True,
            "contrato_id": contrato_id,
            "eliminados": 0,
            "bloqueados_en_uso": sum(1 for f in bundle["pano"].get("filas") or [] if f.get("en_uso")),
            "mensaje": "No hay PK eliminables (todos tienen registros SICOE o Presupuesto).",
        }

    ids = [int(f["maestro_id"]) for f in eliminables]
    eliminados = 0
    for db_id in ids:
        def _del(i=db_id):
            return (
                supabase.table("pk_ids")
                .delete()
                .eq("id", i)
                .eq("contrato_id", contrato_id)
                .execute()
            )

        try:
            supabase_execute(_del)
            eliminados += 1
        except Exception:
            pass

    _sicoe_catalogo_cache_invalidate_pk_ids(contrato_id)

    try:
        u_log = _audit_user_contrato(current_user, contrato_id)
        registrar_log(
            u_log,
            "EDITAR",
            "ADMIN",
            "contrato_pk_ids",
            str(contrato_id),
            {"accion": "eliminar_sin_uso", "eliminados": eliminados, "ids": ids[:200]},
        )
    except Exception:
        pass

    return {
        "ok": True,
        "contrato_id": contrato_id,
        "eliminados": eliminados,
        "pk_eliminados": [f.get("pk_id") for f in eliminables[:200]],
        "bloqueados_en_uso": sum(1 for f in bundle["pano"].get("filas") or [] if f.get("en_uso")),
        "total_despues": _count_pk_ids_maestro_contrato_simple(contrato_id),
    }


@app.delete("/admin/contratos/{contrato_id}/pk-ids/{pk_maestro_id}")
def admin_eliminar_pk_id(
    contrato_id: int,
    pk_maestro_id: int,
    current_user=Depends(get_current_user),
):
    """Elimina un PK del maestro si no tiene vínculos SICOE ni Presupuesto."""
    _require_admin_contratos_pk_maestro(current_user)

    def _row():
        return (
            supabase.table("pk_ids")
            .select("id, pk_id")
            .eq("id", pk_maestro_id)
            .eq("contrato_id", contrato_id)
            .limit(1)
            .execute()
            .data
        )

    rows = supabase_execute(_row) or []
    if not rows:
        raise HTTPException(status_code=404, detail="PK no encontrado en el maestro del contrato.")

    row = rows[0]
    code = str(row.get("pk_id") or "").strip()
    sicoe = _pk_ids_sicoe_refs_por_db_id(contrato_id).get(int(pk_maestro_id)) or {}
    ppto = _pk_ids_presupuesto_refs_por_codigo(contrato_id).get(code) or {}
    if int(sicoe.get("total") or 0) > 0 or int(ppto.get("total") or 0) > 0:
        raise HTTPException(
            status_code=409,
            detail=(
                f"No se puede eliminar PK {code}: "
                f"{sicoe.get('total', 0)} registro(s) SICOE · "
                f"{ppto.get('total', 0)} ítem(s) Presupuesto."
            ),
        )

    def _del():
        return (
            supabase.table("pk_ids")
            .delete()
            .eq("id", pk_maestro_id)
            .eq("contrato_id", contrato_id)
            .execute()
        )

    supabase_execute(_del)
    _sicoe_catalogo_cache_invalidate_pk_ids(contrato_id)
    return {"ok": True, "contrato_id": contrato_id, "pk_id": code, "maestro_id": pk_maestro_id}


@app.post("/admin/contratos/{contrato_id}/pk-ids/importar-csv")
async def admin_importar_csv_pk_ids(
    contrato_id: int,
    modo: str = Form(...),
    archivo: UploadFile = File(...),
    current_user=Depends(get_current_user),
):
    """
    Carga maestro PK-ID desde CSV.
    modo: 'agregar' | 'sincronizar' | 'reemplazar'
    """
    _require_admin_contratos_pk_maestro(current_user)
    modo_n = (modo or "").strip().lower()
    if modo_n not in ("agregar", "sincronizar", "reemplazar"):
        raise HTTPException(status_code=400, detail="modo debe ser 'agregar', 'sincronizar' o 'reemplazar'.")

    def _contrato():
        return supabase.table("contratos").select("id, numero").eq("id", contrato_id).limit(1).execute().data

    crows = supabase_execute(_contrato)
    if not crows:
        raise HTTPException(status_code=404, detail="Contrato no encontrado")

    raw = (await archivo.read()).decode("utf-8-sig", errors="replace")
    payloads, info = parse_and_build_payloads(contrato_id, raw)
    if payloads is None:
        raise HTTPException(
            status_code=400,
            detail=info.get("error") or "El archivo no cumple la estructura esperada del maestro PK-ID.",
        )

    total_antes = _count_pk_ids_maestro_contrato_simple(contrato_id)
    insertados = 0
    actualizados = 0
    omitidos_existentes = 0
    eliminados = 0

    if modo_n == "reemplazar":
        refs = _pk_ids_referenciados_en_obra(contrato_id)
        if refs > 0:
            raise HTTPException(
                status_code=409,
                detail=(
                    f"No se puede reemplazar el maestro: hay {refs} reporte(s)/registro(s) SICOE "
                    "vinculados a PK del catálogo actual. Use Sincronizar para actualizar datos del CSV "
                    "sin borrar el catálogo, o Agregar solo para PK nuevos."
                ),
            )

        def _del():
            return supabase.table("pk_ids").delete().eq("contrato_id", contrato_id).execute()

        supabase_execute(_del)
        eliminados = total_antes
        _insertar_pk_ids_chunks(payloads)
        insertados = len(payloads)
    elif modo_n == "sincronizar":
        insertados, actualizados = _sincronizar_pk_ids_desde_csv(contrato_id, payloads)
    else:
        existentes = _pk_ids_existentes_por_codigo(contrato_id)
        nuevos = [p for p in payloads if str(p.get("pk_id") or "").strip() not in existentes]
        omitidos_existentes = len(payloads) - len(nuevos)
        if nuevos:
            _insertar_pk_ids_chunks(nuevos)
        insertados = len(nuevos)

    _sicoe_catalogo_cache_invalidate_pk_ids(contrato_id)
    total_despues = _count_pk_ids_maestro_contrato_simple(contrato_id)

    try:
        u_log = _audit_user_contrato(current_user, contrato_id)
        registrar_log(
            u_log,
            "EDITAR",
            "ADMIN",
            "contrato_pk_ids",
            str(contrato_id),
            {
                "modo": modo_n,
                "archivo": archivo.filename or "",
                "insertados": insertados,
                "actualizados": actualizados,
                "omitidos_existentes": omitidos_existentes,
                "eliminados_previos": eliminados,
                "total_antes": total_antes,
                "total_despues": total_despues,
                "pk_unicos_archivo": info.get("pk_unicos"),
            },
        )
    except Exception:
        pass

    return {
        "ok": True,
        "modo": modo_n,
        "contrato_id": contrato_id,
        "insertados": insertados,
        "actualizados": actualizados,
        "omitidos_existentes": omitidos_existentes,
        "eliminados_previos": eliminados,
        "total_antes": total_antes,
        "total_despues": total_despues,
        "pk_unicos_archivo": info.get("pk_unicos"),
        "duplicados_capa_en_archivo": info.get("duplicados_capa_en_archivo"),
        "filas_sin_capa": info.get("filas_sin_capa"),
    }


@app.get("/contratos/{contrato_id}/plano-geojson")
def obtener_contrato_plano_geojson(contrato_id: int):
    """Solo plano + centro. Usar desde el cliente con caché para no repetir descargas de JSON enormes."""
    r = (
        supabase.table("contratos")
        .select("plano_geojson, centro_lat, centro_lng")
        .eq("id", contrato_id)
        .limit(1)
        .execute()
    )
    if not r.data:
        raise HTTPException(status_code=404, detail="Contrato no encontrado")
    row = r.data[0]
    return {
        "plano_geojson": row.get("plano_geojson"),
        "centro_lat": row.get("centro_lat"),
        "centro_lng": row.get("centro_lng"),
    }


@app.get("/contratos/{contrato_id}")
def obtener_contrato(contrato_id: int, include_plano: bool = Query(False)):
    """
    Por defecto **no** incluye `plano_geojson` (payload muy pesado). El mapa y módulos afines deben usar
    `GET /contratos/{id}/plano-geojson` (con caché en cliente) o `?include_plano=1` (p. ej. panel Admin al editar).
    """
    sel = _CONTRATOS_SELECT_DETALLE if include_plano else _CONTRATOS_SELECT_DETALLE_SIN_PLANO
    r = supabase.table("contratos").select(sel).eq("id", contrato_id).limit(1).execute()
    row = r.data[0] if r.data else None
    if not row:
        raise HTTPException(status_code=404, detail="Contrato no encontrado")
    row["export_palette"] = _export_palette_desde_contrato(row)
    return row

@app.post("/auth/login")
def login(request: Request, body: LoginRequest):
    ip = _client_ip(request)
    result = supabase.table("usuarios").select("*").eq("email", body.email).execute()
    if not result.data:
        registrar_log(
            {"nombre": "", "email": body.email},
            "LOGIN_FAIL", "AUTH", None, None,
            {"motivo": "usuario_no_encontrado", "email": body.email},
            resultado="fallido",
            ip=ip,
            severidad="WARNING",
        )
        _track_login_failure_alert(body.email, ip)
        raise HTTPException(status_code=401, detail="Usuario no encontrado")
    usuario = result.data[0]
    if not verify_password(body.password, usuario["password_hash"]):
        registrar_log(
            {"sub": str(usuario["id"]), "nombre": usuario.get("nombre", ""), "email": body.email,
             "cargo_nombre": "", "contrato_id": usuario.get("contrato_id")},
            "LOGIN_FAIL", "AUTH", "usuario", str(usuario["id"]),
            {"motivo": "password_incorrecto"},
            resultado="fallido",
            ip=ip,
            severidad="WARNING",
        )
        _track_login_failure_alert(body.email, ip)
        raise HTTPException(status_code=401, detail="Contraseña incorrecta")
    if usuario.get("estado") == "pendiente":
        registrar_log(
            {"sub": str(usuario["id"]), "nombre": usuario.get("nombre", ""), "email": body.email,
             "contrato_id": usuario.get("contrato_id")},
            "LOGIN_FAIL", "AUTH", "usuario", str(usuario["id"]),
            {"motivo": "cuenta_pendiente"},
            resultado="denegado",
            ip=ip,
            severidad="WARNING",
        )
        raise HTTPException(status_code=403, detail="Tu cuenta está pendiente de aprobación")
    if usuario.get("estado") == "rechazado":
        registrar_log(
            {"sub": str(usuario["id"]), "nombre": usuario.get("nombre", ""), "email": body.email},
            "LOGIN_FAIL", "AUTH", "usuario", str(usuario["id"]),
            {"motivo": "cuenta_rechazada"},
            resultado="denegado",
            ip=ip,
            severidad="WARNING",
        )
        raise HTTPException(status_code=403, detail="Tu cuenta fue rechazada")

    cargo_nombre = None
    if usuario.get("cargo_id"):
        r = supabase.table("cargos").select("nombre").eq("id", usuario["cargo_id"]).execute()
        if r.data: cargo_nombre = r.data[0]["nombre"]

    rol_nombre = None
    if usuario.get("rol_id"):
        r = supabase.table("roles").select("nombre").eq("id", usuario["rol_id"]).execute()
        if r.data: rol_nombre = r.data[0]["nombre"]

    contrato_numero = None
    logo_contratista = None
    logo_interventoria = None
    if usuario.get("contrato_id"):
        r = supabase.table("contratos").select("numero, logo_contratista, logo_interventoria").eq("id", usuario["contrato_id"]).execute()
        if r.data:
            contrato_numero = r.data[0]["numero"]
            logo_contratista = r.data[0].get("logo_contratista")
            logo_interventoria = r.data[0].get("logo_interventoria")

    nombre_completo = f"{usuario.get('nombre','')} {usuario.get('apellidos','')}".strip()
    token = create_token({
        "sub": str(usuario["id"]),
        "email": usuario["email"],
        "nombre": nombre_completo or usuario.get("nombre") or "",
        "cargo_nombre": cargo_nombre or "",
        "rol_nombre": rol_nombre or "",
        "contrato_id": usuario.get("contrato_id"),
        "contrato_numero": contrato_numero or "",
    })

    # Cargar permisos del cargo para control de acceso en el panel
    permisos = []
    funciones_rows = []
    if usuario.get("cargo_id"):
        permisos_raw = _permisos_rows_para_cargo(
            int(usuario["cargo_id"]),
            int(usuario["contrato_id"]) if usuario.get("contrato_id") is not None else None,
        )
        funciones_rows = supabase.table("funciones").select("id, nombre").execute().data
        funciones_map = {f["id"]: f["nombre"] for f in funciones_rows}
        permisos = [{**p, "funcion_nombre": funciones_map.get(p["funcion_id"], "")} for p in permisos_raw]
    # Desarrollador: acceso total (sin depender de la matriz por función).
    es_dev_login = (
        (cargo_nombre or "").strip().lower() == "desarrollador"
        or (rol_nombre or "").strip().lower() == "desarrollador"
    )
    if es_dev_login:
        # Asegura «Seguimiento» (y demás requeridas) en `funciones` para filas sintéticas.
        try:
            funciones_rows = _ensure_funciones_requeridas()
        except Exception:
            if not funciones_rows:
                try:
                    funciones_rows = supabase.table("funciones").select("id, nombre").execute().data or []
                except Exception:
                    funciones_rows = []
        permisos = _permisos_desarrollador_acceso_total(
            permisos, funciones_rows, usuario.get("cargo_id")
        )
    # C3: Subcontratista sin subcontratista asignado → sin acceso
    if cargo_nombre and cargo_nombre.lower() == 'subcontratista' and not usuario.get('subcontratista_id'):
        permisos = []
    # Contador: solo módulo Contabilidad (sin módulos de obra)
    if cargo_nombre and cargo_nombre.strip().lower() == 'contador':
        permisos = [
            p for p in (permisos or [])
            if (p.get("funcion_nombre") or "").strip().lower() == "contabilidad"
        ]

    registrar_log(
        {"sub": str(usuario["id"]), "nombre": nombre_completo or usuario.get("nombre", ""),
         "cargo_nombre": cargo_nombre, "contrato_id": usuario.get("contrato_id"),
         "contrato_numero": contrato_numero, "rol_nombre": rol_nombre},
        "LOGIN", "AUTH", "usuario", str(usuario["id"]),
        {"email": usuario["email"], "cargo": cargo_nombre, "contrato": contrato_numero},
        ip=ip,
        rol_nombre=rol_nombre,
    )

    return {
        "access_token": token,
        "token_type": "bearer",
        "usuario": {
            "id": usuario["id"],
            "nombre": usuario["nombre"],
            "apellidos": usuario.get("apellidos"),
            "email": usuario["email"],
            "cargo_id": usuario.get("cargo_id"),
            "cargo_nombre": cargo_nombre,
            "rol_id": usuario.get("rol_id"),
            "rol_nombre": rol_nombre,
            "contrato_id": usuario.get("contrato_id"),
            "contrato_numero": contrato_numero,
            "logo_contratista": logo_contratista,
            "logo_interventoria": logo_interventoria,
            "estado": usuario.get("estado"),
            "activo": usuario.get("activo"),
            "subcontratista_id": usuario.get("subcontratista_id"),
            "permisos": permisos,
            "fecha_nacimiento": usuario.get("fecha_nacimiento"),
            "foto_perfil_url": usuario.get("foto_perfil_url"),
            "firma_imagen_url": usuario.get("firma_imagen_url"),
            "politicas_aceptadas": usuario.get("politicas_aceptadas") is True,
            "politicas_fecha": usuario.get("politicas_fecha"),
            "politicas_version": usuario.get("politicas_version"),
            "politicas_ip": usuario.get("politicas_ip"),
        }
    }

def _ids_cargo_por_nombre(nombre_cargo: str) -> List[int]:
    """IDs de cargos cuyo nombre coincide (case-insensitive)."""
    target = (nombre_cargo or "").strip().lower()
    if not target:
        return []
    try:
        rows = supabase.table("cargos").select("id, nombre").execute().data or []
        return [
            int(r["id"])
            for r in rows
            if r.get("id") is not None
            and ((r.get("nombre") or "").strip().lower() == target)
        ]
    except Exception:
        return []


def _usuarios_activos_por_cargos(cargo_ids: List[int]) -> List[dict]:
    """Usuarios activos con los cargos dados y estado Aprobado (notif. automáticas)."""
    if not cargo_ids:
        return []
    try:
        rows = (
            supabase.table("usuarios")
            .select("id, cargo_id, contrato_id, activo, estado")
            .in_("cargo_id", cargo_ids)
            .eq("activo", True)
            .eq("estado", "aprobado")
            .execute()
            .data
            or []
        )
        return filtrar_usuarios_para_notificaciones_automaticas(rows)
    except Exception:
        return []


def _destinatarios_notif_nuevo_registro(contrato_id: Optional[int]) -> List[int]:
    """
    Desarrolladores (todos) + Administradores del contrato del registrado.
    Sin contrato: solo Desarrolladores.
    """
    dest: Set[int] = set()
    for u in _usuarios_activos_por_cargos(_ids_cargo_por_nombre("desarrollador")):
        try:
            dest.add(int(u["id"]))
        except (TypeError, ValueError, KeyError):
            pass
    if contrato_id is not None:
        try:
            cid = int(contrato_id)
        except (TypeError, ValueError):
            cid = None
        if cid is not None:
            for u in _usuarios_activos_por_cargos(_ids_cargo_por_nombre("administrador")):
                try:
                    if u.get("contrato_id") is not None and int(u["contrato_id"]) == cid:
                        dest.add(int(u["id"]))
                except (TypeError, ValueError, KeyError):
                    pass
                # También administradores vinculados vía usuario_contratos
            try:
                admin_ids = [
                    int(u["id"])
                    for u in _usuarios_activos_por_cargos(_ids_cargo_por_nombre("administrador"))
                    if u.get("id") is not None
                ]
                if admin_ids:
                    uc = (
                        supabase.table("usuario_contratos")
                        .select("usuario_id")
                        .eq("contrato_id", cid)
                        .in_("usuario_id", admin_ids)
                        .execute()
                        .data
                        or []
                    )
                    for row in uc:
                        try:
                            dest.add(int(row["usuario_id"]))
                        except (TypeError, ValueError, KeyError):
                            pass
            except Exception:
                pass
    return sorted(dest)


