def _destinatarios_resumen_jornada(contrato_id: Optional[int]) -> List[int]:
    """
    Legacy (pruebas temp): Desarrolladores (todos) +
    Contratista Gerencial vinculado al contrato (por rol, no por permiso admin).
    Los correos diarios apertura/cierre ya no se programan; el informe semanal
    usa `_destinatarios_informe_validacion_dashboard`.
    """
    dest: Set[int] = set()
    for u in _usuarios_activos_por_cargos(_ids_cargo_por_nombre("desarrollador")):
        try:
            dest.add(int(u["id"]))
        except (TypeError, ValueError, KeyError):
            pass
    if contrato_id is None:
        return sorted(dest)
    try:
        cid = int(contrato_id)
    except (TypeError, ValueError):
        return sorted(dest)
    cg_rol_ids = _ids_rol_por_nombre("contratista gerencial")
    for u in _usuarios_activos_por_roles(cg_rol_ids):
        try:
            uid = int(u["id"])
        except (TypeError, ValueError, KeyError):
            continue
        if _usuario_vinculado_a_contrato(uid, cid):
            dest.add(uid)
    return sorted(dest)


def _ids_roles_excluidos_informe_validacion() -> Set[int]:
    """IDs de rol Operativo Gerencial / Contratista Gerencial (excluidos del informe)."""
    from notificaciones_email_config import ROLES_EXCLUIDOS_INFORME_VALIDACION

    out: Set[int] = set()
    targets = tuple(ROLES_EXCLUIDOS_INFORME_VALIDACION)
    # Coincidencia exacta por helper existente
    for nombre in targets:
        for rid in _ids_rol_por_nombre(nombre):
            out.add(int(rid))
    # También por substring (p. ej. variaciones de nombre en BD)
    try:
        rows = supabase.table("roles").select("id, nombre").execute().data or []
        for r in rows:
            nom = (r.get("nombre") or "").strip().lower()
            if any(t in nom for t in targets):
                if r.get("id") is not None:
                    out.add(int(r["id"]))
    except Exception:
        pass
    return out


def _usuario_es_rol_excluido_informe_validacion(user_id: int) -> bool:
    """True si el usuario tiene rol Operativo/Contratista Gerencial."""
    try:
        uid = int(user_id)
    except (TypeError, ValueError):
        return False
    excluidos = _ids_roles_excluidos_informe_validacion()
    if not excluidos:
        return False
    try:
        rows = (
            supabase.table("usuarios")
            .select("id, rol_id")
            .eq("id", uid)
            .limit(1)
            .execute()
            .data
            or []
        )
        if not rows:
            return False
        rid = rows[0].get("rol_id")
        return rid is not None and int(rid) in excluidos
    except Exception:
        return False


def _destinatarios_informe_validacion_dashboard(contrato_id: Optional[int]) -> List[int]:
    """
    Popup 9:00 + informe semanal lunes 8:00:
    Desarrolladores + usuarios vinculados con permiso editar en «Reporte de Cantidades»,
    excluyendo rol Operativo Gerencial / Contratista Gerencial.
    """
    dest: Set[int] = set()
    for u in _usuarios_activos_por_cargos(_ids_cargo_por_nombre("desarrollador")):
        try:
            uid = int(u["id"])
        except (TypeError, ValueError, KeyError):
            continue
        if not _usuario_es_rol_excluido_informe_validacion(uid):
            dest.add(uid)
    if contrato_id is None:
        return sorted(dest)
    try:
        cid = int(contrato_id)
    except (TypeError, ValueError):
        return sorted(dest)

    # Candidatos vinculados al contrato (misma lógica que runner email)
    uid_set: Set[int] = set()
    try:
        prim = (
            supabase.table("usuarios")
            .select("id")
            .eq("contrato_id", cid)
            .eq("activo", True)
            .eq("estado", "aprobado")
            .execute()
            .data
            or []
        )
        for r in prim:
            uid_set.add(int(r["id"]))
    except Exception:
        pass
    try:
        uc = (
            supabase.table("usuario_contratos")
            .select("usuario_id")
            .eq("contrato_id", cid)
            .execute()
            .data
            or []
        )
        for r in uc:
            uid_set.add(int(r["usuario_id"]))
    except Exception:
        pass

    for uid in uid_set:
        if not _usuario_vinculado_a_contrato(uid, cid):
            continue
        if _usuario_es_rol_excluido_informe_validacion(uid):
            continue
        if _es_desarrollador({"sub": str(uid)}) or _cargo_permiso_reporte_cantidades_user_id(
            uid, "editar", cid
        ):
            dest.add(uid)
    return sorted(dest)


def _usuario_puede_suscribirse_push(user_id: int) -> bool:
    """Editar/validar SICOE en algún contrato, o cargo Administrador/Desarrollador.

    Solo usuarios con estado Aprobado (mismo gate que notificaciones automáticas).
    """
    try:
        uid = int(user_id)
    except (TypeError, ValueError):
        return False
    dev_ids = set(_ids_cargo_por_nombre("desarrollador"))
    admin_ids = set(_ids_cargo_por_nombre("administrador"))
    try:
        urows = (
            supabase.table("usuarios")
            .select("id, cargo_id, contrato_id, estado")
            .eq("id", uid)
            .eq("activo", True)
            .limit(1)
            .execute()
            .data
            or []
        )
    except Exception:
        return False
    if not urows:
        return False
    u = urows[0]
    if not usuario_estado_es_aprobado(u.get("estado")):
        return False
    cid_cargo = u.get("cargo_id")
    if cid_cargo is not None and int(cid_cargo) in dev_ids | admin_ids:
        return True
    cids: Set[int] = set()
    if u.get("contrato_id") is not None:
        try:
            cids.add(int(u["contrato_id"]))
        except (TypeError, ValueError):
            pass
    try:
        uc = (
            supabase.table("usuario_contratos")
            .select("contrato_id")
            .eq("usuario_id", uid)
            .execute()
            .data
            or []
        )
        for row in uc:
            if row.get("contrato_id") is not None:
                cids.add(int(row["contrato_id"]))
    except Exception:
        pass
    for cid in cids:
        if _cargo_permiso_reporte_cantidades_user_id(uid, "editar", cid):
            return True
        if _cargo_permiso_reporte_cantidades_user_id(uid, "validar", cid):
            return True
    return False


def _fmt_fecha_hora_registro(created_at) -> str:
    if not created_at:
        return datetime.now(timezone.utc).strftime("%d/%m/%Y %H:%M UTC")
    try:
        if isinstance(created_at, datetime):
            dt = created_at
        else:
            s = str(created_at).replace("Z", "+00:00")
            dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc).strftime("%d/%m/%Y %H:%M UTC")
    except Exception:
        return str(created_at)[:19]


def _notificar_registro_usuario_pendiente(usuario_row: dict) -> None:
    """Inserta notificaciones SISTEMA en el buzón de Desarrolladores y Admin del contrato."""
    try:
        uid = int(usuario_row["id"])
        nombre = f"{usuario_row.get('nombre') or ''} {usuario_row.get('apellidos') or ''}".strip() or "Usuario"
        email = (usuario_row.get("email") or "").strip()
        cargo_id = usuario_row.get("cargo_id")
        contrato_id = usuario_row.get("contrato_id")
        cargo_nombre = "Sin cargo"
        contrato_etiqueta = "Sin contrato"
        if cargo_id:
            cr = supabase.table("cargos").select("nombre").eq("id", cargo_id).limit(1).execute().data
            if cr:
                cargo_nombre = cr[0].get("nombre") or cargo_nombre
        if contrato_id is not None:
            ct = (
                supabase.table("contratos")
                .select("numero, objeto")
                .eq("id", contrato_id)
                .limit(1)
                .execute()
                .data
            )
            if ct:
                num = (ct[0].get("numero") or "").strip()
                contrato_etiqueta = num or f"Contrato #{contrato_id}"
        fecha_txt = _fmt_fecha_hora_registro(usuario_row.get("created_at"))
        asunto = f"Nuevo usuario pendiente: {nombre}"
        mensaje = (
            f"Se registró un nuevo usuario pendiente de aprobación.\n\n"
            f"Nombre: {nombre}\n"
            f"Correo: {email}\n"
            f"Cargo: {cargo_nombre}\n"
            f"Contrato: {contrato_etiqueta}\n"
            f"Fecha y hora de registro: {fecha_txt}\n\n"
            f"Abra Gestión de usuarios en el Panel Admin para aprobar o rechazar."
        )
        dest_ids = _destinatarios_notif_nuevo_registro(
            int(contrato_id) if contrato_id is not None else None
        )
        if not dest_ids:
            _log_api.warning(
                "registro: sin destinatarios para notificación de usuario pendiente id=%s",
                uid,
            )
            return
        rows = []
        for did in dest_ids:
            rows.append({
                "remitente_id": None,
                "remitente_nombre": "ClaraCore",
                "destinatario_id": did,
                "asunto": asunto,
                "mensaje": mensaje,
                "tipo": "SISTEMA",
                "modulo": "AUTH",
                "contrato_id": int(contrato_id) if contrato_id is not None else None,
                "entidad_tipo": "usuario",
                "entidad_id": str(uid),
                "leido": False,
            })
        # Insertar por lotes pequeños
        batch = 50
        for i in range(0, len(rows), batch):
            supabase.table("notificaciones").insert(rows[i : i + batch]).execute()
    except Exception as e:
        _log_api.exception(
            "registro: fallo al notificar nuevo usuario pendiente: %s", e
        )


def _registrar_log_correo_bienvenida(
    *,
    usuario_id: int,
    destinatario: str,
    asunto: Optional[str],
    exito: bool,
    error_detalle: Optional[str],
    enviado_por: Optional[int],
) -> None:
    try:
        supabase.table("usuario_correo_envio").insert({
            "usuario_id": usuario_id,
            "tipo": "bienvenida",
            "destinatario": (destinatario or "").strip().lower(),
            "asunto": asunto,
            "exito": bool(exito),
            "error_detalle": (error_detalle or None),
            "enviado_por": enviado_por,
        }).execute()
    except Exception as e:
        _log_api.exception(
            "bienvenida: no se pudo registrar log de correo usuario_id=%s: %s",
            usuario_id,
            e,
        )


def _enviar_bienvenida_usuario_aprobado(
    usuario_id: int,
    aprobado_por: Optional[int] = None,
) -> None:
    """
    Envía correo de bienvenida sin bloquear la aprobación.
    Registra éxito/fallo en usuario_correo_envio y actualiza bienvenida_enviada_en si ok.
    """
    destinatario = ""
    asunto = None
    try:
        rows = (
            supabase.table("usuarios")
            .select("id, nombre, apellidos, email, cargo_id, estado, bienvenida_enviada_en")
            .eq("id", usuario_id)
            .limit(1)
            .execute()
            .data
        )
        if not rows:
            _log_api.warning("bienvenida: usuario %s no encontrado", usuario_id)
            return
        u = rows[0]
        if (u.get("estado") or "").lower() != "aprobado":
            return
        destinatario = (u.get("email") or "").strip().lower()
        if not destinatario:
            _registrar_log_correo_bienvenida(
                usuario_id=usuario_id,
                destinatario="",
                asunto=None,
                exito=False,
                error_detalle="Usuario sin correo",
                enviado_por=aprobado_por,
            )
            return
        cargo_nombre = None
        if u.get("cargo_id"):
            cr = (
                supabase.table("cargos")
                .select("nombre")
                .eq("id", u["cargo_id"])
                .limit(1)
                .execute()
                .data
            )
            if cr:
                cargo_nombre = cr[0].get("nombre")
        nombre_completo = f"{u.get('nombre') or ''} {u.get('apellidos') or ''}".strip()
        if not contacto_smtp_configured():
            _registrar_log_correo_bienvenida(
                usuario_id=usuario_id,
                destinatario=destinatario,
                asunto=None,
                exito=False,
                error_detalle="SMTP contacto no configurado",
                enviado_por=aprobado_por,
            )
            _log_api.warning(
                "bienvenida: SMTP no configurado; usuario %s aprobado sin correo",
                usuario_id,
            )
            return
        asunto = send_bienvenida_email(
            destinatario=destinatario,
            nombre_completo=nombre_completo,
            cargo_nombre=cargo_nombre,
        )
        _registrar_log_correo_bienvenida(
            usuario_id=usuario_id,
            destinatario=destinatario,
            asunto=asunto,
            exito=True,
            error_detalle=None,
            enviado_por=aprobado_por,
        )
        try:
            supabase.table("usuarios").update({
                "bienvenida_enviada_en": datetime.now(timezone.utc).isoformat(),
            }).eq("id", usuario_id).execute()
        except Exception as e:
            _log_api.exception(
                "bienvenida: correo ok pero no se actualizó bienvenida_enviada_en id=%s: %s",
                usuario_id,
                e,
            )
    except BienvenidaEmailError as e:
        _registrar_log_correo_bienvenida(
            usuario_id=usuario_id,
            destinatario=destinatario,
            asunto=asunto,
            exito=False,
            error_detalle=str(e)[:500],
            enviado_por=aprobado_por,
        )
        _log_api.warning("bienvenida: fallo SMTP usuario_id=%s: %s", usuario_id, e)
    except Exception as e:
        _registrar_log_correo_bienvenida(
            usuario_id=usuario_id,
            destinatario=destinatario,
            asunto=asunto,
            exito=False,
            error_detalle=str(e)[:500],
            enviado_por=aprobado_por,
        )
        _log_api.exception("bienvenida: error inesperado usuario_id=%s", usuario_id)


@app.post("/usuarios/registro")
def registro_usuario(usuario: UsuarioRegistro):
    existe = supabase.table("usuarios").select("id").eq("email", usuario.email).execute()
    if existe.data:
        raise HTTPException(status_code=400, detail="Este correo ya está registrado")
    hashed = hash_password(usuario.password)
    result = supabase.table("usuarios").insert({
        "nombre": usuario.nombre,
        "apellidos": usuario.apellidos,
        "email": usuario.email,
        "password_hash": hashed,
        "cargo_id": usuario.cargo_id,
        "contrato_id": usuario.contrato_id,
        "activo": False,
        "estado": "pendiente"
    }).execute()
    nuevo = (result.data or [None])[0]
    if nuevo:
        _notificar_registro_usuario_pendiente(nuevo)
        try:
            from seguimiento_service import inhabilitar_contactos_externos_por_email
            inhabilitar_contactos_externos_por_email(
                supabase, usuario.email, usuario_id=int(nuevo["id"]),
            )
        except Exception as e:
            _log_api.warning("registro: no se inhabilitaron contactos externos: %s", e)
    else:
        # Fallback: reconsultar por email si el insert no devolvió fila
        try:
            again = (
                supabase.table("usuarios")
                .select("id, nombre, apellidos, email, cargo_id, contrato_id, created_at, estado")
                .eq("email", usuario.email)
                .limit(1)
                .execute()
                .data
            )
            if again:
                _notificar_registro_usuario_pendiente(again[0])
                try:
                    from seguimiento_service import inhabilitar_contactos_externos_por_email
                    inhabilitar_contactos_externos_por_email(
                        supabase, usuario.email, usuario_id=int(again[0]["id"]),
                    )
                except Exception as e:
                    _log_api.warning("registro: no se inhabilitaron contactos externos: %s", e)
        except Exception as e:
            _log_api.exception("registro: no se pudo notificar tras insert: %s", e)
    return {"mensaje": "Registro exitoso, pendiente de aprobación"}

