_FUNCIONES_REQUERIDAS = (
    {"codigo": "DASHBOARD", "nombre": "Dashboard", "modulo": "Dashboard"},
    {"codigo": "INFCCD", "nombre": "Informes CCD", "modulo": "Informes"},
    {"codigo": "AUDSST", "nombre": "Auditor SST (IA)", "modulo": "SST"},
    {"codigo": "PROGOB", "nombre": "Programación de obra", "modulo": "Programación"},
    {"codigo": "ALMACEN", "nombre": "Almacén", "modulo": "Obra"},
    {"codigo": "CATINS", "nombre": "Catálogo de insumos", "modulo": "Obra"},
    {"codigo": "SEGUIMIENTO", "nombre": "Seguimiento", "modulo": "Obra"},
)


def _ensure_funciones_requeridas(sb=None) -> list:
    """Inserta funciones base faltantes (p. ej. Seguimiento) sin paso manual en Supabase."""
    sb = sb or supabase
    funciones = sb.table("funciones").select("*").order("nombre").execute().data or []
    existentes = {(f.get("nombre") or "").strip().lower() for f in funciones}
    codigos_existentes = {
        str((f.get("codigo") or "")).strip().upper()
        for f in funciones
        if f.get("codigo") is not None and str(f.get("codigo")).strip() != ""
    }
    # En producción el INSERT vía API a veces falla por RLS; fallback: sql/seguimiento_modulo.sql
    for req in _FUNCIONES_REQUERIDAS:
        nombre_funcion = req["nombre"]
        cod = str(req.get("codigo") or "").strip().upper()
        if nombre_funcion.lower() in existentes or (cod and cod in codigos_existentes):
            continue
        try:
            sb.table("funciones").insert(req).execute()
            existentes.add(nombre_funcion.lower())
            if cod:
                codigos_existentes.add(cod)
        except Exception as e:
            try:
                sb.table("funciones").upsert(req, on_conflict="codigo").execute()
                existentes.add(nombre_funcion.lower())
                if cod:
                    codigos_existentes.add(cod)
            except Exception as e2:
                _log_api.warning(
                    "funciones requeridas: no se pudo insertar ni upsert '%s' (%s). "
                    "Si falta en el panel admin, ejecuta backend/sql/seguimiento_modulo.sql "
                    "(u homólogo) en Supabase. insert_err=%s | upsert_err=%s",
                    nombre_funcion,
                    req.get("codigo"),
                    e,
                    e2,
                )
    return sb.table("funciones").select("*").order("nombre").execute().data or []


@app.get("/funciones")
def listar_funciones(current_user=Depends(get_current_user)):
    return _ensure_funciones_requeridas()

def _sanitize_export_palette(raw: Any) -> dict:
    if not isinstance(raw, dict):
        return {}
    defaults = {
        "encabezado": {"bg": "#DDEFF8", "text": "#0F2942"},
        "titulo_1": {"bg": "#EEF7FB", "text": "#0F2942"},
        "titulo_2": {"bg": "#E5F4FA", "text": "#1F4E70"},
        "linea_principal": {"bg": "#FFFFFF", "text": "#0F2942"},
        "linea_secundaria": {"bg": "#F8FAFC", "text": "#0F2942"},
    }
    legacy_bg = {
        "encabezado": "encabezado",
        "titulo_1": "subtitulos",
        "titulo_2": "cuerpo_principal",
        "linea_principal": "cuerpo_principal",
        "linea_secundaria": "cuerpo_secundario",
    }

    def _hex(v: Any) -> Optional[str]:
        if v is None:
            return None
        s = str(v).strip()
        if not s:
            return None
        if not s.startswith("#"):
            s = f"#{s}"
        if re.match(r"^#[0-9A-Fa-f]{6}$", s):
            return s.upper()
        return None

    out: dict = {}
    for tier, def_t in defaults.items():
        block = raw.get(tier)
        bg = None
        text = None
        if isinstance(block, dict):
            bg = _hex(block.get("bg"))
            text = _hex(block.get("text"))
        elif isinstance(block, str):
            bg = _hex(block)
        if not bg:
            bg = _hex(raw.get(legacy_bg.get(tier, "")))
        if not text:
            text = _hex(raw.get(f"{tier}_text"))
        if tier == "linea_secundaria" and not bg and isinstance(raw.get("cuerpos"), dict):
            bg = _hex(raw["cuerpos"].get("bg"))
            text = text or _hex(raw["cuerpos"].get("text"))
        out[tier] = {
            "bg": bg or def_t["bg"],
            "text": text or def_t["text"],
        }
    return out


def _export_palette_desde_contrato(row: dict) -> dict:
    if not isinstance(row, dict):
        return _sanitize_export_palette({})
    if row.get("export_palette"):
        return _sanitize_export_palette(row.get("export_palette"))
    cfg = row.get("ccd_firma_config")
    if isinstance(cfg, dict) and cfg.get("export_palette"):
        return _sanitize_export_palette(cfg.get("export_palette"))
    return _sanitize_export_palette({})


def _guardar_export_palette_contrato(contrato_id: int, palette: Any) -> None:
    clean = _sanitize_export_palette(palette or {})
    rows = (
        supabase.table("contratos")
        .select("ccd_firma_config")
        .eq("id", contrato_id)
        .limit(1)
        .execute()
        .data
        or []
    )
    cfg = rows[0].get("ccd_firma_config") if rows else {}
    if not isinstance(cfg, dict):
        cfg = {}
    cfg = {**cfg, "export_palette": clean}
    supabase.table("contratos").update({"ccd_firma_config": cfg}).eq("id", contrato_id).execute()
    try:
        supabase.table("contratos").update({"export_palette": clean}).eq("id", contrato_id).execute()
    except Exception as exc:
        msg = str(exc).lower()
        if "export_palette" not in msg and "pgrst204" not in msg:
            raise


def _normalizar_costos_adicionales_lista(items: List[CostoAdicionalItem]) -> List[dict]:
    out: List[dict] = []

    def _f(x) -> Optional[float]:
        if x is None:
            return None
        try:
            v = float(x)
        except (TypeError, ValueError):
            return None
        if not math.isfinite(v):
            return None
        return v

    for it in items or []:
        c = (it.concepto_contractual or "").strip()
        if not c:
            continue
        vm = _f(it.valor_mensual)
        tm = _f(it.tiempo_meses)
        v_old = _f(it.valor)
        if vm is None and v_old is not None and tm is None:
            vm = v_old
            tm = 1.0
        if vm is None:
            vm = 0.0
        if tm is None:
            tm = 0.0
        if tm < 0.0:
            tm = 0.0
        v = float(round(float(vm) * float(tm), 0))
        out.append(
            {
                "concepto_contractual": c,
                "valor_mensual": float(vm),
                "tiempo_meses": float(tm),
                "valor": v,
            }
        )
    return out


def _suma_costos_adicionales_cop(lista: List[dict]) -> Optional[float]:
    t = 0.0
    n = 0
    for x in lista or []:
        v = x.get("valor")
        if v is None:
            continue
        t += float(v)
        n += 1
    if not lista:
        return None
    if n == 0:
        return None
    return t


def _is_pgrst_missing_column(exc: BaseException, column: str) -> bool:
    """True si PostgREST reporta PGRST204 / schema cache para la columna dada."""
    text = str(exc or "")
    low = text.lower()
    col = (column or "").lower()
    if col not in low:
        return False
    return "pgrst204" in low or "schema cache" in low or "could not find" in low


def _try_reload_postgrest_schema_contratos() -> bool:
    """Best-effort: pide a PostgREST recargar el schema cache (RPC NOTIFY)."""
    try:
        supabase.rpc("sicoe_reload_postgrest_schema").execute()
        return True
    except Exception:
        pass
    try:
        supabase.rpc("pg_notify", {"channel": "pgrst", "payload": "reload schema"}).execute()
        return True
    except Exception:
        return False


def _contratos_write_with_schema_retry(op_name: str, write_fn, *, has_numero_interventoria: bool):
    """Ejecuta insert/update; si falla por numero_interventoria en caché, recarga y reintenta una vez."""
    try:
        return write_fn()
    except Exception as exc:
        if not (has_numero_interventoria and _is_pgrst_missing_column(exc, "numero_interventoria")):
            raise
        reloaded = _try_reload_postgrest_schema_contratos()
        if reloaded:
            try:
                import time as _time

                _time.sleep(0.8)
            except Exception:
                pass
            try:
                return write_fn()
            except Exception as exc2:
                if _is_pgrst_missing_column(exc2, "numero_interventoria"):
                    raise HTTPException(
                        status_code=503,
                        detail=(
                            "PostgREST no reconoce aún la columna contratos.numero_interventoria "
                            "(caché de esquema). Ejecute en Supabase SQL Editor el script "
                            "backend/sql/fix_contratos_numero_interventoria_schema.sql "
                            "(incluye verificación al catálogo + NOTIFY pgrst, 'reload schema') "
                            "y reintente en unos segundos."
                        ),
                    ) from exc2
                raise
        raise HTTPException(
            status_code=503,
            detail=(
                "No se pudo guardar numero_interventoria: la columna no está en el schema cache "
                "de PostgREST y no fue posible recargarlo desde la API. Ejecute en Supabase: "
                "backend/sql/fix_contratos_numero_interventoria_schema.sql"
            ),
        ) from exc


@app.post("/contratos")
def crear_contrato(contrato: ContratoCreate, current_user=Depends(get_current_user)):
    existe = supabase.table("contratos").select("id").eq("numero", contrato.numero).execute()
    if existe.data:
        raise HTTPException(status_code=400, detail="Ya existe un contrato con ese número")
    norm = _normalizar_costos_adicionales_lista(contrato.costos_adicionales_lista or [])
    costos_cop = _suma_costos_adicionales_cop(norm)
    if not norm and contrato.costos_adicionales is not None:
        costos_cop = contrato.costos_adicionales
    payload = {
        "numero": contrato.numero,
        "objeto": contrato.objeto,
        "contratista": contrato.contratista,
        "nit": contrato.nit,
        "interventoria": contrato.interventoria,
        "entidad": contrato.entidad,
        "entidad_otra": contrato.entidad_otra,
        "logo_entidad": contrato.logo_entidad,
        "plano_geojson": contrato.plano_geojson,
        "centro_lat": contrato.centro_lat,
        "centro_lng": contrato.centro_lng,
        "logo_contratista": contrato.logo_contratista,
        "logo_interventoria": contrato.logo_interventoria,
        "numero_interventoria": (contrato.numero_interventoria or "").strip() or None,
        "aiu": contrato.aiu,
        "iva": contrato.iva,
        "valor_componente_ambiental": contrato.valor_componente_ambiental,
        "valor_componente_social": contrato.valor_componente_social,
        "valor_componente_pmt": contrato.valor_componente_pmt,
        "costo_directo_contrato": contrato.costo_directo_contrato,
        "costos_adicionales": costos_cop,
        "costos_adicionales_lista": norm,
    }

    def _ins():
        return supabase.table("contratos").insert(payload).execute()

    result = _contratos_write_with_schema_retry(
        "insert",
        _ins,
        has_numero_interventoria=("numero_interventoria" in payload),
    )
    nuevo = result.data[0]
    if contrato.export_palette is not None:
        try:
            _guardar_export_palette_contrato(nuevo["id"], contrato.export_palette)
        except Exception:
            pass
    nuevo["export_palette"] = _export_palette_desde_contrato(nuevo)
    return nuevo


@app.put("/contratos/{contrato_id}")
def actualizar_contrato(contrato_id: int, body: ContratoUpdate, current_user=Depends(get_current_user)):
    data = body.dict(exclude_unset=True)
    if "costos_adicionales_lista" in data and body.costos_adicionales_lista is not None:
        norm = _normalizar_costos_adicionales_lista(body.costos_adicionales_lista)
        data["costos_adicionales_lista"] = norm
        data["costos_adicionales"] = _suma_costos_adicionales_cop(norm)
    palette_payload = None
    if "export_palette" in data:
        palette_payload = data.pop("export_palette")
    if not data and palette_payload is None:
        return {"mensaje": "Sin cambios"}
    if data:
        def _upd():
            return supabase.table("contratos").update(data).eq("id", contrato_id).execute()

        _contratos_write_with_schema_retry(
            "update",
            _upd,
            has_numero_interventoria=("numero_interventoria" in data),
        )
    if palette_payload is not None:
        _guardar_export_palette_contrato(contrato_id, palette_payload)
    return {"mensaje": "Contrato actualizado"}


@app.get("/admin/contratos/schema-numero-interventoria")
def admin_diagnostico_numero_interventoria(current_user=Depends(get_current_user)):
    """
    Diagnóstico liviano (vía PostgREST, no catálogo SQL):
    indica si la API ve contratos.numero_interventoria y fuerza reload best-effort.
    """
    visto = False
    err_msg = None
    try:
        supabase.table("contratos").select("id,numero_interventoria").limit(1).execute()
        visto = True
    except Exception as exc:
        err_msg = str(exc)
        visto = not _is_pgrst_missing_column(exc, "numero_interventoria")
        if _is_pgrst_missing_column(exc, "numero_interventoria"):
            visto = False
    reloaded = _try_reload_postgrest_schema_contratos()
    visto_tras_reload = visto
    if not visto and reloaded:
        try:
            import time as _time

            _time.sleep(0.8)
            supabase.table("contratos").select("id,numero_interventoria").limit(1).execute()
            visto_tras_reload = True
            err_msg = None
        except Exception as exc2:
            visto_tras_reload = False
            err_msg = str(exc2)
    return {
        "columna": "numero_interventoria",
        "tabla": "contratos",
        "postgrest_ve_columna": visto_tras_reload,
        "reload_solicitado": reloaded,
        "error": err_msg,
        "accion_si_falla": (
            "Ejecutar en Supabase SQL Editor: "
            "backend/sql/fix_contratos_numero_interventoria_schema.sql"
        ),
    }

