@app.put("/admin/usuarios/{usuario_id}/aprobar")
def aprobar_usuario(
    usuario_id: int,
    body: AprobarRequest,
    background_tasks: BackgroundTasks,
    current_user=Depends(get_current_user),
):
    prev = (
        supabase.table("usuarios")
        .select("estado")
        .eq("id", usuario_id)
        .limit(1)
        .execute()
        .data
    )
    prev_estado = ((prev[0].get("estado") if prev else None) or "").lower()
    supabase.table("usuarios").update({
        "estado": "aprobado", "activo": True, "rol_id": body.rol_id
    }).eq("id", usuario_id).execute()
    rol_nombre = ""
    if body.rol_id:
        r = supabase.table("roles").select("nombre").eq("id", body.rol_id).execute()
        rol_nombre = r.data[0]["nombre"] if r.data else str(body.rol_id)
    registrar_log(current_user, "APROBAR", "USUARIOS", "usuario", str(usuario_id),
        {"estado": "aprobado", "rol": rol_nombre})
    if prev_estado != "aprobado":
        try:
            aprobado_por = int(current_user.get("sub"))
        except (TypeError, ValueError):
            aprobado_por = None
        background_tasks.add_task(
            _enviar_bienvenida_usuario_aprobado, usuario_id, aprobado_por
        )
        try:
            urows = (
                supabase.table("usuarios")
                .select("id, email")
                .eq("id", usuario_id)
                .limit(1)
                .execute()
                .data
                or []
            )
            if urows and urows[0].get("email"):
                from seguimiento_service import inhabilitar_contactos_externos_por_email
                inhabilitar_contactos_externos_por_email(
                    supabase, urows[0]["email"], usuario_id=int(usuario_id),
                )
        except Exception as e:
            _log_api.warning("aprobar: no se inhabilitaron contactos externos: %s", e)
    return {"mensaje": "Usuario aprobado"}

