@app.get("/admin/todos-usuarios")
def todos_usuarios(current_user=Depends(get_current_user)):
    """Lista solo usuarios vivos: pendiente y aprobado. Los rechazados no aparecen."""
    result = supabase.table("usuarios").select(
        "id, nombre, apellidos, email, activo, cargo_id, rol_id, contrato_id, estado, created_at, politicas_aceptadas, politicas_fecha, politicas_version, politicas_ip"
    ).order("nombre").execute()
    cargos = {c["id"]: c["nombre"] for c in supabase.table("cargos").select("id, nombre").execute().data}
    roles = {r["id"]: r["nombre"] for r in supabase.table("roles").select("id, nombre").execute().data}
    contratos = {c["id"]: c["numero"] for c in supabase.table("contratos").select("id, numero").execute().data}
    caller_contrato, _ = _caller_contract_scope(current_user)
    for u in result.data:
        u["cargo_nombre"] = cargos.get(u.get("cargo_id"), "Sin cargo")
        u["rol_nombre"] = roles.get(u.get("rol_id"), "Sin rol")
        u["contrato_numero"] = contratos.get(u.get("contrato_id"), "Sin contrato")
    caller_id = int(current_user["sub"])
    # Privacidad estricta: cada sesión solo puede ver usuarios de su contrato.
    if caller_contrato:
        filtered = [u for u in result.data if u.get("contrato_id") == caller_contrato]
    else:
        filtered = list(result.data)
    filtered = [u for u in filtered if u.get("cargo_nombre", "").lower() != "desarrollador" or u["id"] == caller_id]
    # Rechazados = papelera: fuera de la vista de gestión
    return filtrar_usuarios_visibles_gestion(filtered)

def _admin_usuario_fk_int_o_none(value) -> Optional[int]:
    """Normaliza FK opcionales: None/''/'None' → None; evita .eq(id, None) → 22P02."""
    if value is None:
        return None
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if value != value:  # NaN
            return None
        return int(value)
    s = str(value).strip()
    if not s or s.lower() in ("none", "null", "undefined", "nan"):
        return None
    try:
        return int(s)
    except (TypeError, ValueError):
        return None


def _admin_usuario_nombre_fk(tabla: str, col: str, fk_id) -> Optional[str]:
    """Resuelve nombre legible de FK; no consulta si el id es nulo (PostgREST manda 'None' como texto)."""
    fk = _admin_usuario_fk_int_o_none(fk_id)
    if fk is None:
        return None
    r = supabase.table(tabla).select(col).eq("id", fk).limit(1).execute()
    if r.data and r.data[0].get(col) is not None:
        return r.data[0][col]
    return str(fk)


def _admin_usuario_enriquecer_detalle_log(data: dict) -> dict:
    """Sustituye cargo_id/rol_id/contrato_id por nombres; tolera nulls (p. ej. Sin rol)."""
    detalle = dict(data or {})
    if "cargo_id" in detalle:
        detalle["cargo"] = _admin_usuario_nombre_fk("cargos", "nombre", detalle.pop("cargo_id"))
    if "rol_id" in detalle:
        detalle["rol"] = _admin_usuario_nombre_fk("roles", "nombre", detalle.pop("rol_id"))
    if "contrato_id" in detalle:
        detalle["contrato"] = _admin_usuario_nombre_fk("contratos", "numero", detalle.pop("contrato_id"))
    return detalle


@app.put("/admin/usuarios/{usuario_id}")
def actualizar_usuario(
    usuario_id: int,
    body: UsuarioUpdate,
    background_tasks: BackgroundTasks,
    current_user=Depends(get_current_user),
):
    # Proteger: no se puede modificar un Desarrollador SALVO que sea él mismo editándose
    es_el_mismo = str(usuario_id) == str(current_user.get("sub"))
    if not es_el_mismo:
        target = supabase.table("usuarios").select("cargo_id").eq("id", usuario_id).execute()
        if target.data and target.data[0].get("cargo_id"):
            cargo_res = supabase.table("cargos").select("nombre").eq("id", target.data[0]["cargo_id"]).execute()
            if cargo_res.data and cargo_res.data[0]["nombre"].lower() == "desarrollador":
                raise HTTPException(status_code=403, detail="No se puede modificar un usuario Desarrollador")

    prev_snap = supabase.table("usuarios").select(
        "cargo_id, rol_id, contrato_id, estado, activo, subcontratista_id, nombre, apellidos, email"
    ).eq("id", usuario_id).limit(1).execute().data
    prev_snap = prev_snap[0] if prev_snap else {}
    prev_estado = (prev_snap.get("estado") or "").lower()

    # exclude_unset=True: campos no enviados no se tocan; null explícito sí borra el campo
    data = body.dict(exclude_unset=True)
    for fk in ("cargo_id", "rol_id", "contrato_id", "subcontratista_id"):
        if fk in data:
            data[fk] = _admin_usuario_fk_int_o_none(data.get(fk))
    if body.estado == "aprobado":
        data["activo"] = True
    elif body.estado == "rechazado":
        data["activo"] = False
    if body.politicas_aceptadas is False:
        data["politicas_fecha"] = None
        data["politicas_ip"] = None
    supabase.table("usuarios").update(data).eq("id", usuario_id).execute()
    if body.estado == "rechazado":
        _archivar_usuario_rechazado(usuario_id)
    # Resetear contador de inactividad: insertar LOGIN sintético al reactivar un usuario
    if body.estado == "aprobado":
        try:
            u_data = supabase.table("usuarios").select("nombre, apellidos, cargo_id, contrato_id").eq("id", usuario_id).execute().data
            u_nombre = ""
            u_contrato_id = None
            if u_data:
                u = u_data[0]
                u_nombre = f"{u.get('nombre','')} {u.get('apellidos','')}".strip()
                u_contrato_id = _admin_usuario_fk_int_o_none(u.get("contrato_id"))
            supabase.table("logs").insert({
                "usuario_id":   usuario_id,
                "usuario_nombre": u_nombre,
                "cargo_nombre": "",
                "contrato_id":  u_contrato_id,
                "contrato_numero": None,
                "accion":       "LOGIN",
                "modulo":       "AUTH",
                "entidad_tipo": "usuario",
                "entidad_id":   str(usuario_id),
                "detalle":      {"origen": "Reactivación por administrador"},
                "resultado":    "ok",
            }).execute()
        except Exception:
            pass
        # Correo de bienvenida solo al pasar a aprobado (no reenvía si ya estaba aprobado)
        if prev_estado != "aprobado":
            try:
                aprobado_por = int(current_user.get("sub"))
            except (TypeError, ValueError):
                aprobado_por = None
            background_tasks.add_task(
                _enviar_bienvenida_usuario_aprobado, usuario_id, aprobado_por
            )
    # Enriquecer detalle con nombres legibles (sin .eq(id, None) → 22P02)
    detalle_log = _admin_usuario_enriquecer_detalle_log(data)

    def _usuario_audit_enriquecido(row: dict) -> dict:
        if not row:
            return {}
        o = dict(row)
        if _admin_usuario_fk_int_o_none(row.get("cargo_id")) is not None:
            o["cargo"] = _admin_usuario_nombre_fk("cargos", "nombre", row.get("cargo_id"))
        if _admin_usuario_fk_int_o_none(row.get("rol_id")) is not None:
            o["rol"] = _admin_usuario_nombre_fk("roles", "nombre", row.get("rol_id"))
        if _admin_usuario_fk_int_o_none(row.get("contrato_id")) is not None:
            o["contrato"] = _admin_usuario_nombre_fk("contratos", "numero", row.get("contrato_id"))
        return o

    after_snap = supabase.table("usuarios").select(
        "cargo_id, rol_id, contrato_id, estado, activo, subcontratista_id, nombre, apellidos, email"
    ).eq("id", usuario_id).limit(1).execute().data
    after_snap = after_snap[0] if after_snap else {}

    registrar_log(
        current_user,
        "EDITAR",
        "USUARIOS",
        "usuario",
        str(usuario_id),
        detalle_log,
        valor_anterior=_usuario_audit_enriquecido(prev_snap),
        valor_nuevo=_usuario_audit_enriquecido(after_snap),
        severidad="AUDIT",
    )
    return {"mensaje": "Usuario actualizado"}


def _archivar_usuario_rechazado(usuario_id: int) -> None:
    """
    Rechazado = papelera: sin push, sin resets pendientes, sin buzón activo.
    No borra el registro de usuarios ni busca actividad en módulos.
    """
    uid = int(usuario_id)
    for tabla, col in (
        ("push_subscriptions", "usuario_id"),
        ("password_reset_requests", "usuario_id"),
        ("cad_sessions", "usuario_id"),
    ):
        try:
            supabase.table(tabla).delete().eq(col, uid).execute()
        except Exception:
            pass
    try:
        supabase.table("notificaciones").delete().eq("destinatario_id", uid).execute()
    except Exception:
        pass


@app.post("/admin/verificar-inactividad")
def verificar_inactividad(current_user=Depends(get_current_user)):
    """Marca como pendiente a usuarios aprobados con >7 días sin iniciar sesión (según último LOGIN en logs)."""
    if not _cargo_puede_auditar_logs(current_user):
        raise HTTPException(
            status_code=403,
            detail="Solo Desarrollador o Administrador pueden ejecutar la verificación de inactividad.",
        )
    from datetime import datetime, timedelta, timezone
    CARGOS_EXCLUIDOS = {'director', 'gerencia', 'supervisor externo', 'desarrollador', 'administrador'}
    ahora = datetime.now(timezone.utc)
    limite = ahora - timedelta(days=7)
    usuarios_raw = supabase.table("usuarios").select("id, cargo_id, estado").eq("estado", "aprobado").execute().data
    if not usuarios_raw:
        return {"afectados": 0}
    cargos = {c["id"]: c["nombre"].lower() for c in supabase.table("cargos").select("id, nombre").execute().data}
    candidatos = [u for u in usuarios_raw if cargos.get(u.get("cargo_id"), "") not in CARGOS_EXCLUIDOS]
    if not candidatos:
        return {"afectados": 0}
    cand_ids = [u["id"] for u in candidatos]
    last_login: Dict[int, str] = {}
    page_size = 500
    max_filas_por_bloque = 40000
    # Evita URL/query gigantes y timeouts: bloques de usuarios.
    id_bloque = 100
    for bi in range(0, len(cand_ids), id_bloque):
        sub_ids = cand_ids[bi : bi + id_bloque]
        needed = set(sub_ids)
        escaneadas = 0
        while needed and escaneadas < max_filas_por_bloque:
            start = escaneadas
            end = escaneadas + page_size - 1
            batch = (
                supabase.table("logs")
                .select("usuario_id, created_at")
                .eq("accion", "LOGIN")
                .in_("usuario_id", sub_ids)
                .order("created_at", desc=True)
                .range(start, end)
                .execute()
                .data
                or []
            )
            if not batch:
                break
            for log in batch:
                uid = log.get("usuario_id")
                if uid is None:
                    continue
                if uid in needed and uid not in last_login:
                    last_login[uid] = log.get("created_at")
            needed = set(sub_ids) - set(last_login.keys())
            if not needed:
                break
            escaneadas += len(batch)
            if len(batch) < page_size:
                break
    afectados = 0
    for u in candidatos:
        uid = u["id"]
        last = last_login.get(uid)
        inactivo = False
        if last is None:
            inactivo = True
        else:
            try:
                last_dt = datetime.fromisoformat(last.replace("Z", "+00:00"))
                if last_dt.tzinfo is None:
                    last_dt = last_dt.replace(tzinfo=timezone.utc)
                if last_dt < limite:
                    inactivo = True
            except Exception:
                pass
        if inactivo:
            supabase.table("usuarios").update({"estado": "pendiente", "activo": False}).eq("id", uid).execute()
            afectados += 1
    registrar_log(current_user, "VERIFICAR_INACTIVIDAD", "USUARIOS", None, None, {"afectados": afectados})
    return {"afectados": afectados}

# Campos del selector de contrato en sesión / Admin UC (payload liviano).
_CONTRATOS_SELECT_SELECTOR = (
    "id, numero, contratista, interventoria, entidad, entidad_otra, logo_entidad, "
    "centro_lat, centro_lng, logo_contratista, logo_interventoria, fase"
)


def _listar_contratos_selector(ids=None):
    """Lista contratos para el selector. Si ids es None → todos; si [] → []."""
    q = supabase.table("contratos").select(_CONTRATOS_SELECT_SELECTOR).order("numero")
    if ids is None:
        return q.execute().data or []
    if not ids:
        return []
    return q.in_("id", list(ids)).execute().data or []


@app.get("/admin/usuario-contratos/{usuario_id}")
def get_usuario_contratos(usuario_id: int, current_user=Depends(get_current_user)):
    """Contratos del selector de sesión.

    Desarrollador consultando su propia lista: acceso irrestricto a todos los
    contratos (existentes y futuros), sin depender de filas en usuario_contratos.
    Para terceros (p. ej. UI de asignaciones Admin) se mantiene el vínculo explícito.
    """
    try:
        uid = int(usuario_id)
        caller_id = int(current_user.get("sub"))
    except (TypeError, ValueError):
        raise HTTPException(status_code=401, detail="Token inválido")

    if caller_id == uid and _es_desarrollador(current_user):
        return _listar_contratos_selector(None)

    result = supabase.table("usuario_contratos").select("contrato_id").eq("usuario_id", uid).execute()
    ids = [r["contrato_id"] for r in (result.data or [])]
    return _listar_contratos_selector(ids)

