@app.post("/admin/permisos")
def guardar_permisos(permisos: List[PermisoUpdate], current_user=Depends(get_current_user)):
    cargo_ids = sorted({p.cargo_id for p in permisos})

    def _norm_perm_rows(rows):
        if not rows:
            return []

        def _key(r):
            return (r.get("cargo_id"), r.get("funcion_id"))

        out = []
        for r in sorted(rows, key=_key):
            out.append({
                "cargo_id": r.get("cargo_id"),
                "funcion_id": r.get("funcion_id"),
                "ver": r.get("ver"),
                "crear": r.get("crear"),
                "editar": r.get("editar"),
                "eliminar": r.get("eliminar"),
                "validar": r.get("validar"),
                "exportar": r.get("exportar"),
            })
        return out

    contrato_matriz = permisos[0].contrato_id if permisos else None
    if contrato_matriz is None:
        caller_cid, _ = _caller_contract_scope(current_user)
        contrato_matriz = caller_cid

    antes_por_cargo = {}
    for cid in cargo_ids:
        antes_por_cargo[cid] = _norm_perm_rows(
            _permisos_rows_para_cargo(cid, int(contrato_matriz) if contrato_matriz is not None else None)
        )

    cid_matriz = int(contrato_matriz) if contrato_matriz is not None else None

    for permiso in permisos:
        data = permiso.dict()
        if cid_matriz is not None:
            data["contrato_id"] = cid_matriz

        row_id = None
        if cid_matriz is not None:
            scoped = (
                supabase.table("permisos")
                .select("id")
                .eq("cargo_id", permiso.cargo_id)
                .eq("funcion_id", permiso.funcion_id)
                .eq("contrato_id", cid_matriz)
                .limit(1)
                .execute()
                .data
            )
            if scoped:
                row_id = scoped[0]["id"]

        if row_id is None:
            legacy = (
                supabase.table("permisos")
                .select("id, contrato_id")
                .eq("cargo_id", permiso.cargo_id)
                .eq("funcion_id", permiso.funcion_id)
                .is_("contrato_id", "null")
                .limit(1)
                .execute()
                .data
            )
            if legacy:
                row_id = legacy[0]["id"]

        if row_id is not None:
            supabase.table("permisos").update(data).eq("id", row_id).execute()
        else:
            supabase.table("permisos").insert(data).execute()

    for cid in cargo_ids:
        despues = _norm_perm_rows(
            _permisos_rows_para_cargo(cid, int(contrato_matriz) if contrato_matriz is not None else None)
        )
        if despues == antes_por_cargo.get(cid, []):
            continue
        cargo_row = supabase.table("cargos").select("nombre").eq("id", cid).limit(1).execute().data
        cn = cargo_row[0]["nombre"] if cargo_row else str(cid)
        registrar_log(
            current_user,
            "EDITAR",
            "PERMISOS",
            "cargo",
            str(cid),
            {"cargo": cn, "cambio": "matriz_permisos"},
            valor_anterior=antes_por_cargo.get(cid, []),
            valor_nuevo=despues,
            severidad="AUDIT",
            alerta_generada=True,
        )
    return {"mensaje": f"{len(permisos)} permisos guardados"}

