@app.delete("/listado-precios/agrupadores/{agrupador_id}")
def eliminar_listado_precio_agrupador(agrupador_id: int, current_user=Depends(get_current_user)):
    ex = (
        supabase.table("listado_precios_agrupadores")
        .select("contrato_id, nombre")
        .eq("id", agrupador_id)
        .limit(1)
        .execute()
        .data
    )
    if not ex:
        raise HTTPException(status_code=404, detail="Agrupador no encontrado")
    _require_contract_access(current_user, ex[0]["contrato_id"])
    hijos = (
        supabase.table("listado_precios")
        .select("id", count="exact")
        .eq("agrupador_id", agrupador_id)
        .execute()
    )
    items_desasignados = int(hijos.count or 0)
    if items_desasignados > 0:
        supabase.table("listado_precios").update({"agrupador_id": None}).eq("agrupador_id", agrupador_id).execute()
    acts = (
        supabase.table("prog_actividades")
        .select("id", count="exact")
        .eq("agrupador_id", agrupador_id)
        .execute()
    )
    actividades_programadas = int(acts.count or 0)
    supabase.table("listado_precios_agrupadores").delete().eq("id", agrupador_id).execute()
    registrar_log(current_user, "ELIMINAR", "PRECIOS", "listado_precios_agrupadores", str(agrupador_id),
                  {"nombre": ex[0].get("nombre"), "items_desasignados": items_desasignados,
                   "actividades_programadas": actividades_programadas})
    return {"ok": True, "items_desasignados": items_desasignados, "actividades_programadas": actividades_programadas}


@app.put("/listado-precios/item/{item_id}/agrupador")
def reasignar_item_agrupador(
    item_id: int,
    body: ListadoPrecioAgrupadorAsignarBody,
    current_user=Depends(get_current_user),
):
    row = (
        supabase.table("listado_precios")
        .select("id, contrato_id, capitulo, agrupador_id")
        .eq("id", item_id)
        .limit(1)
        .execute()
        .data
    )
    if not row:
        raise HTTPException(status_code=404, detail="Ítem no encontrado")
    item_row = row[0]
    _require_contract_access(current_user, item_row["contrato_id"])
    cap_item = (item_row.get("capitulo") or "").strip()
    nuevo_id = body.agrupador_id
    if nuevo_id is not None:
        ag = (
            supabase.table("listado_precios_agrupadores")
            .select("id, contrato_id, capitulo, nombre, codigo_wbs")
            .eq("id", nuevo_id)
            .limit(1)
            .execute()
            .data
        )
        if not ag:
            raise HTTPException(status_code=404, detail="Agrupador no encontrado")
        ag_row = ag[0]
        if int(ag_row["contrato_id"]) != int(item_row["contrato_id"]):
            raise HTTPException(status_code=400, detail="El agrupador no pertenece a este contrato.")
        if cap_item and (ag_row.get("capitulo") or "").strip() != cap_item:
            raise HTTPException(status_code=400, detail="El agrupador debe pertenecer al mismo capítulo que el ítem.")
    supabase.table("listado_precios").update({"agrupador_id": nuevo_id}).eq("id", item_id).execute()
    registrar_log(
        current_user, "EDITAR", "PRECIOS", "listado_precios", str(item_id),
        {"agrupador_id": nuevo_id, "accion": "reasignar_agrupador"},
    )
    return {"ok": True, "agrupador_id": nuevo_id}


@app.get("/listado-precios/{contrato_id}")
def get_listado_precios(
    contrato_id: int,
    limit: Optional[int] = None,
    offset: int = 0,
    current_user=Depends(get_current_user),
):
    _require_contract_access(current_user, contrato_id)
    if offset < 0:
        offset = 0
    if limit is not None:
        if limit < 1:
            limit = 1
        if limit > 500:
            limit = 500
        end = offset + limit - 1
        return (
            supabase.table("listado_precios")
            .select("*")
            .eq("contrato_id", contrato_id)
            .order("item_numero")
            .range(offset, end)
            .execute()
            .data
            or []
        )
    all_rows = []
    batch_offset = 0
    while True:
        batch = (
            supabase.table("listado_precios")
            .select("*")
            .eq("contrato_id", contrato_id)
            .order("item_numero")
            .range(batch_offset, batch_offset + 999)
            .execute()
            .data
        )
        all_rows.extend(batch)
        if len(batch) < 1000:
            break
        batch_offset += 1000
    return all_rows

@app.post("/listado-precios/{contrato_id}/bulk")
def bulk_precios(contrato_id: int, items: List[ListadoPrecioItem], current_user=Depends(get_current_user)):
    _require_contract_access(current_user, contrato_id)
    """Reemplaza todos los precios del contrato con los items del CSV."""
    supabase.table("listado_precios").delete().eq("contrato_id", contrato_id).execute()
    if items:
        rows = []
        for item in items:
            rows.append(_listado_precio_row(contrato_id, item))
        supabase.table("listado_precios").insert(rows).execute()
    registrar_log(current_user, "IMPORTAR", "PRECIOS", "listado_precios", str(contrato_id),
                  {"cantidad": len(items)})
    return {"mensaje": f"{len(items)} items cargados"}

@app.put("/listado-precios/item/{item_id}")
def update_precio(
    item_id: int,
    body: ListadoPrecioItem,
    confirm_meta: bool = Query(
        False,
        description="Obligatorio true si cambian ítem/descripción/unidad (tras popup de impacto).",
    ),
    current_user=Depends(get_current_user),
):
    raw = body.dict()
    data = {k: v for k, v in raw.items() if v is not None and k not in ("agrupador_nombre", "agrupador_codigo_wbs")}
    prev_rows = (
        supabase.table("listado_precios")
        .select("id, contrato_id, capitulo, competencia, item_numero, descripcion, unidad")
        .eq("id", item_id)
        .limit(1)
        .execute()
        .data
    )
    if not prev_rows:
        raise HTTPException(status_code=404, detail="Ítem no encontrado")
    prev = prev_rows[0]
    _require_contract_access(current_user, int(prev["contrato_id"]))

    if "agrupador_id" in raw:
        data["agrupador_id"] = raw["agrupador_id"]
    elif body.agrupador_nombre or body.agrupador_codigo_wbs:
        cap = (body.capitulo or "").strip()
        if not cap:
            cap = (prev.get("capitulo") or "") or ""
        cid = prev.get("contrato_id")
        if cid:
            ag_id = _resolve_agrupador_id(int(cid), cap, body)
            if ag_id is None:
                raise HTTPException(status_code=400, detail="Agrupador no encontrado para este capítulo.")
            data["agrupador_id"] = ag_id
    tipo = data.get("tipo_precio")
    if tipo == "Precio Contractual":
        data["estado_precio"] = "Aprobado"
        data["acta_fijacion"] = "Contractual"
        data["acta_modificatoria"] = None
    elif tipo == "Precio No Previsto":
        try:
            f_val = float(data.get("acta_fijacion") or 0)
            m_val = float(data.get("acta_modificatoria") or 0)
        except (ValueError, TypeError):
            f_val, m_val = 0, 0
        data["estado_precio"] = "Aprobado" if (f_val > 0 and m_val > 0) else "Pendiente"

    from listado_precios_meta import meta_fields_changed

    propuesto = {
        "item_numero": data.get("item_numero", prev.get("item_numero")),
        "descripcion": data.get("descripcion", prev.get("descripcion")),
        "unidad": data.get("unidad", prev.get("unidad")),
    }
    cambios_meta = meta_fields_changed(prev, propuesto)
    if cambios_meta and not confirm_meta:
        impacto = _listado_impacto_edicion_meta(int(item_id), campos_cambiados=cambios_meta)
        raise HTTPException(
            status_code=409,
            detail={
                "code": "confirm_meta_required",
                "message": (
                    "Cambiar ítem, descripción o unidad afecta registros de Presupuesto y SicoeObra. "
                    "Confirme el impacto antes de guardar."
                ),
                "campos_cambiados": cambios_meta,
                "impacto": impacto,
            },
        )

    old_item = (prev.get("item_numero") or "").strip()
    new_item = str(propuesto.get("item_numero") or "").strip()
    old_cap = prev.get("capitulo") or ""
    new_cap = data.get("capitulo", old_cap) or ""
    contrato_id = int(prev["contrato_id"])

    supabase.table("listado_precios").update(data).eq("id", item_id).execute()

    propagados = {"presupuesto": 0, "sicoe_registros": 0}
    if "item_numero" in cambios_meta and old_item and new_item and old_item != new_item:
        propagados = _propagar_cambio_item_numero_listado(
            contrato_id=contrato_id,
            capitulo=old_cap or new_cap,
            item_anterior=old_item,
            item_nuevo=new_item,
        )

    _dash_agg_cache_invalidate_listado(contrato_id)
    registrar_log(
        current_user,
        "EDITAR",
        "PRECIOS",
        "listado_precios",
        str(item_id),
        {
            "tipo_precio": data.get("tipo_precio"),
            "estado_precio": data.get("estado_precio"),
            "campos_meta": cambios_meta,
            "propagados": propagados,
        },
    )
    # Devolver fila actualizada para que el front no reutilice estado_precio stale del formulario.
    refreshed = (
        supabase.table("listado_precios")
        .select("*")
        .eq("id", item_id)
        .limit(1)
        .execute()
        .data
    )
    if refreshed:
        out = dict(refreshed[0])
        out["propagados"] = propagados
        out["campos_meta_cambiados"] = cambios_meta
        return out
    return {
        "ok": True,
        "id": item_id,
        "propagados": propagados,
        "campos_meta_cambiados": cambios_meta,
        **{k: data[k] for k in ("tipo_precio", "estado_precio", "acta_fijacion", "acta_modificatoria") if k in data},
    }

@app.delete("/listado-precios/item/{item_id}")
def delete_precio(item_id: int, current_user=Depends(get_current_user)):
    supabase.table("listado_precios").delete().eq("id", item_id).execute()

@app.post("/listado-precios/{contrato_id}/item")
def crear_precio(contrato_id: int, body: ListadoPrecioItem, current_user=Depends(get_current_user)):
    _require_contract_access(current_user, contrato_id)
    """Crea un ítem individual en el listado de precios con lógica de aprobación automática."""
    row = _listado_precio_row(contrato_id, body)
    result = supabase.table("listado_precios").insert(row).execute()
    nuevo = result.data[0] if result.data else {}
    registrar_log(current_user, "CREAR", "PRECIOS", "listado_precios", str(nuevo.get("id", "")),
                  {"item_numero": row.get("item_numero"), "descripcion": row.get("descripcion"),
                   "tipo_precio": row.get("tipo_precio"), "estado_precio": row.get("estado_precio")})
    return nuevo if nuevo else {"ok": True}

def _listado_precio_cant_lookup(cant_map: dict, capitulo: str, competencia: str, item_numero: str) -> float:
    """Busca cantidad agregada por capítulo/competencia/ítem (misma regla que get_precio_stats)."""
    cap_k = _dash_norm_capitulo_key_py(capitulo) if capitulo else ""
    comp_f = (competencia or "").strip()
    it_k = _dash_norm_item_key_py(item_numero)
    if comp_f:
        return float(cant_map.get((cap_k, comp_f, it_k), 0))
    total = 0.0
    for (ck, _cp, ik), val in cant_map.items():
        if ck == cap_k and ik == it_k:
            total += float(val)
    return total


@app.get("/listado-precios/{contrato_id}/cantidades")
def get_listado_precios_cantidades(contrato_id: int, current_user=Depends(get_current_user)):
    """Cantidades calculadas (presupuesto) y aprobadas (so_registros, nivel máximo) por ítem del listado."""
    _require_contract_access(current_user, contrato_id)
    items = []
    offset = 0
    while True:
        batch = (
            supabase.table("listado_precios")
            .select("id, capitulo, competencia, item_numero, precio_unitario")
            .eq("contrato_id", contrato_id)
            .order("item_numero")
            .range(offset, offset + 999)
            .execute()
            .data
        )
        items.extend(batch or [])
        if len(batch or []) < 1000:
            break
        offset += 1000

    ppto_calc: Dict[tuple, float] = defaultdict(float)
    offset = 0
    while True:
        batch = (
            supabase.table("presupuesto")
            .select("capitulo, competencia, item, cant_total")
            .eq("contrato_id", contrato_id)
            .eq("tipo_ejecucion", "Presupuesto de Obra")
            .eq("dado_de_baja", False)
            .order("id").range(offset, offset + 999)
            .execute()
            .data
        )
        for r in batch or []:
            cap_k = _dash_norm_capitulo_key_py(r.get("capitulo") or "")
            comp = (r.get("competencia") or "").strip()
            it_k = _dash_norm_item_key_py(r.get("item"))
            if not it_k:
                continue
            ppto_calc[(cap_k, comp, it_k)] += float(r.get("cant_total") or 0)
        if len(batch or []) < 1000:
            break
        offset += 1000

    so_aprob: Dict[tuple, float] = defaultdict(float)
    offset = 0
    while True:
        def _q_obra(o=offset):
            return (
                supabase.table("so_registros")
                .select(f"capitulo, competencia, item_numero, cantidad_total, {SICOE_SELECT_NIVELES_ESTADO}")
                .eq("contrato_id", contrato_id)
                .order("id").range(o, o + 999)
                .execute()
                .data
            )

        batch = supabase_execute(_q_obra) or []
        for r in batch:
            if _matriz_validacion_norm_estado_nivel_final(r, contrato_id) != "Aprobado":
                continue
            cap_k = _dash_norm_capitulo_key_py(r.get("capitulo") or "")
            comp = (r.get("competencia") or "").strip()
            it_k = _dash_norm_item_key_py(r.get("item_numero"))
            if not it_k:
                continue
            so_aprob[(cap_k, comp, it_k)] += float(r.get("cantidad_total") or 0)
        if len(batch) < 1000:
            break
        offset += 1000

    out = []
    for item in items:
        cap = item.get("capitulo") or ""
        comp = item.get("competencia") or ""
        it = item.get("item_numero") or ""
        cant_calc = _listado_precio_cant_lookup(ppto_calc, cap, comp, it)
        cant_aprob = _listado_precio_cant_lookup(so_aprob, cap, comp, it)
        pu = float(item.get("precio_unitario") or 0)
        out.append({
            "item_id": item["id"],
            "cant_calculada": round(cant_calc, 4),
            "cant_aprobada": round(cant_aprob, 4),
            "valor_calculado": round(cant_calc * pu),
            "valor_aprobado": round(cant_aprob * pu),
            "delta_cantidad": round(cant_calc - cant_aprob, 4),
            "delta_valor": round(cant_calc * pu - cant_aprob * pu),
        })
    return out


def _listado_impacto_edicion_meta(
    item_id: int,
    *,
    campos_cambiados: Optional[List[str]] = None,
) -> dict:
    """Cuenta presupuesto/Sicoe ligados al ítem y lista actas RPO / reportes afectados."""
    from listado_precios_meta import build_impacto_edicion_meta

    precio_rows = (
        supabase.table("listado_precios")
        .select("id, contrato_id, capitulo, competencia, item_numero, descripcion, unidad")
        .eq("id", int(item_id))
        .limit(1)
        .execute()
        .data
    )
    if not precio_rows:
        raise HTTPException(status_code=404, detail="Ítem no encontrado")
    precio = precio_rows[0]
    contrato_id = int(precio["contrato_id"])
    item_numero = precio.get("item_numero") or ""
    capitulo = precio.get("capitulo") or ""
    competencia = precio.get("competencia") or ""

    ppto_q = (
        supabase.table("presupuesto")
        .select("id, capitulo, competencia, item")
        .eq("contrato_id", contrato_id)
        .eq("item", item_numero)
        .eq("dado_de_baja", False)
    )
    if capitulo:
        ppto_q = ppto_q.eq("capitulo", capitulo)
    if competencia:
        ppto_q = ppto_q.eq("competencia", competencia)
    ppto_rows = ppto_q.execute().data or []

    # Fallback por clave normalizada si el match exacto no trae filas (copias con punto final, etc.).
    if not ppto_rows:
        cap_k = _dash_norm_capitulo_key_py(capitulo)
        it_k = _dash_norm_item_key_py(item_numero)
        off = 0
        while True:
            batch = (
                supabase.table("presupuesto")
                .select("id, capitulo, competencia, item")
                .eq("contrato_id", contrato_id)
                .eq("dado_de_baja", False)
                .order("id")
                .range(off, off + 999)
                .execute()
                .data
            ) or []
            for r in batch:
                if it_k and _dash_norm_item_key_py(r.get("item")) != it_k:
                    continue
                if cap_k and _dash_norm_capitulo_key_py(r.get("capitulo")) != cap_k:
                    continue
                if competencia and (r.get("competencia") or "").strip() != competencia.strip():
                    continue
                ppto_rows.append(r)
            if len(batch) < 1000:
                break
            off += 1000

    sicoe_rows: List[dict] = []
    off = 0
    cap_k = _dash_norm_capitulo_key_py(capitulo)
    it_k = _dash_norm_item_key_py(item_numero)
    comp_f = competencia.strip()
    while True:
        batch = (
            supabase.table("so_registros")
            .select("id, capitulo, competencia, item_numero, acta_rpo_id, reporte_id")
            .eq("contrato_id", contrato_id)
            .order("id")
            .range(off, off + 999)
            .execute()
            .data
        ) or []
        for r in batch:
            if it_k and _dash_norm_item_key_py(r.get("item_numero")) != it_k:
                continue
            if cap_k and _dash_norm_capitulo_key_py(r.get("capitulo")) != cap_k:
                continue
            if comp_f and (r.get("competencia") or "").strip() != comp_f:
                continue
            sicoe_rows.append(r)
        if len(batch) < 1000:
            break
        off += 1000

    acta_ids = sorted({
        int(r["acta_rpo_id"])
        for r in sicoe_rows
        if r.get("acta_rpo_id") is not None
    })
    reporte_ids = sorted({
        int(r["reporte_id"])
        for r in sicoe_rows
        if r.get("reporte_id") is not None
    })

    actas_by_id: Dict[int, dict] = {}
    for i in range(0, len(acta_ids), 200):
        chunk = acta_ids[i : i + 200]
        if not chunk:
            continue
        rows = (
            supabase.table("actas")
            .select("id, numero_rpo")
            .in_("id", chunk)
            .execute()
            .data
        ) or []
        for a in rows:
            try:
                actas_by_id[int(a["id"])] = a
            except (TypeError, ValueError, KeyError):
                continue

    reportes_by_id: Dict[int, dict] = {}
    for i in range(0, len(reporte_ids), 200):
        chunk = reporte_ids[i : i + 200]
        if not chunk:
            continue
        rows = (
            supabase.table("so_reportes")
            .select("id, numero_reporte, acta_rpo_id, estado")
            .in_("id", chunk)
            .execute()
            .data
        ) or []
        for rep in rows:
            try:
                reportes_by_id[int(rep["id"])] = rep
            except (TypeError, ValueError, KeyError):
                continue

    firmadas = _actas_rpo_firmadas_ids(contrato_id)
    return build_impacto_edicion_meta(
        precio=precio,
        ppto_rows=ppto_rows,
        sicoe_rows=sicoe_rows,
        actas_by_id=actas_by_id,
        reportes_by_id=reportes_by_id,
        firmadas_ids=firmadas,
        norm_cap=_dash_norm_capitulo_key_py,
        norm_item=_dash_norm_item_key_py,
        campos_cambiados=campos_cambiados,
    )


def _propagar_cambio_item_numero_listado(
    *,
    contrato_id: int,
    capitulo: str,
    item_anterior: str,
    item_nuevo: str,
) -> Dict[str, int]:
    """Actualiza la clave de ítem en presupuesto y so_registros tras renombrar en listado."""
    old_k = _dash_norm_item_key_py(item_anterior)
    new_item = (item_nuevo or "").strip()
    if not old_k or not new_item:
        return {"presupuesto": 0, "sicoe_registros": 0}

    n_ppto = 0
    off = 0
    cap_k = _dash_norm_capitulo_key_py(capitulo)
    while True:
        batch = (
            supabase.table("presupuesto")
            .select("id, capitulo, item")
            .eq("contrato_id", int(contrato_id))
            .order("id")
            .range(off, off + 999)
            .execute()
            .data
        ) or []
        ids = [
            int(r["id"])
            for r in batch
            if _dash_norm_item_key_py(r.get("item")) == old_k
            and (not cap_k or _dash_norm_capitulo_key_py(r.get("capitulo")) == cap_k)
        ]
        for i in range(0, len(ids), 100):
            chunk = ids[i : i + 100]
            if not chunk:
                continue
            supabase.table("presupuesto").update({"item": new_item}).in_("id", chunk).execute()
            n_ppto += len(chunk)
        if len(batch) < 1000:
            break
        off += 1000

    n_sicoe = 0
    off = 0
    while True:
        batch = (
            supabase.table("so_registros")
            .select("id, capitulo, item_numero")
            .eq("contrato_id", int(contrato_id))
            .order("id")
            .range(off, off + 999)
            .execute()
            .data
        ) or []
        ids = [
            int(r["id"])
            for r in batch
            if _dash_norm_item_key_py(r.get("item_numero")) == old_k
            and (not cap_k or _dash_norm_capitulo_key_py(r.get("capitulo")) == cap_k)
        ]
        for i in range(0, len(ids), 100):
            chunk = ids[i : i + 100]
            if not chunk:
                continue
            supabase.table("so_registros").update({"item_numero": new_item}).in_("id", chunk).execute()
            n_sicoe += len(chunk)
        if len(batch) < 1000:
            break
        off += 1000

    return {"presupuesto": n_ppto, "sicoe_registros": n_sicoe}


@app.get("/listado-precios/item/{item_id}/impacto-edicion-meta")
def get_impacto_edicion_meta_listado(
    item_id: int,
    current_user=Depends(get_current_user),
):
    """
    Impacto de editar ítem / descripción / unidad en el listado:
    conteos en Presupuesto y SicoeObra + actas RPO y reportes específicos.
    """
    precio = (
        supabase.table("listado_precios")
        .select("contrato_id")
        .eq("id", item_id)
        .limit(1)
        .execute()
        .data
    )
    if not precio:
        raise HTTPException(status_code=404, detail="Ítem no encontrado")
    _require_contract_access(current_user, int(precio[0]["contrato_id"]))
    return _listado_impacto_edicion_meta(int(item_id))


@app.get("/listado-precios/item/{item_id}/stats")
def get_precio_stats(item_id: int, current_user=Depends(get_current_user)):
    """Retorna cantidades y costos presupuestados, cobrados y balance para un ítem del listado."""
    precio = supabase.table("listado_precios").select(
        "contrato_id, capitulo, competencia, item_numero, precio_unitario"
    ).eq("id", item_id).single().execute().data
    if not precio:
        raise HTTPException(status_code=404, detail="Ítem no encontrado")
    contrato_id  = precio["contrato_id"]
    capitulo     = precio.get("capitulo") or ""
    competencia  = precio.get("competencia") or ""
    item_numero  = precio.get("item_numero") or ""
    vlr_unitario = float(precio.get("precio_unitario") or 0)
    ppto_q = supabase.table("presupuesto").select("cant_total").eq("contrato_id", contrato_id).eq("item", item_numero).eq("tipo_ejecucion", "Presupuesto de Obra").eq("dado_de_baja", False)
    if capitulo:
        ppto_q = ppto_q.eq("capitulo", capitulo)
    if competencia:
        ppto_q = ppto_q.eq("competencia", competencia)
    ppto_rows = ppto_q.execute().data or []
    cant_ppto = sum(float(r.get("cant_total") or 0) for r in ppto_rows)
    cap_k = _dash_norm_capitulo_key_py(capitulo) if capitulo else None
    comp_f = (competencia or "").strip()
    cant_cobro = 0.0
    costo_cobro = 0.0
    off_cb = 0
    it_key = _dash_norm_item_key_py(item_numero)
    while True:
        def _q_obra(o=off_cb):
            q = (
                supabase.table("so_registros")
                .select(f"capitulo, competencia, item_numero, cantidad_total, costo_directo, {SICOE_SELECT_NIVELES_ESTADO}")
                .eq("contrato_id", contrato_id)
                .order("id").range(o, o + 999)
            )
            return q.execute().data

        batch = supabase_execute(_q_obra) or []
        for r in batch:
            if _matriz_validacion_norm_estado_nivel_final(r, contrato_id) != "Aprobado":
                continue
            if cap_k and _dash_norm_capitulo_key_py(r.get("capitulo")) != cap_k:
                continue
            if comp_f and (r.get("competencia") or "").strip() != comp_f:
                continue
            if _dash_norm_item_key_py(r.get("item_numero")) != it_key:
                continue
            cant_cobro += float(r.get("cantidad_total") or 0)
        if len(batch) < 1000:
            break
        off_cb += 1000
    costo_cobro = round(cant_cobro * vlr_unitario, 0) if cant_cobro and vlr_unitario else 0.0
    costo_ppto  = round(cant_ppto * vlr_unitario, 0) if cant_ppto and vlr_unitario else 0.0
    liq_q = supabase.table("presupuesto").select("cant_total").eq("contrato_id", contrato_id).eq("item", item_numero).eq("tipo_ejecucion", "Obra Ejecutada").eq("dado_de_baja", False)
    if capitulo:
        liq_q = liq_q.eq("capitulo", capitulo)
    if competencia:
        liq_q = liq_q.eq("competencia", competencia)
    liq_rows = liq_q.execute().data or []
    cant_liq  = sum(float(r.get("cant_total") or 0) for r in liq_rows)
    costo_liq = round(cant_liq * vlr_unitario)
    return {
        "cant_presupuestada":  round(cant_ppto, 4),
        "costo_presupuestado": costo_ppto,
        "cant_cobrada":        round(cant_cobro, 4),
        "costo_cobrado":       round(costo_cobro),
        "balance_cant":        round(cant_ppto - cant_cobro, 4),
        "balance_costo":       round(costo_ppto - costo_cobro),
        "cant_liquidacion":    round(cant_liq, 4),
        "costo_liquidacion":   costo_liq,
        "balance_liq_cant":    round(cant_liq - cant_cobro, 4),
        "balance_liq_costo":   round(costo_liq - costo_cobro),
    }

def _actas_rpo_firmadas_ids(contrato_id: int) -> set:
    """Actas RPO con al menos una firma CCD registrada (costo histórico firmado)."""
    firmadas: set = set()
    try:
        rows = (
            supabase.table("ccd_firma_registro")
            .select("contexto_id")
            .eq("contrato_id", int(contrato_id))
            .eq("contexto_tipo", "acta_rpo")
            .execute()
            .data
            or []
        )
        for r in rows:
            try:
                cid = int(r.get("contexto_id"))
            except (TypeError, ValueError):
                continue
            if cid:
                firmadas.add(cid)
    except Exception:
        # Si la tabla no existe o falla la consulta, no bloquear el recálculo:
        # se tratará como sin actas firmadas detectables.
        pass
    return firmadas


def _recalc_costo_directo(cantidad, vlr_unitario: float) -> float:
    try:
        cant = float(cantidad or 0)
    except (TypeError, ValueError):
        cant = 0.0
    try:
        vlr = float(vlr_unitario or 0)
    except (TypeError, ValueError):
        vlr = 0.0
    return float(round(cant * vlr, 0))


def _row_needs_recalc_vlr_costo(row: dict, vlr_nuevo: float, cant_key: str, vlr_key: str, costo_key: str) -> bool:
    """True si el valor unitario o el costo directo no coinciden con el precio vigente."""
    try:
        vlr_actual = float(row.get(vlr_key) or 0)
    except (TypeError, ValueError):
        vlr_actual = 0.0
    costo_esperado = _recalc_costo_directo(row.get(cant_key), vlr_nuevo)
    try:
        costo_actual = float(row.get(costo_key) or 0)
    except (TypeError, ValueError):
        costo_actual = 0.0
    if abs(vlr_actual - float(vlr_nuevo)) > 0.009:
        return True
    if abs(costo_actual - costo_esperado) > 0.009:
        return True
    return False


@app.post("/listado-precios/item/{item_id}/recalcular")
def recalcular_cobros_precio(item_id: int, current_user=Depends(get_current_user)):
    """Recalcula costo_directo de registros del ítem con el precio unitario vigente.

    - Solo actualiza valor unitario y costo_directo; nunca toca cantidades.
    - Aplica a so_registros, presupuesto (no sellado) y filas de cobro del ítem.
    - Excluye so_registros / cobros ligados a actas RPO con firma CCD.
    """
    rows = (
        supabase.table("listado_precios")
        .select("id, contrato_id, capitulo, competencia, item_numero, precio_unitario, estado_precio")
        .eq("id", item_id)
        .limit(1)
        .execute()
        .data
        or []
    )
    precio = rows[0] if rows else None
    if not precio:
        raise HTTPException(status_code=404, detail="Ítem no encontrado")

    contrato_id = int(precio["contrato_id"])
    _require_contract_access(current_user, contrato_id)

    estado = str(precio.get("estado_precio") or "").strip()
    if estado != "Aprobado":
        raise HTTPException(
            status_code=400,
            detail="El precio debe estar Aprobado antes de recalcular cobros. Guarde los cambios del ítem e intente de nuevo.",
        )

    try:
        vlr_nuevo = float(precio.get("precio_unitario") or 0)
    except (TypeError, ValueError):
        vlr_nuevo = 0.0
    if vlr_nuevo <= 0:
        raise HTTPException(
            status_code=400,
            detail="El ítem no tiene un valor unitario vigente válido para recalcular.",
        )

    capitulo = (precio.get("capitulo") or "").strip()
    competencia = (precio.get("competencia") or "").strip()
    item_numero = (precio.get("item_numero") or "").strip()
    if not item_numero:
        raise HTTPException(status_code=400, detail="El ítem no tiene número de ítem para localizar registros.")

    cap_k = _dash_norm_capitulo_key_py(capitulo) if capitulo else None
    it_k = _dash_norm_item_key_py(item_numero)
    comp_f = competencia
    actas_firmadas = _actas_rpo_firmadas_ids(contrato_id)

    actualizados_sicoe = 0
    omitidos_acta_firmada = 0
    actualizados_ppto = 0
    omitidos_sellados = 0
    actualizados_cobro = 0
    sin_cambio = 0

    # ── so_registros (cobro SICOE) ───────────────────────────────────────────
    off = 0
    while True:
        def _q_so(o=off):
            return (
                supabase.table("so_registros")
                .select("id, capitulo, competencia, item_numero, cantidad_total, vlr_unitario, costo_directo, acta_rpo_id")
                .eq("contrato_id", contrato_id)
                .order("id")
                .range(o, o + 999)
                .execute()
                .data
            )

        batch = supabase_execute(_q_so) or []
        for r in batch:
            if cap_k and _dash_norm_capitulo_key_py(r.get("capitulo")) != cap_k:
                continue
            if comp_f and (r.get("competencia") or "").strip() != comp_f:
                continue
            if _dash_norm_item_key_py(r.get("item_numero")) != it_k:
                continue
            try:
                acta_id = int(r.get("acta_rpo_id")) if r.get("acta_rpo_id") is not None else None
            except (TypeError, ValueError):
                acta_id = None
            if acta_id and acta_id in actas_firmadas:
                omitidos_acta_firmada += 1
                continue
            if not _row_needs_recalc_vlr_costo(r, vlr_nuevo, "cantidad_total", "vlr_unitario", "costo_directo"):
                sin_cambio += 1
                continue
            nuevo_costo = _recalc_costo_directo(r.get("cantidad_total"), vlr_nuevo)
            supabase.table("so_registros").update(
                {"vlr_unitario": vlr_nuevo, "costo_directo": nuevo_costo}
            ).eq("id", r["id"]).eq("contrato_id", contrato_id).execute()
            actualizados_sicoe += 1
        if len(batch) < 1000:
            break
        off += 1000

    # ── presupuesto (no sellado) ─────────────────────────────────────────────
    off = 0
    while True:
        q = (
            supabase.table("presupuesto")
            .select("id, capitulo, competencia, item, cant_total, vlr_unitario, costo_directo, sellado, dado_de_baja")
            .eq("contrato_id", contrato_id)
            .eq("item", item_numero)
            .order("id")
            .range(off, off + 999)
        )
        if capitulo:
            q = q.eq("capitulo", capitulo)
        if competencia:
            q = q.eq("competencia", competencia)
        batch = q.execute().data or []
        for r in batch:
            if r.get("dado_de_baja"):
                continue
            if r.get("sellado"):
                omitidos_sellados += 1
                continue
            if not _row_needs_recalc_vlr_costo(r, vlr_nuevo, "cant_total", "vlr_unitario", "costo_directo"):
                sin_cambio += 1
                continue
            nuevo_costo = _recalc_costo_directo(r.get("cant_total"), vlr_nuevo)
            supabase.table("presupuesto").update(
                {"vlr_unitario": vlr_nuevo, "costo_directo": nuevo_costo}
            ).eq("id", r["id"]).eq("contrato_id", contrato_id).execute()
            actualizados_ppto += 1
        if len(batch) < 1000:
            break
        off += 1000

    # ── cobro (tabla histórica / importada; no fallar si no existe) ─────────
    try:
        off = 0
        firmadas_numeros: set = set()
        if actas_firmadas:
            try:
                ar = (
                    supabase.table("actas")
                    .select("id, numero_rpo")
                    .eq("contrato_id", contrato_id)
                    .in_("id", list(actas_firmadas))
                    .execute()
                    .data
                    or []
                )
                for a in ar:
                    try:
                        n = int(a.get("numero_rpo"))
                    except (TypeError, ValueError):
                        continue
                    if n:
                        firmadas_numeros.add(n)
            except Exception:
                pass
        while True:
            q = (
                supabase.table("cobro")
                .select("id, capitulo, competencia, item, cantidad, valor_unitario, costo_directo, acta")
                .eq("contrato_id", contrato_id)
                .eq("item", item_numero)
                .order("id")
                .range(off, off + 999)
            )
            if capitulo:
                q = q.eq("capitulo", capitulo)
            if competencia:
                q = q.eq("competencia", competencia)
            batch = q.execute().data or []
            for r in batch:
                try:
                    acta_n = int(r.get("acta")) if r.get("acta") is not None else None
                except (TypeError, ValueError):
                    acta_n = None
                if acta_n and acta_n in firmadas_numeros:
                    omitidos_acta_firmada += 1
                    continue
                if not _row_needs_recalc_vlr_costo(r, vlr_nuevo, "cantidad", "valor_unitario", "costo_directo"):
                    sin_cambio += 1
                    continue
                nuevo_costo = _recalc_costo_directo(r.get("cantidad"), vlr_nuevo)
                supabase.table("cobro").update(
                    {"valor_unitario": vlr_nuevo, "costo_directo": nuevo_costo}
                ).eq("id", r["id"]).eq("contrato_id", contrato_id).execute()
                actualizados_cobro += 1
            if len(batch) < 1000:
                break
            off += 1000
    except Exception as e:
        msg = str(e)
        if "cobro" in msg.lower() and ("does not exist" in msg or "PGRST" in msg):
            pass
        else:
            # No abortar el recálculo ya aplicado en so_registros/presupuesto
            try:
                _log_api.warning("recalcular cobro table: %s", msg[:240])
            except Exception:
                pass

    total = actualizados_sicoe + actualizados_ppto + actualizados_cobro
    registrar_log(
        current_user,
        "EDITAR",
        "PRECIOS",
        "listado_precios",
        str(item_id),
        {
            "accion": "recalcular_cobros",
            "precio_unitario": vlr_nuevo,
            "actualizados_sicoe": actualizados_sicoe,
            "actualizados_presupuesto": actualizados_ppto,
            "actualizados_cobro": actualizados_cobro,
            "omitidos_acta_firmada": omitidos_acta_firmada,
            "omitidos_sellados": omitidos_sellados,
            "sin_cambio": sin_cambio,
        },
    )
    return {
        "ok": True,
        "recalculados": total,
        "actualizados_sicoe": actualizados_sicoe,
        "actualizados_presupuesto": actualizados_ppto,
        "actualizados_cobro": actualizados_cobro,
        "omitidos_acta_firmada": omitidos_acta_firmada,
        "omitidos_sellados": omitidos_sellados,
        "sin_cambio": sin_cambio,
        "precio_unitario": vlr_nuevo,
    }

