@app.post("/presupuesto/{contrato_id}/agregar-cantidad")
def agregar_cantidad(contrato_id: int, body: AgregarCantidadBody, current_user=Depends(get_current_user)):
    """Inserta una nueva cantidad clonando la posición de un registro existente."""
    if not _ppto_puede_editar_nodos_y_area_long_como_dev(contrato_id, current_user):
        raise HTTPException(
            status_code=403,
            detail="Solo Desarrollador o (en el contrato autorizado) usuarios con permiso «editar registros presupuesto» pueden agregar cantidades en presupuesto.",
        )
    area  = float(body.area_long_nod or 0)
    ancho = float(body.ancho or 0)
    esp   = float(body.espesor or 0)
    vlr   = float(body.vlr_unitario or 0)
    cant  = round(area * ancho * esp, 2) if (ancho or esp) else round(area, 2)
    costo = round(cant * vlr, 0)

    # Construir nuevo id_pol: {nuevo_item}_{consecutivo}
    base = body.id_pol_base or ""
    if "._" in base:
        sufijo = base[base.index("._") + 2:]
    elif "_" in base:
        sufijo = base.rsplit("_", 1)[-1]
    else:
        sufijo = "1"
    new_id_pol = f"{body.item}_{sufijo}"

    row = {
        "contrato_id": contrato_id,
        "capitulo":      body.capitulo,
        "competencia":   body.competencia,
        "item":          body.item,
        "descripcion":   body.descripcion,
        "und":           body.und,
        "calzada":       body.calzada,
        "tramo":         body.tramo,
        "abs_inicio":    body.abs_inicio,
        "abs_final":     body.abs_final,
        "no_inicio":     body.no_inicio,
        "no_final":      body.no_final,
        "vlr_unitario":  vlr,
        "area_long_nod": body.area_long_nod,
        "ancho":         body.ancho,
        "espesor":       body.espesor,
        "cant_total":    cant,
        "costo_directo": costo,
        "tipo_ejecucion": body.tipo_ejecucion,
        "tipo_entidad":  body.tipo_entidad,
        "id_pol":        new_id_pol,
        "layer_ent":     body.layer_ent or "",
        "layer_txt":     body.layer_txt or "",
        "x_label":       body.x_label,
        "y_label":       body.y_label,
        "dado_de_baja":  False,
        "revisado":      "No Revisado",
        "pre_interv_estado": "No Revisado",
    }
    inserted = supabase.table("presupuesto").insert(row).execute().data
    if not inserted:
        raise HTTPException(status_code=500, detail="Error al insertar cantidad")
    new_row = inserted[0]

    # Encolar CAD: create_label
    try:
        supabase.table("cad_queue").insert({
            "contrato_id": contrato_id,
            "tipo":        "create_label",
            "estado":      "pendiente",
            "payload": {
                "id_pol":       new_id_pol,
                "layer_ent":    body.layer_ent or "",
                "layer_txt":    body.layer_txt or "",
                "x_label":      body.x_label,
                "y_label":      body.y_label,
                "descripcion":  body.descripcion,
                "unidad":       body.und,
                "cant_total":   cant,
                "costo_directo": costo,
            }
        }).execute()
    except Exception:
        pass

    try:
        cr = supabase.table("contratos").select("numero").eq("id", contrato_id).limit(1).execute().data
        cinfo = cr[0].get("numero") if cr else None
        u_log = {
            "sub": str(current_user.get("sub")),
            "nombre": current_user.get("nombre") or "",
            "email": current_user.get("email"),
            "cargo_nombre": current_user.get("cargo_nombre"),
            "rol_nombre": current_user.get("rol_nombre"),
            "contrato_id": contrato_id,
            "contrato_numero": cinfo,
        }
        registrar_log(
            u_log,
            "CREAR",
            "PRESUPUESTO",
            "presupuesto",
            str(new_row.get("id") or ""),
            {"id_pol": new_id_pol, "origen": "agregar_cantidad"},
            valor_nuevo=_json_for_log(new_row),
        )
    except Exception:
        pass

    return new_row


@app.post("/presupuesto/{contrato_id}/bulk")
def bulk_presupuesto(
    contrato_id: int,
    items: List[PresupuestoRow],
    mode: str = "append",
    source: Optional[str] = None,
    x_sicoe_cad_enviados: Optional[str] = Header(None, alias="X-SicoeCAD-Enviados"),
    current_user=Depends(get_current_user),
):
    """Importa registros de presupuesto. mode=replace elimina todo primero, mode=append agrega.
    Si el cliente es SicoeCAD, usar query source=sicoe_cad y opcional header X-SicoeCAD-Enviados
    (cantidad de registros leídos en el DWG) para la auditoría en la web."""
    if mode == "replace":
        supabase.table("presupuesto").delete().eq("contrato_id", contrato_id).execute()
    if not items:
        return {"insertados": 0}
    BATCH = 500
    maestro_pk = _pk_ids_ubicacion_por_codigo(contrato_id)
    tramos_corregidos = 0
    rows = []
    for item in items:
        d = {k: v for k, v in item.dict().items() if v is not None}
        d["contrato_id"] = contrato_id
        if _aplicar_ubicacion_presupuesto_desde_pk_ids(d, maestro_pk):
            tramos_corregidos += 1
        rows.append(d)
    insertados = 0
    # IDs del lote: necesarios para asociar un gráfico desde el popup de recepción (alternativa B).
    presupuesto_ids: List[int] = []
    want_lote_ids = (source or "").strip().lower() == "sicoe_cad"

    def _collect_ids(res_data) -> None:
        if not want_lote_ids or not res_data:
            return
        rows_data = res_data if isinstance(res_data, list) else [res_data]
        for r in rows_data:
            if not isinstance(r, dict):
                continue
            rid = r.get("id")
            if rid is None:
                continue
            try:
                presupuesto_ids.append(int(rid))
            except (TypeError, ValueError):
                pass

    for i in range(0, len(rows), BATCH):
        batch = rows[i : i + BATCH]
        try:
            # supabase-py 2.x: insert() no encadena .select(); returning=representation por defecto.
            res = supabase.table("presupuesto").insert(batch).execute()
            insertados += len(batch)
            _collect_ids(getattr(res, "data", None))
        except Exception:
            for row in batch:
                try:
                    res = supabase.table("presupuesto").insert(row).execute()
                    insertados += 1
                    _collect_ids(getattr(res, "data", None))
                except Exception:
                    pass
    try:
        _invalidate_dashboard_financial_caches(contrato_id)
    except Exception:
        pass
    registrar_log(current_user, "IMPORTAR", "PRESUPUESTO", "presupuesto_bulk", str(contrato_id),
        {"contrato_id": contrato_id, "mode": mode, "registros_insertados": insertados,
         "tramos_corregidos_desde_pk_ids": tramos_corregidos,
         "source": (source or "").lower() or None})
    if want_lote_ids:
        enviados = None
        h = (x_sicoe_cad_enviados or "").strip()
        if h.isdigit():
            enviados = int(h)
        _sicoe_cad_sincro_audit[contrato_id] = {
            "insertados": insertados,
            "enviados": enviados,
            "ts": time.time(),
            # Solo el usuario que ejecutó el POST /bulk ve el aviso en la web (JWT sub).
            "user_sub": str(current_user.get("sub") or ""),
            # IDs del lote recién insertado → asociar gráfico a todo el lote desde el popup.
            "presupuesto_ids": presupuesto_ids,
        }
        return {
            "insertados": insertados,
            "tramos_corregidos_desde_pk_ids": tramos_corregidos,
            "presupuesto_ids": presupuesto_ids,
        }
    return {"insertados": insertados, "tramos_corregidos_desde_pk_ids": tramos_corregidos}


def _text_similarity_best(needle: Optional[str], choices: List[str]) -> Tuple[Optional[str], float]:
    """Devuelve la cadena de `choices` más parecida a `needle` (SequenceMatcher), o (None, 0)."""
    if not choices:
        return None, 0.0
    n = (needle or "").strip().lower()
    if not n:
        return choices[0], 0.0
    best: Optional[str] = None
    best_r = -1.0
    for c in choices:
        s = (c or "").strip()
        if not s:
            continue
        r = difflib.SequenceMatcher(None, n, s.lower()).ratio()
        if r > best_r:
            best_r, best = r, c
    return best, best_r


def _float_eq_presupuesto_import(a: float, b: float) -> bool:
    return math.isclose(float(a), float(b), rel_tol=0.0, abs_tol=1e-4)


def _fetch_listado_precios_validacion(contrato_id: int) -> List[dict]:
    all_rows: List[dict] = []
    offset = 0
    while True:
        batch = (
            supabase.table("listado_precios")
            .select("id, capitulo, competencia, item_numero, descripcion, unidad, precio_unitario")
            .eq("contrato_id", contrato_id)
            .order("item_numero")
            .range(offset, offset + 999)
            .execute()
            .data
            or []
        )
        all_rows.extend(batch)
        if len(batch) < 1000:
            break
        offset += 1000
    return all_rows


@app.post("/presupuesto/{contrato_id}/bulk-validar")
def bulk_presupuesto_validar_listado(
    contrato_id: int,
    items: List[PresupuestoRow],
    current_user=Depends(get_current_user),
):
    """
    Valida un payload igual a POST /presupuesto/.../bulk contra listado_precios del contrato
    (cruce item ↔ item_numero por capítulo normalizado). No inserta filas.
    """
    _require_contract_access(current_user, contrato_id)
    listado_rows = _fetch_listado_precios_validacion(contrato_id)
    cap_norm_to_display: Dict[str, str] = {}
    for r in listado_rows:
        ck = _dash_norm_capitulo_key_py(r.get("capitulo"))
        if ck not in cap_norm_to_display:
            cap_norm_to_display[ck] = (r.get("capitulo") or "")
    caps_display_unique = list(cap_norm_to_display.values())

    by_cap_item: Dict[Tuple[str, str], dict] = {}
    for r in listado_rows:
        ck = _dash_norm_capitulo_key_py(r.get("capitulo"))
        ik = _dash_norm_item_key_py(r.get("item_numero"))
        if not ik:
            continue
        key = (ck, ik)
        if key not in by_cap_item:
            by_cap_item[key] = r

    discrepancias: List[dict] = []

    for fila_index, prow in enumerate(items):
        cap_rec = prow.capitulo
        item_rec = prow.item
        cap_k = _dash_norm_capitulo_key_py(cap_rec)
        item_k = _dash_norm_item_key_py(item_rec)

        LP: Optional[dict] = by_cap_item.get((cap_k, item_k))
        cap_sug_fuzzy = ""
        item_sug_fuzzy = ""

        if LP is None:
            rows_cap = [r for r in listado_rows if _dash_norm_capitulo_key_py(r.get("capitulo")) == cap_k]
            if rows_cap:
                cap_sug_fuzzy = rows_cap[0].get("capitulo") or ""
                for r in rows_cap:
                    if _dash_norm_item_key_py(r.get("item_numero")) == item_k:
                        LP = r
                        break
                if LP is None:
                    cands_it = sorted(
                        {str(r.get("item_numero") or "").strip() for r in rows_cap if str(r.get("item_numero") or "").strip()}
                    )
                    sug_it, _ = _text_similarity_best(item_rec or "", list(cands_it))
                    item_sug_fuzzy = sug_it or ""
                    if sug_it:
                        for r in rows_cap:
                            if _dash_norm_item_key_py(r.get("item_numero")) == _dash_norm_item_key_py(sug_it):
                                LP = r
                                break
            else:
                best_cap, _ = _text_similarity_best(cap_rec or "", caps_display_unique)
                cap_sug_fuzzy = best_cap or ""
                cap_k2 = _dash_norm_capitulo_key_py(cap_sug_fuzzy)
                rows_sug = [r for r in listado_rows if _dash_norm_capitulo_key_py(r.get("capitulo")) == cap_k2]
                if rows_sug:
                    for r in rows_sug:
                        if _dash_norm_item_key_py(r.get("item_numero")) == item_k:
                            LP = r
                            item_sug_fuzzy = r.get("item_numero") or ""
                            break
                    if LP is None:
                        cands_it = sorted(
                            {
                                str(r.get("item_numero") or "").strip()
                                for r in rows_sug
                                if str(r.get("item_numero") or "").strip()
                            }
                        )
                        sug_it, _ = _text_similarity_best(item_rec or "", list(cands_it))
                        item_sug_fuzzy = sug_it or ""
                        if sug_it:
                            for r in rows_sug:
                                if _dash_norm_item_key_py(r.get("item_numero")) == _dash_norm_item_key_py(sug_it):
                                    LP = r
                                    break

        if LP is not None:
            capitulo_sugerido = LP.get("capitulo") or ""
            item_sugerido = LP.get("item_numero") or ""
            descripcion_correcta = (LP.get("descripcion") or "").strip()
            unidad_correcta = (LP.get("unidad") or "").strip()
            try:
                vlr_unitario_correcto = float(LP.get("precio_unitario") or 0)
            except (TypeError, ValueError):
                vlr_unitario_correcto = 0.0
        else:
            capitulo_sugerido = cap_sug_fuzzy or ""
            item_sugerido = item_sug_fuzzy or ""
            descripcion_correcta = ""
            unidad_correcta = ""
            vlr_unitario_correcto = 0.0

        try:
            vlr_unitario_recibido = float(prow.vlr_unitario) if prow.vlr_unitario is not None else 0.0
        except (TypeError, ValueError):
            vlr_unitario_recibido = 0.0

        requiere_recalculo = False
        if LP is not None and not _float_eq_presupuesto_import(vlr_unitario_recibido, vlr_unitario_correcto):
            requiere_recalculo = True

        if LP is None:
            tiene_fila = True
        else:
            cap_ok = _dash_norm_capitulo_key_py(cap_rec) == _dash_norm_capitulo_key_py(LP.get("capitulo"))
            item_ok = _dash_norm_item_key_py(item_rec) == _dash_norm_item_key_py(LP.get("item_numero"))
            desc_ok = (prow.descripcion or "").strip() == (LP.get("descripcion") or "").strip()
            und_ok = (prow.und or "").strip() == (LP.get("unidad") or "").strip()
            vlr_ok = _float_eq_presupuesto_import(vlr_unitario_recibido, vlr_unitario_correcto)
            tiene_fila = not (cap_ok and item_ok and desc_ok and und_ok and vlr_ok)

        if not tiene_fila:
            continue

        discrepancias.append(
            {
                "fila_index": fila_index,
                "capitulo_recibido": cap_rec or "",
                "capitulo_sugerido": capitulo_sugerido,
                "item_recibido": item_rec or "",
                "item_sugerido": item_sugerido,
                "descripcion_recibida": (prow.descripcion or "").strip(),
                "descripcion_correcta": descripcion_correcta,
                "unidad_recibida": (prow.und or "").strip(),
                "unidad_correcta": unidad_correcta,
                "vlr_unitario_recibido": vlr_unitario_recibido,
                "vlr_unitario_correcto": float(vlr_unitario_correcto),
                "requiere_recalculo": requiere_recalculo,
            }
        )

    return {
        "tiene_discrepancias": len(discrepancias) > 0,
        "discrepancias": discrepancias,
    }


@app.get("/presupuesto/{contrato_id}/sincro-sicoe-cad-auditoria")
def presupuesto_sincro_sicoe_cad_pendiente(contrato_id: int, current_user=Depends(get_current_user)):
    """Aviso para la web: última importación de cantidades por SicoeCAD (sinc. con cola CAD / DWG)."""
    e = _sicoe_cad_sincro_audit.get(contrato_id)
    if not e:
        return {"pendiente": None}
    who = str(current_user.get("sub") or "")
    stored = str(e.get("user_sub") or "")
    # Entradas antiguas sin user_sub: no notificar a nadie (evita spam a toda la mesa).
    if not stored or stored != who:
        return {"pendiente": None}
    if time.time() - e["ts"] > 600:
        _sicoe_cad_sincro_audit.pop(contrato_id, None)
        return {"pendiente": None}
    vis = {k: v for k, v in e.items() if k != "user_sub"}
    return {"pendiente": vis}


@app.post("/presupuesto/{contrato_id}/sincro-sicoe-cad-auditoria/ack")
def presupuesto_sincro_sicoe_cad_ack(contrato_id: int, current_user=Depends(get_current_user)):
    e = _sicoe_cad_sincro_audit.get(contrato_id)
    who = str(current_user.get("sub") or "")
    if e and str(e.get("user_sub") or "") == who:
        _sicoe_cad_sincro_audit.pop(contrato_id, None)
    return {"ok": True}

@app.put("/presupuesto/{contrato_id}/bulk-recalcular")
def bulk_recalcular(contrato_id: int, body: PresupuestoBulkRecalc, current_user=Depends(get_current_user)):
    if not body.ids:
        raise HTTPException(status_code=400, detail="No hay registros seleccionados")
    _reject_if_presupuesto_sellado(supabase, body.ids)
    # Área/long/nodo: Desarrollador o contrato autorizado con matriz editar presupuesto
    has_area_change = any(d.area_long_nod is not None for d in (body.dims or []))
    if has_area_change and not _ppto_puede_editar_nodos_y_area_long_como_dev(contrato_id, current_user):
        raise HTTPException(
            status_code=403,
            detail="No tiene permiso para modificar Área/Long/Nodo en recálculo masivo (requiere Desarrollador o permiso en contrato autorizado).",
        )
    dims_map = {d.id: d for d in (body.dims or [])}
    # Traer también handles, layers e id_pol para cad_queue y reconstrucción de id_pol
    rows = supabase.table("presupuesto").select(
        "id, area_long_nod, ancho, espesor, cant_total, vlr_unitario, ent_handle, txt_handle, layer_ent, layer_txt, color_hex, competencia, id_pol"
    ).in_("id", body.ids).execute().data

    for r in rows:
        dim = dims_map.get(r["id"])
        if not dim:
            continue
        patch = {}
        if dim.area_long_nod is not None:
            patch["area_long_nod"] = dim.area_long_nod
        if dim.ancho is not None:
            patch["ancho"] = dim.ancho
        if dim.espesor is not None:
            patch["espesor"] = dim.espesor
        if patch:
            _ppto_validar_edicion_dimensiones(contrato_id, r, patch)

    ts          = datetime.now(timezone.utc).isoformat()
    calculo_por = _calculo_usuario_label(current_user)

    # Paso 1: calcular todos los payloads en memoria (sin tocar la BD)
    batch_ppto   = []   # para upsert en una sola llamada
    batch_cad    = []   # para insert en una sola llamada

    for r in rows:
        rid = r["id"]
        dim = dims_map.get(rid)
        vlr = body.vlr_unitario if body.vlr_unitario is not None else (r.get("vlr_unitario") or 0)
        vlr = float(vlr) if vlr is not None else 0.0
        if dim and (
            dim.ancho is not None
            or dim.espesor is not None
            or dim.area_long_nod is not None
        ):
            area = float(dim.area_long_nod) if dim.area_long_nod is not None else float(r.get("area_long_nod") or 0)
            ancho = float(dim.ancho) if dim.ancho is not None else float(r.get("ancho") or 0)
            espesor = float(dim.espesor) if dim.espesor is not None else float(r.get("espesor") or 0)
            cant = round(area * ancho * espesor, 2) if (ancho or espesor) else round(area, 2)
            costo = round(cant * vlr, 0)
            data = {
                "area_long_nod": area, "ancho": ancho, "espesor": espesor,
                "cant_total": cant, "costo_directo": costo,
                "updated_at": ts, "calculo_por": calculo_por, "calculo_en": ts,
            }
        else:
            ancho   = (dim.ancho   if dim and dim.ancho   is not None else None) or r.get("ancho")   or 1
            espesor = (dim.espesor if dim and dim.espesor is not None else None) or r.get("espesor") or 1
            area    = r.get("area_long_nod") or 0
            if dim and (dim.ancho is not None or dim.espesor is not None):
                cant = round(float(area) * float(ancho) * float(espesor), 2)
                data_ancho = {"ancho": ancho, "espesor": espesor}
            else:
                cant = r.get("cant_total") or 0
                data_ancho = {}
            costo = round(float(cant) * vlr, 0)
            data  = {
                "cant_total": cant, "costo_directo": costo,
                "updated_at": ts, "calculo_por": calculo_por, "calculo_en": ts,
                **data_ancho,
            }
        # Capitulo/item: valor por fila (dim) tiene prioridad sobre el valor global del body
        cap_eff  = (dim.capitulo if dim and dim.capitulo is not None else None) or body.capitulo
        item_eff = (dim.item     if dim and dim.item     is not None else None) or body.item
        if cap_eff  is not None: data["capitulo"]    = cap_eff
        if item_eff is not None: data["item"]        = item_eff
        if body.descripcion  is not None: data["descripcion"]  = body.descripcion
        if body.vlr_unitario is not None: data["vlr_unitario"] = body.vlr_unitario

        new_id_pol = None
        if item_eff is not None:
            old_id_pol = r.get("id_pol") or ""
            sufijo = old_id_pol[old_id_pol.index("._"):] if "._" in old_id_pol else f"._{rid}"
            new_id_pol = f"{item_eff}{sufijo}"
            data["id_pol"] = new_id_pol

        batch_ppto.append({"id": rid, **data})

        if cap_eff is not None or item_eff is not None:
            nuevo_cap  = cap_eff  or ""
            nuevo_item = item_eff or ""
            comp       = r.get("competencia") or ""
            cap6       = nuevo_cap.replace(".", "")[:5]
            new_layer_ent = f"{cap6}_{comp}_{nuevo_item}"
            new_layer_txt = f"txt_{cap6}_{comp}_{nuevo_item}"
            payload_cad = {
                "ent_handle": r.get("ent_handle") or "",
                "txt_handle": r.get("txt_handle") or "",
                "layer_ent":  new_layer_ent,
                "layer_txt":  new_layer_txt,
                "color_hex":  r.get("color_hex") or "",
            }
            if new_id_pol:
                payload_cad["new_text"] = new_id_pol
            batch_cad.append({
                "contrato_id": contrato_id,
                "tipo": "cambiar_layer",
                "estado": "pendiente",
                "payload": payload_cad,
            })

    # Paso 2: updates secuenciales (ThreadPoolExecutor agota el pool de conexiones de Supabase)
    # El optimistic update del frontend hace que la UI sea instantánea de todas formas
    for item in batch_ppto:
        rid  = item["id"]
        data = {k: v for k, v in item.items() if k != "id"}
        supabase.table("presupuesto").update(data).eq("id", rid).execute()
    if batch_cad:
        supabase.table("cad_queue").insert(batch_cad).execute()

    rows_by_id = {int(r["id"]): r for r in rows}
    audit_filas: List[Tuple[dict, dict]] = []
    for item in batch_ppto:
        rid = int(item["id"])
        prev = rows_by_id.get(rid)
        if not prev:
            continue
        patch = {k: v for k, v in item.items() if k != "id"}
        audit_filas.append((prev, {**prev, **patch}))
    det_bulk = {
        "contrato_id": contrato_id,
        "cantidad_registros": len(rows),
        "capitulo": body.capitulo,
        "item": body.item,
    }
    _registrar_logs_presupuesto_por_fila(current_user, "EDITAR", audit_filas, det_bulk)
    registrar_log(current_user, "RECALCULAR", "PRESUPUESTO", "presupuesto_bulk", str(contrato_id), det_bulk)
    return {"actualizados": len(rows)}

@app.put("/presupuesto/{contrato_id}/bulk-estado")
def bulk_estado(contrato_id: int, body: PresupuestoBulkEstado, current_user=Depends(get_current_user)):
    if not body.ids:
        raise HTTPException(status_code=400, detail="No hay registros seleccionados")
    if not _es_desarrollador(current_user) and not _cargo_permiso_validar_presupuesto(
        current_user, contrato_id
    ):
        raise HTTPException(
            status_code=403,
            detail="No tiene permiso de validación en «editar registros presupuesto» (matriz de accesos).",
        )
    # Traer sellado, pre_interv y datos CAD
    rows_info = supabase.table("presupuesto").select(
        "id, id_pol, x_label, y_label, layer_txt, rev_block_handle, sellado, pre_interv_estado, revisado, validado_por, validado_en"
    ).in_("id", body.ids).execute().data or []
    info_map = {r["id"]: r for r in rows_info}
    if any(r.get("sellado") for r in rows_info):
        raise HTTPException(
            status_code=403,
            detail="Registro sellado (aprobado por Interventoría): no puede modificarse.",
        )
    rol_l = (current_user.get("rol_nombre") or "").strip().lower()
    es_perfil_interventoria = rol_l in ("interventoría", "interventoria", "operativo interventoria")
    if es_perfil_interventoria:
        for rid in body.ids:
            row = info_map.get(rid) or {}
            if not _pre_interv_liberado(row):
                raise HTTPException(
                    status_code=403,
                    detail="El registro debe estar aprobado en depuración contratista (Residente de Costos u Obra) antes de la validación de Interventoría.",
                )
    es_interventoria_sellar = rol_l in ("interventoría", "interventoria") or (
        "intervent" in rol_l and "gerencial" in rol_l
    )
    sellar = body.revisado == "Aprobado" and es_interventoria_sellar
    nombre_usuario = current_user.get("nombre") or current_user.get("email") or "Usuario"
    data_upd = {"revisado": body.revisado, "updated_at": "now()"}
    if sellar:
        data_upd["sellado"] = True
    elif body.revisado != "Aprobado":
        data_upd["sellado"] = False
    if body.revisado == "Aprobado":
        data_upd["validado_por"] = nombre_usuario
        data_upd["validado_en"]  = datetime.utcnow().isoformat()
    else:
        data_upd["validado_por"] = None
        data_upd["validado_en"]  = None
    # Una sola query batch en lugar de N queries secuenciales
    supabase.table("presupuesto").update(data_upd).in_("id", body.ids).execute()
    try:
        _invalidate_dashboard_financial_caches(contrato_id)
    except Exception:
        pass
    det_bulk = {"contrato_id": contrato_id, "cantidad_registros": len(body.ids), "estado": body.revisado}
    audit_filas = []
    for r in rows_info:
        prev = dict(r)
        nuevo = {
            **prev,
            "revisado": body.revisado,
            "sellado": data_upd.get("sellado", prev.get("sellado")),
            "validado_por": data_upd.get("validado_por"),
            "validado_en": data_upd.get("validado_en"),
        }
        audit_filas.append((prev, nuevo))
    _registrar_logs_presupuesto_por_fila(current_user, "VALIDAR", audit_filas, det_bulk)
    registrar_log(current_user, "VALIDAR", "PRESUPUESTO", "presupuesto_bulk", str(contrato_id), det_bulk)
    try:
        from presupuesto_version_biblioteca import sincronizar_validacion_desde_presupuesto_vivo

        n_sync = sincronizar_validacion_desde_presupuesto_vivo(
            supabase,
            contrato_id,
            body.ids,
            {
                "revisado": body.revisado,
                "validado_por": data_upd.get("validado_por"),
                "validado_en": data_upd.get("validado_en"),
            },
        )
        if n_sync:
            logging.getLogger(__name__).info(
                "sync validación vivo→versiones: contrato=%s ids=%s sincronizados=%s",
                contrato_id,
                body.ids,
                n_sync,
            )
    except Exception as exc:
        logging.getLogger(__name__).warning(
            "sync validación vivo→versiones falló contrato=%s ids=%s: %s",
            contrato_id,
            body.ids,
            exc,
            exc_info=True,
        )
    return {"actualizados": len(body.ids)}


@app.put("/presupuesto/{contrato_id}/bulk-pre-interv")
def bulk_pre_interv(contrato_id: int, body: PresupuestoBulkPreInterv, current_user=Depends(get_current_user)):
    """Depuración contratista: Residente de Costos u Obra aprueba antes de que Interventoría vea/valide."""
    if not body.ids:
        raise HTTPException(status_code=400, detail="No hay registros seleccionados")
    _reject_if_presupuesto_sellado(supabase, body.ids)
    ESTADOS_PRE = {"No Revisado", "Pendiente", "Rechazado", "Aprobado"}
    if body.estado not in ESTADOS_PRE:
        raise HTTPException(status_code=422, detail=f"Estado inválido. Use: {ESTADOS_PRE}")
    rol = (current_user.get("rol_nombre") or "").strip().lower()
    cargo = (current_user.get("cargo_nombre") or "").strip().lower()
    es_dev = cargo == "desarrollador" or rol == "desarrollador"
    if not es_dev:
        if not _usuario_puede_depuracion_presupuesto(current_user, contrato_id):
            raise HTTPException(
                status_code=403,
                detail=(
                    "No tiene permiso para depuración masiva. Requiere la acción «validar» "
                    "en «editar registros presupuesto» (matriz de accesos)."
                ),
            )
    nombre_usuario = current_user.get("nombre") or current_user.get("email") or "Usuario"
    rows_prev = (
        supabase.table("presupuesto")
        .select("id, id_pol, pre_interv_estado, pre_interv_por, pre_interv_en")
        .in_("id", body.ids)
        .execute()
        .data
        or []
    )
    data_upd = {"pre_interv_estado": body.estado, "updated_at": "now()"}
    if body.estado == "Aprobado":
        data_upd["pre_interv_por"] = nombre_usuario
        data_upd["pre_interv_en"] = datetime.utcnow().isoformat()
    else:
        data_upd["pre_interv_por"] = None
        data_upd["pre_interv_en"] = None
    # Una sola query batch en lugar de N queries secuenciales
    supabase.table("presupuesto").update(data_upd).in_("id", body.ids).execute()
    try:
        _invalidate_dashboard_financial_caches(contrato_id)
    except Exception:
        pass
    det_bulk = {"contrato_id": contrato_id, "cantidad_registros": len(body.ids), "estado": body.estado}
    audit_filas = [(dict(r), {**dict(r), **data_upd}) for r in rows_prev]
    _registrar_logs_presupuesto_por_fila(current_user, "VALIDAR", audit_filas, det_bulk)
    registrar_log(
        current_user, "VALIDAR", "PRESUPUESTO", "presupuesto_pre_interv", str(contrato_id), det_bulk,
    )
    try:
        from presupuesto_version_biblioteca import sincronizar_validacion_desde_presupuesto_vivo

        n_sync = sincronizar_validacion_desde_presupuesto_vivo(
            supabase,
            contrato_id,
            body.ids,
            {
                "pre_interv_estado": body.estado,
                "pre_interv_por": data_upd.get("pre_interv_por"),
                "pre_interv_en": data_upd.get("pre_interv_en"),
            },
        )
        if n_sync:
            logging.getLogger(__name__).info(
                "sync depuración vivo→versiones: contrato=%s ids=%s sincronizados=%s",
                contrato_id,
                body.ids,
                n_sync,
            )
    except Exception as exc:
        logging.getLogger(__name__).warning(
            "sync depuración vivo→versiones falló contrato=%s ids=%s: %s",
            contrato_id,
            body.ids,
            exc,
            exc_info=True,
        )
    return {"actualizados": len(body.ids)}


@app.put("/presupuesto/{contrato_id}/bulk-tipo-ejecucion")
def bulk_tipo_ejecucion(contrato_id: int, body: PresupuestoBulkTipoEjecucion, current_user=Depends(get_current_user)):
    """Cambia tipo_ejecucion (Presupuesto de Obra / Obra Ejecutada) en lote."""
    _require_contract_access(current_user, contrato_id)
    if not body.ids:
        raise HTTPException(status_code=400, detail="No hay registros seleccionados")
    if not _es_desarrollador(current_user) and not _cargo_permiso_editar_registros_presupuesto(
        current_user, contrato_id
    ):
        raise HTTPException(status_code=403, detail="No tiene permiso para editar registros de presupuesto.")
    te = str(body.tipo_ejecucion or "").strip()
    if te not in ("Presupuesto de Obra", "Obra Ejecutada"):
        raise HTTPException(status_code=422, detail="tipo_ejecucion debe ser «Presupuesto de Obra» u «Obra Ejecutada».")
    _reject_if_presupuesto_sellado(supabase, body.ids)
    rows = (
        supabase.table("presupuesto")
        .select("id, contrato_id, id_pol, tipo_ejecucion")
        .in_("id", body.ids)
        .execute()
        .data
        or []
    )
    ids_ok = [int(r["id"]) for r in rows if int(r.get("contrato_id") or 0) == int(contrato_id)]
    if not ids_ok:
        raise HTTPException(status_code=400, detail="Ningún registro válido para este contrato.")
    rows_ok = [r for r in rows if int(r["id"]) in ids_ok]
    supabase.table("presupuesto").update({"tipo_ejecucion": te, "updated_at": "now()"}).in_("id", ids_ok).execute()
    try:
        _invalidate_dashboard_financial_caches(contrato_id)
    except Exception:
        pass
    det_bulk = {"contrato_id": contrato_id, "cantidad_registros": len(ids_ok), "tipo_ejecucion": te}
    audit_filas = [(dict(r), {**dict(r), "tipo_ejecucion": te}) for r in rows_ok]
    _registrar_logs_presupuesto_por_fila(current_user, "EDITAR", audit_filas, det_bulk)
    registrar_log(
        current_user,
        "EDITAR",
        "PRESUPUESTO",
        "presupuesto_bulk_tipo_ejecucion",
        str(contrato_id),
        det_bulk,
    )
    return {"actualizados": len(ids_ok), "tipo_ejecucion": te}


@app.put("/presupuesto/{contrato_id}/bulk-observacion")
def bulk_observacion_externa(
    contrato_id: int, body: PresupuestoBulkObservacion, current_user=Depends(get_current_user)
):
    """Actualiza observacion_externa en lote (edición masiva presupuesto)."""
    _require_contract_access(current_user, contrato_id)
    if not body.ids:
        raise HTTPException(status_code=400, detail="No hay registros seleccionados")
    texto = str(body.observacion_externa or "").strip()
    if not texto:
        raise HTTPException(status_code=422, detail="observacion_externa no puede estar vacía.")
    modo = str(body.modo or "replace").strip().lower()
    if modo not in ("append", "replace"):
        raise HTTPException(status_code=422, detail="modo debe ser 'append' o 'replace'.")
    if not _es_desarrollador(current_user) and not _cargo_permiso_editar_registros_presupuesto(
        current_user, contrato_id
    ):
        raise HTTPException(status_code=403, detail="No tiene permiso para editar registros de presupuesto.")
    _reject_if_presupuesto_sellado(supabase, body.ids)
    rows = (
        supabase.table("presupuesto")
        .select("id, contrato_id, id_pol, observacion_externa")
        .in_("id", body.ids)
        .execute()
        .data
        or []
    )
    ids_ok = [int(r["id"]) for r in rows if int(r.get("contrato_id") or 0) == int(contrato_id)]
    if not ids_ok:
        raise HTTPException(status_code=400, detail="Ningún registro válido para este contrato.")
    rows_ok = [r for r in rows if int(r["id"]) in ids_ok]
    audit_filas = []
    if modo == "append":
        for r in rows_ok:
            prev = str(r.get("observacion_externa") or "").strip()
            nuevo = f"{prev}\n{texto}" if prev else texto
            supabase.table("presupuesto").update(
                {"observacion_externa": nuevo, "updated_at": "now()"}
            ).eq("id", int(r["id"])).execute()
            audit_filas.append((dict(r), {**dict(r), "observacion_externa": nuevo}))
    else:
        supabase.table("presupuesto").update(
            {"observacion_externa": texto, "updated_at": "now()"}
        ).in_("id", ids_ok).execute()
        audit_filas = [(dict(r), {**dict(r), "observacion_externa": texto}) for r in rows_ok]
    det_bulk = {"contrato_id": contrato_id, "cantidad_registros": len(ids_ok), "modo": modo}
    _registrar_logs_presupuesto_por_fila(current_user, "EDITAR", audit_filas, det_bulk)
    registrar_log(
        current_user,
        "EDITAR",
        "PRESUPUESTO",
        "presupuesto_bulk_observacion",
        str(contrato_id),
        det_bulk,
    )
    return {"actualizados": len(ids_ok), "modo": modo}


@app.put("/presupuesto/{contrato_id}/bulk-reabrir")
def bulk_reabrir_sellados(
    contrato_id: int, body: PresupuestoBulkReabrir, current_user=Depends(get_current_user)
):
    """Reabre registros sellados: sellado=false, revisado=No Revisado, comentario + notificación."""
    _require_contract_access(current_user, contrato_id)
    if not body.ids:
        raise HTTPException(status_code=400, detail="No hay registros seleccionados")
    if not _puede_reabrir_presupuesto_sellado(current_user, contrato_id):
        raise HTTPException(
            status_code=403,
            detail=(
                "No tiene permiso para reabrir registros sellados "
                "(requiere «editar registros presupuesto» con editar)."
            ),
        )
    motivo = str(body.motivo or "").strip()
    if len(motivo) < 15:
        raise HTTPException(
            status_code=400,
            detail="Debe consignar un motivo de reapertura (mínimo 15 caracteres).",
        )
    if body.destinatario_id is None:
        raise HTTPException(
            status_code=400,
            detail="Debe indicar un destinatario para notificar la reapertura.",
        )
    rows = (
        supabase.table("presupuesto")
        .select(
            "id, contrato_id, id_pol, sellado, revisado, validado_por, validado_en"
        )
        .in_("id", body.ids)
        .execute()
        .data
        or []
    )
    rows_ok = [
        r
        for r in rows
        if int(r.get("contrato_id") or 0) == int(contrato_id) and r.get("sellado")
    ]
    if not rows_ok:
        raise HTTPException(
            status_code=400,
            detail="Ningún registro sellado válido para reabrir en este contrato.",
        )
    ids_ok = [int(r["id"]) for r in rows_ok]
    patch = {
        "sellado": False,
        "revisado": "No Revisado",
        "validado_por": None,
        "validado_en": None,
        "updated_at": "now()",
    }
    supabase.table("presupuesto").update(patch).in_("id", ids_ok).execute()
    nombre_u = current_user.get("nombre") or current_user.get("email") or "Usuario"
    msg_com = f"[Reapertura tras aprobación Interventoría] {motivo}"
    try:
        supabase.table("comentarios").insert(
            [
                {
                    "presupuesto_id": rid,
                    "tipo": "validacion",
                    "mensaje": msg_com,
                    "usuario_nombre": nombre_u,
                    "parent_id": None,
                }
                for rid in ids_ok
            ]
        ).execute()
    except Exception:
        try:
            _log_api.warning("comentarios bulk-reabrir fallaron contrato_id=%s n=%s", contrato_id, len(ids_ok))
        except Exception:
            pass
    _notificar_reapertura_presupuesto(
        current_user,
        contrato_id=contrato_id,
        destinatario_id=body.destinatario_id,
        motivo=motivo,
        ids=ids_ok,
    )
    audit_filas = [
        (dict(r), {**dict(r), **{k: v for k, v in patch.items() if k != "updated_at"}})
        for r in rows_ok
    ]
    det_bulk = {
        "contrato_id": contrato_id,
        "cantidad_registros": len(ids_ok),
        "reapertura_tras_sellado": True,
        "destinatario_id": body.destinatario_id,
    }
    _registrar_logs_presupuesto_por_fila(current_user, "EDITAR", audit_filas, det_bulk)
    registrar_log(
        current_user,
        "EDITAR",
        "PRESUPUESTO",
        "presupuesto_bulk_reabrir",
        str(contrato_id),
        det_bulk,
    )
    return {"reabiertos": len(ids_ok), "ids": ids_ok}


@app.post("/presupuesto/{contrato_id}/sincronizar-vlr-unitario")
def post_presupuesto_sincronizar_vlr_unitario(
    contrato_id: int,
    capitulo: Optional[str] = None,
    capitulos: Optional[List[str]] = Query(None),
    item: Optional[str] = None,
    items: Optional[List[str]] = Query(None),
    tramo: Optional[str] = None,
    tramos: Optional[List[str]] = Query(None),
    calzada: Optional[str] = None,
    calzadas: Optional[List[str]] = Query(None),
    infraestructura: Optional[str] = None,
    infraestructuras: Optional[List[str]] = Query(None),
    competencia: Optional[str] = None,
    competencias: Optional[List[str]] = Query(None),
    und: Optional[str] = None,
    unds: Optional[List[str]] = Query(None),
    nodo_inicio: Optional[str] = None,
    nodo_final: Optional[str] = None,
    buscar: Optional[str] = None,
    id_pol: Optional[str] = None,
    pk_criterio: Optional[str] = None,
    texto: Optional[str] = None,
    abs_desde: Optional[float] = None,
    abs_hasta: Optional[float] = None,
    revisado: Optional[str] = None,
    pre_interv_estado: Optional[str] = None,
    sellado: Optional[bool] = None,
    vlr_unitario_desde: Optional[float] = None,
    vlr_unitario_hasta: Optional[float] = None,
    cant_total_desde: Optional[float] = None,
    cant_total_hasta: Optional[float] = None,
    costo_directo_desde: Optional[float] = None,
    costo_directo_hasta: Optional[float] = None,
    dado_de_baja: Optional[bool] = Query(None),
    tipo_ejecucion: Optional[str] = None,
    papelera: bool = False,
    current_user=Depends(get_current_user),
):
    """Alinea vlr_unitario y costo_directo con listado_precios (vivo + version_items).

    Requiere Desarrollador o permiso matriz «editar registros presupuesto»
    con acción crear o editar en el contrato.
    """
    if not _puede_sincronizar_vlr_unitario(current_user, contrato_id):
        raise HTTPException(
            status_code=403,
            detail=(
                "No tiene permiso para sincronizar valores unitarios "
                "(requiere Desarrollador o «editar registros presupuesto» con crear/editar)."
            ),
        )
    _require_contract_access(current_user, contrato_id)
    from presupuesto_sincronizar_vlr import sincronizar_vlr_unitario_contrato

    filtros = {
        "capitulo": capitulo,
        "capitulos": capitulos,
        "item": item,
        "items": items,
        "tramo": tramo,
        "tramos": tramos,
        "calzada": calzada,
        "calzadas": calzadas,
        "infraestructura": infraestructura,
        "infraestructuras": infraestructuras,
        "competencia": competencia,
        "competencias": competencias,
        "und": und,
        "unds": unds,
        "nodo_inicio": nodo_inicio,
        "nodo_final": nodo_final,
        "buscar": buscar,
        "id_pol": id_pol,
        "pk_criterio": pk_criterio,
        "texto": texto,
        "abs_desde": abs_desde,
        "abs_hasta": abs_hasta,
        "revisado": revisado,
        "pre_interv_estado": pre_interv_estado,
        "sellado": sellado,
        "vlr_unitario_desde": vlr_unitario_desde,
        "vlr_unitario_hasta": vlr_unitario_hasta,
        "cant_total_desde": cant_total_desde,
        "cant_total_hasta": cant_total_hasta,
        "costo_directo_desde": costo_directo_desde,
        "costo_directo_hasta": costo_directo_hasta,
        "dado_de_baja": dado_de_baja,
        "tipo_ejecucion": tipo_ejecucion,
        "papelera": papelera,
    }
    result = sincronizar_vlr_unitario_contrato(supabase, contrato_id, filtros)
    try:
        _invalidate_dashboard_financial_caches(contrato_id)
    except Exception:
        pass
    det = {"contrato_id": contrato_id, **result}
    registrar_log(
        current_user,
        "EDITAR",
        "PRESUPUESTO",
        "presupuesto_sincronizar_vlr_unitario",
        str(contrato_id),
        det,
        severidad="AUDIT",
    )
    return result


