@app.post("/admin/inicio/novedades/mejorar-texto")
def admin_inicio_novedad_mejorar_texto(
    body: InicioNovedadMejorarTexto,
    current_user=Depends(require_logs_auditoria),
):
    """Mejora la redacción del resumen con el mismo modelo que /frase-del-dia (Anthropic)."""
    raw = (body.texto or "").strip()
    if len(raw) > 8000:
        raise HTTPException(status_code=400, detail="Texto demasiado largo (máx. 8000 caracteres).")
    if not raw:
        return {"texto": ""}
    api_key = os.getenv("ANTHROPIC_API_KEY")
    if not api_key:
        return {"texto": raw, "sin_ia": True}
    try:
        res = httpx.post(
            "https://api.anthropic.com/v1/messages",
            headers={
                "x-api-key": api_key,
                "anthropic-version": "2023-06-01",
                "content-type": "application/json",
            },
            json={
                "model": "claude-haiku-4-5",
                "max_tokens": 900,
                "messages": [{
                    "role": "user",
                    "content": (
                        "Eres editor en español para avisos de una plataforma de gestión de obra (ClaraCore). "
                        "Mejora la redacción del siguiente resumen de novedad: tono claro y profesional, "
                        "sin inventar datos ni añadir información que no aparezca en el original. "
                        "Conserva listas o viñetas si las hay. "
                        "Devuelve SOLO el texto mejorado, sin título, sin comillas envolventes ni frases como \"Aquí tienes\".\n\n"
                        + raw
                    ),
                }],
            },
            timeout=35.0,
        )
        data = res.json()
        if res.status_code >= 400:
            detail = data.get("error", {}).get("message") if isinstance(data.get("error"), dict) else data
            raise HTTPException(status_code=503, detail=str(detail or "Error del proveedor IA"))
        if "content" not in data or not data["content"]:
            return {"texto": raw, "sin_ia": True}
        texto = (data["content"][0].get("text") or "").strip()
        if not texto:
            return {"texto": raw, "sin_ia": True}
        return {"texto": texto}
    except HTTPException:
        raise
    except Exception as e:
        _log_api.warning("mejorar-texto novedad: %s", e)
        return {"texto": raw, "sin_ia": True}


# ─────────────────────────────────────────────
# NOTIFICACIONES
# ─────────────────────────────────────────────

_REPORTE_ATENDIDO_ASUNTO = "Reporte atendido ✅"
_REPORTE_ATENDIDO_MENSAJE = (
    "🛟 Tu reporte fue recibido y atendido. Gracias por tomarte el tiempo de reportarlo — "
    "cada observación nos ayuda a hacer ClaraCore mejor para todos. "
    "¡Seguimos construyendo juntos!"
)
_SUGERENCIA_ANOTADA_ASUNTO = "Sugerencia anotada 💡"
_SUGERENCIA_ANOTADA_MENSAJE = (
    "💡 Tu sugerencia fue recibida y anotada. ¡Gracias! "
    "Las mejores ideas vienen de quienes usan la plataforma todos los días."
)
_SOPORTE_BOGOTA = pytz.timezone("America/Bogota")


def _soporte_es_error(row: dict) -> bool:
    asunto = (row.get("asunto") or "").strip()
    mensaje = row.get("mensaje") or ""
    return asunto.startswith("[Error]") or "── Reporte de error ──" in mensaje


def _soporte_es_sugerencia(row: dict) -> bool:
    asunto = (row.get("asunto") or "").strip()
    mensaje = row.get("mensaje") or ""
    return asunto.startswith("[Mejora]") or "── Sugerencia de mejora ──" in mensaje


def _soporte_tipo_reporte(row: dict) -> str:
    if _soporte_es_error(row):
        return "error"
    if _soporte_es_sugerencia(row):
        return "sugerencia"
    return "otro"


def _soporte_parse_urgencia(mensaje: str) -> Optional[str]:
    if not mensaje:
        return None
    for line in mensaje.splitlines():
        s = line.strip()
        if s.startswith("Criticidad:"):
            return s[11:].strip() or None
        if s.startswith("Urgencia:"):
            return s[9:].strip() or None
    return None


def _soporte_descripcion_resumen(mensaje: str, max_len: int = 220) -> str:
    if not mensaje:
        return ""
    if "── Reporte de error ──" in mensaje:
        m = re.search(r"Descripción:\s*\n([\s\S]+?)(?:\n\n|\Z)", mensaje)
        text = (m.group(1).strip() if m else mensaje).replace("\n", " ")
    elif "── Sugerencia de mejora ──" in mensaje:
        _, _, body = mensaje.partition("── Sugerencia de mejora ──")
        text = body.strip().replace("\n", " ")
    else:
        text = mensaje.strip().replace("\n", " ")
    if len(text) > max_len:
        return text[: max_len - 1] + "…"
    return text


def _parse_ts_bogota(iso_val) -> Optional[datetime]:
    if iso_val is None or iso_val == "":
        return None
    try:
        s = str(iso_val).strip().replace(" ", "T")
        if not re.search(r"[Zz]|[+-]\d{2}:", s):
            s += "Z"
        dt = datetime.fromisoformat(s.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(_SOPORTE_BOGOTA)
    except Exception:
        return None


def _es_hoy_bogota(iso_val) -> bool:
    dt = _parse_ts_bogota(iso_val)
    if not dt:
        return False
    return dt.date() == datetime.now(_SOPORTE_BOGOTA).date()


def _registrar_gestion_soporte(
    notificacion_soporte_id: int,
    estado: str,
    origen: str,
    por_nombre: str,
) -> bool:
    """Actualiza fila SOPORTE. Retorna False si no existe o ya fue gestionada."""
    try:
        rows = (
            supabase.table("notificaciones")
            .select("id, soporte_estado, tipo")
            .eq("id", notificacion_soporte_id)
            .limit(1)
            .execute()
            .data
        )
        if not rows or (rows[0].get("tipo") or "").upper() != "SOPORTE":
            return False
        if rows[0].get("soporte_estado"):
            return False
        now = datetime.now(_SOPORTE_BOGOTA)
        supabase.table("notificaciones").update(
            {
                "soporte_estado": estado,
                "soporte_gestionado_at": now.isoformat(),
                "soporte_gestionado_por_nombre": (por_nombre or "Usuario").strip() or "Usuario",
                "soporte_gestion_origen": origen,
            }
        ).eq("id", notificacion_soporte_id).execute()
        return True
    except Exception as e:
        _log_api.exception(
            "registrar_gestion_soporte falló id=%s: %s",
            notificacion_soporte_id,
            e,
        )
        return False


def _nombre_desde_telegram_callback(callback_query: Optional[dict]) -> str:
    u = (callback_query or {}).get("from") or {}
    parts = [u.get("first_name"), u.get("last_name")]
    name = " ".join(p for p in parts if p).strip()
    if name:
        return name
    un = (u.get("username") or "").strip()
    return f"@{un}" if un else "Telegram"


def _on_telegram_gestionado(notif_id: int, callback_query: Optional[dict] = None) -> None:
    nombre = _nombre_desde_telegram_callback(callback_query)
    if _registrar_gestion_soporte(notif_id, "gestionado", "telegram", nombre):
        _notificar_usuario_reporte_atendido(notif_id)


def _on_telegram_anotado(notif_id: int, callback_query: Optional[dict] = None) -> None:
    nombre = _nombre_desde_telegram_callback(callback_query)
    if _registrar_gestion_soporte(notif_id, "anotado", "telegram", nombre):
        _notificar_usuario_sugerencia_anotada(notif_id)


def _soporte_parse_campo_line(mensaje: str, prefix: str) -> Optional[str]:
    if not mensaje:
        return None
    for line in mensaje.splitlines():
        s = line.strip()
        if s.startswith(prefix):
            return s[len(prefix) :].strip() or None
    return None


def _soporte_parse_imagen_adjunta(mensaje: str) -> Optional[bool]:
    if not mensaje:
        return None
    for line in mensaje.splitlines():
        s = line.strip()
        if s.startswith("Imagen adjunta:"):
            v = s[15:].strip().lower()
            return v.startswith("sí") or v.startswith("si")
    return None


def _soporte_parse_descripcion_completa(mensaje: str) -> str:
    if not mensaje:
        return ""
    if "── Reporte de error ──" in mensaje:
        m = re.search(r"Descripción:\s*\n([\s\S]+?)(?:\n\n|\Z)", mensaje)
        return (m.group(1).strip() if m else mensaje.strip())
    if "── Sugerencia de mejora ──" in mensaje:
        _, _, body = mensaje.partition("── Sugerencia de mejora ──")
        return body.strip()
    return mensaje.strip()


def _contratos_numero_map(contrato_ids: list) -> dict:
    """Mapa id → número de contrato para enriquecer reportes SOPORTE (vista global multi-contrato)."""
    uniq = []
    seen = set()
    for raw in contrato_ids or []:
        if raw is None:
            continue
        try:
            cid = int(raw)
        except (TypeError, ValueError):
            continue
        if cid in seen:
            continue
        seen.add(cid)
        uniq.append(cid)
    if not uniq:
        return {}
    rows = (
        supabase.table("contratos")
        .select("id, numero")
        .in_("id", uniq)
        .execute()
        .data
        or []
    )
    out = {}
    for row in rows:
        rid = row.get("id")
        if rid is None:
            continue
        try:
            iid = int(rid)
        except (TypeError, ValueError):
            continue
        num = row.get("numero")
        out[iid] = str(num).strip() if num not in (None, "") else str(iid)
    return out


def _enriquecer_reportes_soporte_contratos(items: list) -> list:
    cmap = _contratos_numero_map([x.get("contrato_id") for x in (items or [])])
    for item in items or []:
        cid = item.get("contrato_id")
        if cid is None:
            continue
        try:
            iid = int(cid)
        except (TypeError, ValueError):
            item["contrato_numero"] = str(cid)
            continue
        item["contrato_numero"] = cmap.get(iid, str(iid))
    return items


def _serializar_reporte_soporte(row: dict, contrato_numero: Optional[str] = None) -> dict:
    mensaje = row.get("mensaje") or ""
    modulo_msg = _soporte_parse_campo_line(mensaje, "Módulo:")
    cid = row.get("contrato_id")
    cnum = contrato_numero
    if cnum is None and cid is not None:
        cnum = str(cid)
    return {
        "id": row.get("id"),
        "asunto": row.get("asunto"),
        "mensaje": mensaje,
        "created_at": row.get("created_at"),
        "remitente_nombre": row.get("remitente_nombre"),
        "modulo": modulo_msg or row.get("modulo"),
        "ubicacion": _soporte_parse_campo_line(mensaje, "Ubicación:"),
        "sector": _soporte_parse_campo_line(mensaje, "Sector:"),
        "contrato_id": cid,
        "contrato_numero": cnum,
        "soporte_estado": row.get("soporte_estado"),
        "soporte_gestionado_at": row.get("soporte_gestionado_at"),
        "soporte_gestionado_por_nombre": row.get("soporte_gestionado_por_nombre"),
        "soporte_gestion_origen": row.get("soporte_gestion_origen"),
        "tipo_reporte": _soporte_tipo_reporte(row),
        "urgencia": _soporte_parse_urgencia(mensaje),
        "imagen_adjunta": _soporte_parse_imagen_adjunta(mensaje),
        "descripcion_resumen": _soporte_descripcion_resumen(mensaje),
        "descripcion_completa": _soporte_parse_descripcion_completa(mensaje),
    }


def _notificar_usuario_reporte_atendido(notificacion_soporte_id: int) -> None:
    """Inserta notificación SISTEMA al usuario que reportó. Errores solo se registran."""
    try:
        rows = (
            supabase.table("notificaciones")
            .select("id, remitente_id, destinatario_id, contrato_id, modulo, tipo")
            .eq("id", notificacion_soporte_id)
            .limit(1)
            .execute()
            .data
        )
        if not rows:
            _log_api.warning(
                "reporte atendido: notificación SOPORTE %s no encontrada",
                notificacion_soporte_id,
            )
            return
        orig = rows[0]
        if (orig.get("tipo") or "").upper() != "SOPORTE":
            _log_api.warning(
                "reporte atendido: id %s no es tipo SOPORTE",
                notificacion_soporte_id,
            )
            return
        reporter_id = orig.get("remitente_id")
        if not reporter_id:
            _log_api.warning(
                "reporte atendido: SOPORTE %s sin remitente_id",
                notificacion_soporte_id,
            )
            return
        reporter_id = int(reporter_id)
        dev_id = orig.get("destinatario_id")
        contrato_id = orig.get("contrato_id")
        modulo = orig.get("modulo")

        dup = (
            supabase.table("notificaciones")
            .select("id")
            .eq("tipo", "SISTEMA")
            .eq("destinatario_id", reporter_id)
            .eq("entidad_tipo", "notificacion")
            .eq("entidad_id", str(notificacion_soporte_id))
            .limit(1)
            .execute()
            .data
        )
        if dup:
            return

        row = {
            "remitente_id": int(dev_id) if dev_id else None,
            "remitente_nombre": "ClaraCore",
            "destinatario_id": reporter_id,
            "asunto": _REPORTE_ATENDIDO_ASUNTO,
            "mensaje": _REPORTE_ATENDIDO_MENSAJE,
            "tipo": "SISTEMA",
            "modulo": modulo,
            "contrato_id": contrato_id,
            "entidad_tipo": "notificacion",
            "entidad_id": str(notificacion_soporte_id),
        }
        supabase.table("notificaciones").insert(row).execute()
    except Exception as e:
        _log_api.exception(
            "reporte atendido: fallo al notificar usuario (SOPORTE id=%s): %s",
            notificacion_soporte_id,
            e,
        )


