def _remitente_nombre_from_user(current_user) -> str:
    return (current_user.get("nombre") or current_user.get("email") or "").strip() or "Usuario"


def _resolver_contrato_notificacion(
    current_user,
    destinatario_id: Optional[int],
    contrato_id_explicit: Optional[int],
) -> Optional[int]:
    """Rellena contrato_id cuando el cliente envía null: evita que el buzón (filtrado por contrato) oculte el mensaje."""
    if contrato_id_explicit is not None:
        try:
            return int(contrato_id_explicit)
        except (TypeError, ValueError):
            pass
    try:
        uid = int(current_user.get("sub", 0))
    except (TypeError, ValueError):
        uid = 0
    if uid:
        urows = supabase.table("usuarios").select("contrato_id").eq("id", uid).limit(1).execute().data
        u = urows[0] if urows else {}
        if u.get("contrato_id") is not None:
            try:
                return int(u["contrato_id"])
            except (TypeError, ValueError):
                pass
        uc = (
            supabase.table("usuario_contratos")
            .select("contrato_id")
            .eq("usuario_id", uid)
            .limit(1)
            .execute()
            .data
        )
        if uc and uc[0].get("contrato_id") is not None:
            try:
                return int(uc[0]["contrato_id"])
            except (TypeError, ValueError):
                pass
    if destinatario_id is not None:
        try:
            did = int(destinatario_id)
        except (TypeError, ValueError):
            return None
        u2 = supabase.table("usuarios").select("contrato_id").eq("id", did).limit(1).execute().data
        u2r = u2[0] if u2 else {}
        if u2r.get("contrato_id") is not None:
            try:
                return int(u2r["contrato_id"])
            except (TypeError, ValueError):
                pass
        uc2 = (
            supabase.table("usuario_contratos")
            .select("contrato_id")
            .eq("usuario_id", did)
            .limit(1)
            .execute()
            .data
        )
        if uc2 and uc2[0].get("contrato_id") is not None:
            try:
                return int(uc2[0]["contrato_id"])
            except (TypeError, ValueError):
                pass
    return None


def _filtro_query_notif_contrato_o_nulo(q, contrato_id: Optional[int]):
    """Solo notificaciones del contrato activo (sin mezclar legacy contrato_id NULL ni otros contratos)."""
    if contrato_id is None:
        return q
    try:
        cid = int(contrato_id)
    except (TypeError, ValueError):
        return q
    return q.eq("contrato_id", cid)


def _contrato_id_efectivo_buzon(
    contrato_id: Optional[int],
    current_user,
) -> Optional[int]:
    """Contrato para listados del buzón: query param o, si falta, contrato activo del usuario.

    Nunca deja el listado sin filtro (evita mezclar notificaciones de todos los
    contratos vinculados / vistas Desarrollador sin contrato_id).
    """
    if contrato_id is not None:
        try:
            return int(contrato_id)
        except (TypeError, ValueError):
            return None
    try:
        uid = int(current_user.get("sub", 0))
    except (TypeError, ValueError):
        return None
    if not uid:
        return None
    return _usuario_contrato_id_por_user_id(uid)


def _filtro_notif_visible_buzon_recibidas(q):
    """Excluye mensajes que el destinatario ocultó de su buzón."""
    q = q.or_("oculto_destinatario.eq.false,oculto_destinatario.is.null")
    return _filtro_notif_excluir_soporte(q)


def _filtro_notif_visible_buzon_enviadas(q):
    """Excluye mensajes que el remitente ocultó de su bandeja de enviados."""
    q = q.or_("oculto_remitente.eq.false,oculto_remitente.is.null")
    return _filtro_notif_excluir_soporte(q)


def _filtro_notif_excluir_soporte(q):
    """El buzón solo muestra MENSAJE_DIRECTO, BROADCAST y SISTEMA (no reportes SOPORTE)."""
    return q.neq("tipo", "SOPORTE")


def _push_notif_validacion_sicoe_destinatarios(
    current_user,
    autor_id: int,
    contrato_id: int,
    registro_id: int,
    asunto: str,
    mensaje: str,
    comentario_data: Optional[dict],
) -> None:
    if not comentario_data:
        return
    rem_nom = _remitente_nombre_from_user(current_user)
    for dest in comentario_data.get("destinatarios") or []:
        dest_id = dest.get("id") if isinstance(dest, dict) else None
        if not dest_id:
            continue
        try:
            did = int(dest_id)
        except (TypeError, ValueError):
            continue
        if did == autor_id:
            continue
        row = {
            "destinatario_id": did,
            "remitente_id": autor_id,
            "remitente_nombre": rem_nom,
            "contrato_id": contrato_id,
            "tipo": "validacion",
            "modulo": "sicoe_obra",
            "entidad_tipo": "registro",
            "entidad_id": str(registro_id),
            "asunto": asunto,
            "mensaje": mensaje or "",
            "leido": False,
        }
        try:
            supabase_execute(lambda: supabase.table("notificaciones").insert(row).execute().data)
        except Exception as e:
            try:
                _log_api.warning(
                    "notificación SICOE validación: insert falló destinatario=%s contrato=%s reg=%s %s",
                    did,
                    contrato_id,
                    registro_id,
                    e,
                )
            except Exception:
                pass


class NotificacionCreate(BaseModel):
    destinatario_id: Optional[int] = None  # None = broadcast a todos
    asunto: str
    mensaje: str
    tipo: str = "MENSAJE_DIRECTO"  # MENSAJE_DIRECTO | BROADCAST | SISTEMA | SOPORTE
    modulo: Optional[str] = None
    contrato_id: Optional[int] = None
    entidad_tipo: Optional[str] = None
    entidad_id: Optional[str] = None
    padre_id: Optional[int] = None

@app.post("/notificaciones")
def crear_notificacion(body: NotificacionCreate, current_user=Depends(get_current_user)):
    """Envía una notificación. Si destinatario_id es None y tipo=BROADCAST, envía a todos."""
    uid = int(current_user.get("sub", 0))
    nombre = _remitente_nombre_from_user(current_user)

    if body.tipo == "BROADCAST":
        # Enviar a todos los usuarios activos excepto el remitente
        usuarios = supabase.table("usuarios").select("id").eq("activo", True).execute().data
        rows = []
        for u in usuarios:
            if u["id"] == uid:
                continue
            dest_id = int(u["id"])
            rcid = _resolver_contrato_notificacion(current_user, dest_id, body.contrato_id)
            rows.append({
                "remitente_id":     uid,
                "remitente_nombre": nombre,
                "destinatario_id":  dest_id,
                "asunto":           body.asunto,
                "mensaje":          body.mensaje,
                "tipo":             body.tipo,
                "modulo":           body.modulo,
                "contrato_id":      rcid,
                "entidad_tipo":     body.entidad_tipo,
                "entidad_id":       body.entidad_id,
                "padre_id":         body.padre_id,
            })
        if rows:
            supabase.table("notificaciones").insert(rows).execute()
        registrar_log(current_user, "BROADCAST", "NOTIFICACIONES", "notificacion", None,
            {"asunto": body.asunto, "destinatarios": len(rows)})
        return {"enviados": len(rows)}
    else:
        rcid = _resolver_contrato_notificacion(current_user, body.destinatario_id, body.contrato_id)
        row = {
            "remitente_id":     uid,
            "remitente_nombre": nombre,
            "destinatario_id":  body.destinatario_id,
            "asunto":           body.asunto,
            "mensaje":          body.mensaje,
            "tipo":             body.tipo,
            "modulo":           body.modulo,
            "contrato_id":      rcid,
            "entidad_tipo":     body.entidad_tipo,
            "entidad_id":       body.entidad_id,
            "padre_id":         body.padre_id,
        }
        result = supabase.table("notificaciones").insert(row).execute()

        # Si es respuesta, marcar el mensaje raíz como no leído para el destinatario
        if body.padre_id:
            try:
                supabase.table("notificaciones") \
                    .update({"leido": False}) \
                    .eq("id", body.padre_id) \
                    .execute()
            except: pass

        if body.tipo == "SOPORTE":
            try:
                contrato_lbl = "—"
                if rcid is not None:
                    crow = (
                        supabase.table("contratos")
                        .select("numero")
                        .eq("id", rcid)
                        .limit(1)
                        .execute()
                        .data
                    )
                    if crow and crow[0].get("numero"):
                        contrato_lbl = str(crow[0]["numero"])
                    else:
                        contrato_lbl = str(rcid)
                notif_id = result.data[0].get("id") if result.data else None
                try_send_soporte_telegram(
                    usuario_nombre=nombre,
                    contrato=contrato_lbl,
                    mensaje=body.mensaje,
                    modulo=body.modulo,
                    notificacion_id=notif_id,
                )
            except Exception:
                pass

        registrar_log(current_user, "ENVIAR", "NOTIFICACIONES", "notificacion",
            str(result.data[0]["id"]) if result.data else None,
            {"asunto": body.asunto, "destinatario_id": body.destinatario_id, "tipo": body.tipo})
        return result.data[0] if result.data else {}


class SoporteGestionBody(BaseModel):
    accion: str  # gestionado | anotado


@app.get("/admin/soporte")
def admin_soporte_list(
    filtro: str = Query("todos"),
    current_user=Depends(require_solo_desarrollador),
):
    """Panel de soporte: KPIs y listado global de reportes SOPORTE (todos los contratos).

    El Desarrollador ve reportes de cualquier contrato, sin importar el contrato activo en sesión.
    """
    del current_user
    filtro_norm = (filtro or "todos").strip().lower()

    def _q_soporte():
        return (
            supabase.table("notificaciones")
            .select(
                "id, created_at, asunto, mensaje, remitente_nombre, modulo, contrato_id, "
                "soporte_estado, soporte_gestionado_at, soporte_gestionado_por_nombre, soporte_gestion_origen"
            )
            .eq("tipo", "SOPORTE")
            .order("created_at", desc=True)
            .limit(500)
            .execute()
            .data
            or []
        )

    rows = supabase_execute(_q_soporte, retries=3, delay=0.4)
    contrato_nums = _contratos_numero_map([r.get("contrato_id") for r in rows])

    kpis = {
        "pendientes": 0,
        "errores_hoy": 0,
        "sugerencias": 0,
        "gestionados": 0,
    }
    for row in rows:
        pendiente = not row.get("soporte_estado")
        es_error = _soporte_es_error(row)
        es_sug = _soporte_es_sugerencia(row)
        if pendiente:
            kpis["pendientes"] += 1
        if row.get("soporte_estado"):
            kpis["gestionados"] += 1
        if es_error and _es_hoy_bogota(row.get("created_at")):
            kpis["errores_hoy"] += 1
        if es_sug and pendiente:
            kpis["sugerencias"] += 1

    filtrados = []
    for row in rows:
        cid = row.get("contrato_id")
        cnum = None
        if cid is not None:
            try:
                cnum = contrato_nums.get(int(cid), str(cid))
            except (TypeError, ValueError):
                cnum = str(cid)
        item = _serializar_reporte_soporte(row, contrato_numero=cnum)
        t = item["tipo_reporte"]
        gest = bool(item.get("soporte_estado"))
        if filtro_norm == "errores" and t != "error":
            continue
        if filtro_norm == "sugerencias" and t != "sugerencia":
            continue
        if filtro_norm == "gestionados" and not gest:
            continue
        filtrados.append(item)

    filtrados.sort(
        key=lambda x: (
            1 if x.get("soporte_estado") else 0,
            -( _parse_ts_bogota(x.get("created_at")) or datetime.min.replace(tzinfo=timezone.utc) ).timestamp(),
        )
    )

    return {"kpis": kpis, "reportes": filtrados}


@app.put("/admin/soporte/{notif_id}/gestionar")
def admin_soporte_gestionar(
    notif_id: int,
    body: SoporteGestionBody,
    current_user=Depends(require_solo_desarrollador),
):
    """Marca un reporte SOPORTE como gestionado o anotado desde el panel admin."""
    accion = (body.accion or "").strip().lower()
    if accion not in ("gestionado", "anotado"):
        raise HTTPException(status_code=400, detail="accion debe ser gestionado o anotado")

    rows = (
        supabase.table("notificaciones")
        .select(
            "id, tipo, asunto, mensaje, soporte_estado, remitente_id, destinatario_id, "
            "contrato_id, modulo, created_at, remitente_nombre, soporte_gestionado_at, "
            "soporte_gestionado_por_nombre, soporte_gestion_origen"
        )
        .eq("id", notif_id)
        .limit(1)
        .execute()
        .data
    )
    if not rows or (rows[0].get("tipo") or "").upper() != "SOPORTE":
        raise HTTPException(status_code=404, detail="Reporte SOPORTE no encontrado")

    row = rows[0]
    if row.get("soporte_estado"):
        return {"ok": True, "ya_gestionado": True, "reporte": _serializar_reporte_soporte(row)}

    tipo_rep = _soporte_tipo_reporte(row)
    if accion == "gestionado" and tipo_rep not in ("error", "otro"):
        raise HTTPException(status_code=400, detail="Solo los errores se marcan como gestionados")
    if accion == "anotado" and tipo_rep != "sugerencia":
        raise HTTPException(status_code=400, detail="Solo las sugerencias se marcan como anotadas")

    nombre = _remitente_nombre_from_user(current_user)
    if not _registrar_gestion_soporte(notif_id, accion, "claracore", nombre):
        raise HTTPException(status_code=409, detail="No se pudo registrar la gestión")

    if accion == "gestionado":
        try:
            _notificar_usuario_reporte_atendido(notif_id)
        except Exception:
            _log_api.exception("admin soporte: fallo notificación SISTEMA gestionado id=%s", notif_id)
    else:
        try:
            _notificar_usuario_sugerencia_anotada(notif_id)
        except Exception:
            _log_api.exception("admin soporte: fallo notificación SISTEMA anotado id=%s", notif_id)

    updated = (
        supabase.table("notificaciones")
        .select(
            "id, created_at, asunto, mensaje, remitente_nombre, modulo, contrato_id, "
            "soporte_estado, soporte_gestionado_at, soporte_gestionado_por_nombre, soporte_gestion_origen"
        )
        .eq("id", notif_id)
        .limit(1)
        .execute()
        .data
    )
    rep = _serializar_reporte_soporte(updated[0]) if updated else None
    return {"ok": True, "reporte": rep}


def _eliminar_hijas_notificacion_padre(notif_id: int) -> None:
    """Elimina respuestas/hijas con padre_id apuntando al reporte antes de borrar el padre."""
    supabase.table("notificaciones").delete().eq("padre_id", notif_id).execute()


@app.delete("/admin/soporte/limpiar")
def admin_soporte_limpiar(
    pestana: str = Query(..., description="pendientes | gestionados"),
    current_user=Depends(require_solo_desarrollador),
):
    """Elimina todos los reportes SOPORTE de la pestaña indicada (solo Desarrollador)."""
    del current_user
    pest = (pestana or "").strip().lower()
    if pest not in ("pendientes", "gestionados"):
        raise HTTPException(status_code=400, detail="pestana debe ser pendientes o gestionados")
    q = supabase.table("notificaciones").select("id").eq("tipo", "SOPORTE")
    if pest == "pendientes":
        q = q.is_("soporte_estado", "null")
    else:
        q = q.not_.is_("soporte_estado", "null")
    rows = q.execute().data or []
    ids = [int(r["id"]) for r in rows if r.get("id") is not None]
    for nid in ids:
        _eliminar_hijas_notificacion_padre(nid)
    if ids:
        supabase.table("notificaciones").delete().in_("id", ids).execute()
    return {"ok": True, "eliminados": len(ids)}


@app.delete("/admin/soporte/{notif_id}")
def admin_soporte_eliminar(
    notif_id: int,
    current_user=Depends(require_solo_desarrollador),
):
    """Elimina un reporte SOPORTE de notificaciones (solo Desarrollador)."""
    del current_user
    rows = (
        supabase.table("notificaciones")
        .select("id, tipo")
        .eq("id", notif_id)
        .limit(1)
        .execute()
        .data
    )
    if not rows or (rows[0].get("tipo") or "").upper() != "SOPORTE":
        raise HTTPException(status_code=404, detail="Reporte SOPORTE no encontrado")
    _eliminar_hijas_notificacion_padre(notif_id)
    supabase.table("notificaciones").delete().eq("id", notif_id).execute()
    return {"ok": True, "id": notif_id}


