@app.get("/notificaciones/recibidas")
def get_notificaciones_recibidas(
    solo_no_leidas: bool = False,
    limit: int = 50,
    offset: int = 0,
    contrato_id: Optional[int] = None,
    current_user=Depends(get_current_user)
):
    """Notificaciones recibidas del contrato activo (query o contrato del usuario)."""
    uid = int(current_user.get("sub", 0))
    cid = _contrato_id_efectivo_buzon(contrato_id, current_user)
    if cid is None:
        return []
    q = supabase.table("notificaciones").select("*") \
        .eq("destinatario_id", uid) \
        .order("created_at", desc=True)
    q = _filtro_query_notif_contrato_o_nulo(q, cid)
    q = _filtro_notif_visible_buzon_recibidas(q)
    if solo_no_leidas:
        q = q.eq("leido", False)
    q = q.range(offset, offset + limit - 1)
    return q.execute().data

@app.get("/notificaciones/enviadas")
def get_notificaciones_enviadas(
    limit: int = 50,
    offset: int = 0,
    contrato_id: Optional[int] = None,
    current_user=Depends(get_current_user)
):
    """Notificaciones enviadas del contrato activo (query o contrato del usuario)."""
    uid = int(current_user.get("sub", 0))
    cid = _contrato_id_efectivo_buzon(contrato_id, current_user)
    if cid is None:
        return []
    q = supabase.table("notificaciones").select("*") \
        .eq("remitente_id", uid) \
        .order("created_at", desc=True)
    q = _filtro_query_notif_contrato_o_nulo(q, cid)
    q = _filtro_notif_visible_buzon_enviadas(q)
    return q.range(offset, offset + limit - 1).execute().data

@app.get("/notificaciones/no-leidas-count")
def get_no_leidas_count(
    contrato_id: Optional[int] = None,
    current_user=Depends(get_current_user)
):
    """Conteo de no leídas (raíz) del contrato activo."""
    uid = int(current_user.get("sub", 0))
    cid = _contrato_id_efectivo_buzon(contrato_id, current_user)
    if cid is None:
        return {"count": 0}
    try:
        q = supabase.table("notificaciones").select("id", count="exact") \
            .eq("destinatario_id", uid) \
            .eq("leido", False) \
            .is_("padre_id", "null")
        q = _filtro_query_notif_contrato_o_nulo(q, cid)
        q = _filtro_notif_visible_buzon_recibidas(q)
        result = q.execute()
        return {"count": result.count or 0}
    except Exception:
        return {"count": 0}

@app.get("/notificaciones/{notif_id}/hilo")
def get_hilo(notif_id: int, current_user=Depends(get_current_user)):
    """Devuelve el hilo completo de una notificación (padre + respuestas)."""
    # Primero encontrar el padre raíz
    notif = supabase.table("notificaciones").select("*").eq("id", notif_id).execute().data
    if not notif:
        raise HTTPException(status_code=404, detail="No encontrada")
    if (notif[0].get("tipo") or "").upper() == "SOPORTE":
        raise HTTPException(status_code=404, detail="No encontrada")
    padre_id = notif[0].get("padre_id") or notif_id
    padre = supabase.table("notificaciones").select("*").eq("id", padre_id).execute().data
    if not padre or (padre[0].get("tipo") or "").upper() == "SOPORTE":
        raise HTTPException(status_code=404, detail="No encontrada")
    # Marcar como leída
    uid = int(current_user.get("sub", 0))
    supabase.table("notificaciones").update({"leido": True, "leido_at": datetime.utcnow().isoformat()}) \
        .eq("id", notif_id).eq("destinatario_id", uid).execute()
    # Traer padre + todas las respuestas
    respuestas = supabase.table("notificaciones").select("*") \
        .eq("padre_id", padre_id).order("created_at").execute().data
    hilo = [m for m in (padre + respuestas) if (m.get("tipo") or "").upper() != "SOPORTE"]
    return {"hilo": hilo}

@app.put("/notificaciones/{notif_id}/leida")
def marcar_leida(notif_id: int, current_user=Depends(get_current_user)):
    uid = int(current_user.get("sub", 0))
    supabase.table("notificaciones").update({"leido": True, "leido_at": "now()"}) \
        .eq("id", notif_id).eq("destinatario_id", uid).execute()
    return {"ok": True}


@app.put("/notificaciones/{notif_id}/ocultar")
def ocultar_notificacion_buzon(notif_id: int, current_user=Depends(get_current_user)):
    """Oculta la notificación solo en el buzón del usuario (no borra la fila)."""
    uid = int(current_user.get("sub", 0))
    rows = (
        supabase.table("notificaciones")
        .select("id, destinatario_id, remitente_id, tipo")
        .eq("id", notif_id)
        .limit(1)
        .execute()
        .data
    )
    if not rows or (rows[0].get("tipo") or "").upper() == "SOPORTE":
        raise HTTPException(status_code=404, detail="No encontrada")
    row = rows[0]
    patch = {}
    if row.get("destinatario_id") == uid:
        patch["oculto_destinatario"] = True
    if row.get("remitente_id") == uid:
        patch["oculto_remitente"] = True
    if not patch:
        raise HTTPException(status_code=403, detail="Sin permiso para ocultar esta notificación")
    supabase.table("notificaciones").update(patch).eq("id", notif_id).execute()
    return {"ok": True}


@app.get("/notificaciones/usuarios-destinatarios")
def get_usuarios_destinatarios(
    contrato_id: Optional[int] = Query(None, description="Acota destinatarios a este contrato (recomendado)"),
    current_user=Depends(get_current_user),
):
    """Usuarios activos del contrato para el selector de destinatario. No devuelve toda la plataforma."""
    uid = int(current_user.get("sub", 0))
    urow = supabase.table("usuarios").select("contrato_id, cargo_id").eq("id", uid).limit(1).execute().data
    urow = urow[0] if urow else {}
    cargo_nom = ""
    if urow.get("cargo_id"):
        crow = supabase.table("cargos").select("nombre").eq("id", urow["cargo_id"]).limit(1).execute().data
        if crow:
            cargo_nom = (crow[0].get("nombre") or "").strip().lower()

    es_dev = _es_desarrollador(current_user) or cargo_nom == "desarrollador"
    scope = set()

    if contrato_id is not None:
        try:
            cid = int(contrato_id)
        except (TypeError, ValueError):
            raise HTTPException(status_code=400, detail="contrato_id inválido")
        if not es_dev and not _usuario_vinculado_a_contrato(uid, cid):
            raise HTTPException(status_code=403, detail="No tienes acceso a destinatarios de ese contrato")
        scope.add(cid)
    else:
        # Sin query: solo el contrato activo del usuario (no todos los vinculados).
        cid_act = _usuario_contrato_id_por_user_id(uid)
        if cid_act is not None:
            scope.add(cid_act)
        else:
            jwt_cid = current_user.get("contrato_id")
            if jwt_cid is not None and str(jwt_cid).strip() != "":
                try:
                    scope.add(int(jwt_cid))
                except (TypeError, ValueError):
                    pass

    def _rows_to_out(rows: list) -> list:
        cargos = {c["id"]: c["nombre"] for c in supabase.table("cargos").select("id, nombre").execute().data}
        roles = {r["id"]: r["nombre"] for r in (supabase.table("roles").select("id, nombre").execute().data or [])}
        return [
            {
                "id": r["id"],
                "nombre": f"{r['nombre']} {r.get('apellidos','')}",
                "cargo": cargos.get(r.get("cargo_id"), ""),
                "rol": roles.get(r.get("rol_id"), ""),
            }
            for r in (rows or []) if r.get("id") is not None and r["id"] != uid
        ]

    by_id = {}
    if scope:
        scope_l = list(scope)
        r1 = supabase.table("usuarios").select("id, nombre, apellidos, cargo_id, rol_id").eq("activo", True).in_("contrato_id", scope_l).execute().data or []
        for r in r1:
            by_id[r["id"]] = r
        uc = supabase.table("usuario_contratos").select("usuario_id").in_("contrato_id", scope_l).execute().data or []
        extra_ids = list({int(x["usuario_id"]) for x in uc if x.get("usuario_id") is not None} - {uid})
        if extra_ids:
            chunk = 120
            for i in range(0, len(extra_ids), chunk):
                part = extra_ids[i : i + chunk]
                r2 = supabase.table("usuarios").select("id, nombre, apellidos, cargo_id, rol_id").eq("activo", True).in_("id", part).execute().data or []
                for r in r2:
                    by_id[r["id"]] = r

    dev_cargo_ids = [
        c["id"]
        for c in (supabase.table("cargos").select("id, nombre").execute().data or [])
        if (c.get("nombre") or "").strip().lower() == "desarrollador"
    ]
    if dev_cargo_ids:
        r_dev = (
            supabase.table("usuarios")
            .select("id, nombre, apellidos, cargo_id, rol_id")
            .eq("activo", True)
            .in_("cargo_id", dev_cargo_ids)
            .execute()
            .data
            or []
        )
        for r in r_dev:
            by_id[r["id"]] = r

    if not by_id:
        return []

    out = _rows_to_out(list(by_id.values()))
    out.sort(key=lambda x: (x.get("nombre") or "").lower())
    return out

