class CerrarActaRpoBody(BaseModel):
    """Cierra un acta RPO en fecha_cierre; traslada residuales sin N3 al acta siguiente (existente si ya está creado, o nuevo período desde cierre+1 hasta fin de mes)."""
    fecha_cierre: str
    acta_id: Optional[int] = None


def _last_day_of_month(y: int, m: int) -> date:
    return date(y, m, calendar.monthrange(y, m)[1])


def _acta_rpo_periodos_se_solapan(fi_a: str, ff_a: str, fi_b: str, ff_b: str) -> bool:
    """[fi_a,ff_a] y [fi_b,ff_b] se solapan (inclusive)."""
    return fi_a <= ff_b and ff_a >= fi_b


def _periodo_siguiente_tras_cierre(fc: date) -> Tuple[date, date]:
    """Período nuevo si no hay acta previo: desde (día de cierre + 1) hasta fin de ese mes calendario."""
    fi_n = fc + timedelta(days=1)
    ff_n = _last_day_of_month(fi_n.year, fi_n.month)
    return fi_n, ff_n


def _buscar_acta_rpo_siguiente_existente(contrato_id: int, cerrar_id: int, fc: date) -> Optional[dict]:
    """
    Acta RPO ya creado cuya fecha_inicio >= día siguiente al cierre (el más próximo por fecha_inicio).
    Si existe, el cierre solo acorta el acta actual y traslada residuales aquí — sin insertar otro acta.
    """
    umbral = (fc + timedelta(days=1)).isoformat()
    rows = supabase.table("actas").select("*").eq("contrato_id", contrato_id).eq("tipo_grupo", "RPO").execute().data or []
    candidatos = []
    for r in rows:
        if int(r.get("id") or 0) == int(cerrar_id):
            continue
        fi = (r.get("fecha_inicio") or "")[:10]
        if fi and fi >= umbral:
            candidatos.append(r)
    if not candidatos:
        return None
    candidatos.sort(key=lambda x: (x.get("fecha_inicio") or "")[:10])
    return candidatos[0]


def _mover_registros_residual_hacia_acta(contrato_id: int, source_acta_ids: List[int], hacia_acta_id: int) -> int:
    """
    Traslada so_registros sin aprobación en el último nivel activo del contrato desde actas fuente
    hacia hacia_acta_id; actualiza acta_rpo_id en so_reportes tocados (updates en lote, no fila a fila).
    """
    sources = sorted({int(x) for x in source_acta_ids if x is not None and int(x) != int(hacia_acta_id)})
    if not sources or not hacia_acta_id:
        return 0
    ids_mover: List[int] = []
    reportes_tocados: Set[int] = set()
    off = 0
    while True:
        batch = supabase.table("so_registros").select(f"id, reporte_id, {SICOE_SELECT_NIVELES_ESTADO},contrato_id")\
            .eq("contrato_id", contrato_id).in_("acta_rpo_id", sources)\
            .order("id").range(off, off + 199).execute().data or []
        for reg in batch:
            if _registro_nivel_max_aprobado(reg, contrato_id):
                continue
            ids_mover.append(int(reg["id"]))
            rp = reg.get("reporte_id")
            if rp is not None:
                reportes_tocados.add(int(rp))
        if len(batch) < 200:
            break
        off += 200
    chunk = 200
    for i in range(0, len(ids_mover), chunk):
        parte = ids_mover[i : i + chunk]
        supabase.table("so_registros").update({"acta_rpo_id": hacia_acta_id})\
            .eq("contrato_id", contrato_id).in_("id", parte).execute()
    reportes_list = sorted(reportes_tocados)
    for i in range(0, len(reportes_list), chunk):
        parte = reportes_list[i : i + chunk]
        supabase.table("so_reportes").update({"acta_rpo_id": hacia_acta_id})\
            .eq("contrato_id", contrato_id).in_("id", parte).execute()
    return len(ids_mover)


def _cerrar_acta_rpo_mover_residuales_background(
    contrato_id: int,
    cerrar_id: int,
    nueva_id: int,
    fc_iso: str,
    current_user: dict,
    log_accion: str,
    reutilizo: bool,
):
    """Traslado de residuales fuera del request HTTP (evita timeout/CORS en Azure)."""
    try:
        n = _mover_registros_residual_hacia_acta(contrato_id, [cerrar_id], nueva_id)
        registrar_log(
            current_user,
            "EDITAR",
            "ACTAS",
            "acta",
            str(cerrar_id),
            {
                "accion": log_accion,
                "fecha_cierre": fc_iso,
                "nueva_acta_id": nueva_id,
                "registros_movidos": n,
                "reutilizo_acta_existente": reutilizo,
                "movimiento_segundo_plano": True,
            },
        )
    except Exception as e:
        try:
            registrar_log_sistema(
                "ERROR",
                "/actas/rpo/cerrar-mover-residuales",
                "BACKGROUND",
                {
                    "contrato_id": contrato_id,
                    "cerrar_id": cerrar_id,
                    "nueva_acta_id": nueva_id,
                    "error": str(e)[:2000],
                },
                traceback.format_exc()[:8000],
            )
        except Exception:
            pass


def _cerrar_acta_rpo_ejecutar(
    contrato_id: int,
    fc: date,
    cerrar_id: int,
    acta_row: dict,
    current_user,
    log_accion: str = "cerrar_rpo_anticipado",
    *,
    defer_mover_residuales: bool = False,
) -> dict:
    """
    Cierra acta RPO (acorta fecha_fin), traslada residuales sin N3 aprobado al acta siguiente.
    Si ya existe un acta con inicio >= día después del cierre, reutiliza ese registro (no inserta duplicado).
    Si no, crea período [cierre+1, fin de mes]; si ese tramo solapa otro acta existente, reutiliza ese acta.
    """
    if (acta_row.get("tipo_grupo") or "").strip().upper() != "RPO":
        raise HTTPException(status_code=400, detail="Solo aplica a actas con tipo_grupo RPO.")

    fi_old = (acta_row.get("fecha_inicio") or "")[:10]
    ff_old = (acta_row.get("fecha_fin") or "")[:10]
    if not fi_old or not ff_old:
        raise HTTPException(status_code=400, detail="El acta no tiene fecha_inicio / fecha_fin.")
    try:
        d_ini = date.fromisoformat(fi_old)
        d_fin_prev = date.fromisoformat(ff_old)
    except ValueError:
        raise HTTPException(status_code=400, detail="Fechas del acta corruptas.")

    if fc < d_ini:
        raise HTTPException(status_code=422, detail="La fecha de cierre no puede ser anterior al inicio del acta.")
    if fc > d_fin_prev:
        raise HTTPException(status_code=422, detail="La fecha de cierre no puede ser posterior al fin vigente del acta.")
    if fc > date.today():
        raise HTTPException(status_code=422, detail="La fecha de cierre no puede ser futura.")

    existentes = supabase.table("actas").select(
        "id, numero_rpo, fecha_inicio, fecha_fin, consecutivo, tipo_acta_id, asignado_a, fecha_asignacion, observacion"
    ).eq("contrato_id", contrato_id).eq("tipo_grupo", "RPO").execute().data or []

    siguiente_existente = _buscar_acta_rpo_siguiente_existente(contrato_id, cerrar_id, fc)
    fi_n, ff_n = _periodo_siguiente_tras_cierre(fc)
    fi_ns, ff_ns = fi_n.isoformat(), ff_n.isoformat()

    supabase.table("actas").update({"fecha_fin": fc.isoformat(), "updated_at": "now()"}).eq("id", cerrar_id).execute()

    nueva_id = None
    creada: Dict[str, Any] = {}
    reutilizo = False

    if siguiente_existente:
        nueva_id = int(siguiente_existente["id"])
        creada = siguiente_existente
        reutilizo = True
    else:
        overlap_row = None
        for ex in existentes:
            if int(ex.get("id") or 0) == int(cerrar_id):
                continue
            ei = (ex.get("fecha_inicio") or "")[:10]
            ef = (ex.get("fecha_fin") or "")[:10]
            if ei and ef and _acta_rpo_periodos_se_solapan(ei, ef, fi_ns, ff_ns):
                overlap_row = ex
                break
        if overlap_row:
            nueva_id = int(overlap_row["id"])
            creada = overlap_row
            reutilizo = True
        else:
            rpo_rows = [r for r in existentes if r.get("numero_rpo") is not None]
            max_rpo = max((int(r["numero_rpo"]) for r in rpo_rows), default=0)
            nuevo_numero_rpo = max_rpo + 1

            cons_rows = supabase.table("actas").select("consecutivo").eq("contrato_id", contrato_id).execute().data or []
            max_cons = max((r["consecutivo"] for r in cons_rows), default=0)
            nuevo_cons = max_cons + 1

            new_row = {
                "contrato_id":      contrato_id,
                "consecutivo":      nuevo_cons,
                "tipo_grupo":       "RPO",
                "numero_rpo":       nuevo_numero_rpo,
                "fecha_inicio":     fi_ns,
                "fecha_fin":        ff_ns,
                "tipo_acta_id":     acta_row.get("tipo_acta_id"),
                "asignado_a":       acta_row.get("asignado_a"),
                "fecha_asignacion": acta_row.get("fecha_asignacion"),
                "observacion":      acta_row.get("observacion"),
            }
            new_row = {k: v for k, v in new_row.items() if v is not None}
            ins = supabase.table("actas").insert(new_row).execute()
            creada = ins.data[0] if ins.data else {}
            nueva_id = creada.get("id")
            if not nueva_id:
                raise HTTPException(
                    status_code=500,
                    detail="No se pudo crear el acta RPO siguiente (insert sin id). Revise permisos o restricciones en la tabla actas.",
                )

    registros_movidos = 0
    movimiento_pendiente = False
    if nueva_id and not defer_mover_residuales:
        registros_movidos = _mover_registros_residual_hacia_acta(contrato_id, [cerrar_id], nueva_id)
    elif nueva_id and defer_mover_residuales:
        movimiento_pendiente = True

    if not defer_mover_residuales:
        registrar_log(
            current_user,
            "EDITAR",
            "ACTAS",
            "acta",
            str(cerrar_id),
            {
                "accion": log_accion,
                "fecha_cierre": fc.isoformat(),
                "nueva_acta_id": nueva_id,
                "registros_movidos": registros_movidos,
                "reutilizo_acta_existente": reutilizo,
            },
        )
    else:
        registrar_log(
            current_user,
            "EDITAR",
            "ACTAS",
            "acta",
            str(cerrar_id),
            {
                "accion": log_accion,
                "fecha_cierre": fc.isoformat(),
                "nueva_acta_id": nueva_id,
                "registros_movidos": 0,
                "reutilizo_acta_existente": reutilizo,
                "movimiento_segundo_plano": True,
            },
        )

    peri_fi = (creada.get("fecha_inicio") or fi_ns)[:10] if creada else fi_ns
    peri_ff = (creada.get("fecha_fin") or ff_ns)[:10] if creada else ff_ns

    return {
        "ok": True,
        "acta_cerrada": {"id": cerrar_id, "fecha_fin": fc.isoformat()},
        "acta_creada": creada,
        "nueva_acta_id": nueva_id,
        "periodo_siguiente": {"fecha_inicio": peri_fi, "fecha_fin": peri_ff},
        "registros_movidos_residual": registros_movidos,
        "reutilizo_acta_existente": reutilizo,
        "movimiento_en_segundo_plano": movimiento_pendiente,
    }


@app.post("/actas/{contrato_id}/rpo/cerrar-y-siguiente")
def cerrar_acta_rpo_y_crear_siguiente(
    contrato_id: int,
    body: CerrarActaRpoBody,
    background_tasks: BackgroundTasks,
    current_user=Depends(get_current_user),
):
    try:
        fc = date.fromisoformat((body.fecha_cierre or "")[:10])
    except ValueError:
        raise HTTPException(status_code=422, detail="fecha_cierre debe ser YYYY-MM-DD válida.")

    cerrar_id = body.acta_id
    acta_row = None

    if cerrar_id is not None:
        rows = supabase.table("actas").select("*").eq("id", cerrar_id).eq("contrato_id", contrato_id).limit(1).execute().data
        if not rows:
            raise HTTPException(status_code=404, detail="Acta no encontrada en este contrato.")
        acta_row = rows[0]
    else:
        ds = fc.isoformat()
        rows = supabase.table("actas").select("*").eq("contrato_id", contrato_id).eq("tipo_grupo", "RPO")\
            .lte("fecha_inicio", ds).gte("fecha_fin", ds).order("id", desc=True).limit(1).execute().data
        if not rows:
            raise HTTPException(
                status_code=404,
                detail="No hay Acta RPO cuyo período incluya la fecha de cierre. Indica acta_id o revise las fechas.",
            )
        acta_row = rows[0]
        cerrar_id = acta_row["id"]

    u_log = dict(current_user) if isinstance(current_user, dict) else current_user
    r = _cerrar_acta_rpo_ejecutar(
        contrato_id, fc, cerrar_id, acta_row, u_log, "cerrar_rpo_anticipado", defer_mover_residuales=True,
    )
    nueva_id = r.get("nueva_acta_id")
    if r.get("movimiento_en_segundo_plano") and nueva_id:
        background_tasks.add_task(
            _cerrar_acta_rpo_mover_residuales_background,
            contrato_id,
            int(cerrar_id),
            int(nueva_id),
            fc.isoformat(),
            u_log,
            "cerrar_rpo_anticipado",
            bool(r.get("reutilizo_acta_existente")),
        )
    return r


def sincronizar_actas_rpo_por_vencimiento(contrato_id: int, current_user) -> dict:
    """
    1) Si no hay acta RPO vigente para hoy pero existe un acta cuyo período ya terminó: aplica la misma lógica que cerrar
       (período siguiente = día después del fin hasta fin de mes; reutiliza acta si ya existe).
    2) Con acta vigente: mueve registros sin N3 aprobado desde todos los actas con fecha_fin < hoy hacia el acta vigente.
    """
    today = date.today()
    today_s = today.isoformat()
    moved_total = 0
    cerrado_por_vencimiento = False
    acta_creada_auto = None

    vig = _acta_rpo_vigente_row(contrato_id)

    if not vig:
        rows = supabase.table("actas").select("*")\
            .eq("contrato_id", contrato_id).eq("tipo_grupo", "RPO")\
            .lt("fecha_fin", today_s)\
            .order("fecha_fin", desc=True).limit(1).execute().data or []
        if rows:
            L = rows[0]
            lid = int(L["id"])
            ff_L = (L.get("fecha_fin") or "")[:10]
            try:
                fc = date.fromisoformat(ff_L)
            except ValueError:
                fc = None
            if fc is not None and fc <= today:
                fi_n, ff_n = _periodo_siguiente_tras_cierre(fc)
                fi_ns, ff_ns = fi_n.isoformat(), ff_n.isoformat()
                existentes = supabase.table("actas").select("id, numero_rpo, fecha_inicio, fecha_fin")\
                    .eq("contrato_id", contrato_id).eq("tipo_grupo", "RPO").execute().data or []
                overlap_id = None
                for ex in existentes:
                    if int(ex.get("id") or 0) == lid:
                        continue
                    ei = (ex.get("fecha_inicio") or "")[:10]
                    ef = (ex.get("fecha_fin") or "")[:10]
                    if ei and ef and _acta_rpo_periodos_se_solapan(ei, ef, fi_ns, ff_ns):
                        overlap_id = int(ex["id"])
                        break
                if overlap_id:
                    moved_total += _mover_registros_residual_hacia_acta(contrato_id, [lid], overlap_id)
                else:
                    try:
                        r = _cerrar_acta_rpo_ejecutar(
                            contrato_id, fc, lid, L, current_user,
                            log_accion="cerrar_rpo_vencimiento_calendario",
                        )
                        cerrado_por_vencimiento = True
                        acta_creada_auto = r.get("acta_creada")
                        moved_total += int(r.get("registros_movidos_residual") or 0)
                    except HTTPException as e:
                        if e.status_code != 409:
                            raise
                        overlap_id = None
                        for ex in existentes:
                            if int(ex.get("id") or 0) == lid:
                                continue
                            ei = (ex.get("fecha_inicio") or "")[:10]
                            ef = (ex.get("fecha_fin") or "")[:10]
                            if ei and ef and _acta_rpo_periodos_se_solapan(ei, ef, fi_ns, ff_ns):
                                overlap_id = int(ex["id"])
                                break
                        if overlap_id:
                            moved_total += _mover_registros_residual_hacia_acta(contrato_id, [lid], overlap_id)

        vig = _acta_rpo_vigente_row(contrato_id)

    out: Dict[str, Any] = {
        "ok": True,
        "vigente_id": vig["id"] if vig else None,
        "registros_movidos": moved_total,
        "cerrado_automatico_vencimiento": cerrado_por_vencimiento,
        "acta_creada_automatica": acta_creada_auto,
    }

    if not vig:
        out["sin_acta_vigente"] = True
        return out

    vig_id = int(vig["id"])
    past_rows = supabase.table("actas").select("id")\
        .eq("contrato_id", contrato_id).eq("tipo_grupo", "RPO")\
        .lt("fecha_fin", today_s).execute().data or []
    past_ids = [int(r["id"]) for r in past_rows if int(r["id"]) != vig_id]
    if past_ids:
        moved_total += _mover_registros_residual_hacia_acta(contrato_id, past_ids, vig_id)

    out["registros_movidos"] = moved_total
    return out


@app.post("/actas/{contrato_id}/rpo/sincronizar-vencimiento")
def actas_rpo_sincronizar_vencimiento(contrato_id: int, current_user=Depends(get_current_user)):
    """Alinea residuales por vencimiento de período (y crea acta siguiente si faltaba). Invocable desde panel admin."""
    return sincronizar_actas_rpo_por_vencimiento(contrato_id, current_user)


@app.get("/actas/{acta_id}/financiero")
def acta_financiero(acta_id: int, current_user=Depends(get_current_user)):
    acta = supabase.table("actas").select("contrato_id, numero_rpo, tipo_grupo")\
        .eq("id", acta_id).single().execute().data
    if not acta or acta.get("tipo_grupo") != "cobro":
        return {"resumen": [], "capitulos": []}
    contrato_id = acta["contrato_id"]
    caps = supabase.table("listado_precios").select("capitulo").eq("contrato_id", contrato_id)\
        .execute().data or []
    caps_unicos = list(dict.fromkeys([r["capitulo"] for r in caps if r.get("capitulo")]))
    resumen = [
        {"estado": "Aprobado",                    "aiu": 0, "iva": 0},
        {"estado": "Pendiente",                   "aiu": 0, "iva": 0},
        {"estado": "Pendiente aprobación precio", "aiu": 0, "iva": 0},
        {"estado": "Rechazado",                   "aiu": 0, "iva": 0},
    ]
    capitulos = [{"capitulo": c, "aprobado": 0, "pendiente": 0, "pendiente_precio": 0,
                  "no_revisado": 0, "rechazado": 0} for c in caps_unicos]
    return {"resumen": resumen, "capitulos": capitulos}


@app.get("/actas/{acta_id}/rpo-costo-conciliacion")
def acta_rpo_costo_conciliacion(acta_id: int, current_user=Depends(get_current_user)):
    """Desglose de costo directo (SICOE, N3 aprobado) por capítulo; solo actas tipo RPO."""
    acta = supabase.table("actas").select(
        "id, contrato_id, tipo_grupo, numero_rpo, consecutivo, fecha_inicio, fecha_fin, tipo_acta_id"
    ).eq("id", acta_id).limit(1).execute().data
    acta = acta[0] if acta else None
    if not acta or (acta.get("tipo_grupo") or "").strip().upper() != "RPO":
        raise HTTPException(status_code=400, detail="Solo aplica a actas con tipo RPO.")
    contrato_id = int(acta["contrato_id"])
    _campo_mx, _niv_act = matriz_params_contrato(supabase, contrato_id)
    block = rpo_conciliacion_un_acta_rpc(
        supabase,
        contrato_id,
        int(acta_id),
        campo_nivel_max=_campo_mx,
        niveles_activos=_niv_act,
    )
    if block is None:
        m = rpo_conciliacion_por_contrato(
            supabase,
            contrato_id,
            [int(acta_id)],
            campo_nivel_max=_campo_mx,
            niveles_activos=_niv_act,
        )
        block = m.get(
            int(acta_id),
            {
                "costo_directo_total": 0.0,
                "registros_n3_aprobado": 0,
                "registros_cascade_interventoria": 0,
                "por_capitulo": [],
                "secciones": {},
            },
        )
    return {
        "acta_id": int(acta_id),
        "contrato_id": contrato_id,
        "numero_rpo": acta.get("numero_rpo"),
        "consecutivo": acta.get("consecutivo"),
        "periodo": {
            "fecha_inicio": (acta.get("fecha_inicio") or "")[:10],
            "fecha_fin": (acta.get("fecha_fin") or "")[:10],
        },
        "criterio": (
            f"Alineado con el dashboard de validación: ítem asignado, prerequisitos de niveles activos "
            f"inferiores a «Aprobado» y {_campo_mx} en «Aprobado» (último nivel activo del contrato: "
            f"{sorted(_niv_act)}). Sin filtro de «bloqueado». "
            "Bloque obra / ensayos = misma regla de capítulos que dashboard_matriz_validacion."
        ),
        "costo_directo_total": block.get("costo_directo_total", 0.0),
        "registros_n3_aprobado": block.get("registros_n3_aprobado", 0),
        "registros_cascade_interventoria": block.get("registros_cascade_interventoria", block.get("registros_n3_aprobado", 0)),
        "por_capitulo": block.get("por_capitulo") or [],
        "secciones": block.get("secciones") or {},
    }


