def listar_inspectores(contrato_id: int, current_user=Depends(get_current_user)):
    """
    Usuarios del contrato cuyo rol coincide con el configurado para el Nivel 1
    (o el nivel activo mínimo) en «Niveles de validación» — sin asumir cargo Inspector (54)
    ni rol Contratista fijo.
    """
    _require_contract_access(current_user, contrato_id)
    return _listar_inspectores_payload(contrato_id)

@app.get("/sicoe-obra/{contrato_id}/capitulos")
def listar_capitulos_obra(contrato_id: int, current_user=Depends(get_current_user)):
    """
    Capítulos distintos de listado_precios del contrato.
    Pagina por lotes (PostgREST ~1000 filas/respuesta): sin .range solo se veían
    los primeros ~1000 precios y podían faltar capítulos.
    """
    from sicoe_catalogo import capitulos_distinct_desde_filas, capitulos_payload

    _require_contract_access(current_user, contrato_id)
    rows: List[dict] = []
    offset = 0
    while True:
        def _q(o=offset):
            return (
                supabase.table("listado_precios")
                .select("capitulo")
                .eq("contrato_id", contrato_id)
                .order("id")
                .range(o, o + 999)
                .execute()
                .data
            )

        batch = supabase_execute(_q) or []
        rows.extend(batch)
        if len(batch) < 1000:
            break
        offset += 1000
    return capitulos_payload(capitulos_distinct_desde_filas(rows))

@app.get("/sicoe-obra/{contrato_id}/next-reporte")
def next_numero_reporte(contrato_id: int, current_user=Depends(get_current_user)):
    """Vista previa del siguiente número (sin llamar a la RPC ni reservar). Misma lógica que
    `siguiente_numero_reporte` (incl. contratos con sicoe_consecutivos_desde_uno)."""

    def _contrato():
        return supabase.table("contratos").select("sicoe_consecutivos_desde_uno")\
            .eq("id", contrato_id).limit(1).execute().data

    def _max_num():
        return supabase.table("so_reportes").select("numero_reporte")\
            .eq("contrato_id", contrato_id).order("numero_reporte", desc=True).limit(1).execute().data

    def _rsv():
        return supabase.table("sico_ultimo_numero_reporte").select("reservado_hasta")\
            .eq("contrato_id", contrato_id).limit(1).execute().data

    crows = supabase_execute(_contrato)
    desde_uno = bool(crows and crows[0].get("sicoe_consecutivos_desde_uno"))
    mrows = supabase_execute(_max_num)
    m_tab = mrows[0]["numero_reporte"] if mrows else 0
    if m_tab is None:
        m_tab = 0
    urows = supabase_execute(_rsv)
    if urows:
        rsv = urows[0].get("reservado_hasta")
    else:
        rsv = 0 if desde_uno else 34999
    if rsv is None:
        rsv = 0 if desde_uno else 34999
    piso = 35000
    rsv = _sicoe_rsv_efectivo(desde_uno, rsv, m_tab, piso)
    if desde_uno:
        sig = max(m_tab + 1, rsv + 1)
    else:
        sig = max(piso, m_tab + 1, rsv + 1)
    return {"siguiente": sig}

_SICOE_CATALOGO_CACHE: Dict[tuple, Tuple[float, Any]] = {}
_SICOE_CATALOGO_CACHE_TTL = 120.0


def _sicoe_catalogo_cache_get(key: tuple) -> Optional[Any]:
    row = _SICOE_CATALOGO_CACHE.get(key)
    if not row:
        return None
    exp, data = row
    if exp < time.time():
        _SICOE_CATALOGO_CACHE.pop(key, None)
        return None
    return data


def _sicoe_catalogo_cache_set(key: tuple, data: Any) -> None:
    _SICOE_CATALOGO_CACHE[key] = (time.time() + _SICOE_CATALOGO_CACHE_TTL, data)
    if len(_SICOE_CATALOGO_CACHE) > 500:
        now = time.time()
        for k in [k for k, (e, _) in _SICOE_CATALOGO_CACHE.items() if e < now]:
            _SICOE_CATALOGO_CACHE.pop(k, None)


@app.get("/sicoe-obra/{contrato_id}/nodos")
def listar_nodos_obra(contrato_id: int, capitulo: str = None, current_user=Depends(get_current_user)):
    _require_contract_access(current_user, contrato_id)
    cap_key = (capitulo or "").strip()
    cache_key = ("nodos", int(contrato_id), cap_key)
    cached = _sicoe_catalogo_cache_get(cache_key)
    if cached is not None:
        return cached

    def _q():
        q = supabase.table("presupuesto")\
            .select("no_inicio, no_final")\
            .eq("contrato_id", contrato_id)\
            .eq("dado_de_baja", False)
        if cap_key:
            q = q.eq("capitulo", cap_key)
        return q.execute().data
    rows = supabase_execute(_q)
    nodos = set()
    for r in rows:
        if r.get("no_inicio"): nodos.add(r["no_inicio"])
        if r.get("no_final"): nodos.add(r["no_final"])
    out = sorted(list(nodos))
    _sicoe_catalogo_cache_set(cache_key, out)
    return out

