@app.get("/sicoe-obra/{contrato_id}/cargos-validacion")
def cargos_con_validacion(contrato_id: int, current_user=Depends(get_current_user)):
    try:
        # Cargos que están en CARGO_ID_NIVEL_MAP (tabla cargos). Siempre listarlos para
        # filtros aunque no haya usuario aprobado con ese cargo en el contrato — si no,
        # opciones como «Residente de Obra» desaparecen sin poder filtrar registros ya validados.
        cargo_ids_nivel = list(CARGO_ID_NIVEL_MAP.keys())

        def _cargos():
            return supabase.table("cargos").select("id, nombre")\
                .in_("id", cargo_ids_nivel).execute().data
        cargos_rows = supabase_execute(_cargos)
        cargo_id_nombre = {r["id"]: r["nombre"] for r in cargos_rows}

        return [
            {"id": cid, "nombre": cargo_id_nombre[cid]}
            for cid in cargo_ids_nivel
            if cid in cargo_id_nombre
        ]
    except Exception as e:
        return []


@app.get("/sicoe-obra/{contrato_id}/reportes/buscar")
def buscar_reportes_obra(
    contrato_id: int,
    numero_reporte: Optional[int] = None,
    numero_registro: Optional[int] = None,
    semana: Optional[int] = None,
    acta_rpo: Optional[int] = None,
    subcontratista_id: Optional[int] = None,
    capitulo: Optional[str] = None,
    capitulos_filtro: Optional[str] = None,
    item: Optional[str] = None,
    items_filtro: Optional[str] = None,
    items_filtro_op: Optional[str] = Query(None),
    actas_filtro: Optional[str] = None,
    tramo: Optional[str] = None,
    costado: Optional[str] = None,
    pk_id: Optional[int] = None,
    abs_inicio: Optional[float] = None,
    abs_final: Optional[float] = None,
    estado: Optional[str] = None,
    cargo_id: Optional[int] = None,
    estado_validacion: Optional[str] = None,
    validacion_capas: Optional[str] = None,
    validacion_capas_op: Optional[str] = Query(None),
    q_observacion: Optional[str] = None,
    q_nodo: Optional[str] = None,
    etiqueta_validacion: Optional[str] = None,
    cantidad_desde: Optional[float] = None,
    cantidad_hasta: Optional[float] = None,
    costo_directo_desde: Optional[float] = None,
    costo_directo_hasta: Optional[float] = None,
    ambito_fecha: Optional[str] = None,
    tipo_fecha: Optional[str] = None,
    fecha_desde: Optional[str] = None,
    fecha_hasta: Optional[str] = None,
    usuario_id: Optional[int] = None,
    usuario_accion: Optional[str] = None,
    pendiente_item: bool = Query(False),
    offset: int = 0,
    limit: int = 50,
    current_user=Depends(get_current_user)
):
    limit = min(limit, 100)
    _ocultar_costo_rep = _sicoe_ocultar_costo_directo_reportes(current_user)
    _amb_fu, _tip_fu, _fd_fu, _fh_fu, _uid_fu, _uacc_fu, _tiene_fu = _sicoe_parse_filtros_fecha_usuario(
        ambito_fecha, tipo_fecha, fecha_desde, fecha_hasta, usuario_id, usuario_accion
    )
    _filtro_fu_rep = _amb_fu == "reporte" and _tiene_fu
    _filtro_fu_reg = _amb_fu == "registro" and _tiene_fu
    capas_v = _parse_validacion_capas_param(validacion_capas, cargo_id, estado_validacion)
    consulta_directa_identificador = (
        numero_reporte is not None or numero_registro is not None
    )
    if consulta_directa_identificador:
        capas_v = []
        semana = None
        acta_rpo = None
    _cap_op_buscar = _parse_capas_validacion_op(validacion_capas_op)
    _rev_modo = _sicoe_reversion_modo_filtro(estado, current_user)
    _defer_capas_or_grilla = (
        bool(capas_v)
        and not _estado_filtro_omite_validacion_por_cargo(estado)
        and len(capas_v) > 1
        and _cap_op_buscar == "or"
    )
    _nivel_l = None
    _ev_l = None
    if capas_v:
        try:
            _nivel_l = capas_v[0].get("campo") or _capa_campo_validacion(capas_v[0])
            _ev_l = (capas_v[0].get("estado") or "").strip()
        except (TypeError, ValueError, KeyError, IndexError):
            _nivel_l = None
            _ev_l = None

    items_buscar_norm = _normalize_items_filtro_list(items_filtro, item)
    items_buscar_op = items_filtro_op
    caps_buscar_norm = _normalize_items_filtro_list(capitulos_filtro, capitulo)
    actas_rpo_buscar_norm = _normalize_actas_filtro_list(actas_filtro, acta_rpo)
    acta_ids_panel_buscar = (
        _sicoe_resolve_acta_ids_por_rpo(contrato_id, actas_rpo_buscar_norm)
        if actas_rpo_buscar_norm else []
    )
    if actas_rpo_buscar_norm and not acta_ids_panel_buscar:
        return {"reportes": [], "total": 0, "offset": offset, "limit": limit, "hay_mas": False}

    has_reg_f = any([
        bool(caps_buscar_norm), bool(items_buscar_norm), subcontratista_id is not None,
        bool(tramo), bool(costado),
        cantidad_desde is not None, cantidad_hasta is not None,
        costo_directo_desde is not None, costo_directo_hasta is not None,
    ])
    capas_aplican_a_lineas = bool(capas_v) and not _estado_filtro_omite_validacion_por_cargo(estado)
    q_obs_trim = (str(q_observacion).strip() if q_observacion is not None else "")

    # Universo de reportes: IDs con al menos una fila de obra que cumple todos los criterios de línea a la vez
    # (AND), alineado con GET /sicoe-obra/.../analisis. Evita intersectar conjuntos por reporte_id con criterios distintos.
    reporte_ids_from_reg = None
    omit_header_semana_acta_en_reportes = False

    semana_id_filtro = None
    if semana is not None:
        try:
            def _sem_id():
                return supabase.table("so_semanas").select("id")\
                    .eq("contrato_id", contrato_id)\
                    .eq("numero_semana", semana).execute().data
            sem_rows = supabase_execute(_sem_id)
            if sem_rows:
                semana_id_filtro = sem_rows[0]["id"]
            else:
                return {"reportes": [], "total": 0, "offset": offset, "limit": limit, "hay_mas": False}
        except Exception:
            return {"reportes": [], "total": 0, "offset": offset, "limit": limit, "hay_mas": False}

    acta_id_filtro = None
    if acta_rpo is not None:
        try:
            def _acta_id():
                rows = supabase.table("actas").select("id")\
                    .eq("contrato_id", contrato_id)\
                    .eq("numero_rpo", acta_rpo).execute().data
                if not rows:
                    rows = supabase.table("actas").select("id")\
                        .eq("contrato_id", contrato_id)\
                        .eq("consecutivo", acta_rpo).execute().data
                return rows
            acta_rows = supabase_execute(_acta_id)
            if acta_rows:
                acta_id_filtro = acta_rows[0]["id"]
            else:
                return {"reportes": [], "total": 0, "offset": offset, "limit": limit, "hay_mas": False}
        except Exception:
            return {"reportes": [], "total": 0, "offset": offset, "limit": limit, "hay_mas": False}

    etiqueta_f = _sicoe_parse_etiqueta_validacion_param(etiqueta_validacion)
    registro_ids_etiqueta = (
        _sicoe_fetch_registro_ids_etiqueta_validacion(contrato_id, etiqueta_f)
        if etiqueta_f
        else None
    )

    acta_id_para_lineas = acta_id_filtro
    # Solo «pendiente ítem» hereda acta vigente de la matriz. Filtro por capas de validación
    # (p. ej. cola N2 «No Revisado» al entrar) debe abarcar todo el contrato salvo que el
    # usuario elija acta/semana en el modal.
    if (
        not consulta_directa_identificador
        and acta_id_para_lineas is None
        and semana_id_filtro is None
        and not acta_ids_panel_buscar
        and pendiente_item
    ):
        injected = _acta_rpo_id_matriz_dashboard_default(contrato_id)
        if injected is not None:
            acta_id_para_lineas = injected

    aids_linea_buscar: List[int] = list(acta_ids_panel_buscar)
    if not aids_linea_buscar and acta_id_para_lineas is not None:
        aids_linea_buscar = [int(acta_id_para_lineas)]

    _estado_sin_asignar_item = _estado_filtro_es_sin_asignar_item(estado)

    unified_line = any([
        numero_registro is not None,
        abs_inicio is not None or abs_final is not None,
        has_reg_f,
        bool(q_obs_trim),
        pk_id is not None,
        capas_aplican_a_lineas,
        semana_id_filtro is not None,
        acta_id_filtro is not None,
        bool(acta_ids_panel_buscar),
        bool(etiqueta_f),
        pendiente_item,
        cantidad_desde is not None or cantidad_hasta is not None,
        costo_directo_desde is not None or costo_directo_hasta is not None,
        _filtro_fu_reg,
        _rev_modo is not None,
    ])

    if unified_line:
        ids_unif = _sicoe_collect_reporte_ids_misma_linea(
            contrato_id,
            numero_registro=numero_registro,
            abs_inicio=abs_inicio,
            abs_final=abs_final,
            cantidad_desde=cantidad_desde,
            cantidad_hasta=cantidad_hasta,
            costo_directo_desde=costo_directo_desde,
            costo_directo_hasta=costo_directo_hasta,
            capitulos=caps_buscar_norm,
            items=items_buscar_norm,
            items_op=items_buscar_op,
            subcontratista_id=subcontratista_id,
            tramo=tramo,
            costado=costado,
            pk_id=pk_id,
            q_observacion=q_obs_trim or None,
            semana_id=semana_id_filtro,
            acta_rpo_ids=aids_linea_buscar,
            capas_v=(capas_v if capas_aplican_a_lineas else None),
            capas_v_op=validacion_capas_op,
            estado=estado,
            registro_ids_etiqueta=registro_ids_etiqueta,
            pendiente_item=pendiente_item,
            filtro_fecha_usuario_registro=_filtro_fu_reg,
            fecha_desde=_fd_fu,
            fecha_hasta=_fh_fu,
            tipo_fecha=_tip_fu,
            usuario_id=_uid_fu,
            usuario_accion=_uacc_fu,
            reversion_modo=_rev_modo,
        )
        if not ids_unif:
            return {"reportes": [], "total": 0, "offset": offset, "limit": limit, "hay_mas": False}
        if _estado_sin_asignar_item:
            ids_sin_trim = _sicoe_reporte_ids_con_lineas_sin_item(
                contrato_id, restrict_to=ids_unif
            )
            reporte_ids_from_reg = sorted(ids_sin_trim)
            if not reporte_ids_from_reg:
                return {"reportes": [], "total": 0, "offset": offset, "limit": limit, "hay_mas": False}
        else:
            reporte_ids_from_reg = list(ids_unif)
        if semana_id_filtro is not None or acta_id_filtro is not None or acta_ids_panel_buscar:
            omit_header_semana_acta_en_reportes = True
        if _rev_modo is not None:
            omit_header_semana_acta_en_reportes = True

    elif _estado_sin_asignar_item and not consulta_directa_identificador:
        ids_sin_item = _sicoe_reporte_ids_con_lineas_sin_item(contrato_id)
        if not ids_sin_item:
            return {"reportes": [], "total": 0, "offset": offset, "limit": limit, "hay_mas": False}
        reporte_ids_from_reg = sorted(ids_sin_item)

    if _filtro_fu_rep:
        try:
            def _rep_fu_ids():
                q = supabase.table("so_reportes").select("id").eq("contrato_id", contrato_id)
                col_f = "updated_at" if _tip_fu == "modificacion" else "created_at"
                q = _sicoe_aplicar_filtro_fecha_q(q, col_f, _fd_fu, _fh_fu)
                if _uid_fu is not None:
                    q = _sicoe_aplicar_filtro_usuario_reportes_q(q, _uid_fu, _uacc_fu)
                return q.limit(50000).execute().data
            ids_fu = {r["id"] for r in supabase_execute(_rep_fu_ids) if r.get("id")}
            if not ids_fu:
                return {"reportes": [], "total": 0, "offset": offset, "limit": limit, "hay_mas": False}
            if reporte_ids_from_reg is not None:
                reporte_ids_from_reg = [x for x in reporte_ids_from_reg if x in ids_fu]
                if not reporte_ids_from_reg:
                    return {"reportes": [], "total": 0, "offset": offset, "limit": limit, "hay_mas": False}
            else:
                reporte_ids_from_reg = list(ids_fu)
        except Exception:
            return {"reportes": [], "total": 0, "offset": offset, "limit": limit, "hay_mas": False}

    if q_nodo is not None and str(q_nodo).strip():
        ids_n = _sicoe_reporte_ids_coinciden_nodo(contrato_id, q_nodo, reporte_ids_from_reg)
        if ids_n is not None:
            if not ids_n:
                return {"reportes": [], "total": 0, "offset": offset, "limit": limit, "hay_mas": False}
            if reporte_ids_from_reg is not None:
                reporte_ids_from_reg = [x for x in reporte_ids_from_reg if x in ids_n]
            else:
                reporte_ids_from_reg = list(ids_n)
            if not reporte_ids_from_reg:
                return {"reportes": [], "total": 0, "offset": offset, "limit": limit, "hay_mas": False}

    # PostgREST envía .in_() como parámetro URL; listas grandes superan el límite
    # de longitud del servidor y se truncan silenciosamente. Se divide en chunks
    # para garantizar que todos los IDs se filtren correctamente.
    _IDS_CHUNK_SIZE = 200

    def _build_q(ids_chunk=None, lite: bool = False):
        cols = (
            "id, numero_reporte"
            if lite
            else "*, subcontratistas(razon_social)"
        )
        q = supabase.table("so_reportes").select(cols).eq("contrato_id", contrato_id)
        if numero_reporte is not None:
            q = q.eq("numero_reporte", numero_reporte)
        # subcontratista / tramo / costado: ya restringidos vía so_registros (has_reg_f)
        # o vía bloque de validación; repetir en cabecera vacía el universo.
        # pk_id: restringido por reporte_ids_from_reg (líneas so_registros), no por cabecera.
        # abs_inicio/abs_final: ya aplicados por solape en so_registros (arriba)
        _hay_n23_build = (
            (_validacion_cualquier_nivel2_o_3(capas_v) if capas_v else False)
            or (_nivel_l is not None and _es_validacion_avanzada(_nivel_l))
        )
        if estado and not _estado_filtro_es_reversion(estado) and not _estado_filtro_es_sin_asignar_item(estado):
            q = _so_reportes_q_por_estado(q, estado)
        elif _hay_n23_build and ids_chunk is None:
            q = q.not_.in_("estado", list(ESTADOS_REPORTE_EXCL_VALIDACION_AVANZADA))
        # Importante: para validaciones por nivel, el universo debe definirse por
        # estado de so_registros (nivelX_estado), no por estado de so_reportes.
        # Solo se filtra por estado de reporte cuando el usuario lo pide explícitamente.
        # Si ya tenemos IDs desde so_registros (ids_chunk), no volver a excluir por cabecera.
        if not omit_header_semana_acta_en_reportes:
            if semana_id_filtro is not None:
                q = q.eq("semana_id", semana_id_filtro)
            if acta_id_filtro is not None:
                q = q.eq("acta_rpo_id", acta_id_filtro)
        if ids_chunk is not None:
            q = q.in_("id", ids_chunk)
        if _filtro_fu_rep and ids_chunk is None:
            col_f = "updated_at" if _tip_fu == "modificacion" else "created_at"
            q = _sicoe_aplicar_filtro_fecha_q(q, col_f, _fd_fu, _fh_fu)
            if _uid_fu is not None:
                q = _sicoe_aplicar_filtro_usuario_reportes_q(q, _uid_fu, _uacc_fu)
        return q

    # ── Cabeceras: sin precargar miles de reportes (*) para ordenar/paginar en Python.
    #    - Sin universo por línea: orden + range en BD (solo la página solicitada).
    #    - Con reporte_ids_from_reg: sólo id+numero_reporte para ordenar todo el universo filtrado;
    #      luego select * + join sólo para offset..offset+limit de esos IDs (~50 filas típ.).
    rows: List[Dict[str, Any]] = []
    hay_mas = False
    _vm_grilla_usada = False

    _hay_n23_vm = (
        (_validacion_cualquier_nivel2_o_3(capas_v) if capas_v else False)
        or (_nivel_l is not None and _es_validacion_avanzada(_nivel_l))
    )
    _puede_vm_grilla = (
        not consulta_directa_identificador
        and not unified_line
        and not capas_aplican_a_lineas
        and not _defer_capas_or_grilla
        and not _filtro_fu_rep
        and not (q_nodo is not None and str(q_nodo).strip())
        and etiqueta_f is None
        and not pendiente_item
    )

    if _puede_vm_grilla:
        try:
            vm_page_ids, vm_hay_mas = _sicoe_vm_grilla_paginar(
                contrato_id,
                offset,
                limit,
                numero_reporte=numero_reporte,
                semana_id=semana_id_filtro,
                acta_id=acta_id_filtro,
                estado=estado if not _estado_sin_asignar_item else None,
                excluir_estados_avanzados=_hay_n23_vm,
                reporte_ids=reporte_ids_from_reg,
            )
            hay_mas = vm_hay_mas
            page_ids_ordered = vm_page_ids
            rows = []
            for j in range(0, len(page_ids_ordered), _IDS_CHUNK_SIZE):
                chk = page_ids_ordered[j : j + _IDS_CHUNK_SIZE]

                def _qfull_ids(c=chk):
                    return _build_q(c).execute().data

                batch = supabase_execute(_qfull_ids) or []
                by_id = {r["id"]: r for r in batch}
                for rid_one in chk:
                    if rid_one in by_id:
                        rows.append(by_id[rid_one])
            if rows:
                _vm_grilla_usada = True
        except Exception:
            rows = []
            hay_mas = False

    if reporte_ids_from_reg is not None and not rows:
        id_num: Dict[int, int] = {}
        seen_rid = set()
        for i in range(0, len(reporte_ids_from_reg), _IDS_CHUNK_SIZE):
            _chunk = reporte_ids_from_reg[i : i + _IDS_CHUNK_SIZE]

            def _qc_ids(c=_chunk):
                return _build_q(c, lite=True).execute().data

            for row in supabase_execute(_qc_ids) or []:
                rid_one = row.get("id")
                if rid_one is None or rid_one in seen_rid:
                    continue
                seen_rid.add(rid_one)
                try:
                    n = int(row.get("numero_reporte") or 0)
                except (TypeError, ValueError):
                    n = 0
                id_num[int(rid_one)] = n
        sorted_ids = sorted(id_num.keys(), key=lambda rr: id_num[rr], reverse=True)
        page_slice = sorted_ids[offset : offset + limit + 1]
        hay_mas = len(page_slice) > limit
        page_ids_ordered = page_slice[:limit]
        rows = []
        for j in range(0, len(page_ids_ordered), _IDS_CHUNK_SIZE):
            chk = page_ids_ordered[j : j + _IDS_CHUNK_SIZE]

            def _qfull_ids(c=chk):
                return _build_q(c).execute().data

            batch = supabase_execute(_qfull_ids) or []
            by_id = {r["id"]: r for r in batch}
            for rid_one in chk:
                if rid_one in by_id:
                    rows.append(by_id[rid_one])
    elif not rows:
        q_page = _build_q(None).order("numero_reporte", desc=True)

        def _qrange_pg():
            return q_page.range(offset, offset + limit).execute().data

        pg = supabase_execute(_qrange_pg) or []
        hay_mas = len(pg) > limit
        rows = pg[:limit]

    # Batch-resolve semana_numero y acta_rpo
    semana_ids = list({r["semana_id"] for r in rows if r.get("semana_id")})
    acta_ids   = list({r["acta_rpo_id"] for r in rows if r.get("acta_rpo_id")})
    semana_map = {}
    if semana_ids:
        try:
            def _sems():
                return supabase.table("so_semanas").select("id, numero_semana")\
                    .in_("id", semana_ids).execute().data
            for s in supabase_execute(_sems):
                semana_map[s["id"]] = s["numero_semana"]
        except Exception:
            pass
    acta_map = {}
    if acta_ids:
        try:
            def _actas():
                return supabase.table("actas").select("id, numero_rpo, consecutivo")\
                    .in_("id", acta_ids).execute().data
            for a in supabase_execute(_actas):
                acta_map[a["id"]] = a
        except Exception:
            pass
    # Batch-resolve per-cargo estado_max desde so_registros
    reporte_ids_batch = [r["id"] for r in rows]
    _usar_vm_agregados_grilla = (
        _vm_grilla_usada
        and reporte_ids_batch
        and not capas_v
        and not _defer_capas_or_grilla
        and not caps_buscar_norm
        and not items_buscar_norm
        and subcontratista_id is None
        and not tramo
        and not costado
        and pk_id is None
        and not q_obs_trim
        and numero_registro is None
        and not pendiente_item
        and registro_ids_etiqueta is None
        and abs_inicio is None
        and abs_final is None
        and cantidad_desde is None
        and cantidad_hasta is None
        and costo_directo_desde is None
        and costo_directo_hasta is None
        and not _filtro_fu_reg
        and not _estado_sin_asignar_item
    )
    if reporte_ids_batch:
        try:
            if _usar_vm_agregados_grilla:
                vm_agg = _sicoe_vm_grilla_agregados(reporte_ids_batch)
                for r in rows:
                    agg = vm_agg.get(int(r["id"]), {})
                    r["num_registros"] = int(agg.get("total_registros") or 0)
                    if not _ocultar_costo_rep:
                        r["costo_directo_validacion"] = round(float(agg.get("costo_directo_total") or 0), 0)
                    r["nivel1_estados"] = []
                    r["nivel2_estados"] = []
                    r["nivel3_estados"] = []
                    r["sub_estados"] = []
            else:
                _rb_l = reporte_ids_batch

                def _reg_estados_q_base(reg_id_filter: Optional[List[int]] = None):
                    q = supabase.table("so_registros")\
                        .select("reporte_id, costo_directo, " + SICOE_SELECT_NIVELES_ESTADO + ", sub_estado, semana_id, acta_rpo_id, item_numero, capitulo, subcontratista_id, tramo, margen")\
                        .in_("reporte_id", _rb_l)
                    if reg_id_filter is not None:
                        q = q.in_("id", reg_id_filter)

                    if numero_registro is not None:
                        q = q.eq("numero_registro", numero_registro)

                    # Mantener coherencia con el universo filtrado de grilla/panel
                    if semana_id_filtro is not None:
                        q = q.eq("semana_id", semana_id_filtro)
                    if aids_linea_buscar:
                        q = _apply_acta_rpo_ids_to_so_registros_q(q, aids_linea_buscar)
                    if caps_buscar_norm:
                        q = _apply_capitulos_to_so_registros_q(q, caps_buscar_norm)
                    if subcontratista_id is not None:
                        q = q.eq("subcontratista_id", subcontratista_id)
                    q = _apply_item_patterns_to_so_registros_q(q, items_buscar_norm, items_buscar_op)
                    if tramo:
                        q = q.eq("tramo", tramo)
                    if costado:
                        q = _so_reg_filtro_costado(q, costado)
                    if pk_id is not None:
                        q = q.eq("pk_id_id", pk_id)
                    if q_observacion is not None and str(q_observacion).strip():
                        q = q.ilike("observacion", f"%{str(q_observacion).strip()}%")
                    q = _so_reg_filtro_abs_solape(q, abs_inicio, abs_final)
                    if acta_id_para_lineas is not None and not _estado_filtro_es_sin_asignar_item(estado):
                        q = _so_reg_item_asignado(q)

                    if capas_v and not _estado_filtro_omite_validacion_por_cargo(estado):
                        if not _defer_capas_or_grilla:
                            q = _so_registros_q_y_capas_validacion(
                                q, capas_v, pk_id, tramo, costado, capitulo, subcontratista_id, None, contrato_id
                            )

                    if _estado_filtro_es_sin_asignar_item(estado):
                        q = _so_reg_sin_item_asignado(q)
                    if pendiente_item:
                        q = _sicoe_so_registros_q_aplicar_filtro_pendiente_item_matriz(q, contrato_id=contrato_id)
                    return q

                reg_estados = []
                if registro_ids_etiqueta is not None and not registro_ids_etiqueta:
                    reg_estados = []
                elif registro_ids_etiqueta is not None:
                    for rg_chunk in _sicoe_chunks_int(sorted(registro_ids_etiqueta), 200):
                        rc = list(rg_chunk)
                        _re_off = 0
                        _re_page = 1000
                        while True:
                            def _re_fetch(o=_re_off, ids=rc):
                                return _reg_estados_q_base(ids).order("id").range(o, o + _re_page - 1).execute().data

                            _batch = supabase_execute(_re_fetch)
                            reg_estados.extend(_batch)
                            if len(_batch) < _re_page:
                                break
                            _re_off += _re_page
                else:
                    _re_off = 0
                    _re_page = 1000
                    while True:
                        def _re_fetch(o=_re_off):
                            return _reg_estados_q_base().order("id").range(o, o + _re_page - 1).execute().data

                        _batch = supabase_execute(_re_fetch)
                        reg_estados.extend(_batch)
                        if len(_batch) < _re_page:
                            break
                        _re_off += _re_page
                if _estado_filtro_es_sin_asignar_item(estado):
                    reg_estados = [
                        x for x in reg_estados
                        if not _sicoe_registro_tiene_item_asignado(x)
                    ]
                if _defer_capas_or_grilla:
                    reg_estados = _filtrar_registros_validacion_capas_sicoe(
                        reg_estados, capas_v, None, "or", contrato_id
                    )
                cmx_aggr = _get_nivel_maximo_contrato(contrato_id)
                cargo_map = {r["id"]: {"n1": [], "n2": [], "n3": [], "sub": [], "count": 0} for r in rows}
                costo_map = {}
                for reg in reg_estados:
                    rid = reg.get("reporte_id")
                    if rid in cargo_map:
                        cargo_map[rid]["n1"].append(reg.get("nivel1_estado") or "No Revisado")
                        cargo_map[rid]["n2"].append(reg.get("nivel2_estado") or "No Revisado")
                        cargo_map[rid]["n3"].append(reg.get(cmx_aggr) or "No Revisado")
                        cargo_map[rid]["sub"].append(reg.get("sub_estado") or "No Revisado")
                        cargo_map[rid]["count"] += 1
                        costo_map[rid] = costo_map.get(rid, 0.0) + float(reg.get("costo_directo") or 0)
                cap_por_rep: dict = {}
                for reg in reg_estados:
                    rid = reg.get("reporte_id")
                    if not rid:
                        continue
                    c = (reg.get("capitulo") or "").strip()
                    if rid not in cap_por_rep:
                        cap_por_rep[rid] = set()
                    if c:
                        cap_por_rep[rid].add(c)
                for r in rows:
                    m = cargo_map.get(r["id"], {})
                    r["nivel1_estados"] = list(set(m.get("n1", [])))
                    r["nivel2_estados"] = list(set(m.get("n2", [])))
                    r["nivel3_estados"] = list(set(m.get("n3", [])))
                    r["sub_estados"]    = list(set(m.get("sub", [])))
                    r["num_registros"] = m.get("count", 0)
                    if not _ocultar_costo_rep:
                        r["costo_directo_validacion"] = round(costo_map.get(r["id"], 0.0), 0)
                    caps = cap_por_rep.get(r["id"], set())
                    if caps:
                        r["capitulo"] = ", ".join(sorted(caps))
        except Exception:
            for r in rows:
                r["nivel1_estados"] = r["nivel2_estados"] = r["nivel3_estados"] = r["sub_estados"] = []
                r["num_registros"] = 0
            if not _ocultar_costo_rep:
                for r in rows:
                    r["costo_directo_validacion"] = 0.0

    # "Sin asignar ítem" aplica a registros: un reporte sin filas en so_registros no puede asignar ítem
    if _estado_filtro_es_sin_asignar_item(estado):
        rows = [r for r in rows if (r.get("num_registros") or 0) > 0]

    for r in rows:
        sub = r.pop("subcontratistas", None)
        r["subcontratista_nombre"] = sub["razon_social"] if sub else None
        r["semana_numero"]    = semana_map.get(r.get("semana_id"))
        acta = acta_map.get(r.get("acta_rpo_id"))
        r["acta_rpo"]         = acta["numero_rpo"] if acta else None
        r["acta_consecutivo"] = acta["consecutivo"] if acta else None

    # Si la búsqueda está en modo validación por nivel, eliminar reportes
    # sin registros coincidentes para evitar descuadres panel/grilla.
    if _nivel_l and _ev_l:
        rows = [r for r in rows if (r.get("num_registros") or 0) > 0]

    return {"reportes": rows, "total": len(rows), "offset": offset, "limit": limit, "hay_mas": hay_mas}


# ─── SICOE OBRA: Exportar registros filtrados ───────────────────────────────

def _as_int_id(val) -> Optional[int]:
    try:
        return int(val) if val is not None else None
    except (TypeError, ValueError):
        return None


def _sicoe_enriquecer_registros_export(rows: List[dict]) -> List[dict]:
    """Resuelve FK internas (reporte, acta, semana, PK, subcontratista, inspector) a valores de negocio."""
    if not rows:
        return rows
    reporte_ids = list({r.get("reporte_id") for r in rows if r.get("reporte_id")})
    rep_map = {}
    if reporte_ids:
        try:
            rep_rows = supabase_execute(
                lambda: supabase.table("so_reportes")
                .select("id, numero_reporte, acta_rpo_id, semana_id, pk_id_id, subcontratista_id, inspector_id")
                .in_("id", reporte_ids)
                .execute()
                .data
            )
            rep_map = {r["id"]: r for r in rep_rows if r.get("id")}
        except Exception:
            rep_map = {}

    acta_ids = list({
        aid
        for r in rows
        for raw_aid in (
            r.get("acta_rpo_id"),
            (rep_map.get(r.get("reporte_id")) or {}).get("acta_rpo_id"),
        )
        for aid in [(_as_int_id(raw_aid) if raw_aid is not None else None)]
        if aid is not None
    })
    semana_ids = list({
        (r.get("semana_id") or (rep_map.get(r.get("reporte_id")) or {}).get("semana_id"))
        for r in rows
        if (r.get("semana_id") or (rep_map.get(r.get("reporte_id")) or {}).get("semana_id"))
    })
    pk_ids = list({
        rid
        for r in rows
        for rid in (
            r.get("pk_id_id"),
            (rep_map.get(r.get("reporte_id")) or {}).get("pk_id_id"),
        )
        if rid
    })

    acta_map = {}
    if acta_ids:
        try:
            aa = supabase_execute(
                lambda: supabase.table("actas")
                .select("id, numero_rpo, consecutivo")
                .in_("id", acta_ids)
                .execute()
                .data
            )
            acta_map = {
                int(a["id"]): (
                    a.get("numero_rpo") if a.get("numero_rpo") not in (None, "") else a.get("consecutivo")
                )
                for a in aa
                if a.get("id") is not None
            }
        except Exception:
            acta_map = {}

    semana_map = {}
    if semana_ids:
        try:
            ss = supabase_execute(
                lambda: supabase.table("so_semanas")
                .select("id, numero_semana")
                .in_("id", semana_ids)
                .execute()
                .data
            )
            semana_map = {s["id"]: s.get("numero_semana") for s in ss if s.get("id")}
        except Exception:
            semana_map = {}

    pk_map = {}
    if pk_ids:
        try:
            pp = supabase_execute(
                lambda: supabase.table("pk_ids")
                .select("id, pk_id")
                .in_("id", pk_ids)
                .execute()
                .data
            )
            pk_map = {p["id"]: p.get("pk_id") for p in pp if p.get("id")}
        except Exception:
            pk_map = {}

    sub_ids = list({
        (r.get("subcontratista_id") or (rep_map.get(r.get("reporte_id")) or {}).get("subcontratista_id"))
        for r in rows
        if (r.get("subcontratista_id") or (rep_map.get(r.get("reporte_id")) or {}).get("subcontratista_id"))
    })
    sub_map = {}
    if sub_ids:
        try:
            ssb = supabase_execute(
                lambda: supabase.table("subcontratistas")
                .select("id, razon_social")
                .in_("id", sub_ids)
                .execute()
                .data
            )
            sub_map = {s["id"]: s.get("razon_social") for s in ssb if s.get("id")}
        except Exception:
            sub_map = {}

    insp_ids = list({
        (r.get("inspector_id") or (rep_map.get(r.get("reporte_id")) or {}).get("inspector_id"))
        for r in rows
        if (r.get("inspector_id") or (rep_map.get(r.get("reporte_id")) or {}).get("inspector_id"))
    })
    insp_map = {}
    if insp_ids:
        try:
            uu = supabase_execute(
                lambda: supabase.table("usuarios")
                .select("id, nombre, apellidos")
                .in_("id", insp_ids)
                .execute()
                .data
            )
            insp_map = {
                u["id"]: f"{u.get('nombre') or ''} {u.get('apellidos') or ''}".strip()
                for u in uu
                if u.get("id")
            }
        except Exception:
            insp_map = {}

    for r in rows:
        rep = rep_map.get(r.get("reporte_id")) or {}
        acta_id_raw = r.get("acta_rpo_id") or rep.get("acta_rpo_id")
        acta_id = _as_int_id(acta_id_raw)
        sem_id = r.get("semana_id") or rep.get("semana_id")
        pk_id_id = r.get("pk_id_id") or rep.get("pk_id_id")
        sub_id = r.get("subcontratista_id") or rep.get("subcontratista_id")
        insp_id = r.get("inspector_id") or rep.get("inspector_id")
        r["reporte_numero"] = rep.get("numero_reporte")
        r["acta_rpo_numero"] = acta_map.get(acta_id)
        r["semana_numero"] = semana_map.get(sem_id)
        # pk_id en so_registros es el valor de negocio; pk_id_id es FK interna opcional.
        r["pk_id_valor"] = r.get("pk_id") or pk_map.get(pk_id_id)
        r["subcontratista_nombre"] = sub_map.get(sub_id)
        r["inspector_nombre"] = insp_map.get(insp_id)
    return rows


_SICOE_XLSX_SKIP_KEYS = frozenset({
    "id",
    "contrato_id",
    "pk_id_id",
    "corte_id",
    # Virtuales de enriquecimiento (se vuelcan sobre las columnas *_id originales).
    "reporte_numero",
    "acta_rpo_numero",
    "semana_numero",
    "pk_id_valor",
    "subcontratista_nombre",
    "inspector_nombre",
})

_SICOE_XLSX_FK_A_VALOR = {
    "semana_id": "semana_numero",
    "acta_rpo_id": "acta_rpo_numero",
    "subcontratista_id": "subcontratista_nombre",
    "inspector_id": "inspector_nombre",
    "reporte_id": "reporte_numero",
}


def _sicoe_registros_xlsx_sin_ids_internos(rows: List[dict]) -> List[dict]:
    """Export dashboard: mismas columnas que so_registros, FKs con valor legible (no ID interno).

    - pk_id_id (FK interna) se exporta como pk_id con el valor de pk_ids.pk_id.
    - numero_registro permanece (en lugar del id interno de fila).
    - semana_id / acta_rpo_id / subcontratista_id / inspector_id / reporte_id muestran
      número de semana, acta, nombre, inspector y reporte respectivamente.
    """
    if not rows:
        return []
    enriched = _sicoe_enriquecer_registros_export([dict(r) for r in rows])

    def _columnas(sample: dict) -> List[str]:
        cols: List[str] = []
        for k in sample.keys():
            if k == "pk_id_id":
                if "pk_id" not in cols:
                    cols.append("pk_id")
                continue
            if k in _SICOE_XLSX_SKIP_KEYS:
                continue
            if k.startswith("nivel") and k.endswith("_usuario_id"):
                continue
            if k == "pk_id" and "pk_id" in cols:
                continue
            cols.append(k)
        if "pk_id" not in cols and sample.get("pk_id_valor") is not None:
            cols.append("pk_id")
        return cols

    col_order = _columnas(enriched[0])
    out: List[dict] = []
    for r in enriched:
        row: dict = {}
        for k in col_order:
            if k == "pk_id":
                row[k] = r.get("pk_id_valor") or r.get("pk_id")
            elif k in _SICOE_XLSX_FK_A_VALOR:
                row[k] = r.get(_SICOE_XLSX_FK_A_VALOR[k])
            else:
                row[k] = r.get(k)
        out.append(row)
    return out


class ExportarRegistrosBody(BaseModel):
    campos: List[str]

    # Filtros (mismos nombres que la grilla / buscar_reportes_obra)
    numero_reporte: Optional[int] = None
    numero_registro: Optional[int] = None
    semana: Optional[int] = None
    acta_rpo: Optional[int] = None
    subcontratista_id: Optional[int] = None
    capitulo: Optional[str] = None
    item: Optional[str] = None
    items_filtro: Optional[str] = None
    items_filtro_op: Optional[str] = None
    tramo: Optional[str] = None
    costado: Optional[str] = None
    pk_id: Optional[int] = None
    abs_inicio: Optional[float] = None
    abs_final: Optional[float] = None
    estado: Optional[str] = None

    # Validación por nivel (JSON [{cargo_id, estado}, ...] o capasValidacion[0] vía cargo_id/estado)
    cargo_id: Optional[int] = None
    estado_validacion: Optional[str] = None
    validacion_capas: Optional[str] = None
    validacion_capas_op: Optional[str] = None

    q_observacion: Optional[str] = None
