def _normalizar_macro_rol(valor: Optional[str]) -> Optional[str]:
    txt = (valor or "").strip().lower()
    if not txt:
        return None
    if "intervent" in txt:
        return "interventoria"
    # Subcontratista se considera del lado contratista para confidencialidad.
    if "subcontrat" in txt:
        return "contratista"
    if "contrat" in txt:
        return "contratista"
    return None

def _macro_rol_usuario_por_id(usuario_id: Optional[int]) -> Optional[str]:
    if not usuario_id:
        return None
    try:
        u = supabase.table("usuarios").select("cargo_id, rol_id").eq("id", usuario_id).single().execute().data or {}
        cargo_id = u.get("cargo_id")
        if cargo_id:
            c = supabase.table("cargos").select("nombre").eq("id", cargo_id).single().execute().data or {}
            m = _normalizar_macro_rol(c.get("nombre"))
            if m:
                return m
        rol_id = u.get("rol_id")
        if rol_id:
            r = supabase.table("roles").select("nombre").eq("id", rol_id).single().execute().data or {}
            m = _normalizar_macro_rol(r.get("nombre"))
            if m:
                return m
        return None
    except Exception:
        return None

def _macro_rol_current_user(current_user) -> Optional[str]:
    try:
        uid = int(current_user.get("sub") or current_user.get("id", 0))
    except (TypeError, ValueError):
        return None
    return _macro_rol_usuario_por_id(uid)

def _cargo_current_user(current_user) -> str:
    try:
        uid = int(current_user.get("sub") or current_user.get("id", 0))
        u = supabase.table("usuarios").select("cargo_id").eq("id", uid).single().execute().data or {}
        cargo_id = u.get("cargo_id")
        if not cargo_id:
            return ""
        c = supabase.table("cargos").select("nombre").eq("id", cargo_id).single().execute().data or {}
        return (c.get("nombre") or "").strip().lower()
    except Exception:
        return ""

def _macro_roles_destinatarios(destinatarios: list) -> set:
    roles_dest = set()
    for d in (destinatarios or []):
        if not isinstance(d, dict):
            continue
        r_macro = _normalizar_macro_rol(
            d.get("rol") or d.get("rol_nombre") or d.get("cargo_nombre") or d.get("cargo")
        )
        if not r_macro:
            r_macro = _macro_rol_usuario_por_id(d.get("id"))
        if r_macro:
            roles_dest.add(r_macro)
    return roles_dest


def _insertar_comentario(contrato_id: int, registro_id: int, autor_id: int,
                         comentario_data: dict, tipo_override: str = None, nivel_validacion_override: str = None,
                         audit_user=None):
    """Inserta un comentario en so_registro_comentarios calculando confidencialidad."""
    destinatarios = comentario_data.get("destinatarios") or []
    rol_origen_payload = comentario_data.get("rol_origen", "")
    # Fuente de verdad: preferir el lado real del autor en BD.
    rol_origen_macro = _normalizar_macro_rol(rol_origen_payload) or _macro_rol_usuario_por_id(autor_id)
    rol_origen = (rol_origen_macro or (rol_origen_payload or "").strip() or None)
    if not rol_origen:
        # El CHECK en BD exige un macro-rol reconocible (p. ej. contratista / interventoria).
        rol_origen = "contratista"

    roles_dest = _macro_roles_destinatarios(destinatarios)

    if not destinatarios:
        confidencialidad = "publico"
    else:
        if roles_dest == {"contratista"} and rol_origen_macro == "contratista":
            confidencialidad = "contratista_interno"
        elif roles_dest == {"interventoria"} and rol_origen_macro == "interventoria":
            confidencialidad = "interventoria_interna"
        elif not roles_dest:
            confidencialidad = "publico"
        else:
            confidencialidad = "cruzado"

    row = {
        "registro_id":        registro_id,
        "contrato_id":        contrato_id,
        "autor_id":           autor_id,
        "rol_origen":         rol_origen,
        "confidencialidad":   confidencialidad,
        "destinatarios":      destinatarios,
        "etiqueta":           comentario_data.get("etiqueta"),
        "asunto":             comentario_data.get("asunto"),
        "mensaje":            comentario_data.get("mensaje"),
        "enlaces":            comentario_data.get("enlaces") or [],
        "cantidad_verificada": comentario_data.get("cantidad_verificada"),
        "tipo":               tipo_override or comentario_data.get("tipo"),
        "nivel_validacion":   nivel_validacion_override or comentario_data.get("nivel_validacion"),
        "padre_id":           comentario_data.get("padre_id"),
    }

    def _ins():
        return supabase.table("so_registro_comentarios").insert(row).execute().data
    try:
        data = supabase_execute(_ins)
    except Exception as ex:
        low = str(ex).lower()
        if "so_registro_comentarios_tipo_check" in low or (
            "23514" in low and "tipo" in low
        ):
            raise HTTPException(
                status_code=503,
                detail=(
                    "Falta ejecutar la migración SQL "
                    "alter_so_registro_comentarios_tipo_reversion_doble_llave.sql en Supabase."
                ),
            ) from ex
        raise
    ins_row = data[0] if data else {}
    if audit_user and ins_row:
        try:
            u_log = _audit_user_contrato(audit_user, contrato_id)
            msg = ins_row.get("mensaje") or ""
            registrar_log(
                u_log,
                "COMENTAR",
                "SICOE",
                "registro",
                str(registro_id),
                {
                    "so_comentario_id": ins_row.get("id"),
                    "tipo": ins_row.get("tipo"),
                    "nivel_validacion": ins_row.get("nivel_validacion"),
                    "etiqueta": ins_row.get("etiqueta"),
                    "asunto": ins_row.get("asunto"),
                    "mensaje_excerpt": msg[:800],
                },
                severidad="AUDIT",
            )
        except Exception:
            pass
    return ins_row


def _put_validar_nivel_sicoe_alto(
    contrato_id: int,
    registro_id: int,
    body: ValidarNivel3Body,
    nivel: int,
    current_user,
):
    """Lógica compartida de PUT validar-nivel3 … nivel6 (bloqueado solo al aprobar el nivel máximo activo del contrato)."""
    if nivel not in (3, 4, 5, 6):
        raise HTTPException(status_code=500, detail="Nivel interno inválido.")
    activos = _get_niveles_activos_contrato(contrato_id)
    if nivel not in activos:
        raise HTTPException(
            status_code=422,
            detail=f"El contrato no tiene activo el nivel {nivel} de validación.",
        )
    ESTADOS = {"Aprobado", "Pendiente", "Rechazado"}
    if body.estado not in ESTADOS:
        raise HTTPException(status_code=422, detail=f"Estado inválido. Acepta: {ESTADOS}")
    if body.estado in ("Pendiente", "Rechazado") and not body.comentario_data:
        raise HTTPException(
            status_code=422,
            detail="Se requiere comentario_data cuando el estado es Pendiente o Rechazado.",
        )
    try:
        autor_id = int(current_user.get("sub") or current_user.get("id", 0))
        _require_sicoe_puede_validar_nivel(current_user, autor_id, nivel, contrato_id)
        campo = NIVEL_VALIDACION_NUM_A_CAMPO.get(nivel)
        if not campo:
            raise HTTPException(status_code=500, detail="Mapa de nivel inconsistente.")
        # Misma regla que filtros / `_so_registros_q_y_capas_validacion`: nivel previo *activo* en el contrato
        # (p. ej. [1,2,4] → validar N4 exige N2 aprobado, no N3).
        prereq = _get_prereq_nivel_activo(campo, contrato_id) or CARGO_NIVEL_PRERREQUISITO.get(campo)
        if not prereq:
            raise HTTPException(status_code=500, detail="Sin prerrequisito para este nivel.")
        prev_f, prev_ok = prereq

        def _get():
            return (
                supabase.table("so_registros")
                .select(f"{prev_f},{campo}")
                .eq("id", registro_id)
                .eq("contrato_id", contrato_id)
                .limit(1)
                .execute()
                .data
            )

        rows = supabase_execute(_get)
        if not rows:
            raise HTTPException(status_code=404, detail="Registro no encontrado.")
        r0 = rows[0]
        if (r0.get(campo) or "") == "Aprobado" and body.estado != "Aprobado":
            raise HTTPException(
                status_code=400,
                detail=f"El registro ya está aprobado en Nivel {nivel}. Use el flujo de reversión para modificar la validación.",
            )
        if r0.get(prev_f) != prev_ok:
            raise HTTPException(
                status_code=422,
                detail=f"El registro debe estar {prev_ok} en el nivel previo antes de validar en Nivel {nivel}.",
            )

        prev_audit = _so_registro_fetch_validacion_audit(contrato_id, registro_id) or {}
        u_key, f_key = _sicoe_campo_usuario_fecha_desde_estado(campo)
        update = {
            campo: body.estado,
            u_key: autor_id,
            f_key: datetime.utcnow().isoformat(),
        }
        _sicoe_aplicar_bloqueado_si_nivel_es_maximo(contrato_id, nivel, update, body.estado)

        def _upd():
            return (
                supabase.table("so_registros")
                .update(update)
                .eq("id", registro_id)
                .eq("contrato_id", contrato_id)
                .execute()
                .data
            )

        supabase_execute(_upd)
        if body.estado == "Aprobado":
            try:
                _aplicar_acta_rpo_vigente_a_registro(contrato_id, registro_id, date.today())
            except Exception:
                pass
        if body.comentario_data:
            _insertar_comentario(
                contrato_id,
                registro_id,
                autor_id,
                body.comentario_data,
                tipo_override="validacion",
                nivel_validacion_override=f"Nivel {nivel}",
                audit_user=current_user,
            )
            _push_notif_validacion_sicoe_destinatarios(
                current_user,
                autor_id,
                contrato_id,
                registro_id,
                f"Validación Nivel {nivel}: {body.estado}",
                body.comentario_data.get("mensaje", "") or "",
                body.comentario_data,
            )
        try:
            u_log = _audit_user_contrato(current_user, contrato_id)
            after_audit = _so_registro_fetch_validacion_audit(contrato_id, registro_id) or {}
            registrar_log(
                u_log,
                "VALIDAR",
                "SICOE",
                "registro",
                str(registro_id),
                {"nivel": nivel, "estado": body.estado},
                valor_anterior=_so_registro_validacion_audit_snapshot(prev_audit),
                valor_nuevo=_so_registro_validacion_audit_snapshot(after_audit),
            )
        except Exception:
            pass
        return {"ok": True}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


def _roles_nombres_por_ids(rol_ids: Iterable[int]) -> Dict[int, str]:
    ids = sorted({int(x) for x in rol_ids if x is not None})
    if not ids:
        return {}
    try:
        rows = (
            supabase.table("roles")
            .select("id, nombre")
            .in_("id", ids)
            .execute()
            .data
            or []
        )
    except Exception:
        return {}
    out: Dict[int, str] = {}
    for r in rows:
        try:
            out[int(r["id"])] = (r.get("nombre") or "").strip()
        except (TypeError, ValueError, KeyError):
            continue
    return out


def _encabezado_nivel_con_rol(nivel: int, rol_id: Optional[int], rol_nombre: Optional[str]) -> str:
    base = NIVEL_VALIDACION_ENCABEZADO.get(nivel) or f"Nivel {nivel}"
    nom = (rol_nombre or "").strip()
    if nom:
        return f"Nivel {nivel} · {nom}"
    if rol_id is not None and rol_id != DEFAULT_ROLES_POR_NIVEL.get(nivel):
        return f"Nivel {nivel} · rol #{rol_id}"
    return base


@app.get("/sicoe-obra/{contrato_id}/niveles-validacion")
def sicoe_obra_niveles_validacion(contrato_id: int, current_user=Depends(get_current_user)):
    """Niveles activos + mapa rol→nivel del contrato (`contrato_niveles_validacion`)."""
    _ = current_user
    ma, roles_raw = _get_contrato_niveles_cfg(contrato_id)
    rpm = _roles_por_nivel_efectivo(roles_raw)
    mx = max(ma) if ma else 3
    campo_mx = f"nivel{min(6, max(1, mx))}_estado"
    nombres = _roles_nombres_por_ids(rpm.values())
    niveles = []
    for n in ma:
        rid = rpm.get(n)
        rnom = nombres.get(rid) if rid is not None else None
        niveles.append(
            {
                "nivel": n,
                "campo": NIVEL_VALIDACION_NUM_A_CAMPO[n],
                "encabezado": _encabezado_nivel_con_rol(n, rid, rnom),
                "rol_id": rid,
                "rol_nombre": rnom,
            }
        )
    roles_por_nivel_out = {str(k): v for k, v in sorted(rpm.items())}
    roles_raw_out = {str(k): v for k, v in sorted(roles_raw.items())}
    return {
        "contrato_id": contrato_id,
        "niveles_activos": ma,
        "nivel_maximo": mx,
        "campo_nivel_maximo": campo_mx,
        "roles_por_nivel": roles_por_nivel_out,
        "roles_por_nivel_configurados": roles_raw_out,
        "niveles": niveles,
    }


@app.put("/sicoe-obra/{contrato_id}/niveles-validacion")
def sicoe_obra_put_niveles_validacion(
    contrato_id: int,
    body: NivelesValidacionContratoPutBody,
    current_user=Depends(get_current_user),
):
    """Upsert en `contrato_niveles_validacion`. Solo desarrollador o administrador."""
    _, cargo = _caller_contract_scope(current_user)
    if (cargo or "").strip().lower() not in ("desarrollador", "administrador"):
        raise HTTPException(
            status_code=403,
            detail="Solo desarrollador o administrador pueden configurar niveles de validación.",
        )
    raw = body.niveles_activos or []
    if not isinstance(raw, list) or len(raw) < 2:
        raise HTTPException(status_code=422, detail="Debe indicar al menos 2 niveles activos.")
    norm: List[int] = []
    for x in raw:
        try:
            xi = int(x)
        except (TypeError, ValueError):
            raise HTTPException(status_code=422, detail="niveles_activos debe ser una lista de enteros entre 1 y 6.")
        if xi < 1 or xi > 6:
            raise HTTPException(status_code=422, detail="Cada nivel debe estar entre 1 y 6.")
        if xi not in norm:
            norm.append(xi)
    norm.sort()

    roles_parsed = _parse_roles_por_nivel_raw(body.roles_por_nivel) if body.roles_por_nivel is not None else None
    if roles_parsed is not None:
        # Completar activos sin rol con default; exigir unicidad entre niveles activos.
        for n in norm:
            if n not in roles_parsed:
                roles_parsed[n] = DEFAULT_ROLES_POR_NIVEL[n]
        seen_rol: Dict[int, int] = {}
        for n in norm:
            rid = roles_parsed[n]
            if rid in seen_rol:
                raise HTTPException(
                    status_code=422,
                    detail=(
                        f"El mismo rol_id={rid} no puede ocupar dos niveles activos "
                        f"(N{seen_rol[rid]} y N{n})."
                    ),
                )
            seen_rol[rid] = n
        # Persistir solo niveles 1–6 presentes en el payload efectivo (activos + opcionales extra).
        roles_store = {str(k): int(v) for k, v in sorted(roles_parsed.items()) if 1 <= k <= 6}
    else:
        roles_store = None

    ex = supabase.table("contratos").select("id").eq("id", contrato_id).limit(1).execute()
    if not ex.data:
        raise HTTPException(status_code=404, detail="Contrato no encontrado")
    row_up: Dict[str, Any] = {"contrato_id": contrato_id, "niveles_activos": norm}
    if roles_store is not None:
        row_up["roles_por_nivel"] = roles_store
    try:
        supabase.table("contrato_niveles_validacion").upsert(
            row_up,
            on_conflict="contrato_id",
        ).execute()
    except Exception as e:
        # Si la columna aún no existe, guardar al menos niveles_activos.
        if roles_store is not None and "roles_por_nivel" in str(e).lower():
            supabase.table("contrato_niveles_validacion").upsert(
                {"contrato_id": contrato_id, "niveles_activos": norm},
                on_conflict="contrato_id",
            ).execute()
            raise HTTPException(
                status_code=503,
                detail=(
                    "Falta migrar la columna roles_por_nivel "
                    "(backend/sql/contrato_niveles_validacion_roles_por_nivel.sql)."
                ),
            )
        raise
    _invalidar_cache_niveles_contrato(contrato_id)
    rpm_eff = _get_roles_por_nivel_contrato(contrato_id)
    return {
        "ok": True,
        "contrato_id": contrato_id,
        "niveles_activos": norm,
        "roles_por_nivel": {str(k): v for k, v in sorted(rpm_eff.items())},
    }


@app.put("/sicoe-obra/{contrato_id}/registros/{registro_id}/validar-nivel1")
def validar_nivel1(contrato_id: int, registro_id: int, body: ValidarNivel1Body,
                   current_user=Depends(get_current_user)):
    ESTADOS = {"Aprobado", "Pendiente", "Rechazado"}
    if body.estado not in ESTADOS:
        raise HTTPException(status_code=422, detail=f"Estado inválido. Acepta: {ESTADOS}")
    if body.estado in ("Pendiente", "Rechazado") and not body.comentario_data:
        raise HTTPException(status_code=422,
            detail="Se requiere comentario_data cuando el estado es Pendiente o Rechazado.")
    try:
        autor_id = int(current_user.get("sub") or current_user.get("id", 0))
        _require_sicoe_puede_validar_nivel(current_user, autor_id, 1, contrato_id)
        def _get_n3():
            return supabase.table("so_registros").select(
                f"contrato_id,{SICOE_SELECT_NIVELES_ESTADO},reporte_id"
            ).eq("id", registro_id).eq("contrato_id", contrato_id).limit(1).execute().data
        n3rows = supabase_execute(_get_n3)
        if not n3rows:
            raise HTTPException(status_code=404, detail="Registro no encontrado.")
        if _registro_nivel_max_aprobado(n3rows[0], contrato_id):
            raise HTTPException(
                status_code=400,
                detail="El registro está aprobado en el último nivel de validación del contrato y no puede modificarse por esta vía.",
            )
        prev_audit = _so_registro_fetch_validacion_audit(contrato_id, registro_id) or {}
        update = {
            "nivel1_estado":     body.estado,
            "nivel1_usuario_id": autor_id,
            "nivel1_fecha":      datetime.utcnow().isoformat(),
        }
        # Actualizar modificado_por en so_reportes para reflejar la validación
        try:
            def _get_rep_id():
                return supabase.table("so_registros").select("reporte_id")\
                    .eq("id", registro_id).eq("contrato_id", contrato_id)\
                    .limit(1).execute().data
            rep_rows = supabase_execute(_get_rep_id)
            if rep_rows:
                rep_id = rep_rows[0]["reporte_id"]
                def _upd_rep():
                    return supabase.table("so_reportes")\
                        .update({"modificado_por": autor_id, "updated_at": datetime.utcnow().isoformat()})\
                        .eq("id", rep_id).eq("contrato_id", contrato_id).execute().data
                supabase_execute(_upd_rep)
        except Exception:
            pass
        def _upd():
            return supabase.table("so_registros")\
                .update(update).eq("id", registro_id)\
                .eq("contrato_id", contrato_id).execute().data
        supabase_execute(_upd)
        if body.comentario_data:
            _insertar_comentario(contrato_id, registro_id, autor_id, body.comentario_data,
                                 tipo_override="validacion", nivel_validacion_override="Nivel 1",
                                 audit_user=current_user)
            _push_notif_validacion_sicoe_destinatarios(
                current_user,
                autor_id,
                contrato_id,
                registro_id,
                f"Validación Nivel 1: {body.estado}",
                body.comentario_data.get("mensaje", "") or "",
                body.comentario_data,
            )
        try:
            u_log = _audit_user_contrato(current_user, contrato_id)
            after_audit = _so_registro_fetch_validacion_audit(contrato_id, registro_id) or {}
            registrar_log(
                u_log, "VALIDAR", "SICOE", "registro", str(registro_id),
                {"nivel": 1, "estado": body.estado},
                valor_anterior=_so_registro_validacion_audit_snapshot(prev_audit),
                valor_nuevo=_so_registro_validacion_audit_snapshot(after_audit),
            )
        except Exception:
            pass
        return {"ok": True}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.patch("/sicoe-obra/{contrato_id}/registros/{registro_id}/objeto-pago-sub")
def patch_objeto_pago_sub(
    contrato_id: int,
    registro_id: int,
    body: ObjetoPagoSubBody,
    current_user=Depends(get_current_user),
):
    """Marca o desmarca objeto de pago a subcontratista sin cambiar nivel2_estado."""
    try:
        autor_id = int(current_user.get("sub") or current_user.get("id", 0))
        _require_sicoe_puede_validar_nivel(current_user, autor_id, 2, contrato_id)

        def _get():
            return (
                supabase.table("so_registros")
                .select(f"contrato_id,nivel1_estado,{SICOE_SELECT_NIVELES_ESTADO}")
                .eq("id", registro_id)
                .eq("contrato_id", contrato_id)
                .limit(1)
                .execute()
                .data
            )

        rows = supabase_execute(_get)
        if not rows:
            raise HTTPException(status_code=404, detail="Registro no encontrado.")
        if _registro_nivel_max_aprobado(rows[0], contrato_id):
            raise HTTPException(
                status_code=400,
                detail="El registro está aprobado en el último nivel de validación del contrato y no puede modificarse por esta vía.",
            )
        if rows[0].get("nivel1_estado") != "Aprobado":
            raise HTTPException(
                status_code=422,
                detail="El registro debe estar aprobado por Nivel 1 antes de marcar objeto de pago.",
            )

        prev_audit = _so_registro_fetch_validacion_audit(contrato_id, registro_id) or {}

        def _upd():
            return (
                supabase.table("so_registros")
                .update({"nivel2_objeto_pago_sub": body.objeto_pago_sub})
                .eq("id", registro_id)
                .eq("contrato_id", contrato_id)
                .execute()
                .data
            )

        supabase_execute(_upd)
        try:
            u_log = _audit_user_contrato(current_user, contrato_id)
            after_audit = _so_registro_fetch_validacion_audit(contrato_id, registro_id) or {}
            registrar_log(
                u_log,
                "EDITAR",
                "SICOE",
                "registro",
                str(registro_id),
                {"alcance": "objeto_pago_sub", "nivel2_objeto_pago_sub": body.objeto_pago_sub},
                valor_anterior=_so_registro_validacion_audit_snapshot(prev_audit),
                valor_nuevo=_so_registro_validacion_audit_snapshot(after_audit),
            )
        except Exception:
            pass
        return {"ok": True, "nivel2_objeto_pago_sub": body.objeto_pago_sub}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.put("/sicoe-obra/{contrato_id}/registros/{registro_id}/validar-nivel2")
def validar_nivel2(contrato_id: int, registro_id: int, body: ValidarNivel2Body,
                   current_user=Depends(get_current_user)):
    ESTADOS = {"Aprobado", "Pendiente", "Rechazado", "No Objeto de Cobro"}
    if body.estado not in ESTADOS:
        raise HTTPException(status_code=422, detail=f"Estado inválido. Acepta: {ESTADOS}")
    try:
        autor_id = int(current_user.get("sub") or current_user.get("id", 0))
        _require_sicoe_puede_validar_nivel(current_user, autor_id, 2, contrato_id)
        # Verificar nivel1
        def _get():
            return supabase.table("so_registros")\
                .select(f"contrato_id,{SICOE_SELECT_NIVELES_ESTADO},reporte_id").eq("id", registro_id)\
                .eq("contrato_id", contrato_id).limit(1).execute().data
        rows = supabase_execute(_get)
        if not rows:
            raise HTTPException(status_code=404, detail="Registro no encontrado.")
        if _registro_nivel_max_aprobado(rows[0], contrato_id):
            raise HTTPException(
                status_code=400,
                detail="El registro está aprobado en el último nivel de validación del contrato y no puede modificarse por esta vía.",
            )
        if rows[0].get("nivel1_estado") != "Aprobado":
            raise HTTPException(status_code=422,
                detail="El registro debe estar aprobado por Nivel 1 primero.")

        estado_real = body.estado
        if body.estado == "No Objeto de Cobro":
            estado_real = "Rechazado"
            if not body.comentario_data:
                raise HTTPException(status_code=422,
                    detail="Se requiere comentario_data para 'No Objeto de Cobro'.")

        if body.estado in ("Pendiente", "Rechazado") and not body.comentario_data:
            raise HTTPException(status_code=422,
                detail="Se requiere comentario_data cuando el estado es Pendiente o Rechazado.")

        if estado_real == "Aprobado" and _sicoe_exige_topografia_para_aprobar_nivel2(contrato_id):
            rep_id = rows[0].get("reporte_id")
            if not rep_id or not _reporte_tiene_puntos_topograficos(contrato_id, rep_id):
                raise HTTPException(
                    status_code=422,
                    detail="No se puede aprobar en Nivel 2 (Residente) sin coordenadas topográficas en la Portada del reporte. Carga al menos un punto en Topografía antes de aprobar.",
                )

        prev_audit = _so_registro_fetch_validacion_audit(contrato_id, registro_id) or {}
        update = {
            "nivel2_estado":     estado_real,
            "nivel2_usuario_id": autor_id,
            "nivel2_fecha":      datetime.utcnow().isoformat(),
        }
        if body.objeto_pago_sub is not None:
            update["nivel2_objeto_pago_sub"] = body.objeto_pago_sub

        def _upd():
            return supabase.table("so_registros")\
                .update(update).eq("id", registro_id)\
                .eq("contrato_id", contrato_id).execute().data
        supabase_execute(_upd)
        # Acta RPO parcial: al aprobar Residente de Obra (N2), alinear a acta vigente a la fecha de aprobación
        if estado_real == "Aprobado":
            try:
                _aplicar_acta_rpo_vigente_a_registro(contrato_id, registro_id, date.today())
            except Exception:
                pass
        if body.comentario_data:
            _insertar_comentario(contrato_id, registro_id, autor_id, body.comentario_data,
                                 tipo_override="validacion", nivel_validacion_override="Nivel 2",
                                 audit_user=current_user)
            _push_notif_validacion_sicoe_destinatarios(
                current_user,
                autor_id,
                contrato_id,
                registro_id,
                f"Validación Nivel 2: {body.estado}",
                body.comentario_data.get("mensaje", "") or "",
                body.comentario_data,
            )
        try:
            u_log = _audit_user_contrato(current_user, contrato_id)
            after_audit = _so_registro_fetch_validacion_audit(contrato_id, registro_id) or {}
            registrar_log(
                u_log, "VALIDAR", "SICOE", "registro", str(registro_id),
                {"nivel": 2, "estado": body.estado, "nivel2_objeto_pago_sub": body.objeto_pago_sub},
                valor_anterior=_so_registro_validacion_audit_snapshot(prev_audit),
                valor_nuevo=_so_registro_validacion_audit_snapshot(after_audit),
            )
        except Exception:
            pass
        return {"ok": True}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


