LIQ_SUPERCOBRO_COP = 20_000_000.0


def _liquidacion_row_categoria(delta_costo: float, es_calculado: bool) -> str:
    if not es_calculado:
        return "EJECUCION"
    if abs(delta_costo) < 0.5:
        return "EQUILIBRIO"
    if delta_costo < 0:
        return "SUPERCOBRO" if abs(delta_costo) > LIQ_SUPERCOBRO_COP else "DEVOLUCION"
    return "POR_COBRAR"


def _liquidacion_pct_ejecucion(cobrado: float, recalculado: float) -> float:
    if recalculado and recalculado > 0:
        return round(cobrado / recalculado * 100, 1)
    if cobrado and cobrado > 0:
        return 999.0
    return 0.0


def _liquidacion_analisis_items(contrato_id: int, nivel: str, current_user) -> List[Dict[str, Any]]:
    """Agrega por ítem o capítulo: ítems con polígono (tipo Presupuesto de Obra) usan cant/costo PPTO; el resto toma obra N3 ✓ como recalc (= cobro)."""
    ppo: Dict[Tuple[str, str], Dict[str, Any]] = {}
    off = 0
    pto_iv = _presupuesto_aplica_filtro_interventoria(current_user)
    while True:
        def _q_pres(o=off):
            q = (
                supabase.table("presupuesto")
                .select("capitulo, item, tipo_ejecucion, cant_total, costo_directo, descripcion")
                .eq("contrato_id", contrato_id)
                .eq("dado_de_baja", False)
            )
            if pto_iv:
                q = q.eq("pre_interv_estado", "Aprobado")
            return q.order("id").range(o, o + 999).execute().data

        batch = supabase_execute(_q_pres) or []
        for r in batch:
            ck = _dash_norm_capitulo_key_py(r.get("capitulo"))
            ik = _dash_norm_item_key_py(r.get("item"))
            if not ik:
                continue
            k = (ck, ik)
            if k not in ppo:
                ppo[k] = {
                    "cant_po": 0.0,
                    "cost_po": 0.0,
                    "desc": "",
                    "calculado": False,
                    "cap_raw": (r.get("capitulo") or "").strip() or ck,
                    "item_raw": (r.get("item") or "").strip() or ik,
                }
            te = (r.get("tipo_ejecucion") or "").strip()
            if te == PRESUPUESTO_TIPO_POLIGONO:
                ppo[k]["calculado"] = True
                ppo[k]["cant_po"] += float(r.get("cant_total") or 0)
                ppo[k]["cost_po"] += float(r.get("costo_directo") or 0)
            if not ppo[k]["desc"] and r.get("descripcion"):
                ppo[k]["desc"] = str(r.get("descripcion"))[:400]
        if len(batch) < 1000:
            break
        off += 1000

    sic: Dict[Tuple[str, str], Dict[str, Any]] = {}
    off = 0
    while True:
        def _q_reg(o=off):
            return (
                supabase.table("so_registros")
                .select("capitulo, item_numero, cantidad_total, costo_directo, " + SICOE_SELECT_NIVELES_ESTADO)
                .eq("contrato_id", contrato_id)
                .order("id").range(o, o + 999)
                .execute()
                .data
            )

        batch = supabase_execute(_q_reg) or []
        for r in batch:
            if _matriz_validacion_norm_estado_nivel_final(r, contrato_id) != "Aprobado":
                continue
            ck = _dash_norm_capitulo_key_py(r.get("capitulo"))
            ik = _dash_norm_item_key_py(r.get("item_numero"))
            if not ik:
                continue
            k = (ck, ik)
            if k not in sic:
                sic[k] = {
                    "cant": 0.0,
                    "cost": 0.0,
                    "cap_raw": (r.get("capitulo") or "").strip() or ck,
                    "item_raw": (r.get("item_numero") or "").strip() or ik,
                }
            sic[k]["cant"] += cantidad_dashboard(float(r.get("cantidad_total") or 0))
            sic[k]["cost"] += float(r.get("costo_directo") or 0)
        if len(batch) < 1000:
            break
        off += 1000

    keys_all = set(ppo.keys()) | set(sic.keys())
    item_rows: List[Dict[str, Any]] = []
    for k in sorted(keys_all, key=lambda x: (x[0], x[1])):
        meta = ppo.get(k)
        sg = sic.get(
            k,
            {"cant": 0.0, "cost": 0.0, "cap_raw": k[0], "item_raw": k[1]},
        )
        cant_cob = float(sg["cant"])
        cob = float(sg["cost"])
        if meta:
            cap_raw = meta.get("cap_raw") or sg.get("cap_raw") or k[0]
            item_raw = meta.get("item_raw") or sg.get("item_raw") or k[1]
            desc = meta.get("desc") or ""
            calc = bool(meta.get("calculado"))
        else:
            cap_raw = sg.get("cap_raw") or k[0]
            item_raw = sg.get("item_raw") or k[1]
            desc = ""
            calc = False
        if calc and meta:
            cant_re = float(meta["cant_po"])
            rec = float(meta["cost_po"])
        else:
            cant_re, rec = cant_cob, cob
        delta_cant = cant_re - cant_cob
        delta_cost = rec - cob
        item_rows.append(
            {
                "capitulo": cap_raw,
                "nombre": item_raw,
                "descripcion": desc,
                "cant_recalc": round(cant_re, 2),
                "recalculado": round(rec, 0),
                "cant_cobro": round(cant_cob, 2),
                "cobrado": round(cob, 0),
                "delta_cant": round(delta_cant, 2),
                "delta_costo": round(delta_cost, 0),
                "pct": _liquidacion_pct_ejecucion(cob, rec),
                "categoria": _liquidacion_row_categoria(delta_cost, calc),
                "_ck": k[0],
                "_calc": calc,
            }
        )

    if nivel != "capitulo":
        for r in item_rows:
            r.pop("_ck", None)
            r.pop("_calc", None)
        return item_rows

    caps: Dict[str, Dict[str, Any]] = {}
    for r in item_rows:
        ck = r["_ck"]
        if ck not in caps:
            caps[ck] = {
                "capitulo": r["capitulo"],
                "nombre": r["capitulo"],
                "cant_recalc": 0.0,
                "recalculado": 0.0,
                "cant_cobro": 0.0,
                "cobrado": 0.0,
                "any_calc": False,
            }
        caps[ck]["cant_recalc"] += float(r["cant_recalc"])
        caps[ck]["recalculado"] += float(r["recalculado"])
        caps[ck]["cant_cobro"] += float(r["cant_cobro"])
        caps[ck]["cobrado"] += float(r["cobrado"])
        if r.get("_calc"):
            caps[ck]["any_calc"] = True

    out: List[Dict[str, Any]] = []
    for ck in sorted(caps.keys(), key=lambda x: x):
        c = caps[ck]
        d_cant = c["cant_recalc"] - c["cant_cobro"]
        d_cost = c["recalculado"] - c["cobrado"]
        ac = bool(c["any_calc"])
        out.append(
            {
                "capitulo": c["capitulo"],
                "nombre": c["nombre"],
                "descripcion": "",
                "cant_recalc": round(c["cant_recalc"], 2),
                "recalculado": round(c["recalculado"], 0),
                "cant_cobro": round(c["cant_cobro"], 2),
                "cobrado": round(c["cobrado"], 0),
                "delta_cant": round(d_cant, 2),
                "delta_costo": round(d_cost, 0),
                "pct": _liquidacion_pct_ejecucion(c["cobrado"], c["recalculado"]),
                "categoria": _liquidacion_row_categoria(d_cost, ac),
            }
        )
    return out


def _dashboard_pkid_colores_liquidacion(
    contrato_id: int,
    capitulo: Optional[str],
    item: Optional[str],
    vista: str = "obra_ejecutada",
    current_user=None,
) -> Dict[str, Any]:
    """Mini mapa liquidación: por PK, referencia presupuesto vista vs cobrado SICOE N3 ✓."""
    cap_k = _dash_norm_capitulo_key_py(capitulo) if capitulo else None
    it_k = _dash_norm_item_key_py(item) if item else None
    ppto_rows, allowed_keys, _ = ppto_filas_pk_drill(
        supabase, contrato_id, capitulo, item, vista, current_user
    )

    po_by: Dict[Tuple[str, str], Dict[str, float]] = defaultdict(lambda: defaultdict(float))
    for r in ppto_rows:
        ck = _dash_norm_capitulo_key_py(r.get("capitulo"))
        ik = _dash_norm_item_key_py(r.get("item"))
        if not ik:
            continue
        if cap_k and ck != cap_k:
            continue
        if it_k and ik != it_k:
            continue
        pk = _dash_pk_disp_key_py(r.get("pk_id"))
        if pk != "(sin pk)":
            po_by[(ck, ik)][pk] += float(r.get("costo_directo") or 0)

    sic_by: Dict[Tuple[str, str], Dict[str, float]] = defaultdict(lambda: defaultdict(float))
    off = 0
    while True:
        def _qs(o=off, cap_eq=capitulo):
            q = (
                supabase.table("so_registros")
                .select("capitulo, item_numero, costo_directo, " + SICOE_SELECT_NIVELES_ESTADO + ", pk_id_id, pk_ids(pk_id)")
                .eq("contrato_id", contrato_id)
            )
            if cap_eq and str(cap_eq).strip():
                q = apply_sicoe_capitulo_filter(q, supabase, contrato_id, str(cap_eq).strip())
            return q.order("id").range(o, o + 999).execute().data

        batch = supabase_execute(_qs) or []
        for r in batch:
            if _matriz_validacion_norm_estado_nivel_final(r, contrato_id) != "Aprobado":
                continue
            ck = _dash_norm_capitulo_key_py(r.get("capitulo"))
            ik = _dash_norm_item_key_py(r.get("item_numero"))
            if not ik:
                continue
            if cap_k and ck != cap_k:
                continue
            if it_k and ik != it_k:
                continue
            if not sicoe_registro_en_vista(r, allowed_keys):
                continue
            pk_join = r.get("pk_ids") or {}
            pk_raw = pk_join.get("pk_id")
            pk = (
                _dash_pk_disp_key_py(pk_raw)
                if pk_raw is not None and str(pk_raw).strip() != ""
                else _dash_pk_disp_key_py(r.get("pk_id_id"))
            )
            if pk == "(sin pk)":
                continue
            sic_by[(ck, ik)][pk] += float(r.get("costo_directo") or 0)
        if len(batch) < 1000:
            break
        off += 1000

    if allowed_keys is not None:
        keys_scope = set(po_by.keys()) & set(sic_by.keys())
    else:
        keys_scope = set(po_by.keys()) | set(sic_by.keys())
    if cap_k:
        keys_scope = {x for x in keys_scope if x[0] == cap_k}
    if it_k:
        keys_scope = {x for x in keys_scope if x[1] == it_k}

    all_pks: Set[str] = set()
    for k in keys_scope:
        all_pks.update(sic_by[k].keys())
        all_pks.update(po_by[k].keys())

    result: Dict[str, Any] = {}
    for pk in all_pks:
        sap = 0.0
        pref = 0.0
        for k in keys_scope:
            sap += float(sic_by[k].get(pk, 0.0))
            pref += float(po_by[k].get(pk, 0.0))
        result[pk] = {
            "cobrado": round(sap, 2),
            "presupuesto": round(pref, 2),
            "sicoe_aprobado": round(sap, 2),
            "pct": round(sap / pref * 100, 1) if pref else 0,
            "sobrecosto": sap > pref,
        }
    return result


_DASH_AGG_CACHE: Dict[str, Tuple[float, Any]] = {}
_DASH_AGG_CACHE_LOCK = threading.Lock()
_DASH_AGG_CACHE_TTL_SEC = 300


def _dash_agg_cache_get(kind: str, contrato_id: int):
    key = f"{kind}:{int(contrato_id)}"
    now = time.time()
    with _DASH_AGG_CACHE_LOCK:
        hit = _DASH_AGG_CACHE.get(key)
        if hit and now - hit[0] < _DASH_AGG_CACHE_TTL_SEC:
            return hit[1]
    return None


def _dash_agg_cache_set(kind: str, contrato_id: int, value: Any) -> None:
    key = f"{kind}:{int(contrato_id)}"
    with _DASH_AGG_CACHE_LOCK:
        _DASH_AGG_CACHE[key] = (time.time(), value)


def _dashboard_scan_sicoe_by_item(
    contrato_id: int, *, acta_id: Optional[int] = None
) -> Dict[Tuple[str, str], Dict[str, Any]]:
    """Agrega SICOE por (capítulo_norm, ítem_norm) con costos/cantidades aprobados y en cola."""
    cache_kind = "sicoe_by_item_v2" if acta_id is None else f"sicoe_by_item_v2_acta_{int(acta_id)}"
    cached = _dash_agg_cache_get(cache_kind, contrato_id)
    if cached is not None:
        return cached
    sicoe_by_item: Dict[Tuple[str, str], Dict[str, Any]] = {}
    listado_idx = _listado_precios_vu_by_cap_item(contrato_id)
    off = 0
    while True:
        def _b(o=off, _aid=acta_id):
            q = (
                supabase.table("so_registros")
                .select(
                    "capitulo, cantidad_total, vlr_unitario, item_numero, "
                    f"{SICOE_SELECT_NIVELES_ESTADO}"
                )
                .eq("contrato_id", contrato_id)
            )
            if _aid is not None:
                q = q.eq("acta_rpo_id", int(_aid))
            return q.order("id").range(o, o + 999).execute().data

        batch = supabase_execute(_b) or []
        for reg in batch:
            if not (reg.get("item_numero") or "").strip():
                continue
            ck = _dash_norm_capitulo_key_py(reg.get("capitulo"))
            ik = _dash_norm_item_key_py(reg.get("item_numero"))
            if not ik:
                continue
            k = (ck, ik)
            if k not in sicoe_by_item:
                sicoe_by_item[k] = {
                    "cap_display": _dash_norm_cap(reg.get("capitulo")),
                    "ap_c": 0.0,
                    "nr_c": 0.0,
                    "ap_q": 0.0,
                    "nr_q": 0.0,
                }
            cq = cantidad_dashboard(float(reg.get("cantidad_total") or 0))
            nfin = _matriz_validacion_norm_estado_nivel_final(reg, contrato_id)
            if nfin == "Aprobado":
                sicoe_by_item[k]["ap_q"] += cq
            elif _so_reg_en_cola_interventoria(reg, contrato_id) and nfin == "No Revisado":
                sicoe_by_item[k]["nr_q"] += cq
        if len(batch) < 1000:
            break
        off += 1000
    for (ck, ik), sg in sicoe_by_item.items():
        lp_vu = _dash_listado_vu_resolved(contrato_id, ck, ik, full_listado_idx=listado_idx)
        for qk in ("ap_q", "nr_q"):
            sg[qk] = cantidad_dashboard(float(sg.get(qk) or 0))
        sicoe_finalize_costs(sg, listado_vu=lp_vu)
    _dash_agg_cache_set(cache_kind, contrato_id, sicoe_by_item)
    return sicoe_by_item


def _dashboard_scan_sicoe_by_item_capitulo(contrato_id: int, capitulo: str) -> Dict[Tuple[str, str], Dict[str, Any]]:
    """SICOE agregado por ítem solo para un capítulo (drill rápido)."""
    cap_raw = (capitulo or "").strip()
    if not cap_raw:
        return {}
    cap_key = _dash_norm_capitulo_key_py(cap_raw)
    cache_key = f"sicoe_by_item_cap:{int(contrato_id)}:{cap_key}"
    now = time.time()
    with _DASH_AGG_CACHE_LOCK:
        hit = _DASH_AGG_CACHE.get(cache_key)
        if hit and now - hit[0] < _DASH_AGG_CACHE_TTL_SEC:
            return hit[1]

    sicoe_by_item: Dict[Tuple[str, str], Dict[str, Any]] = {}
    listado_idx = _listado_precios_vu_by_cap_item(contrato_id)

    def _ingest_batch(batch: List[dict]) -> None:
        for reg in batch or []:
            if cap_key and _dash_norm_capitulo_key_py(reg.get("capitulo")) != cap_key:
                continue
            ik = _dash_norm_item_key_py(reg.get("item_numero"))
            if not ik:
                continue
            k = (cap_key, ik)
            if k not in sicoe_by_item:
                sicoe_by_item[k] = {
                    "cap_display": _dash_norm_cap(reg.get("capitulo")),
                    "ap_c": 0.0,
                    "nr_c": 0.0,
                    "ap_q": 0.0,
                    "nr_q": 0.0,
                }
            cq = cantidad_dashboard(float(reg.get("cantidad_total") or 0))
            nfin = _matriz_validacion_norm_estado_nivel_final(reg, contrato_id)
            if nfin == "Aprobado":
                sicoe_by_item[k]["ap_q"] += cq
            elif _so_reg_en_cola_interventoria(reg, contrato_id) and nfin == "No Revisado":
                sicoe_by_item[k]["nr_q"] += cq

    def _scan_pages(use_cap_filter: bool) -> None:
        off = 0
        while True:
            def _b(o=off, cap_eq=cap_raw, filtered=use_cap_filter):
                q = (
                    supabase.table("so_registros")
                    .select(
                        "capitulo, cantidad_total, vlr_unitario, item_numero, "
                        f"{SICOE_SELECT_NIVELES_ESTADO}"
                    )
                    .eq("contrato_id", contrato_id)
                )
                if filtered:
                    q = apply_sicoe_capitulo_filter(q, supabase, contrato_id, cap_eq)
                return q.order("id").range(o, o + 999).execute().data

            batch = supabase_execute(_b) or []
            _ingest_batch(batch)
            if len(batch) < 1000:
                break
            off += 1000

    _scan_pages(use_cap_filter=True)
    for (ck, ik), sg in sicoe_by_item.items():
        lp_vu = _dash_listado_vu_resolved(contrato_id, ck, ik, full_listado_idx=listado_idx)
        for qk in ("ap_q", "nr_q"):
            sg[qk] = cantidad_dashboard(float(sg.get(qk) or 0))
        sicoe_finalize_costs(sg, listado_vu=lp_vu)
    if not sicoe_by_item:
        full = _dash_agg_cache_get("sicoe_by_item_v2", contrato_id)
        if full is not None:
            for k, v in full.items():
                if k[0] == cap_key:
                    sicoe_by_item[k] = v
    with _DASH_AGG_CACHE_LOCK:
        _DASH_AGG_CACHE[cache_key] = (time.time(), sicoe_by_item)
    return sicoe_by_item


def _sicoe_by_item_for_capitulo(contrato_id: int, capitulo: str) -> Dict[Tuple[str, str], Dict[str, Any]]:
    """SICOE por ítem del capítulo: caché capítulo → caché contrato filtrada → scan acotado."""
    cap_raw = (capitulo or "").strip()
    if not cap_raw:
        return {}
    cap_key = _dash_norm_capitulo_key_py(cap_raw)
    cache_key = f"sicoe_by_item_cap:{int(contrato_id)}:{cap_key}"
    now = time.time()
    with _DASH_AGG_CACHE_LOCK:
        hit = _DASH_AGG_CACHE.get(cache_key)
        if hit and now - hit[0] < _DASH_AGG_CACHE_TTL_SEC:
            return hit[1]

    full = _dash_agg_cache_get("sicoe_by_item_v2", contrato_id)
    if full is not None:
        filtered = {k: v for k, v in full.items() if k[0] == cap_key}
        if filtered:
            with _DASH_AGG_CACHE_LOCK:
                _DASH_AGG_CACHE[cache_key] = (time.time(), filtered)
            return filtered

    sicoe_by = _dashboard_scan_sicoe_by_item_capitulo(contrato_id, cap_raw)
    if sicoe_by:
        return sicoe_by

    full = _dash_agg_cache_get("sicoe_by_item_v2", contrato_id)
    if full is not None:
        filtered = {k: v for k, v in full.items() if k[0] == cap_key}
        with _DASH_AGG_CACHE_LOCK:
            _DASH_AGG_CACHE[cache_key] = (time.time(), filtered)
        return filtered

    return {}


def _dashboard_sicoe_from_hit(hit: dict) -> Tuple[Dict[str, float], Dict[str, float], float, float]:
    """SICOE N3 aprobado / no revisado desde RPC dashboard_resumen_sicoe_agg (sin re-escaneo)."""
    comparativo = hit.get("comparativo_capitulos") or []
    sicoe_ap_c: Dict[str, float] = {}
    sicoe_nr_c: Dict[str, float] = {}
    for row in comparativo:
        cap = row.get("capitulo") or "Sin capítulo"
        sicoe_ap_c[cap] = float(row.get("cobrado") or 0)
        sicoe_nr_c[cap] = float(row.get("sicoe_no_revisado_n3") or row.get("sicoe_no_revisado") or 0)
    total_cobrado = float(hit.get("total_cobrado") if hit.get("total_cobrado") is not None else sum(sicoe_ap_c.values()))
    total_nr = float(
        hit.get("total_sicoe_n3_no_revisado")
        if hit.get("total_sicoe_n3_no_revisado") is not None
        else sum(sicoe_nr_c.values())
    )
    return sicoe_ap_c, sicoe_nr_c, total_cobrado, total_nr


def _rpc_drill_items_agg(contrato_id: int, capitulo: str) -> List[dict]:
    """Ítems por capítulo vía SQL (normaliza capítulo; usa nivel máximo del contrato, p. ej. N4)."""
    campo_max = _get_nivel_maximo_contrato(contrato_id)
    na = _get_niveles_activos_contrato(contrato_id)
    cap_s = str(capitulo or "").strip()
    cache_key = ("dashboard_drill_items_agg", int(contrato_id), cap_s, campo_max or "", tuple(int(x) for x in (na or ())))

    def _call():
        return supabase.rpc(
            "dashboard_drill_items_agg",
            {
                "p_contrato_id": int(contrato_id),
                "p_capitulo": cap_s,
                "p_campo_nivel_max": campo_max,
                "p_niveles_activos": na,
            },
        ).execute().data

    raw, _hit = _get_dashboard_rpc_cached(cache_key, lambda: supabase_execute(_call, retries=1))
    items = _parse_rpc_jsonb_value(raw)
    if not isinstance(items, list):
        return []
    return [x for x in items if isinstance(x, dict)]


def _rpc_pkid_tabla_agg(contrato_id: int, capitulo: str, item: Optional[str] = None) -> dict:
    """Tabla PK por capítulo+ítem vía SQL (normaliza capítulo/ítem; nivel máx. contrato)."""
    campo_max = _get_nivel_maximo_contrato(contrato_id)
    na = _get_niveles_activos_contrato(contrato_id)
    cap_s = str(capitulo or "").strip()
    item_s = str(item or "").strip() if item else None
    cache_key = (
        "dashboard_pkid_tabla_agg",
        int(contrato_id),
        cap_s,
        item_s or "",
        campo_max or "",
        tuple(int(x) for x in (na or ())),
    )

    def _call():
        return supabase.rpc(
            "dashboard_pkid_tabla_agg",
            {
                "p_contrato_id": int(contrato_id),
                "p_capitulo": cap_s,
                "p_item": item_s,
                "p_campo_nivel_max": campo_max,
                "p_niveles_activos": na,
            },
        ).execute().data

    raw, _hit = _get_dashboard_rpc_cached(cache_key, lambda: supabase_execute(_call, retries=1))
    parsed = _parse_rpc_jsonb_value(raw)
    if isinstance(parsed, dict) and isinstance(parsed.get("rows"), list):
        return parsed
    return {}


def _pkid_tabla_empty_metric() -> Dict[str, float]:
    return {"cant": 0.0, "costo": 0.0}


def _aggregate_pkid_ppto_rows(ppto_rows: List[dict]) -> Tuple[Dict[str, Any], Dict[str, Any], Dict[str, Any], Dict[str, Any], Dict[str, Any]]:
    agg_meta: Dict[str, Any] = {}
    agg_p_ap: Dict[str, Any] = {}
    agg_p_nr: Dict[str, Any] = {}
    agg_p_pd: Dict[str, Any] = {}
    agg_p_rj: Dict[str, Any] = {}
    empty_m = _pkid_tabla_empty_metric
    for r in ppto_rows or []:
        k = _dash_pk_disp_key_py(r.get("pk_id"))
        if k not in agg_meta:
            agg_meta[k] = {"desc": "", "_rev_track": []}
        cost_line = float(r.get("costo_directo") or 0)
        agg_meta[k]["_rev_track"].append((cost_line, r.get("revisado")))
        if not agg_meta[k]["desc"] and r.get("descripcion"):
            agg_meta[k]["desc"] = r["descripcion"]
        rv = _matriz_validacion_norm_estado(r.get("revisado"))
        cq = cantidad_dashboard(float(r.get("cant_total") or 0))
        cd = float(r.get("costo_directo") or 0)
        if rv == "Aprobado":
            tgt = agg_p_ap
        elif rv == "Pendiente":
            tgt = agg_p_pd
        elif rv == "Rechazado":
            tgt = agg_p_rj
        else:
            tgt = agg_p_nr
        if k not in tgt:
            tgt[k] = empty_m()
        tgt[k]["cant"] += cq
        tgt[k]["costo"] += cd
    return agg_meta, agg_p_ap, agg_p_nr, agg_p_pd, agg_p_rj


def _build_pkid_tabla_row_from_aggs(
    pk: str,
    meta: Dict[str, Any],
    pap: Dict[str, float],
    pnr: Dict[str, float],
    ppd: Dict[str, float],
    prj: Dict[str, float],
    sic: Dict[str, float],
    snr: Dict[str, float],
    spe: Dict[str, float],
    srj: Dict[str, float],
) -> dict:
    cant_ppto = pap["cant"] + pnr["cant"] + ppd["cant"] + prj["cant"]
    costo_ppto = pap["costo"] + pnr["costo"] + ppd["costo"] + prj["costo"]
    dcant = pap["cant"] - sic["cant"]
    dcosto = pap["costo"] - sic["costo"]
    tr = meta.get("_rev_track") or []
    rev_dom = "No Revisado"
    if tr:
        rev_dom = _matriz_validacion_norm_estado(max(tr, key=lambda x: float(x[0] or 0))[1])
    return {
        "pk_id": pk,
        "cant_ppto": round(cant_ppto, 2),
        "costo_ppto": round(costo_ppto, 0),
        "cant_ppto_aprobado_n3": round(pap["cant"], 2),
        "costo_ppto_aprobado_n3": round(pap["costo"], 0),
        "cant_ppto_estado_no_revisado": round(pnr["cant"], 2),
        "costo_ppto_estado_no_revisado": round(pnr["costo"], 0),
        "cant_ppto_estado_pendiente": round(ppd["cant"], 2),
        "costo_ppto_estado_pendiente": round(ppd["costo"], 0),
        "cant_ppto_estado_rechazado": round(prj["cant"], 2),
        "costo_ppto_estado_rechazado": round(prj["costo"], 0),
        "cant_sicoe_aprobado": round(sic["cant"], 2),
        "costo_sicoe_aprobado": round(sic["costo"], 0),
        "cant_sicoe_no_revisado": round(snr["cant"], 2),
        "costo_sicoe_no_revisado": round(snr["costo"], 0),
        "cant_sicoe_pendiente": round(spe["cant"], 2),
        "costo_sicoe_pendiente": round(spe["costo"], 0),
        "cant_sicoe_rechazado": round(srj["cant"], 2),
        "costo_sicoe_rechazado": round(srj["costo"], 0),
        "cant_sicoe": round(sic["cant"], 2),
        "costo_sicoe": round(sic["costo"], 0),
        "cant_facturado": 0.0,
        "costo_facturado": 0.0,
        "delta_cant": round(dcant, 2),
        "delta_costo": round(dcosto, 0),
        "descripcion": meta.get("desc", ""),
        "revisado": rev_dom,
        "cant_nr": round(pnr["cant"], 2),
        "costo_nr": round(pnr["costo"], 0),
        "cant_p": round(ppd["cant"], 2),
        "costo_p": round(ppd["costo"], 0),
        "cant_r": round(prj["cant"], 2),
        "costo_r": round(prj["costo"], 0),
        "cant_a": round(pap["cant"], 2),
        "costo_a": round(pap["costo"], 0),
        "tiene_ppto_obra_ejecutada": bool(cant_ppto or costo_ppto),
    }


def _sync_pkid_row_financiero_fields(row: dict) -> None:
    """Alias NR|P|R|A + cobrado para misma lógica que tabla ítems."""
    if not isinstance(row, dict):
        return
    row["cant_nr"] = round(float(row.get("cant_nr") or row.get("cant_ppto_estado_no_revisado") or 0), 2)
    row["costo_nr"] = round(float(row.get("costo_nr") or row.get("costo_ppto_estado_no_revisado") or 0), 0)
    row["cant_p"] = round(float(row.get("cant_p") or row.get("cant_ppto_estado_pendiente") or 0), 2)
    row["costo_p"] = round(float(row.get("costo_p") or row.get("costo_ppto_estado_pendiente") or 0), 0)
    row["cant_r"] = round(float(row.get("cant_r") or row.get("cant_ppto_estado_rechazado") or 0), 2)
    row["costo_r"] = round(float(row.get("costo_r") or row.get("costo_ppto_estado_rechazado") or 0), 0)
    row["cant_a"] = round(float(row.get("cant_a") or row.get("cant_ppto_aprobado_n3") or 0), 2)
    row["costo_a"] = round(float(row.get("costo_a") or row.get("costo_ppto_aprobado_n3") or 0), 0)
    cp = float(row.get("cant_ppto") or 0)
    co = float(row.get("costo_ppto") or 0)
    tiene = bool(row.get("tiene_ppto_obra_ejecutada"))
    if not tiene:
        tiene = bool(cp or co or row["cant_a"] or row["costo_a"] or row["cant_nr"] or row["costo_nr"]
                     or row["cant_p"] or row["costo_p"] or row["cant_r"] or row["costo_r"])
    row["tiene_ppto_obra_ejecutada"] = tiene
    row["cant_cobrado"] = round(float(row.get("cant_cobrado") or row.get("cant_sicoe_aprobado") or row.get("cant_sicoe") or 0), 3)
    row["costo_cobrado"] = round(float(row.get("costo_cobrado") or row.get("costo_sicoe_aprobado") or row.get("costo_sicoe") or 0), 2)


def _item_tiene_ppto_obra_ejecutada(
    contrato_id: int,
    capitulo: str,
    item: str,
    current_user,
) -> bool:
    """True si el ítem tiene filas en Presupuesto Obra Ejecutada (misma regla que drill ítems)."""
    cap_raw = (capitulo or "").strip()
    it_key = _dash_norm_item_key_py(item)
    if not cap_raw or not it_key:
        return False
    for r in _ppto_rows_capitulo_tipo(contrato_id, cap_raw, TIPO_OBRA_EJECUTADA, current_user):
        if _dash_norm_item_key_py(r.get("item")) == it_key:
            return True
    return False


def _finalize_pkid_tabla_row(
    row: dict,
    vista: str,
    *,
    item_tiene_ppto_oe: Optional[bool] = None,
) -> None:
    _sync_pkid_row_financiero_fields(row)
    if parse_dash_vista(vista) == DASH_VISTA_OBRA_EJECUTADA:
        _apply_obra_ejecutada_drill_item(row, item_tiene_ppto=item_tiene_ppto_oe)
    else:
        _apply_presupuesto_obra_drill_item(row)


def _enrich_drill_items_meta(
    contrato_id: int,
    capitulo: str,
    rows: List[dict],
    current_user,
) -> List[dict]:
    """Completa descripción y unidad desde presupuesto (Obra / Obra Ejecutada) y SICOE."""
    if not rows:
        return rows
    meta: Dict[str, Dict[str, str]] = {}
    cap_key = _dash_norm_capitulo_key_py(capitulo)
    for tipo in (TIPO_OBRA_EJECUTADA, TIPO_PRESUPUESTO_OBRA):
        for r in _ppto_rows_capitulo_tipo(contrato_id, capitulo, tipo, current_user):
            it = _dash_norm_item_key_py(r.get("item"))
            if not it:
                continue
            slot = meta.setdefault(it, {"descripcion": "", "unidad": ""})
            desc = str(r.get("descripcion") or "").strip()
            und = str(r.get("und") or "").strip()
            if desc and not slot["descripcion"]:
                slot["descripcion"] = desc
            if und and not slot["unidad"]:
                slot["unidad"] = und
    off = 0
    while True:
        def _b(o=off):
            q = (
                supabase.table("so_registros")
                .select("item_numero, item_descripcion, unidad, capitulo")
                .eq("contrato_id", contrato_id)
            )
            return apply_sicoe_capitulo_filter(q, supabase, contrato_id, capitulo).order("id").range(o, o + 999).execute().data

        batch = supabase_execute(_b) or []
        for r in batch:
            if _dash_norm_capitulo_key_py(r.get("capitulo")) != cap_key:
                continue
            it = _dash_norm_item_key_py(r.get("item_numero"))
            if not it:
                continue
            slot = meta.setdefault(it, {"descripcion": "", "unidad": ""})
            desc = str(r.get("item_descripcion") or "").strip()
            und = str(r.get("unidad") or "").strip()
            if desc and not slot["descripcion"]:
                slot["descripcion"] = desc
            if und and not slot["unidad"]:
                slot["unidad"] = und
        if len(batch) < 1000:
            break
        off += 1000
    out: List[dict] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        r = dict(row)
        ik = _dash_norm_item_key_py(r.get("item") or r.get("nombre"))
        m = meta.get(ik) or {}
        if not str(r.get("descripcion") or "").strip() and m.get("descripcion"):
            r["descripcion"] = m["descripcion"]
        if not str(r.get("unidad") or "").strip() and m.get("unidad"):
            r["unidad"] = m["unidad"]
        out.append(r)
    return out


def _hydrate_drill_items_ppto_obra_ejecutada(
    contrato_id: int,
    capitulo: str,
    rows: List[dict],
    current_user,
    *,
    listado_idx: Optional[Dict[str, dict]] = None,
    ppto_obra_by: Optional[Dict[str, List[dict]]] = None,
) -> List[dict]:
    """Obra Ejecutada: inyecta cantidades/costos NR|P|R|A desde presupuesto vivo del capítulo."""
    if not rows:
        return rows
    if listado_idx is None or ppto_obra_by is None:
        listado_idx, ppto_obra_by = _capitulo_export_vu_context(
            contrato_id, capitulo, DASH_VISTA_OBRA_EJECUTADA, current_user
        )
    listado_full = _listado_precios_vu_by_cap_item(contrato_id)
    ppto_by: Dict[str, List[dict]] = defaultdict(list)
    for r in _ppto_rows_capitulo_tipo(contrato_id, capitulo, TIPO_OBRA_EJECUTADA, current_user):
        it = _dash_norm_item_key_py(r.get("item"))
        if it:
            ppto_by[it].append(r)
    out: List[dict] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        r = dict(row)
        ik = _dash_norm_item_key_py(r.get("item") or r.get("nombre"))
        rows_it = ppto_by.get(ik) or []
        if rows_it:
            lp_vu = _dash_listado_vu_resolved(
                contrato_id,
                capitulo,
                ik,
                cap_listado_idx=listado_idx,
                full_listado_idx=listado_full,
            )
            alt = (ppto_obra_by or {}).get(ik)
            est, unidad, vu = _ppto_metricas_por_estado(
                rows_it, listado_vu=lp_vu, alt_rows=alt, obra_ejecutada=True
            )
            rows_vu = ppto_rows_with_resolved_vu(rows_it, listado_vu=lp_vu, alt_rows=alt)
            p_cant = cantidad_dashboard_sum(rows_vu)
            p_cost = costo_agregado_cant_vu(p_cant, vu)
            desc = next((str(x.get("descripcion") or "").strip() for x in rows_it if x.get("descripcion")), "")
            estado = _drill_item_estado_fields(est, unidad, {}, vu=vu, obra_ejecutada=True)
            r.update(estado)
            r["item_vu"] = float(vu or 0)
            r["cant_ppto"] = cantidad_dashboard(p_cant)
            r["presupuesto"] = round(p_cost, 0)
            r["tiene_ppto_obra_ejecutada"] = True
            if desc and not str(r.get("descripcion") or "").strip():
                r["descripcion"] = desc
            if unidad and not str(r.get("unidad") or "").strip():
                r["unidad"] = unidad
        else:
            r["tiene_ppto_obra_ejecutada"] = False
        out.append(r)
    return out


def _apply_obra_ejecutada_drill_item(row: dict, *, item_tiene_ppto: Optional[bool] = None) -> None:
    """Obra Ejecutada: CC y cobrado = round(Σcant × V.U., 0); nunca sumar costos por bucket/línea."""
    if not isinstance(row, dict):
        return
    vu_cc = float(row.get("item_vu") or 0)
    cant_nr = cantidad_dashboard(float(row.get("cant_nr") or 0))
    cant_p = cantidad_dashboard(float(row.get("cant_p") or 0))
    cant_r = cantidad_dashboard(float(row.get("cant_r") or 0))
    cant_a = cantidad_dashboard(float(row.get("cant_a") or 0))
    total_q = cantidad_dashboard(cant_nr + cant_p + cant_r + cant_a)
    cob_q = cantidad_dashboard(float(row.get("cant_cobrado") or row.get("cant_sicoe_aprobado") or 0))
    vu_cob = float(row.get("sicoe_item_vu") or vu_cc or 0)
    cob_c = drill_item_costo_total(cob_q, vu_cob)
    tiene_ppto_fila = bool(row.get("tiene_ppto_obra_ejecutada"))
    if item_tiene_ppto is True and not tiene_ppto_fila:
        cc_q = cc_c = 0.0
        row["claracore_igualado_cobro"] = False
    elif tiene_ppto_fila:
        cc_q = cantidad_dashboard(float(row.get("total_claracore_cant") or 0)) or total_q or cantidad_dashboard(
            float(row.get("cant_ppto") or 0)
        )
        cc_c = drill_item_costo_total(
            cc_q,
            vu_cc,
        )
        row["claracore_igualado_cobro"] = False
    elif cob_q or cob_c:
        cc_q, cc_c = cob_q, cob_c
        row["claracore_igualado_cobro"] = True
    else:
        cc_q = cc_c = 0.0
        row["claracore_igualado_cobro"] = False
    row["total_claracore_cant"] = cantidad_dashboard(cc_q)
    row["total_claracore_costo"] = round(cc_c, 0)
    row["cant_cobrado"] = cantidad_dashboard(cob_q)
    row["costo_cobrado"] = round(cob_c, 0)
    row["cobrado"] = round(cob_c, 0)
    row["delta_cant"] = cantidad_dashboard(cc_q - cob_q)
    row["delta_costo"] = round(cc_c - cob_c, 0)
    row["delta"] = row["delta_costo"]


def _apply_presupuesto_obra_drill_item(row: dict) -> None:
    """Presupuesto de Obra (ítem): CC = round((cant_a+cant_nr) × V.U., 0); cobrado = round(cant × V.U., 0)."""
    if not isinstance(row, dict):
        return
    vu = float(row.get("item_vu") or 0)
    cc_q = cantidad_dashboard(float(row.get("cant_a") or 0) + float(row.get("cant_nr") or 0))
    cob_q = cantidad_dashboard(float(row.get("cant_cobrado") or row.get("cant_sicoe_aprobado") or 0))
    vu_cob = float(row.get("sicoe_item_vu") or vu or 0)
    cc_c = drill_item_costo_total(cc_q, vu)
    cob_c = drill_item_costo_total(cob_q, vu_cob)
    row["total_claracore_cant"] = cantidad_dashboard(cc_q)
    row["total_claracore_costo"] = round(cc_c, 0)
    row["cant_cobrado"] = cantidad_dashboard(cob_q)
    row["costo_cobrado"] = round(cob_c, 0)
    row["cobrado"] = round(cob_c, 0)
    row["delta_cant"] = cantidad_dashboard(cc_q - cob_q)
    row["delta_costo"] = round(cc_c - cob_c, 0)
    row["delta"] = row["delta_costo"]


def _finalize_drill_items_vista(rows: Optional[List[dict]], vista: str) -> List[dict]:
    out: List[dict] = []
    es_oe = parse_dash_vista(vista) == DASH_VISTA_OBRA_EJECUTADA
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        r = dict(row)
        if es_oe:
            _apply_obra_ejecutada_drill_item(r)
        else:
            _apply_presupuesto_obra_drill_item(r)
        out.append(r)
    return out


def _apply_obra_ejecutada_pkid_delta(row: dict, *, item_tiene_ppto_oe: Optional[bool] = None) -> None:
    """Obra Ejecutada PK: misma lógica que ítems, con contexto de ítem para sumas coherentes."""
    _finalize_pkid_tabla_row(row, DASH_VISTA_OBRA_EJECUTADA, item_tiene_ppto_oe=item_tiene_ppto_oe)


def _merge_pkid_tabla_vista_ppto(rpc_payload: dict, ppto_rows: List[dict]) -> dict:
    """Mantiene obra/SICOE del RPC; sustituye columnas de presupuesto según vista."""
    if not ppto_rows:
        return rpc_payload
    empty_m = _pkid_tabla_empty_metric
    agg_meta, agg_p_ap, agg_p_nr, agg_p_pd, agg_p_rj = _aggregate_pkid_ppto_rows(ppto_rows)
    rpc_rows = rpc_payload.get("rows") or []
    rpc_by_pk = {_dash_pk_disp_key_py(r.get("pk_id")): r for r in rpc_rows if isinstance(r, dict)}
    keys = sorted(
        set(rpc_by_pk)
        | set(agg_meta)
        | set(agg_p_ap)
        | set(agg_p_nr)
        | set(agg_p_pd)
        | set(agg_p_rj),
        key=lambda x: str(x),
    )
    rows: List[dict] = []
    for pk in keys:
        base = rpc_by_pk.get(pk) or {}
        pap = agg_p_ap.get(pk, empty_m())
        pnr = agg_p_nr.get(pk, empty_m())
        ppd = agg_p_pd.get(pk, empty_m())
        prj = agg_p_rj.get(pk, empty_m())
        sic = {
            "cant": float(base.get("cant_sicoe_aprobado") or base.get("cant_sicoe") or 0),
            "costo": float(base.get("costo_sicoe_aprobado") or base.get("costo_sicoe") or 0),
        }
        snr = {"cant": float(base.get("cant_sicoe_no_revisado") or 0), "costo": float(base.get("costo_sicoe_no_revisado") or 0)}
        spe = {"cant": float(base.get("cant_sicoe_pendiente") or 0), "costo": float(base.get("costo_sicoe_pendiente") or 0)}
        srj = {"cant": float(base.get("cant_sicoe_rechazado") or 0), "costo": float(base.get("costo_sicoe_rechazado") or 0)}
        meta = agg_meta.get(pk, {"desc": base.get("descripcion") or "", "_rev_track": []})
        rows.append(_build_pkid_tabla_row_from_aggs(pk, meta, pap, pnr, ppd, prj, sic, snr, spe, srj))
    por_cobrar = sum(r["delta_costo"] for r in rows if r["delta_costo"] > 0)
    devolucion = sum(abs(r["delta_costo"]) for r in rows if r["delta_costo"] < 0)
    return {
        **rpc_payload,
        "rows": rows,
        "por_cobrar": por_cobrar,
        "devolucion": devolucion,
    }


def _canonicalize_pkid_tabla_rows(
    contrato_id: int,
    rows: List[dict],
    alias_map: Optional[Dict[str, str]] = None,
    *,
    vista: str = "presupuesto_obra",
    item_tiene_ppto_oe: Optional[bool] = None,
    listado_vu: Optional[float] = None,
) -> List[dict]:
    """Unifica alias de PK (id interno vs pk_ids.pk_id) en filas de tabla drill."""
    if not rows:
        return []
    raw_keys = {
        _dash_pk_disp_key_py(row.get("pk_id"))
        for row in rows
        if isinstance(row, dict) and row.get("pk_id") not in (None, "")
    }
    if alias_map is None:
        alias_map = _preload_pk_alias_map(contrato_id, raw_keys)
    merged: Dict[str, dict] = {}
    sum_fields = (
        "cant_ppto", "costo_ppto", "cant_ppto_aprobado_n3", "costo_ppto_aprobado_n3",
        "cant_ppto_estado_no_revisado", "costo_ppto_estado_no_revisado",
        "cant_ppto_estado_pendiente", "costo_ppto_estado_pendiente",
        "cant_ppto_estado_rechazado", "costo_ppto_estado_rechazado",
        "cant_sicoe_aprobado", "costo_sicoe_aprobado", "cant_sicoe_no_revisado", "costo_sicoe_no_revisado",
        "cant_sicoe_pendiente", "costo_sicoe_pendiente", "cant_sicoe_rechazado", "costo_sicoe_rechazado",
        "cant_sicoe", "costo_sicoe", "delta_cant", "delta_costo",
    )
    for row in rows:
        if not isinstance(row, dict):
            continue
        pk_raw = _dash_pk_disp_key_py(row.get("pk_id"))
        pk = alias_map.get(pk_raw, alias_map.get(f"id:{pk_raw}", pk_raw))
        base = dict(row)
        base["pk_id"] = pk
        if pk not in merged:
            merged[pk] = base
            continue
        tgt = merged[pk]
        for f in sum_fields:
            if f in base:
                tgt[f] = float(tgt.get(f) or 0) + float(base.get(f) or 0)
        if not tgt.get("descripcion") and base.get("descripcion"):
            tgt["descripcion"] = base["descripcion"]
    out = list(merged.values())
    if listado_vu is not None and float(listado_vu) > 0:
        vu = float(listado_vu)
        for r in out:
            r["item_vu"] = vu
            r["sicoe_item_vu"] = vu
    for r in out:
        _finalize_pkid_tabla_row(r, vista, item_tiene_ppto_oe=item_tiene_ppto_oe)
    return sorted(out, key=lambda x: str(x.get("pk_id") or ""))


def _normalize_pkid_tabla_payload(
    payload: dict,
    contrato_id: Optional[int] = None,
    alias_map: Optional[Dict[str, str]] = None,
    vista: str = "presupuesto_obra",
    *,
    capitulo: Optional[str] = None,
    item: Optional[str] = None,
    current_user=None,
    item_tiene_ppto_oe: Optional[bool] = None,
) -> dict:
    rows = payload.get("rows") or []
    if not isinstance(rows, list):
        rows = []
    if (
        item_tiene_ppto_oe is None
        and parse_dash_vista(vista) == DASH_VISTA_OBRA_EJECUTADA
        and contrato_id
        and (item or "").strip()
    ):
        item_tiene_ppto_oe = _item_tiene_ppto_obra_ejecutada(
            int(contrato_id), capitulo or "", item or "", current_user
        )
    listado_vu: Optional[float] = None
    if contrato_id and (capitulo or "").strip() and (item or "").strip():
        listado_vu = _dash_listado_vu_resolved(int(contrato_id), capitulo or "", item or "")
    if contrato_id:
        rows = _canonicalize_pkid_tabla_rows(
            contrato_id,
            rows,
            alias_map=alias_map,
            vista=vista,
            item_tiene_ppto_oe=item_tiene_ppto_oe,
            listado_vu=listado_vu,
        )
    elif parse_dash_vista(vista) == DASH_VISTA_OBRA_EJECUTADA:
        for r in rows:
            if isinstance(r, dict):
                _finalize_pkid_tabla_row(r, vista, item_tiene_ppto_oe=item_tiene_ppto_oe)
    por_cobrar = sum(float(r.get("delta_costo") or 0) for r in rows if float(r.get("delta_costo") or 0) > 0)
    devolucion = sum(abs(float(r.get("delta_costo") or 0)) for r in rows if float(r.get("delta_costo") or 0) < 0)
    return {
        "rows": rows,
        "por_cobrar": por_cobrar,
        "devolucion": devolucion,
        "descripcion_item": str(payload.get("descripcion_item") or ""),
        "meta": {
            "item_tiene_ppto_obra_ejecutada": item_tiene_ppto_oe,
            "pk_cc_coherente_item": parse_dash_vista(vista) == DASH_VISTA_OBRA_EJECUTADA,
        },
    }


def _rpc_drill_capitulos_agg(contrato_id: int) -> List[dict]:
    campo_max = _get_nivel_maximo_contrato(contrato_id)
    na = _get_niveles_activos_contrato(contrato_id)

    def _call():
        return supabase.rpc(
            "dashboard_drill_capitulos_agg",
            {
                "p_contrato_id": int(contrato_id),
                "p_campo_nivel_max": campo_max,
                "p_niveles_activos": na,
            },
        ).execute().data

    raw = supabase_execute(_call)
    rows = _parse_rpc_jsonb_value(raw)
    if not isinstance(rows, list):
        return []
    out = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        cap = row.get("capitulo") or row.get("nombre") or ""
        out.append(
            {
                "capitulo": cap,
                "nombre": row.get("nombre") or cap,
                "descripcion": row.get("descripcion") or "",
                "presupuesto": float(row.get("presupuesto") or 0),
                "cobrado": float(row.get("cobrado") or 0),
                "presupuesto_aprobado_n3": float(row.get("presupuesto_aprobado_n3") or 0),
                "presupuesto_no_revisado_n3": float(row.get("presupuesto_no_revisado_n3") or 0),
                "sicoe_no_revisado_n3": float(row.get("sicoe_no_revisado_n3") or 0),
                "delta": float(row.get("delta") or 0),
                "pct": float(row.get("pct") or 0),
                "cant_ppto": float(row.get("cant_ppto") or 0),
                "cant_sicoe_aprobado": float(row.get("cant_sicoe_aprobado") or 0),
                "cant_sicoe_no_revisado": float(row.get("cant_sicoe_no_revisado") or 0),
            }
        )
    return out


def _ppto_scan_maps_by_norm_cap(scan: dict) -> Tuple[dict, dict, dict, dict]:
    """Agrega totales de presupuesto por clave normalizada de capítulo."""
    ap_m: Dict[str, float] = defaultdict(float)
    nr_m: Dict[str, float] = defaultdict(float)
    tot_m: Dict[str, float] = defaultdict(float)
    disp: Dict[str, str] = {}
    for k, v in (scan.get("ppto_ap_c") or {}).items():
        nk = norm_capitulo_key(k)
        ap_m[nk] += float(v or 0)
        disp.setdefault(nk, norm_capitulo_display(k))
    for k, v in (scan.get("ppto_nr_c") or {}).items():
        nk = norm_capitulo_key(k)
        nr_m[nk] += float(v or 0)
        disp.setdefault(nk, norm_capitulo_display(k))
    for k, v in (scan.get("ppto_total_c") or {}).items():
        nk = norm_capitulo_key(k)
        tot_m[nk] += float(v or 0)
        disp.setdefault(nk, norm_capitulo_display(k))
    return ap_m, nr_m, tot_m, disp


def _overlay_vista_presupuesto_comparativo(base_rows: List[dict], scan: dict) -> List[dict]:
    """Mantiene SICOE del RPC; sustituye columnas de presupuesto según vista (tipo ejecución)."""
    ap_m, nr_m, tot_m, disp = _ppto_scan_maps_by_norm_cap(scan)
    out: List[dict] = []
    seen: set = set()
    for row in base_rows or []:
        if not isinstance(row, dict):
            continue
        cap_label = row.get("capitulo") or row.get("nombre") or ""
        nk = norm_capitulo_key(cap_label)
        seen.add(nk)
        pap = float(ap_m.get(nk, 0))
        pnr = float(nr_m.get(nk, 0))
        pt = float(tot_m.get(nk, pap + pnr))
        cob = float(row.get("cobrado") or 0)
        label = disp.get(nk, cap_label or nk)
        out.append(
            {
                **row,
                "capitulo": label,
                "nombre": label,
                "presupuesto": round(pt, 2),
                "presupuesto_aprobado_n3": round(pap, 2),
                "presupuesto_no_revisado_n3": round(pnr, 2),
                "cobrado": round(cob, 2),
                "sicoe_no_revisado_n3": round(float(row.get("sicoe_no_revisado_n3") or 0), 2),
                "delta": round(pt - cob, 2),
                "pct": round(cob / pt * 100, 1) if pt else 0,
            }
        )
    for nk, pt in tot_m.items():
        if nk in seen:
            continue
        pap = float(ap_m.get(nk, 0))
        pnr = float(nr_m.get(nk, 0))
        label = disp.get(nk, nk)
        out.append(
            {
                "capitulo": label,
                "nombre": label,
                "descripcion": "",
                "presupuesto": round(pt, 2),
                "presupuesto_aprobado_n3": round(pap, 2),
                "presupuesto_no_revisado_n3": round(pnr, 2),
                "cobrado": 0.0,
                "sicoe_no_revisado_n3": 0.0,
                "delta": round(pt, 2),
                "pct": 0.0,
                "cant_ppto": 0,
                "cant_sicoe_aprobado": 0,
                "cant_sicoe_no_revisado": 0,
            }
        )
    return out


def _merge_drill_rpc_sicoe_vista_ppto(rpc_items: List[dict], ppto_items: List[dict]) -> List[dict]:
    """Une obra (RPC/SICOE, nivel máx. contrato) con presupuesto filtrado por vista."""
    _fin_fields = (
        "unidad",
        "cant_nr", "costo_nr", "cant_p", "costo_p", "cant_r", "costo_r", "cant_a", "costo_a",
        "total_claracore_cant", "total_claracore_costo", "cant_cobrado", "costo_cobrado",
        "delta_cant", "delta_costo",
    )
    rpc_map = {_dash_norm_item_key_py(r.get("item") or r.get("nombre")): r for r in (rpc_items or [])}
    ppto_map = {_dash_norm_item_key_py(r.get("item") or r.get("nombre")): r for r in (ppto_items or [])}
    keys = sorted(set(rpc_map) | set(ppto_map), key=lambda x: str(x))
    out: List[dict] = []
    for ik in keys:
        if not ik:
            continue
        r = dict(rpc_map.get(ik) or {})
        p = ppto_map.get(ik) or {}
        pap = float((p.get("presupuesto_aprobado_n3") if p else r.get("presupuesto_aprobado_n3")) or 0)
        pnr = float((p.get("presupuesto_no_revisado_n3") if p else r.get("presupuesto_no_revisado_n3")) or 0)
        pp_raw = p.get("presupuesto") if p else r.get("presupuesto")
        if pp_raw not in (None, ""):
            pp_cost = float(pp_raw)
        else:
            pp_cost = float(
                (p.get("total_claracore_costo") if p else None)
                or (p.get("costo_ppto_claracore") if p else None)
                or 0
            )
        cob = float(r.get("cobrado") or 0)
        row = {
            "item": ik,
            "nombre": ik,
            "descripcion": (p.get("descripcion") or r.get("descripcion") or ""),
            "presupuesto": round(pp_cost, 2),
            "cobrado": round(cob, 2),
            "presupuesto_aprobado_n3": round(pap, 2),
            "presupuesto_no_revisado_n3": round(pnr, 2),
            "sicoe_no_revisado_n3": round(float(r.get("sicoe_no_revisado_n3") or 0), 2),
            "delta": round(pp_cost - cob, 2),
            "pct": round(cob / pp_cost * 100, 1) if pp_cost else 0,
            "cant_ppto": round(float(p.get("cant_ppto") or r.get("cant_ppto") or 0), 3),
            "cant_ppto_claracore": round(float(p.get("cant_ppto_claracore") or 0), 3),
            "costo_ppto_claracore": round(float(p.get("costo_ppto_claracore") or 0), 2),
            "cant_sicoe_aprobado": round(float(r.get("cant_sicoe_aprobado") or 0), 3),
            "cant_sicoe_no_revisado": round(float(r.get("cant_sicoe_no_revisado") or 0), 3),
            "cant_cobrado": round(float(r.get("cant_sicoe_aprobado") or 0), 3),
            "costo_cobrado": round(cob, 2),
        }
        for f in _fin_fields:
            if f in p and p.get(f) is not None:
                row[f] = p[f]
        if p:
            row["tiene_ppto_obra_ejecutada"] = bool(p.get("tiene_ppto_obra_ejecutada", True))
        out.append(row)
    return out


def _drill_rows_missing_sicoe_cobrado(rows: List[dict]) -> bool:
    if not rows:
        return False
    return sum(float(r.get("cobrado") or 0) for r in rows if isinstance(r, dict)) <= 0


def _overlay_sicoe_on_drill_items(rows: List[dict], sicoe_by: dict, capitulo: str) -> List[dict]:
    """Superpone cobrado SICOE (nivel máx. contrato) sobre filas del drill."""
    cap_key = _dash_norm_capitulo_key_py(capitulo)
    out: List[dict] = []
    seen_items: set = set()
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        r = dict(row)
        ik = _dash_norm_item_key_py(r.get("item") or r.get("nombre"))
        if ik:
            seen_items.add(ik)
        sg = sicoe_by.get((cap_key, ik), {}) if ik else {}
        apc = float(sg.get("ap_c") or 0)
        nrc = float(sg.get("nr_c") or 0)
        ap_q = cantidad_dashboard(float(sg.get("ap_q") or 0))
        rpc_cob = float(r.get("cobrado") or 0)
        if (cap_key, ik) in sicoe_by:
            cob = apc
            r["costo_cobrado"] = round(apc, 0)
            r["sicoe_item_vu"] = float(sg.get("item_vu") or 0)
            r["listado_vu_ausente"] = bool(sg.get("listado_vu_ausente"))
            r["listado_vu_encontrado"] = bool(sg.get("listado_vu_encontrado"))
            r["sicoe_no_revisado_n3"] = round(nrc, 0)
            r["cant_sicoe_aprobado"] = ap_q
            r["cant_sicoe_no_revisado"] = cantidad_dashboard(float(sg.get("nr_q") or 0))
            r["cant_cobrado"] = ap_q
        else:
            cob = rpc_cob
            r["costo_cobrado"] = round(rpc_cob, 0)
        r["cobrado"] = round(cob, 0)
        pp = float(r.get("presupuesto") or 0)
        r["delta"] = round(pp - cob, 2)
        r["pct"] = round(cob / pp * 100, 1) if pp else 0
        out.append(r)

    for (ck, ik), sg in (sicoe_by or {}).items():
        if ck != cap_key or not ik or ik in seen_items:
            continue
        apc = float(sg.get("ap_c") or 0)
        nrc = float(sg.get("nr_c") or 0)
        if apc <= 0 and nrc <= 0:
            continue
        cob = apc
        out.append(
            {
                "item": ik,
                "nombre": ik,
                "descripcion": "",
                "presupuesto": 0.0,
                "cobrado": round(cob, 0),
                "costo_cobrado": round(cob, 0),
                "presupuesto_aprobado_n3": 0.0,
                "presupuesto_no_revisado_n3": 0.0,
                "sicoe_no_revisado_n3": round(nrc, 0),
                "delta": round(-cob, 0),
                "pct": 0.0,
                "cant_ppto": 0.0,
                "cant_cobrado": cantidad_dashboard(float(sg.get("ap_q") or 0)),
                "sicoe_item_vu": float(sg.get("item_vu") or 0),
                "cant_sicoe_aprobado": cantidad_dashboard(float(sg.get("ap_q") or 0)),
                "cant_sicoe_no_revisado": cantidad_dashboard(float(sg.get("nr_q") or 0)),
            }
        )
    out.sort(key=lambda x: str(x.get("item") or ""))
    return out


def _dashboard_apply_vista_presupuesto(
    contrato_id: int,
    hit: dict,
    vista: str,
    current_user,
) -> dict:
    """Presupuesto KPI/gráfico según vista (tipo_ejecucion); SICOE N3 siempre completo."""
    hit = dict(hit or {})
    if hit.get("comparativo_capitulos") is not None and hit.get("total_cobrado") is not None:
        sicoe_ap_c, sicoe_nr_c, total_cobrado, total_sicoe_nr = _dashboard_sicoe_from_hit(hit)
    else:
        ex = _dashboard_resumen_scan_caps(contrato_id)
        sicoe_ap_c = ex["sicoe_ap_c"]
        sicoe_nr_c = ex["sicoe_nr_c"]
        total_cobrado = sum(sicoe_ap_c.values())
        total_sicoe_nr = sum(sicoe_nr_c.values())

    scan = scan_presupuesto_vista(
        supabase, contrato_id, vista, current_user, resumen_only=True
    )
    base_comp = hit.get("comparativo_capitulos")
    if isinstance(base_comp, list) and base_comp:
        comparativo = _overlay_vista_presupuesto_comparativo(base_comp, scan)
    else:
        comparativo = rebuild_comparativo_capitulos(scan, sicoe_ap_c, sicoe_nr_c)
    ppto_ap = sum((scan.get("ppto_ap_c") or {}).values())
    ppto_nr = sum((scan.get("ppto_nr_c") or {}).values())
    ppto_total = float(scan.get("costo_total") or (ppto_ap + ppto_nr))

    hit["comparativo_capitulos"] = comparativo
    hit["total_presupuesto"] = round(ppto_total, 2)
    hit["total_cobrado"] = round(total_cobrado, 2)
    hit["delta"] = round(ppto_total - total_cobrado, 2)
    hit["consumo_pct"] = round(total_cobrado / ppto_total * 100, 1) if ppto_total else 0
    hit["total_presupuesto_aprobado_n3"] = round(ppto_ap, 2)
    hit["total_presupuesto_no_revisado_n3"] = round(ppto_nr, 2)
    hit["total_sicoe_n3_no_revisado"] = round(total_sicoe_nr, 2)
    hit["vista"] = parse_dash_vista(vista)
    if scan.get("por_capitulo_list"):
        hit["por_capitulo_presupuesto"] = scan["por_capitulo_list"]
    return hit


@app.get("/sicoe-obra/{contrato_id}/dashboard-resumen")
def dashboard_resumen_obra(
    contrato_id: int,
    vista: str = Query("presupuesto_obra", description="presupuesto_obra | obra_ejecutada"),
    current_user=Depends(get_current_user),
):
    vista_n = parse_dash_vista(vista)
    cache_key = (
        "dashboard_resumen_endpoint_v3",
        int(contrato_id),
        vista_n,
        _dashboard_resumen_user_cache_key(current_user),
    )
    cached = _dashboard_response_cache_get(cache_key)
    if cached is not None:
        return cached
    try:
        campo_max = _get_nivel_maximo_contrato(contrato_id)
        try:
            na = _get_niveles_activos_contrato(contrato_id)
            hit = _fetch_dashboard_resumen_sicoe_agg(contrato_id, campo_max, na)
            if hit is not None and isinstance(hit.get("comparativo_capitulos"), list):
                result = _dashboard_apply_vista_presupuesto(contrato_id, hit, vista, current_user)
                _dashboard_response_cache_set(cache_key, result)
                return result
        except Exception:
            pass

        # 1. Obra aprobada: Σ cant × V.U. por ítem (nunca SUM(costo_directo) por línea).
        def _actas_map():
            return supabase.table("actas").select("id, numero_rpo")\
                .eq("contrato_id", contrato_id).execute().data
        acta_rows = supabase_execute(_actas_map) or []
        acta_id_to_nr = {a["id"]: a.get("numero_rpo") for a in acta_rows if a.get("id") is not None}
        nr_to_aid = {v: k for k, v in acta_id_to_nr.items() if v is not None}

        sicoe_by = _dashboard_scan_sicoe_by_item(contrato_id)
        total_cobrado = 0.0
        obra_caps: Dict[str, float] = {}
        for (ck, _ik), sg in sicoe_by.items():
            cob = float(sg.get("ap_c") or 0)
            if not cob:
                continue
            total_cobrado += cob
            obra_caps[ck] = obra_caps.get(ck, 0.0) + cob

        acta_agg: Dict[Any, float] = {}
        for nr, aid in nr_to_aid.items():
            if aid is None:
                continue
            by_acta = _dashboard_scan_sicoe_by_item(contrato_id, acta_id=int(aid))
            acta_agg[nr] = sum(float(sg.get("ap_c") or 0) for sg in by_acta.values())

        # 2. Presupuesto por capítulo
        def _ppto():
            return supabase.table("vista_ppto_por_capitulo")\
                .select("*").eq("contrato_id", contrato_id).execute().data
        ppto_raw = supabase_execute(_ppto)
        ppto_caps = {r["capitulo"]: float(r.get("presupuesto") or 0) for r in ppto_raw}
        ppto_total = sum(ppto_caps.values())

        # 3. Comparativo por capítulo (presupuesto vs obra aprobada N3)

        def _sort_acta_key(x):
            try:
                return float(x[0])
            except (TypeError, ValueError):
                return 0.0

        def _acta_num(k):
            try:
                return float(k)
            except (TypeError, ValueError):
                return 0.0

        por_acta = [{"acta": nr, "cobrado": round(v, 2)} for nr, v in sorted(acta_agg.items(), key=_sort_acta_key, reverse=True)]

        caps = sorted(set(list(ppto_caps.keys()) + list(obra_caps.keys())))
        comparativo = [
            {
                "capitulo": c,
                "presupuesto": ppto_caps.get(c, 0),
                "cobrado": round(obra_caps.get(c, 0), 2),
                "delta": round(ppto_caps.get(c, 0) - obra_caps.get(c, 0), 2),
                "consumo_pct": round(obra_caps.get(c, 0) / ppto_caps.get(c, 0) * 100, 1) if ppto_caps.get(c, 0) else 0,
            }
            for c in caps
        ]

        base = {
            "total_presupuesto": ppto_total,
            "total_cobrado": round(total_cobrado, 2),
            "delta": round(ppto_total - total_cobrado, 2),
            "consumo_pct": round(total_cobrado / ppto_total * 100, 1) if ppto_total else 0,
            "actas": sorted(acta_agg.keys(), key=_acta_num, reverse=True),
            "comparativo_capitulos": comparativo,
            "por_acta": por_acta,
        }
        result = _dashboard_apply_vista_presupuesto(contrato_id, base, vista, current_user)
        _dashboard_response_cache_set(cache_key, result)
        return result
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


def _matriz_validacion_norm_estado(v) -> str:
    if v is None:
        return "No Revisado"
    s = str(v).strip()
    if not s:
        return "No Revisado"
    sl = s.lower()
    if sl == "aprobado":
        return "Aprobado"
    if sl == "pendiente":
        return "Pendiente"
    if sl == "rechazado":
        return "Rechazado"
    if "no revis" in sl or sl == "no revisado":
        return "No Revisado"
    return s


def _dash_norm_cap(s: Optional[str]) -> str:
    t = (s or "").strip()
    return t if t else "Sin capítulo"


def _so_reg_cola_n1_n2_aprobados(reg: dict) -> bool:
    return (
        _matriz_validacion_norm_estado(reg.get("nivel1_estado")) == "Aprobado"
        and _matriz_validacion_norm_estado(reg.get("nivel2_estado")) == "Aprobado"
    )


def _so_reg_prereqs_activos_aprobados_antes_max(reg: dict, contrato_id: int) -> bool:
    """Todos los niveles activos estrictamente menores al máximo activo deben estar «Aprobado» (p. ej. [1,2,4] → N1 y N2; N3 inactivo no exige)."""
    activos = _get_niveles_activos_contrato(contrato_id)
    if not activos:
        activos = [1, 2, 3]
    try:
        max_n = max(int(x) for x in activos)
    except (TypeError, ValueError):
        max_n = 3
    max_n = min(6, max(1, max_n))
    for n in activos:
        try:
            ni = int(n)
        except (TypeError, ValueError):
            continue
        if ni >= max_n:
            continue
        campo = NIVEL_VALIDACION_NUM_A_CAMPO.get(ni)
        if not campo:
            continue
        if _matriz_validacion_norm_estado(reg.get(campo)) != "Aprobado":
            return False
    return True


def _so_reg_en_cola_interventoria(reg: dict, contrato_id: int) -> bool:
    """Línea en cola del último nivel activo: ítem asignado, prerequisitos de niveles activos inferiores y nivel final «No Revisado»."""
    if not (reg.get("item_numero") or "").strip():
        return False
    if not _so_reg_prereqs_activos_aprobados_antes_max(reg, contrato_id):
        return False
    return _matriz_validacion_norm_estado_nivel_final(reg, contrato_id) == "No Revisado"


def _dashboard_resumen_scan_caps(contrato_id: int) -> Dict[str, Any]:
    """
    Por capítulo: costo/cant SICOE N3 aprobado, SICOE N3 no revisado (en cola),
    y presupuesto ClaraCore partido por columna revisado (aprobado vs resto).
    SICOE: agrega por ítem (Σ cant × V.U., un redondeo) — nunca SUM(costo_directo).
    """
    cached = _dash_agg_cache_get("resumen_caps_v2", contrato_id)
    if cached is not None:
        return cached
    sicoe_ap_c = defaultdict(float)
    sicoe_ap_q = defaultdict(float)
    sicoe_nr_c = defaultdict(float)
    sicoe_nr_q = defaultdict(float)
    sicoe_by = _dashboard_scan_sicoe_by_item(contrato_id)
    for (ck, _ik), sg in sicoe_by.items():
        sicoe_ap_c[ck] += float(sg.get("ap_c") or 0)
        sicoe_ap_q[ck] += float(sg.get("ap_q") or 0)
        sicoe_nr_c[ck] += float(sg.get("nr_c") or 0)
        sicoe_nr_q[ck] += float(sg.get("nr_q") or 0)

    ppto_ap_c = defaultdict(float)
    ppto_nr_c = defaultdict(float)
    off = 0
    while True:
        def _pp(o=off):
            return (
                supabase.table("presupuesto")
                .select("capitulo, costo_directo, revisado")
                .eq("contrato_id", contrato_id)
                .eq("dado_de_baja", False)
                .order("id").range(o, o + 999)
                .execute()
                .data
            )

        batch = supabase_execute(_pp) or []
        for r in batch:
            cap = _dash_norm_cap(r.get("capitulo"))
            cost = float(r.get("costo_directo") or 0)
            if _matriz_validacion_norm_estado(r.get("revisado")) == "Aprobado":
                ppto_ap_c[cap] += cost
            else:
                ppto_nr_c[cap] += cost
        if len(batch) < 1000:
            break
        off += 1000

    result = {
        "sicoe_ap_c": dict(sicoe_ap_c),
        "sicoe_ap_q": dict(sicoe_ap_q),
        "sicoe_nr_c": dict(sicoe_nr_c),
        "sicoe_nr_q": dict(sicoe_nr_q),
        "ppto_ap_c": dict(ppto_ap_c),
        "ppto_nr_c": dict(ppto_nr_c),
    }
    _dash_agg_cache_set("resumen_caps_v2", contrato_id, result)
    return result


def _dashboard_resumen_merge_extras(contrato_id: int, hit: dict) -> dict:
    """Si el RPC ya trae dashboard_schema=2, no escanear tablas. Si no, enriquecer con scan Python."""
    if hit.get("dashboard_schema") == 2:
        return hit
    try:
        ex = _dashboard_resumen_scan_caps(contrato_id)
    except Exception:
        return hit
    comp = hit.get("comparativo_capitulos")
    if not isinstance(comp, list):
        return hit
    tot_nr = tot_pap = tot_pnr = 0.0
    for row in comp:
        if not isinstance(row, dict):
            continue
        cap = row.get("capitulo")
        nr = float(ex["sicoe_nr_c"].get(cap, 0))
        pap = float(ex["ppto_ap_c"].get(cap, 0))
        pnr = float(ex["ppto_nr_c"].get(cap, 0))
        row["sicoe_no_revisado_n3"] = round(nr, 2)
        row["presupuesto_aprobado_n3"] = round(pap, 2)
        row["presupuesto_no_revisado_n3"] = round(pnr, 2)
        row["sicoe_aprobado_n3"] = float(row.get("cobrado") or 0)
        tot_nr += nr
        tot_pap += pap
        tot_pnr += pnr
    hit["total_sicoe_n3_no_revisado"] = round(tot_nr, 2)
    hit["total_presupuesto_aprobado_n3"] = round(tot_pap, 2)
    hit["total_presupuesto_no_revisado_n3"] = round(tot_pnr, 2)
    return hit


def _ppto_drill_rows_for_vista(
    contrato_id: int,
    capitulo: str,
    vista: str,
    current_user,
    *,
    listado_idx: Optional[Dict[str, dict]] = None,
    ppto_obra_by: Optional[Dict[str, List[dict]]] = None,
) -> List[dict]:
    """Filas presupuesto para merge con RPC (solo columnas de vista / revisado)."""
    cap_raw = (capitulo or "").strip()
    if listado_idx is None or (parse_dash_vista(vista) == DASH_VISTA_OBRA_EJECUTADA and ppto_obra_by is None):
        listado_idx, ppto_obra_by = _capitulo_export_vu_context(contrato_id, cap_raw, vista, current_user)
    if parse_dash_vista(vista) == DASH_VISTA_OBRA_EJECUTADA:
        listado_full = _listado_precios_vu_by_cap_item(contrato_id)
        scan = scan_presupuesto_capitulo_vista(supabase, contrato_id, cap_raw, vista, current_user)
        return drill_items_capitulo_vista(
            scan,
            cap_raw,
            {},
            None,
            listado_idx=listado_idx,
            ppto_obra_by=ppto_obra_by,
            listado_full_idx=listado_full,
        )

    ppto_by: Dict[str, List[dict]] = {}
    for r in _ppto_rows_capitulo_tipo(contrato_id, cap_raw, TIPO_PRESUPUESTO_OBRA, current_user):
        it = _dash_norm_item_key_py(r.get("item"))
        if it:
            ppto_by.setdefault(it, []).append(r)

    listado_full = _listado_precios_vu_by_cap_item(contrato_id)
    rows: List[dict] = []
    for k in sorted(ppto_by.keys(), key=lambda x: str(x)):
        rows_it = ppto_by[k]
        lp_vu = _dash_listado_vu_resolved(
            contrato_id, cap_raw, k, cap_listado_idx=listado_idx, full_listado_idx=listado_full
        )
        est, unidad, vu = _ppto_metricas_por_estado(
            rows_it, listado_vu=lp_vu, alt_rows=alt, obra_ejecutada=False
        )
        rows_vu = ppto_rows_with_resolved_vu(rows_it, listado_vu=lp_vu)
        p_cant = cantidad_dashboard_sum(rows_vu)
        p_cost = costo_agregado_cant_vu(p_cant, vu)
        revsplit = _ppto_costo_por_revisado(rows_vu)
        pap = float(revsplit.get("Aprobado") or 0)
        pnr = (
            float(revsplit.get("No Revisado") or 0)
            + float(revsplit.get("Pendiente") or 0)
            + float(revsplit.get("Rechazado") or 0)
        )
        cc_cant, cc_cost = _ppto_claracore_split(rows_vu, listado_vu=lp_vu)
        desc = next((str(x["descripcion"]) for x in rows_it if x.get("descripcion")), "")
        estado_fields = _drill_item_estado_fields(
            est, unidad, {}, vu=vu, obra_ejecutada=False
        )
        rows.append(
            {
                "item": k,
                "nombre": k,
                "descripcion": desc,
                "item_vu": float(vu or 0),
                "presupuesto": round(p_cost, 0),
                "presupuesto_aprobado_n3": round(pap, 0),
                "presupuesto_no_revisado_n3": round(pnr, 0),
                "cant_ppto": cantidad_dashboard(p_cant),
                "cant_ppto_claracore": cantidad_dashboard(cc_cant),
                "costo_ppto_claracore": round(cc_cost, 0),
                **estado_fields,
            }
        )
    return rows


def _drill_agg_by_item(
    contrato_id: int,
    capitulo: str,
    item_filtro: Optional[str] = None,
    vista: str = "presupuesto_obra",
    current_user=None,
) -> List[dict]:
    """
    Ítems del capítulo: RPC SQL (rápido, ~5s) + presupuesto según toggle de vista.
    Fallback acotado al capítulo si el RPC no está disponible.
    """
    cap_raw = (capitulo or "").strip()
    if not cap_raw:
        return []
    listado_idx, ppto_obra_by = _capitulo_export_vu_context(contrato_id, cap_raw, vista, current_user)
    t0 = time.time()
    out: Optional[List[dict]] = None
    try:
        rpc_items = _rpc_drill_items_agg(contrato_id, cap_raw)
        ppto_items = _ppto_drill_rows_for_vista(
            contrato_id, cap_raw, vista, current_user,
            listado_idx=listado_idx, ppto_obra_by=ppto_obra_by,
        )
        out = _merge_drill_rpc_sicoe_vista_ppto(rpc_items, ppto_items)
        sicoe_by = _dashboard_scan_sicoe_by_item_capitulo(contrato_id, cap_raw)
        out = _overlay_sicoe_on_drill_items(out, sicoe_by, cap_raw)
        print(
            f"dashboard_drill_items RPC ok cap={cap_raw!r} rpc={len(rpc_items)} out={len(out)} "
            f"ms={int((time.time() - t0) * 1000)}",
            flush=True,
        )
    except Exception as rpc_err:
        print(
            f"dashboard_drill_items_agg RPC FALLÓ, fallback capítulo: "
            f"{type(rpc_err).__name__}: {rpc_err}",
            flush=True,
        )
        scan = scan_presupuesto_capitulo_vista(supabase, contrato_id, cap_raw, vista, current_user)
        sicoe_by = _dashboard_scan_sicoe_by_item_capitulo(contrato_id, cap_raw)
        allowed = None if parse_dash_vista(vista) == DASH_VISTA_OBRA_EJECUTADA else scan.get("allowed_sicoe_keys")
        out = drill_items_capitulo_vista(
            scan, cap_raw, sicoe_by, allowed,
            listado_idx=listado_idx, ppto_obra_by=ppto_obra_by,
            listado_full_idx=_listado_precios_vu_by_cap_item(contrato_id),
        )
        print(
            f"dashboard_drill_items fallback cap={cap_raw!r} out={len(out or [])} "
            f"ms={int((time.time() - t0) * 1000)}",
            flush=True,
        )
    if parse_dash_vista(vista) == DASH_VISTA_OBRA_EJECUTADA and out:
        out = _hydrate_drill_items_ppto_obra_ejecutada(
            contrato_id, cap_raw, out, current_user,
            listado_idx=listado_idx, ppto_obra_by=ppto_obra_by,
        )
    finalized = _finalize_drill_items_vista(out, vista)
    return _filter_drill_item_rows(
        _enrich_drill_items_meta(contrato_id, cap_raw, finalized, current_user),
        item_filtro,
    )


def _filter_drill_item_rows(out: Optional[List[dict]], item_filtro: Optional[str]) -> List[dict]:
    rows = out or []
    if item_filtro and str(item_filtro).strip():
        itf = _dash_norm_item_key_py(str(item_filtro).strip())
        rows = [row for row in rows if _dash_norm_item_key_py(row.get("item")) == itf]
    return rows


def _drill_agg_capitulos(contrato_id: int, vista: str = "presupuesto_obra", current_user=None) -> List[dict]:
    """Listado por capítulo: SICOE desde RPC + presupuesto según vista."""
    scan = scan_presupuesto_vista(supabase, contrato_id, vista, current_user, resumen_only=True)
    try:
        rpc_rows = _rpc_drill_capitulos_agg(contrato_id)
        return _overlay_vista_presupuesto_comparativo(rpc_rows, scan)
    except Exception as rpc_err:
        print(
            f"dashboard_drill_capitulos_agg RPC FALLÓ, fallback Python: {type(rpc_err).__name__}: {rpc_err}",
            flush=True,
        )
        allowed = scan.get("allowed_sicoe_keys")
        if allowed is not None:
            sicoe_by = _dashboard_scan_sicoe_by_item(contrato_id)
            sicoe_ap_c, sicoe_nr_c, sicoe_ap_q, sicoe_nr_q = filter_sicoe_by_allowed_keys(sicoe_by, allowed)
        else:
            ex = _dashboard_resumen_scan_caps(contrato_id)
            sicoe_ap_c = ex["sicoe_ap_c"]
            sicoe_nr_c = ex["sicoe_nr_c"]
            sicoe_ap_q = ex["sicoe_ap_q"]
            sicoe_nr_q = ex["sicoe_nr_q"]
        return rebuild_comparativo_capitulos(scan, sicoe_ap_c, sicoe_nr_c, sicoe_ap_q, sicoe_nr_q)


def _matriz_validacion_bloque_capitulo(capitulo: Optional[str]) -> str:
    """Obra ejecutada directa vs ensayos/sondeos (cap. 14–15 o nombre típico)."""
    c = (capitulo or "").strip().upper()
    if c.startswith("14.") or c.startswith("15.") or "ENSAYO" in c or "SONDEO" in c:
        return "ensayos"
    return "obra"


def _matriz_col_nivel(n: int) -> str:
    return f"nivel{n}"


def _matriz_validacion_empty(niveles_activos: Optional[List[int]] = None) -> dict:
    na = sorted({int(x) for x in (niveles_activos or [1, 2, 3]) if 1 <= int(x) <= 6})
    if not na:
        na = [1, 2, 3]
    z = {_matriz_col_nivel(n): 0.0 for n in na}
    return {
        "aprobado": dict(z),
        "pendiente": dict(z),
        "pendiente_item": dict(z),
        "no_revisado": dict(z),
        "rechazado": dict(z),
        "habilitado": dict(z),
        "otras_actas": dict(z),
    }


def _matriz_prereqs_aprobados(reg: dict, niveles_activos: List[int], nivel_objetivo: int) -> bool:
    """True si todos los niveles activos estrictamente menores a nivel_objetivo están Aprobado."""
    for n in niveles_activos:
        if n >= nivel_objetivo:
            break
        campo = NIVEL_VALIDACION_NUM_A_CAMPO.get(n)
        if not campo:
            continue
        if _matriz_validacion_norm_estado(reg.get(campo)) != "Aprobado":
            return False
    return True


def _matriz_estado_en_nivel(reg: dict, n: int) -> str:
    campo = NIVEL_VALIDACION_NUM_A_CAMPO.get(n)
    if not campo:
        return "No Revisado"
    return _matriz_validacion_norm_estado(reg.get(campo))


def _matriz_acc_por_estado(M: dict, estado: str, col: str, cd: float) -> None:
    if estado == "Aprobado":
        M["aprobado"][col] += cd
    elif estado == "Pendiente":
        M["pendiente"][col] += cd
    elif estado == "Rechazado":
        M["rechazado"][col] += cd
    else:
        M["no_revisado"][col] += cd


def _matriz_legacy_bloque_a_niveles(bloque: dict, niveles_activos: List[int]) -> dict:
    """Convierte respuesta SQL legada (inspector/residente/interventoria) a nivel1..n."""
    na = sorted({int(x) for x in niveles_activos if 1 <= int(x) <= 6}) or [1, 2, 3]
    if not bloque or not isinstance(bloque, dict):
        return _matriz_validacion_empty(na)
    legacy_map = {1: "inspector", 2: "residente"}
    nmax = max(na)
    out = _matriz_validacion_empty(na)
    for fila in out:
        src = bloque.get(fila) if isinstance(bloque.get(fila), dict) else {}
        use_nivel_keys = any(str(k).startswith("nivel") for k in src.keys())
        for n in na:
            col = _matriz_col_nivel(n)
            if use_nivel_keys:
                out[fila][col] = float(src.get(col) or 0)
            else:
                if n == nmax:
                    leg = "interventoria"
                else:
                    leg = legacy_map.get(n, "interventoria")
                out[fila][col] = float(src.get(leg) or src.get(col) or 0)
    return out


def _matriz_enforce_pendiente_item_n_min(bloque: dict, niveles_activos: List[int]) -> dict:
    """pendiente_item solo en nivel{n_min}; descarta legacy residente→N2 y sub_estado."""
    na = sorted({int(x) for x in niveles_activos if 1 <= int(x) <= 6}) or [1, 2, 3]
    if not bloque or not isinstance(bloque, dict):
        return _matriz_validacion_empty(na)
    n_min = na[0]
    col_min = _matriz_col_nivel(n_min)
    src_pi = bloque.get("pendiente_item") if isinstance(bloque.get("pendiente_item"), dict) else {}
    pi = {_matriz_col_nivel(n): 0.0 for n in na}
    pi[col_min] = float(src_pi.get(col_min) or 0)
    out = dict(bloque)
    out["pendiente_item"] = pi
    return out


def _matriz_bloque_usa_claves_nivel(bloque: Optional[dict]) -> bool:
    """True si el bloque SQL/Python ya trae nivel1..nivel6 (no inspector/residente/interventoria)."""
    if not bloque or not isinstance(bloque, dict):
        return False
    for fila in ("aprobado", "pendiente", "no_revisado", "rechazado", "habilitado"):
        src = bloque.get(fila)
        if isinstance(src, dict) and any(str(k).startswith("nivel") for k in src.keys()):
            return True
    return False


def _matriz_finalizar_bloque(bloque: Optional[dict], niveles_activos: List[int], *, desde_sql_legacy: bool) -> dict:
    na = sorted({int(x) for x in niveles_activos if 1 <= int(x) <= 6}) or [1, 2, 3]
    # SQL nuevo emite nivelN; solo mapear inspector/residente/interventoria si aún viene legado.
    if desde_sql_legacy and not _matriz_bloque_usa_claves_nivel(bloque):
        b = _matriz_legacy_bloque_a_niveles(bloque, na)
    elif bloque and isinstance(bloque, dict):
        if _matriz_bloque_usa_claves_nivel(bloque):
            b = _matriz_legacy_bloque_a_niveles(bloque, na)  # rellena solo niveles activos
        else:
            b = bloque
    else:
        b = _matriz_validacion_empty(na)
    return _matriz_enforce_pendiente_item_n_min(b, na)


def _matriz_finalizar_payload(payload: dict, niveles_activos: List[int], *, desde_sql_legacy: bool) -> dict:
    return {
        "obra_ejecutada_directo_sin_aiu": _matriz_finalizar_bloque(
            payload.get("obra_ejecutada_directo_sin_aiu"), niveles_activos, desde_sql_legacy=desde_sql_legacy
        ),
        "ensayos_sondeos_directo_sin_iva": _matriz_finalizar_bloque(
            payload.get("ensayos_sondeos_directo_sin_iva"), niveles_activos, desde_sql_legacy=desde_sql_legacy
        ),
    }


def _matriz_acc_cost(M: dict, section: str, col: str, cd: float) -> None:
    """Suma costo_directo en celda (section/col) de la matriz."""
    if section not in M or col not in M[section]:
        return
    M[section][col] += float(cd or 0)


def _dashboard_matriz_validacion_por_niveles(
    contrato_id: int,
    acta_id_filtro: Optional[int],
    niveles_activos: Optional[List[int]] = None,
) -> dict:
    """Agrega matriz SICOE por cada nivel de validación activo del contrato (1..6)."""
    na = sorted({int(x) for x in (niveles_activos or _get_niveles_activos_contrato(contrato_id)) if 1 <= int(x) <= 6})
    if not na:
        na = [1, 2, 3]
    obra_m = _matriz_validacion_empty(na)
    ens_m = _matriz_validacion_empty(na)
    n_min = na[0]

    def _fila_estado(est: str) -> str:
        if est == "Aprobado":
            return "aprobado"
        if est == "Pendiente":
            return "pendiente"
        if est == "Rechazado":
            return "rechazado"
        return "no_revisado"

    def _acc_reg_en_matriz(Mroot: dict, reg: dict) -> None:
        cd = float(reg.get("costo_directo") or 0)
        for n in na:
            col = _matriz_col_nivel(n)
            if n == n_min:
                est = _matriz_estado_en_nivel(reg, n)
                _matriz_acc_cost(Mroot, _fila_estado(est), col, cd)
                _matriz_acc_cost(Mroot, "habilitado", col, cd)
            elif _matriz_prereqs_aprobados(reg, na, n):
                est = _matriz_estado_en_nivel(reg, n)
                _matriz_acc_cost(Mroot, _fila_estado(est), col, cd)
                _matriz_acc_cost(Mroot, "habilitado", col, cd)
        if _matriz_estado_en_nivel(reg, n_min) == "Pendiente":
            _matriz_acc_cost(Mroot, "pendiente_item", _matriz_col_nivel(n_min), cd)

    off = 0
    while True:
        def _batch(o=off):
            q = supabase.table("so_registros").select(
                f"costo_directo,{SICOE_SELECT_NIVELES_ESTADO},sub_estado,"
                "capitulo,acta_rpo_id,item_numero"
            ).eq("contrato_id", contrato_id)
            if acta_id_filtro is not None:
                q = q.eq("acta_rpo_id", acta_id_filtro)
            return q.order("id").range(o, o + 999).execute().data

        batch = supabase_execute(_batch) or []
        for reg in batch:
            if not (reg.get("item_numero") or "").strip():
                continue
            bloque = _matriz_validacion_bloque_capitulo(reg.get("capitulo"))
            Mroot = ens_m if bloque == "ensayos" else obra_m
            _acc_reg_en_matriz(Mroot, reg)

        if len(batch) < 1000:
            break
        off += 1000

    if acta_id_filtro is not None:
        off = 0
        while True:
            def _bo(o=off):
                q = supabase.table("so_registros").select(
                    f"costo_directo,{SICOE_SELECT_NIVELES_ESTADO},capitulo,acta_rpo_id,item_numero"
                ).eq("contrato_id", contrato_id)
                return q.order("id").range(o, o + 999).execute().data

            batch = supabase_execute(_bo) or []
            for reg in batch:
                if not (reg.get("item_numero") or "").strip():
                    continue
                aid = reg.get("acta_rpo_id")
                if aid is not None and aid == acta_id_filtro:
                    continue
                cd = float(reg.get("costo_directo") or 0)
                bloque = _matriz_validacion_bloque_capitulo(reg.get("capitulo"))
                Ox = ens_m if bloque == "ensayos" else obra_m
                for n in na:
                    if not _matriz_prereqs_aprobados(reg, na, n):
                        continue
                    if _matriz_estado_en_nivel(reg, n) == "Pendiente":
                        col = _matriz_col_nivel(n)
                        _matriz_acc_cost(Ox, "otras_actas", col, cd)
            if len(batch) < 1000:
                break
            off += 1000

    def round_block(m):
        out = {}
        for k, cols in m.items():
            out[k] = {c: round(v, 0) for c, v in cols.items()}
        return out

    return {
        "obra_ejecutada_directo_sin_aiu": round_block(obra_m),
        "ensayos_sondeos_directo_sin_iva": round_block(ens_m),
    }


def _matriz_validacion_empty_legacy():
    z = {"interventoria": 0.0, "residente": 0.0, "inspector": 0.0}
    return {
        "aprobado": dict(z),
        "pendiente": dict(z),
        "pendiente_item": dict(z),
        "no_revisado": dict(z),
        "rechazado": dict(z),
        "habilitado": dict(z),
        "otras_actas": dict(z),
    }


def _dashboard_matriz_validacion_fallback(
    contrato_id: int,
    acta_id_filtro: Optional[int],
) -> dict:
    """Fallback: delega en agregador dinámico por niveles activos del contrato."""
    na = _get_niveles_activos_contrato(contrato_id)
    return _dashboard_matriz_validacion_por_niveles(contrato_id, acta_id_filtro, na)


@app.get("/sicoe-obra/{contrato_id}/dashboard-matriz-validacion")
def dashboard_matriz_validacion_obra(
    contrato_id: int,
    acta_rpo: Optional[int] = None,
    todo_contrato: bool = Query(False, description="Si true, agrega todo el contrato (lento). Si false y sin acta_rpo, usa acta vigente por período."),
    current_user=Depends(get_current_user),
):
    """
    Matriz de validación por rol (Interventoría=nivel3, Residente=nivel2, Inspector=nivel1).
    Por defecto (sin acta_rpo y todo_contrato=false): solo registros del **Acta RPO vigente** (fecha hoy ∈ [inicio, fin]).
    Con acta_rpo explícito: solo ese acta. Con todo_contrato=true: histórico completo (costoso).
    Preferir función SQL dashboard_matriz_validacion_agg (rápido); si no existe, fallback en Python.
    """
    try:
        matriz_key = ("dashboard_matriz_v2", int(contrato_id), bool(todo_contrato), acta_rpo)
        cached_matriz = _dashboard_response_cache_get(matriz_key)
        if cached_matriz is not None:
            return cached_matriz

        acta_id_filtro: Optional[int] = None
        filtro_modo = "vigente"
        acta_rpo_resp: Optional[int] = None
        vig = None
        payload: dict = {}
        payload_desde_sql = False
        niveles_activos = _get_niveles_activos_contrato(contrato_id)
        campo_max = _get_nivel_maximo_contrato(contrato_id)
        # La RPC SQL lee niveles_activos del contrato (1–6); no limitar al trío clásico [1,2,3].
        usar_sql_matriz = bool(niveles_activos) and all(1 <= int(n) <= 6 for n in niveles_activos)

        def _parse_rpc_matrix_raw(raw):
            if raw is None:
                return {}
            if isinstance(raw, list) and len(raw) > 0:
                return raw[0] if isinstance(raw[0], dict) else {}
            if isinstance(raw, dict) and "obra_ejecutada_directo_sin_aiu" in raw:
                return raw
            if isinstance(raw, dict):
                k = next(iter(raw.keys()), None)
                return raw[k] if k and isinstance(raw.get(k), dict) else raw
            return {}

        if todo_contrato:
            filtro_modo = "todo_contrato"
            acta_id_filtro = None
        elif acta_rpo is not None:
            filtro_modo = "acta"

            def _aid():
                rows = supabase.table("actas").select("id")\
                    .eq("contrato_id", contrato_id).eq("numero_rpo", acta_rpo).execute().data
                if rows:
                    return rows[0]["id"]
                rows = supabase.table("actas").select("id")\
                    .eq("contrato_id", contrato_id).eq("consecutivo", acta_rpo).execute().data
                return rows[0]["id"] if rows else None
            acta_id_filtro = supabase_execute(_aid)
            acta_rpo_resp = int(acta_rpo) if acta_rpo is not None else None
        else:
            # Acta vigente: preferir bundle RPC SQL (niveles dinámicos en contrato_niveles_validacion).
            bundle_meta = None
            if usar_sql_matriz:
                try:
                    raw_bundle, _cache_hit = _fetch_dashboard_matriz_vigente_bundle(contrato_id, campo_max)
                    pay = _parse_rpc_matrix_raw(raw_bundle)
                    vm = pay.get("_vigente") if isinstance(pay, dict) else None
                    if isinstance(vm, dict) and "obra_ejecutada_directo_sin_aiu" in pay:
                        bundle_meta = vm
                        payload = {k: v for k, v in pay.items() if k != "_vigente"}
                        payload_desde_sql = True
                except Exception:
                    payload = {}
                    payload_desde_sql = False

            if bundle_meta is not None:
                aid = bundle_meta.get("acta_id")
                try:
                    acta_id_filtro = int(aid) if aid is not None else None
                except (TypeError, ValueError):
                    acta_id_filtro = None
                fm = bundle_meta.get("filtro")
                if isinstance(fm, str):
                    filtro_modo = fm
                nr = bundle_meta.get("numero_rpo")
                try:
                    acta_rpo_resp = int(nr) if nr is not None else None
                except (TypeError, ValueError):
                    acta_rpo_resp = None
                an_b = bundle_meta.get("asignado_nombre")
                if an_b is not None and not isinstance(an_b, str):
                    an_b = str(an_b)
                if acta_id_filtro is not None:
                    vig = {
                        "id": acta_id_filtro,
                        "numero_rpo": nr,
                        "asignado_nombre": (an_b or "").strip() or None,
                    }
                else:
                    vig = None
            else:
                vig = _acta_rpo_vigente_row(contrato_id)
                if vig:
                    acta_id_filtro = vig.get("id")
                    nr = vig.get("numero_rpo")
                    try:
                        acta_rpo_resp = int(nr) if nr is not None else None
                    except (TypeError, ValueError):
                        acta_rpo_resp = None
                else:
                    filtro_modo = "sin_vigente_todo_contrato"
                    acta_id_filtro = None

        if "obra_ejecutada_directo_sin_aiu" not in payload or "ensayos_sondeos_directo_sin_iva" not in payload:
            if usar_sql_matriz:
                try:
                    def _rpc():
                        return supabase.rpc(
                            "dashboard_matriz_validacion_agg",
                            {"p_contrato_id": contrato_id, "p_acta_id": acta_id_filtro},
                        ).execute().data
                    payload = _parse_rpc_matrix_raw(supabase_execute(_rpc))
                    payload_desde_sql = bool(payload)
                except Exception:
                    payload = {}
                    payload_desde_sql = False
            if "obra_ejecutada_directo_sin_aiu" not in payload or "ensayos_sondeos_directo_sin_iva" not in payload:
                payload = _dashboard_matriz_validacion_por_niveles(contrato_id, acta_id_filtro, niveles_activos)
                payload_desde_sql = False

        payload = _matriz_finalizar_payload(payload, niveles_activos, desde_sql_legacy=payload_desde_sql)

        def _acta_vigente_public(v):
            if not v:
                return None
            nm = v.get("asignado_nombre")
            if nm is not None:
                nm = str(nm).strip() or None
            return {
                "id": v.get("id"),
                "numero_rpo": v.get("numero_rpo"),
                "asignado_nombre": nm,
            }

        result = {
            "acta_rpo": acta_rpo_resp,
            "acta_id_resuelto": acta_id_filtro,
            "filtro": filtro_modo,
            "acta_vigente": _acta_vigente_public(vig),
            "niveles_activos": niveles_activos,
            "obra_ejecutada_directo_sin_aiu": payload.get("obra_ejecutada_directo_sin_aiu") or _matriz_validacion_empty(niveles_activos),
            "ensayos_sondeos_directo_sin_iva": payload.get("ensayos_sondeos_directo_sin_iva") or _matriz_validacion_empty(niveles_activos),
        }
        _dashboard_response_cache_set(matriz_key, result)
        return result
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


_NOTIF_EMAIL_VIEWER = {"id": 0, "rol_nombre": "Desarrollador", "cargo_nombre": "Desarrollador"}


def _parse_matriz_rpc_raw_email(raw):
    if raw is None:
        return {}
    if isinstance(raw, list) and len(raw) > 0:
        return raw[0] if isinstance(raw[0], dict) else {}
    if isinstance(raw, dict) and "obra_ejecutada_directo_sin_aiu" in raw:
        return raw
    if isinstance(raw, dict):
        k = next(iter(raw.keys()), None)
        return raw[k] if k and isinstance(raw.get(k), dict) else raw
    return {}


def _fetch_matriz_validacion_vigente_email(contrato_id: int) -> dict:
    """Matriz validación acta RPO vigente para correo resumen (sin JWT)."""
    niveles_activos = _get_niveles_activos_contrato(contrato_id)
    campo_max = _get_nivel_maximo_contrato(contrato_id)
    vig = _acta_rpo_vigente_row(contrato_id)
    acta_id_filtro: Optional[int] = None
    acta_rpo_resp: Optional[int] = None
    if vig and vig.get("id") is not None:
        try:
            acta_id_filtro = int(vig["id"])
        except (TypeError, ValueError):
            acta_id_filtro = None
    if vig and vig.get("numero_rpo") is not None:
        try:
            acta_rpo_resp = int(vig["numero_rpo"])
        except (TypeError, ValueError):
            acta_rpo_resp = None

    payload: dict = {}
    payload_desde_sql = False
    usar_sql_matriz = bool(niveles_activos) and all(1 <= int(n) <= 6 for n in niveles_activos)

    if acta_id_filtro and usar_sql_matriz:
        try:
            raw_bundle, _ = _fetch_dashboard_matriz_vigente_bundle(contrato_id, campo_max)
            pay = _parse_matriz_rpc_raw_email(raw_bundle)
            if isinstance(pay, dict) and "obra_ejecutada_directo_sin_aiu" in pay:
                payload = {k: v for k, v in pay.items() if k != "_vigente"}
                payload_desde_sql = True
        except Exception:
            payload = {}

    if "obra_ejecutada_directo_sin_aiu" not in payload or "ensayos_sondeos_directo_sin_iva" not in payload:
        if usar_sql_matriz and acta_id_filtro:
            try:
                def _rpc():
                    return supabase.rpc(
                        "dashboard_matriz_validacion_agg",
                        {"p_contrato_id": contrato_id, "p_acta_id": acta_id_filtro},
                    ).execute().data

                payload = _parse_matriz_rpc_raw_email(supabase_execute(_rpc))
                payload_desde_sql = bool(payload)
            except Exception:
                payload = {}
        if "obra_ejecutada_directo_sin_aiu" not in payload or "ensayos_sondeos_directo_sin_iva" not in payload:
            payload = _dashboard_matriz_validacion_por_niveles(
                contrato_id, acta_id_filtro, niveles_activos
            )
            payload_desde_sql = False

    payload = _matriz_finalizar_payload(payload, niveles_activos, desde_sql_legacy=payload_desde_sql)
    return {
        "acta_rpo": acta_rpo_resp,
        "niveles_activos": niveles_activos,
        "nivel_maximo": _get_nivel_numero_maximo_contrato(contrato_id),
        "niveles": [
            {
                "nivel": n,
                "encabezado": NIVEL_VALIDACION_ENCABEZADO.get(n) or f"Nivel {n}",
            }
            for n in niveles_activos
        ],
        "obra_ejecutada_directo_sin_aiu": payload.get("obra_ejecutada_directo_sin_aiu")
        or _matriz_validacion_empty(niveles_activos),
        "ensayos_sondeos_directo_sin_iva": payload.get("ensayos_sondeos_directo_sin_iva")
        or _matriz_validacion_empty(niveles_activos),
    }


def _fetch_capitulos_financiero_email(contrato_id: int) -> dict:
    """Ppto vs Cobro por capítulo (obra ejecutada) para correo resumen."""
    rows_aiu, rows_iva = _gerencial_capitulos_data_both(
        contrato_id, DASH_VISTA_OBRA_EJECUTADA, _NOTIF_EMAIL_VIEWER, acta_id=None
    )
    return _dashboard_capitulos_financiero_build_response(
        contrato_id, DASH_VISTA_OBRA_EJECUTADA, rows_aiu, rows_iva
    )


@app.get("/sicoe-obra/{contrato_id}/dashboard-drill")
def dashboard_drill_obra(
    contrato_id: int,
    capitulo: Optional[str] = None,
    item: Optional[str] = None,
    vista: str = Query("presupuesto_obra", description="presupuesto_obra | obra_ejecutada"),
    current_user=Depends(get_current_user),
):
    # Si falla después, el front espera { campo, items }; evita 500 sin CORS en Azure.
    drill_items_shape = False
    try:
        if capitulo is not None:
            capitulo = unquote(str(capitulo)).strip() or None
        if item is not None:
            item = unquote(str(item)).strip() or None
        drill_items_shape = bool(capitulo)
        vista_n = parse_dash_vista(vista)
        resp_key = (
            "dashboard_drill_v4",
            int(contrato_id),
            vista_n,
            capitulo or "",
            item or "",
            _dashboard_resumen_user_cache_key(current_user),
        )
        cached_resp = _dashboard_response_cache_get(resp_key)
        if cached_resp is not None:
            return cached_resp

        campo_max = _get_nivel_maximo_contrato(contrato_id)
        niveles_activos = _get_niveles_activos_contrato(contrato_id)
        if capitulo:
            items = _drill_agg_by_item(contrato_id, capitulo, item, vista, current_user)
            if item:
                itn = _dash_norm_item_key_py(str(item).strip())
                items = [
                    row
                    for row in items
                    if isinstance(row, dict) and _dash_norm_item_key_py(row.get("item")) == itn
                ]
            result = {"campo": "item", "items": items, "vista": vista_n}
            _dashboard_response_cache_set(resp_key, result)
            return result
        if item:
            raise HTTPException(status_code=422, detail="Indica capitulo junto con item.")
        result = _drill_agg_capitulos(contrato_id, vista, current_user)
        result = {"campo": "capitulo", "items": result, "vista": vista_n}
        _dashboard_response_cache_set(resp_key, result)
        return result
    except HTTPException:
        raise
    except Exception as e:
        print(f"ERROR dashboard_drill_obra: {type(e).__name__}: {e}", flush=True)
        print(traceback.format_exc(), flush=True)
        if drill_items_shape:
            return {"campo": "item", "items": []}
        return {"campo": "capitulo", "items": []}


def _dashboard_pkid_tabla_obra_core(
    contrato_id: int,
    capitulo: Optional[str],
    item: Optional[str],
    vista: str = "presupuesto_obra",
    current_user=None,
) -> Dict[str, Any]:
    """Por PK_ID: presupuesto según vista; obra aprobada al nivel máximo activo."""
    cap_raw = (capitulo or "").strip() if capitulo else ""
    item_raw = (item or "").strip() if item else ""
    t0 = time.time()
    if cap_raw:
        try:
            rpc_hit = _rpc_pkid_tabla_agg(contrato_id, cap_raw, item_raw or None)
            rpc_rows = rpc_hit.get("rows") if isinstance(rpc_hit, dict) else None
            if isinstance(rpc_rows, list):
                ppto_rows: List[dict] = []
                if item_raw:
                    ppto_rows = ppto_rows_item_pk_drill(
                        supabase, contrato_id, cap_raw, item_raw, vista, current_user
                    )
                out = _merge_pkid_tabla_vista_ppto(rpc_hit, ppto_rows) if ppto_rows else rpc_hit
                print(
                    f"dashboard_pkid_tabla RPC ok cap={cap_raw!r} item={item_raw!r} "
                    f"rows={len(out.get('rows') or [])} ms={int((time.time() - t0) * 1000)}",
                    flush=True,
                )
                return _normalize_pkid_tabla_payload(
                    out,
                    contrato_id,
                    vista=vista,
                    capitulo=cap_raw,
                    item=item_raw,
                    current_user=current_user,
                )
        except Exception as rpc_err:
            print(
                f"dashboard_pkid_tabla_agg RPC FALLÓ, fallback Python: "
                f"{type(rpc_err).__name__}: {rpc_err}",
                flush=True,
            )

    ppto, allowed_keys, _scan = ppto_filas_pk_drill(
        supabase, contrato_id, capitulo, item, vista, current_user
    )

    registros = []
    off = 0
    it_norm = _dash_norm_item_key_py(item) if item else ""
    cap_key = _dash_norm_capitulo_key_py(capitulo) if capitulo else None
    item_vars: List[str] = []
    if it_norm:
        item_vars = [v for v in {(item or "").strip(), it_norm, f"{it_norm}."} if v]
    while True:
        def _regs(o=off, caps=cap_raw, iv=item_vars):
            q = supabase.table("so_registros").select(
                f"pk_id_id, capitulo, pk_ids(pk_id), costo_directo, cantidad_total, item_numero, {SICOE_SELECT_NIVELES_ESTADO}"
            ).eq("contrato_id", contrato_id)
            if caps:
                q = apply_sicoe_capitulo_filter(q, supabase, contrato_id, caps)
            if iv:
                if len(iv) == 1:
                    q = q.eq("item_numero", iv[0])
                else:
                    q = q.in_("item_numero", iv)
            return q.order("id").range(o, o + 999).execute().data

        batch = supabase_execute(_regs)
        for reg in batch or []:
            if cap_key and _dash_norm_capitulo_key_py(reg.get("capitulo")) != cap_key:
                continue
            if it_norm and _dash_norm_item_key_py(reg.get("item_numero")) != it_norm:
                continue
            if not sicoe_registro_en_vista(
                reg,
                None if parse_dash_vista(vista) == DASH_VISTA_OBRA_EJECUTADA else allowed_keys,
            ):
                continue
            registros.append(reg)
        if len(batch) < 1000:
            break
        off += 1000

    empty_m = _pkid_tabla_empty_metric
    agg_meta, agg_p_ap, agg_p_nr, agg_p_pd, agg_p_rj = _aggregate_pkid_ppto_rows(ppto)

    agg_sicoe_ap: Dict[str, Any] = {}
    agg_sicoe_nr: Dict[str, Any] = {}
    agg_sicoe_pe: Dict[str, Any] = {}
    agg_sicoe_rej: Dict[str, Any] = {}
    for r in registros:
        pk_join = r.get("pk_ids") or {}
        pk_raw = pk_join.get("pk_id")
        pk = _dash_pk_disp_key_py(pk_raw) if pk_raw is not None and str(pk_raw).strip() != "" else _dash_pk_disp_key_py(r.get("pk_id_id"))
        cd = float(r.get("costo_directo") or 0)
        cq = cantidad_dashboard(float(r.get("cantidad_total") or 0))
        nfin = _matriz_validacion_norm_estado_nivel_final(r, contrato_id)
        if nfin == "Aprobado":
            if pk not in agg_sicoe_ap:
                agg_sicoe_ap[pk] = empty_m()
            agg_sicoe_ap[pk]["cant"] += cq
            agg_sicoe_ap[pk]["costo"] += cd
            continue
        if _so_reg_prereqs_activos_aprobados_antes_max(r, contrato_id):
            if nfin == "Pendiente":
                tgt = agg_sicoe_pe
            elif nfin == "Rechazado":
                tgt = agg_sicoe_rej
            else:
                tgt = agg_sicoe_nr
            if pk not in tgt:
                tgt[pk] = empty_m()
            tgt[pk]["cant"] += cq
            tgt[pk]["costo"] += cd

    keys = sorted(
        set(
            list(agg_meta.keys())
            + list(agg_p_ap.keys())
            + list(agg_p_nr.keys())
            + list(agg_p_pd.keys())
            + list(agg_p_rj.keys())
            + list(agg_sicoe_ap.keys())
            + list(agg_sicoe_nr.keys())
            + list(agg_sicoe_pe.keys())
            + list(agg_sicoe_rej.keys())
        ),
        key=lambda x: str(x),
    )
    rows = []
    for k in keys:
        meta = agg_meta.get(k, {"desc": "", "_rev_track": []})
        rows.append(
            _build_pkid_tabla_row_from_aggs(
                k,
                meta,
                agg_p_ap.get(k, empty_m()),
                agg_p_nr.get(k, empty_m()),
                agg_p_pd.get(k, empty_m()),
                agg_p_rj.get(k, empty_m()),
                agg_sicoe_ap.get(k, empty_m()),
                agg_sicoe_nr.get(k, empty_m()),
                agg_sicoe_pe.get(k, empty_m()),
                agg_sicoe_rej.get(k, empty_m()),
            )
        )

    desc_item = ""
    if item and capitulo:
        d = (
            supabase.table("presupuesto")
            .select("descripcion, item")
            .eq("contrato_id", contrato_id)
            .eq("capitulo", capitulo)
            .not_.is_("descripcion", "null")
            .execute()
            .data
        ) or []
        for row in d:
            if _dash_norm_item_key_py(row.get("item")) == it_norm and row.get("descripcion"):
                desc_item = row["descripcion"] or ""
                break

    por_cobrar = sum(r["delta_costo"] for r in rows if r["delta_costo"] > 0)
    devolucion = sum(abs(r["delta_costo"]) for r in rows if r["delta_costo"] < 0)
    print(
        f"dashboard_pkid_tabla fallback cap={cap_raw!r} item={item_raw!r} rows={len(rows)} "
        f"ms={int((time.time() - t0) * 1000)}",
        flush=True,
    )
    return _normalize_pkid_tabla_payload(
        {"rows": rows, "por_cobrar": por_cobrar, "devolucion": devolucion, "descripcion_item": desc_item},
        contrato_id,
        vista=vista,
        capitulo=cap_raw,
        item=item_raw,
        current_user=current_user,
    )


def _ppto_rows_capitulo(
    contrato_id: int,
    capitulo: str,
    vista: str = "presupuesto_obra",
    current_user=None,
) -> List[dict]:
    return _ppto_rows_capitulo_tipo(contrato_id, capitulo, ppto_tipo_for_vista(vista), current_user)


def _ppto_rows_capitulo_tipo(
    contrato_id: int,
    capitulo: str,
    tipo_ejecucion: str,
    current_user,
) -> List[dict]:
    """Presupuesto de un capítulo (filtro por variantes de texto en BD)."""
    cap_key = _dash_norm_capitulo_key_py(capitulo)
    variants = capitulo_variants_heuristic(capitulo)
    rows: List[dict] = []
    off = 0
    while True:
        def _b(o=off, caps=variants):
            q = (
                supabase.table("presupuesto")
                .select(
                    "id, item, descripcion, capitulo, cant_total, vlr_unitario, costo_directo, revisado, pk_id, "
                    "tipo_ejecucion, und, id_pol, no_inicio, no_final, tramo, calzada"
                )
                .eq("contrato_id", contrato_id)
                .eq("dado_de_baja", False)
                .eq("tipo_ejecucion", tipo_ejecucion)
            )
            if current_user and _presupuesto_aplica_filtro_interventoria(current_user):
                q = q.eq("pre_interv_estado", "Aprobado")
            if caps:
                if len(caps) == 1:
                    q = q.eq("capitulo", caps[0])
                else:
                    q = q.in_("capitulo", caps)
            return q.order("id").range(o, o + 999).execute().data

        batch = supabase_execute(_b) or []
        for row in batch:
            if _dash_norm_capitulo_key_py(row.get("capitulo")) != cap_key:
                continue
            rows.append(row)
        if len(batch) < 1000:
            break
        off += 1000
    return rows


def _ppto_costo_por_revisado(rows_item: List[dict]) -> Dict[str, float]:
    cant: Dict[str, float] = {"Aprobado": 0.0, "Pendiente": 0.0, "Rechazado": 0.0, "No Revisado": 0.0}
    for r in rows_item:
        c = float(r.get("cant_total") or 0)
        rv = _matriz_validacion_norm_estado(r.get("revisado"))
        if rv not in cant:
            rv = "No Revisado"
        cant[rv] += c
    vu = vu_item_rows(rows_item)
    return {k: costo_agregado_cant_vu(v, vu) for k, v in cant.items()}


def _agg_ppto_costo_filas(rows: List[dict]) -> Tuple[float, float]:
    """(cantidad, costo) agregados por ítem: Σcant×VU con un redondeo por ítem."""
    if not rows:
        return 0.0, 0.0
    by_item: Dict[str, List[dict]] = defaultdict(list)
    for r in rows:
        ik = _dash_norm_item_key_py(r.get("item")) or "__"
        by_item[ik].append(r)
    total_q = 0.0
    total_c = 0.0
    for item_rows in by_item.values():
        q = sum(float(x.get("cant_total") or 0) for x in item_rows)
        total_q += q
        total_c += costo_agregado_cant_vu(q, vu_item_rows(item_rows))
    return total_q, total_c


def _agg_sicoe_costo_filas(rows: List[dict]) -> Tuple[float, float]:
    """(cantidad, costo) SICOE agregados por ítem."""
    if not rows:
        return 0.0, 0.0
    by_item: Dict[str, Dict[str, float]] = defaultdict(lambda: {"q": 0.0, "vu": 0.0})
    for r in rows:
        ik = _dash_norm_item_key_py(r.get("item_numero") or r.get("item")) or "__"
        by_item[ik]["q"] += cantidad_dashboard(float(r.get("cantidad_total") or r.get("cantidad") or 0))
        vu = float(r.get("vlr_unitario") or 0)
        if vu > by_item[ik]["vu"]:
            by_item[ik]["vu"] = vu
    total_q = cantidad_dashboard(sum(d["q"] for d in by_item.values()))
    total_c = sum(costo_agregado_cant_vu(d["q"], d["vu"]) for d in by_item.values())
    return total_q, total_c


def _xlsx_safe_sheet_name(name: str, fallback: str = "Hoja") -> str:
    s = re.sub(r"[\[\]\*\/\\\?\:]", "_", str(name or "").strip())[:31]
    return s or fallback[:31]


# Export dashboard capítulo — paleta ClaraCore
_CC_XLSX_PRIMARY = "0077B6"
_CC_XLSX_DARK = "0A1628"
_CC_XLSX_PRIMARY_LIGHT = "E6F4FA"
_CC_XLSX_GREEN_BG = "D1FAE5"
_CC_XLSX_RED_BG = "FEE2E2"
_XLSX_FMT_CANT = "#,##0.0000"
_XLSX_FMT_COP = '"$"#,##0'
_XLSX_PK_COLS = [
    "PK_Id",
    "Cant. ClaraCore",
    "Costo ClaraCore",
    "Cant. Cobrada",
    "Costo Cobrado",
    "Δ Cantidad",
    "Δ Costo",
    "Revisado",
]
_XLSX_PK_CANT_COLS = frozenset({2, 4, 6})
_XLSX_PK_COP_COLS = frozenset({3, 5, 7})
_DASH_DELTA_EPS = 0.5


def _split_pk_export_rows(rows: List[dict]) -> Tuple[List[dict], List[dict], List[dict]]:
    """Clasifica filas PK con el mismo umbral que el dashboard (±0,5 en Δ costo)."""
    pos: List[dict] = []
    neg: List[dict] = []
    equi: List[dict] = []
    for r in rows or []:
        d = float(r.get("delta_costo") or 0)
        if d > _DASH_DELTA_EPS:
            pos.append(r)
        elif d < -_DASH_DELTA_EPS:
            neg.append(r)
        else:
            equi.append(r)
    return pos, neg, equi


def _xlsx_cell_display_width(val, cell) -> int:
    if val is None:
        return 0
    if isinstance(val, bool):
        return 5
    if isinstance(val, (int, float)):
        nf = str(cell.number_format or "")
        if '"$"' in nf:
            return len(f"${val:,.0f}")
        if "0.0000" in nf:
            return len(f"{val:.4f}")
        if "0.00" in nf:
            return len(f"{val:.2f}")
        return len(str(val))
    return len(str(val))


def _xlsx_apply_outer_double_border(
    ws,
    row_start: int,
    row_end: int,
    col_start: int,
    col_end: int,
    *,
    color: str = "000000",
) -> None:
    """Contorno perimetral de doble línea sobre una región con bordes interiores existentes."""
    from openpyxl.styles import Border, Side

    double = Side(style="double", color=color)
    for r in range(row_start, row_end + 1):
        for c in range(col_start, col_end + 1):
            cell = ws.cell(row=r, column=c)
            b = cell.border
            cell.border = Border(
                left=double if c == col_start else b.left,
                right=double if c == col_end else b.right,
                top=double if r == row_start else b.top,
                bottom=double if r == row_end else b.bottom,
            )


def _xlsx_merged_span_width(ws, row: int, col: int) -> float:
    """Ancho efectivo de celda (suma columnas si está en un merge)."""
    from openpyxl.utils import get_column_letter

    for merged in ws.merged_cells.ranges:
        if (
            merged.min_row <= row <= merged.max_row
            and merged.min_col <= col <= merged.max_col
        ):
            total = 0.0
            for c in range(merged.min_col, merged.max_col + 1):
                letter = get_column_letter(c)
                total += float(ws.column_dimensions[letter].width or 12)
            return total
    letter = get_column_letter(col)
    return float(ws.column_dimensions[letter].width or 12)


def _xlsx_estimate_row_height_pt(
    ws,
    row: int,
    cols: Iterable[int],
    *,
    min_height: float = 25,
    font_size: float = 10,
) -> float:
    """Altura mínima o mayor si el texto envuelto lo requiere (wrap_text)."""
    max_lines = 1
    for col in cols:
        cell = ws.cell(row=row, column=col)
        if cell.value is None:
            continue
        eff_w = _xlsx_merged_span_width(ws, row, col)
        chars = max(int(eff_w * 0.85), 8)
        lines = 0
        for part in str(cell.value).replace("\r", "").split("\n"):
            pl = len(part) or 1
            lines += max(1, (pl + chars - 1) // chars)
        max_lines = max(max_lines, lines)
    line_h = font_size * 1.45
    return max(min_height, max_lines * line_h + 8)


def _xlsx_autofit_columns(
    ws,
    col_start: int = 1,
    col_end: Optional[int] = None,
    row_start: int = 1,
    row_end: Optional[int] = None,
    min_w: float = 9,
    max_w: float = 48,
    col_max: Optional[Dict[int, float]] = None,
):
    from openpyxl.utils import get_column_letter

    if col_end is None:
        col_end = ws.max_column or 1
    if row_end is None:
        row_end = ws.max_row or 1
    col_max = col_max or {}
    for col in range(col_start, col_end + 1):
        letter = get_column_letter(col)
        cap = col_max.get(col, max_w)
        best = min_w
        for row in range(row_start, row_end + 1):
            cell = ws.cell(row=row, column=col)
            best = max(best, min(_xlsx_cell_display_width(cell.value, cell) + 2, cap))
        ws.column_dimensions[letter].width = best


def _xlsx_apply_page_footer(ws, contrato_numero: str) -> None:
    num = (contrato_numero or "—").strip()
    for hf in (ws.oddFooter, ws.evenFooter):
        hf.left.text = "Página &P de &N"
        hf.center.text = "&A"
        hf.right.text = f"Producto ClaraCore para el contrato {num}"


def _xlsx_apply_print_summary(ws, contrato_numero: str) -> None:
    ws.page_setup.orientation = "landscape"
    ws.page_setup.paperSize = ws.PAPERSIZE_A4
    ws.page_setup.fitToPage = True
    ws.page_setup.fitToWidth = 1
    ws.page_setup.fitToHeight = 0
    ws.print_options.horizontalCentered = True
    _xlsx_apply_page_footer(ws, contrato_numero)


def _xlsx_apply_print_item(ws, contrato_numero: str) -> None:
    ws.page_setup.orientation = "portrait"
    ws.page_setup.paperSize = ws.PAPERSIZE_A4
    ws.page_setup.fitToPage = True
    ws.page_setup.fitToWidth = 1
    ws.page_setup.fitToHeight = 0
    ws.print_options.horizontalCentered = True
    _xlsx_apply_page_footer(ws, contrato_numero)


def _apply_export_claracore_basis_rows(rows: List[dict]) -> None:
    """Rebasa filas PK del export a la base ClaraCore (in-place).

    ClaraCore = Aprobado + No Revisado (excluye Pendiente/Rechazado), por lo que
    cantidad/costo ClaraCore = total − pendiente − rechazado. El delta pasa a ser
    ClaraCore − Cobrado. Solo afecta los Excel (ejecutivo/completo); el dashboard
    web conserva su lógica original.
    """
    for r in rows or []:
        if not isinstance(r, dict):
            continue
        cc_q = float(r.get("cant_ppto_aprobado_n3") or 0) + float(r.get("cant_ppto_estado_no_revisado") or 0)
        cc_c = float(r.get("costo_ppto_aprobado_n3") or 0) + float(r.get("costo_ppto_estado_no_revisado") or 0)
        sic_q = float(r.get("cant_sicoe") or 0)
        sic_c = float(r.get("costo_sicoe") or 0)
        r["cant_ppto"] = round(cc_q, 2)
        r["costo_ppto"] = round(cc_c, 0)
        r["delta_cant"] = round(cc_q - sic_q, 2)
        r["delta_costo"] = round(cc_c - sic_c, 0)


def _sum_pk_export_rows(rows: List[dict]) -> Dict[str, float]:
    """Totales alineados con dashboard-pkid-tabla (mismos campos por fila PK)."""
    return {
        "cant_ppto": sum(float(r.get("cant_ppto") or 0) for r in rows),
        "costo_ppto": sum(float(r.get("costo_ppto") or 0) for r in rows),
        "cant_sicoe": sum(float(r.get("cant_sicoe") or 0) for r in rows),
        "costo_sicoe": sum(float(r.get("costo_sicoe") or 0) for r in rows),
        "delta_cant": sum(float(r.get("delta_cant") or 0) for r in rows),
        "delta_costo": sum(float(r.get("delta_costo") or 0) for r in rows),
    }


def _dashboard_pkid_tabla_export_item(
    contrato_id: int,
    capitulo: str,
    item: str,
    vista: str,
    current_user,
) -> Dict[str, Any]:
    """Ruta rápida export Excel: RPC + merge presupuesto vista (sin logs ni fallback pesado)."""
    cap_raw = str(capitulo or "").strip()
    item_raw = str(item or "").strip()
    if not cap_raw or not item_raw:
        return {"rows": [], "por_cobrar": 0.0, "devolucion": 0.0, "descripcion_item": ""}
    try:
        rpc_hit = _rpc_pkid_tabla_agg(contrato_id, cap_raw, item_raw)
        ppto_rows = ppto_rows_item_pk_drill(
            supabase, contrato_id, cap_raw, item_raw, vista, current_user
        )
        out = _merge_pkid_tabla_vista_ppto(rpc_hit, ppto_rows) if ppto_rows else rpc_hit
        return _normalize_pkid_tabla_payload(
            out,
            contrato_id,
            vista=vista,
            capitulo=cap_raw,
            item=item_raw,
            current_user=current_user,
        )
    except Exception:
        return _dashboard_pkid_tabla_obra_core(
            contrato_id, capitulo, item, vista, current_user
        )


def _fetch_sicoe_regs_capitulo_export(
    contrato_id: int,
    capitulo: str,
    current_user=None,
) -> List[dict]:
    """Registros SICOE del capítulo (una sola pasada paginada) para export Excel."""
    cap_raw = (capitulo or "").strip()
    cap_key = _dash_norm_capitulo_key_py(cap_raw) if cap_raw else None
    registros: List[dict] = []
    off = 0
    while True:
        def _regs(o=off, caps=cap_raw):
            q = supabase.table("so_registros").select(
                f"pk_id_id, capitulo, pk_ids(pk_id), costo_directo, cantidad_total, item_numero, {SICOE_SELECT_NIVELES_ESTADO}"
            ).eq("contrato_id", contrato_id)
            if caps:
                q = apply_sicoe_capitulo_filter(q, supabase, contrato_id, caps)
            return q.order("id").range(o, o + 999).execute().data

        batch = supabase_execute(_regs) or []
        for reg in batch:
            if cap_key and _dash_norm_capitulo_key_py(reg.get("capitulo")) != cap_key:
                continue
            registros.append(reg)
        if len(batch) < 1000:
            break
        off += 1000
    return registros


def _ppto_pk_rows_from_capitulo_rows(rows: List[dict], item: str) -> List[dict]:
    """Formato pk drill desde filas presupuesto ya cargadas del capítulo."""
    it_norm = _dash_norm_item_key_py(item)
    if not it_norm:
        return []
    out: List[dict] = []
    for r in rows or []:
        if _dash_norm_item_key_py(r.get("item")) != it_norm:
            continue
        out.append(
            {
                "pk_id": r.get("pk_id"),
                "item": it_norm,
                "cant_total": float(r.get("cant_total") or 0),
                "costo_directo": float(r.get("costo_directo") or 0),
                "descripcion": r.get("descripcion") or "",
                "revisado": r.get("revisado"),
                "capitulo": r.get("capitulo") or "",
            }
        )
    return out


def _build_pkid_tabla_item_export(
    contrato_id: int,
    item: str,
    ppto_rows: List[dict],
    sicoe_regs: List[dict],
    vista: str,
) -> Dict[str, Any]:
    """Tabla PK por ítem sin RPC (memoria + un solo scan SICOE del capítulo)."""
    it_norm = _dash_norm_item_key_py(item)
    cap_key = None
    if ppto_rows:
        cap_key = _dash_norm_capitulo_key_py(ppto_rows[0].get("capitulo"))
    allowed = {(cap_key, it_norm)} if parse_dash_vista(vista) == DASH_VISTA_OBRA_EJECUTADA and cap_key and it_norm else None

    item_vars: List[str] = []
    if it_norm:
        item_vars = [v for v in {(item or "").strip(), it_norm, f"{it_norm}."} if v]

    registros: List[dict] = []
    for r in sicoe_regs or []:
        if it_norm and _dash_norm_item_key_py(r.get("item_numero")) != it_norm:
            continue
        if not sicoe_registro_en_vista(r, allowed):
            continue
        registros.append(r)

    empty_m = _pkid_tabla_empty_metric
    agg_meta, agg_p_ap, agg_p_nr, agg_p_pd, agg_p_rj = _aggregate_pkid_ppto_rows(ppto_rows)

    agg_sicoe_ap: Dict[str, Any] = {}
    agg_sicoe_nr: Dict[str, Any] = {}
    agg_sicoe_pe: Dict[str, Any] = {}
    agg_sicoe_rej: Dict[str, Any] = {}
    for r in registros:
        pk_join = r.get("pk_ids") or {}
        pk_raw = pk_join.get("pk_id")
        pk = (
            _dash_pk_disp_key_py(pk_raw)
            if pk_raw is not None and str(pk_raw).strip() != ""
            else _dash_pk_disp_key_py(r.get("pk_id_id"))
        )
        cd = float(r.get("costo_directo") or 0)
        cq = cantidad_dashboard(float(r.get("cantidad_total") or 0))
        nfin = _matriz_validacion_norm_estado_nivel_final(r, contrato_id)
        if nfin == "Aprobado":
            if pk not in agg_sicoe_ap:
                agg_sicoe_ap[pk] = empty_m()
            agg_sicoe_ap[pk]["cant"] += cq
            agg_sicoe_ap[pk]["costo"] += cd
            continue
        if _so_reg_prereqs_activos_aprobados_antes_max(r, contrato_id):
            if nfin == "Pendiente":
                tgt = agg_sicoe_pe
            elif nfin == "Rechazado":
                tgt = agg_sicoe_rej
            else:
                tgt = agg_sicoe_nr
            if pk not in tgt:
                tgt[pk] = empty_m()
            tgt[pk]["cant"] += cq
            tgt[pk]["costo"] += cd

    keys = sorted(
        set(
            list(agg_meta.keys())
            + list(agg_p_ap.keys())
            + list(agg_p_nr.keys())
            + list(agg_p_pd.keys())
            + list(agg_p_rj.keys())
            + list(agg_sicoe_ap.keys())
            + list(agg_sicoe_nr.keys())
            + list(agg_sicoe_pe.keys())
            + list(agg_sicoe_rej.keys())
        ),
        key=lambda x: str(x),
    )
    rows_out = []
    for k in keys:
        meta = agg_meta.get(k, {"desc": "", "_rev_track": []})
        rows_out.append(
            _build_pkid_tabla_row_from_aggs(
                k,
                meta,
                agg_p_ap.get(k, empty_m()),
                agg_p_nr.get(k, empty_m()),
                agg_p_pd.get(k, empty_m()),
                agg_p_rj.get(k, empty_m()),
                agg_sicoe_ap.get(k, empty_m()),
                agg_sicoe_nr.get(k, empty_m()),
                agg_sicoe_pe.get(k, empty_m()),
                agg_sicoe_rej.get(k, empty_m()),
            )
        )

    desc_item = ""
    for row in ppto_rows or []:
        if row.get("descripcion"):
            desc_item = str(row["descripcion"])
            break

    por_cobrar = sum(r["delta_costo"] for r in rows_out if r["delta_costo"] > 0)
    devolucion = sum(abs(r["delta_costo"]) for r in rows_out if r["delta_costo"] < 0)
    return {
        "rows": rows_out,
        "por_cobrar": por_cobrar,
        "devolucion": devolucion,
        "descripcion_item": desc_item,
    }


def _fetch_export_core_by_item(
    contrato_id: int,
    capitulo: str,
    items_sorted: List[str],
    vista: str,
    current_user,
    *,
    ppto_all: Optional[List[dict]] = None,
    job_id: Optional[str] = None,
) -> Dict[str, Dict[str, Any]]:
    """
    Tablas PK por ítem para export Excel.
    Una pasada de presupuesto + una de SICOE del capítulo; alias PK en batch (sin N×Supabase).
    """
    if not items_sorted:
        return {}
    cap_raw = str(capitulo or "").strip()
    if ppto_all is None:
        ppto_all = _ppto_rows_capitulo(contrato_id, cap_raw, vista, current_user)

    ppto_by_item: Dict[str, List[dict]] = {}
    all_pk_keys: Set[str] = set()
    for r in ppto_all or []:
        ik = _dash_norm_item_key_py(r.get("item"))
        if not ik:
            continue
        ppto_by_item.setdefault(ik, []).append(r)
        pk = _dash_pk_disp_key_py(r.get("pk_id"))
        if pk and pk != "(sin pk)":
            all_pk_keys.add(pk)

    if job_id:
        _export_job_set(job_id, progreso="cargando SICOE obra…")
    sicoe_regs = _fetch_sicoe_regs_capitulo_export(contrato_id, cap_raw, current_user)

    if job_id:
        _export_job_set(job_id, progreso="indexando PK…")
    alias_map = _preload_pk_alias_map(contrato_id, all_pk_keys)

    sicoe_by_item: Dict[str, List[dict]] = defaultdict(list)
    for r in sicoe_regs or []:
        ik = _dash_norm_item_key_py(r.get("item_numero"))
        if ik:
            sicoe_by_item[ik].append(r)

    total = len(items_sorted)
    out: Dict[str, Dict[str, Any]] = {}

    def _one_item(it: str) -> Tuple[str, Dict[str, Any]]:
        it_norm = _dash_norm_item_key_py(it)
        ppto_rows = _ppto_pk_rows_from_capitulo_rows(ppto_by_item.get(it_norm, []), it)
        item_regs = sicoe_by_item.get(it_norm, [])
        raw = _build_pkid_tabla_item_export(
            contrato_id, it, ppto_rows, item_regs, vista
        )
        return it, _normalize_pkid_tabla_payload(
            raw,
            contrato_id,
            alias_map=alias_map,
            vista=vista,
            capitulo=capitulo,
            item=it,
            current_user=current_user,
        )

    workers = min(4, max(1, total))
    done = 0
    if total <= 2 or workers == 1:
        for idx, it in enumerate(items_sorted):
            k, data = _one_item(it)
            out[k] = data
            done = idx + 1
            if job_id:
                _export_job_set(job_id, progreso=f"ítems {done}/{total}")
    else:
        with ThreadPoolExecutor(max_workers=workers) as pool:
            futs = {pool.submit(_one_item, it): it for it in items_sorted}
            for fut in futs:
                k, data = fut.result()
                out[k] = data
                done += 1
                if job_id:
                    _export_job_set(job_id, progreso=f"ítems {done}/{total}")
    return out


def _export_sicoe_obra_rows_capitulo(
    contrato_id: int,
    capitulo: str,
    items_sorted: List[str],
) -> List[dict]:
    """Obra SICOE aprobada (nivel máx. contrato) para ítems del capítulo en presupuesto.

    Devuelve filas de so_registros con las mismas columnas que antes; los campos *_id
    muestran valores de negocio (semana, acta, subcontratista, inspector, reporte).
    pk_id_id se resuelve a pk_id (valor de pk_ids.pk_id).
    """
    if not items_sorted:
        return []
    cap_key = _dash_norm_capitulo_key_py(capitulo)
    item_keys = {_dash_norm_item_key_py(it) for it in items_sorted if _dash_norm_item_key_py(it)}
    item_vars: set = set()
    for it in items_sorted:
        s = (it or "").strip()
        if s:
            item_vars.add(s)
        ik = _dash_norm_item_key_py(it)
        if ik:
            item_vars.add(ik)
            item_vars.add(f"{ik}.")
    item_list = sorted(item_vars)
    rows: List[dict] = []
    off = 0
    while True:

        def _fetch(o=off, iv=item_list):
            q = supabase.table("so_registros").select("*").eq("contrato_id", contrato_id)
            q = apply_sicoe_capitulo_filter(q, supabase, contrato_id, capitulo)
            if iv:
                if len(iv) == 1:
                    q = q.eq("item_numero", iv[0])
                else:
                    q = q.in_("item_numero", iv[:400])
            return q.order("id").range(o, o + 999).execute().data

        batch = supabase_execute(_fetch) or []
        for r in batch:
            if cap_key and _dash_norm_capitulo_key_py(r.get("capitulo")) != cap_key:
                continue
            if item_keys and _dash_norm_item_key_py(r.get("item_numero")) not in item_keys:
                continue
            if _matriz_validacion_norm_estado_nivel_final(r, contrato_id) != "Aprobado":
                continue
            rows.append(r)
        if len(batch) < 1000:
            break
        off += 1000
    return _sicoe_registros_xlsx_sin_ids_internos(rows)


def _listado_precios_tipo_calculo_index(contrato_id: int) -> Dict[Tuple[str, str], str]:
    """(capítulo_norm, ítem_norm) → tipo_calculo (AIU | IVA | …) del listado de precios."""
    cached = _dash_agg_cache_get("listado_precios_tipo_idx", contrato_id)
    if cached is not None:
        return cached
    idx: Dict[Tuple[str, str], str] = {}
    off = 0
    while True:

        def _b(o=off):
            return (
                supabase.table("listado_precios")
                .select("capitulo, item_numero, tipo_calculo")
                .eq("contrato_id", contrato_id)
                .range(o, o + 999)
                .execute()
                .data
            )

        batch = supabase_execute(_b) or []
        for r in batch:
            ck = _dash_norm_capitulo_key_py(r.get("capitulo"))
            ik = _dash_norm_item_key_py(r.get("item_numero"))
            if not ik:
                continue
            k = (ck, ik)
            if k not in idx:
                idx[k] = (r.get("tipo_calculo") or "").strip().upper()
        if len(batch) < 1000:
            break
        off += 1000
    _dash_agg_cache_set("listado_precios_tipo_idx", contrato_id, idx)
    return idx


def _dash_listado_vu_resolved(
    contrato_id: int,
    capitulo: str,
    item: str,
    *,
    cap_listado_idx: Optional[Dict[str, dict]] = None,
    full_listado_idx: Optional[Dict[Tuple[str, str], dict]] = None,
) -> Optional[float]:
    """V.U. vigente del Listado de Precios para (capítulo, ítem). Sin cruzar capítulos."""
    from dashboard_costo_agregado import listado_vu_for_cap_item

    ik = _dash_norm_item_key_py(item)
    ck = _dash_norm_capitulo_key_py(capitulo)
    if full_listado_idx is None:
        full_listado_idx = _listado_precios_vu_by_cap_item(contrato_id)
    return listado_vu_for_cap_item(
        ck,
        ik,
        cap_listado_by_item=cap_listado_idx,
        full_listado_by_cap_item=full_listado_idx,
    )


def _listado_precios_vu_by_cap_item(contrato_id: int) -> Dict[Tuple[str, str], Dict[str, Any]]:
    """(capítulo_norm, ítem_norm) → fila listado_precios (V.U. y metadatos)."""
    cached = _dash_agg_cache_get("listado_precios_vu_idx_v2", contrato_id)
    if cached is not None:
        return cached
    idx: Dict[Tuple[str, str], Dict[str, Any]] = {}
    off = 0
    while True:

        def _b(o=off):
            return (
                supabase.table("listado_precios")
                .select("capitulo, item_numero, precio_unitario, unidad, descripcion")
                .eq("contrato_id", contrato_id)
                .range(o, o + 999)
                .execute()
                .data
            )

        batch = supabase_execute(_b) or []
        for r in batch:
            ck = _dash_norm_capitulo_key_py(r.get("capitulo"))
            ik = _dash_norm_item_key_py(r.get("item_numero"))
            if not ik:
                continue
            k = (ck, ik)
            if k not in idx:
                idx[k] = r
        if len(batch) < 1000:
            break
        off += 1000
    _dash_agg_cache_set("listado_precios_vu_idx_v2", contrato_id, idx)
    return idx


def _dash_agg_cache_invalidate_listado(contrato_id: int) -> None:
    """Invalida índices de listado tras editar ficha (ítem/desc/unidad/V.U.)."""
    key = f"listado_precios_vu_idx_v2:{int(contrato_id)}"
    key2 = f"listado_precios_tipo_idx:{int(contrato_id)}"
    with _DASH_AGG_CACHE_LOCK:
        _DASH_AGG_CACHE.pop(key, None)
        _DASH_AGG_CACHE.pop(key2, None)


def _overlay_presupuesto_meta_vivo(contrato_id: int, rows: list) -> list:
    """Resuelve ítem/descripcion/und en vivo desde listado_precios."""
